-- POSTO 17 / GERADOR DO PROJETO | R6 CLASSICO
-- Execute no Roblox Studio > View > Command Bar (modo EDICAO).
-- Restaurar o projeto completo sem reconstruir: abra Compilado/Posto17-v125-COMPLETO.rbxl.
-- Este gerador cria scripts Luau, rigs, mapas via scripts e sequencias R6,
-- sem baixar assets externos nem depender de plugins.
-- NAO execute em servidores publicos. Execute apenas no Studio em uma cópia vazia.
local HttpService = game:GetService("HttpService")
local StarterPlayer = game:GetService("StarterPlayer")
local Workspace = game:GetService("Workspace")
local countScripts,countInstances = 0,0
local activeScripts={}
local failCount=0
local function warnSet(className,prop,msg)
    failCount+=1
    if failCount<18 then warn("[Posto17] Propriedade nao aplicada:",className,prop,msg) end
end
local function destination(path)
    local parent
    local first=true
    for piece in string.gmatch(path,"[^/]+") do
        if first then
            parent=game:GetService(piece)
            first=false
        else
            local nextObj=parent:FindFirstChild(piece)
            if not nextObj then
                nextObj=Instance.new("Folder")
                nextObj.Name=piece
                nextObj.Parent=parent
            end
            parent=nextObj
        end
    end
    return parent
end
local function enumValue(name,value)
    local mapping={
        Priority="AnimationPriority",RigType="HumanoidRigType",
        EasingStyle="PoseEasingStyle",EasingDirection="PoseEasingDirection",
        MeshType="MeshType",Face="NormalId",Material="Material",
        BackSurface="SurfaceType",BottomSurface="SurfaceType",
        FrontSurface="SurfaceType",LeftSurface="SurfaceType",
        RightSurface="SurfaceType",TopSurface="SurfaceType",
        Orientation="OrientationAlignmentMode",Shape="PartType",
        AutomaticSize="AutomaticSize",TextXAlignment="TextXAlignment",
        TextYAlignment="TextYAlignment",ScaleType="ScaleType",
        ZIndexBehavior="ZIndexBehavior",BorderMode="BorderMode",
        SizeConstraint="SizeConstraint",Font="Font",
    }
    local category=mapping[name]
    if not category then return nil end
    local enum=Enum[category]
    if not enum then return nil end
    for _,item in ipairs(enum:GetEnumItems()) do
        if item.Value==value then return item end
    end
    return nil
end
local function propertyValue(prop,kind,v)
    if kind=="CFrame" then
        return CFrame.new(table.unpack(v))
    elseif kind=="Vector3" then
        return Vector3.new(table.unpack(v))
    elseif kind=="Vector2" then
        return Vector2.new(table.unpack(v))
    elseif kind=="Color3" then
        return Color3.new(table.unpack(v))
    elseif kind=="UDim2" then
        return UDim2.new(table.unpack(v))
    elseif kind=="UDim" then
        return UDim.new(table.unpack(v))
    elseif kind=="NumberRange" then
        return NumberRange.new(table.unpack(v))
    elseif kind=="NumberSequence" then
        local points={}
        for _,k in ipairs(v) do
            table.insert(points,NumberSequenceKeypoint.new(k[1],k[2],k[3]))
        end
        return NumberSequence.new(points)
    elseif kind=="ColorSequence" then
        local points={}
        for _,k in ipairs(v) do
            table.insert(points,ColorSequenceKeypoint.new(k[1],Color3.new(k[2],k[3],k[4])))
        end
        return ColorSequence.new(points)
    elseif kind=="token" then
        return enumValue(prop,v) or v
    end
    return v
end
local function installAsset(group)
    local folder=destination(group.service)
    local instanceList={}
    local refList={}
    local delayed={}
    for i,item in ipairs(group.nodes) do
        local typ,parentIndex,referent,props=item[1],item[2],item[3],item[4]
        local success,obj=pcall(Instance.new,typ)
        if not success then
            warnSet(typ,"Instance.new",obj)
        else
            instanceList[i]=obj
            if referent then refList[referent]=obj end
            for _,prop in ipairs(props) do
                local key,kind,v=prop[1],prop[2],prop[3]
                if kind=="Ref" then
                    if v~="null" and v~="" then table.insert(delayed,{obj,key,v}) end
                elseif key=="Source" then
                    -- Assets from earlier Studio versions may omit embedded source.
                    -- The canonical .rbxl includes exact original serialized data.
                else
                    local result,value=pcall(propertyValue,key,kind,v)
                    if result then
                        local ok,err=pcall(function()obj[key]=value end)
                        if not ok and key~="AttributesSerialize" and key~="SourceAssetId" then
                            warnSet(typ,key,err)
                        end
                    end
                end
            end
            obj.Parent=parentIndex>0 and instanceList[parentIndex] or folder
            countInstances+=1
        end
    end
    for _,ref in ipairs(delayed) do
        local source,key,target=ref[1],ref[2],ref[3]
        local obj=refList[target]
        if obj then
            pcall(function()source[key]=obj end)
        end
    end
    print("[Posto17]",group.source,#group.nodes,"objetos")
end
local function installScript(item)
    local className=item.class
    local segments=string.split(item.studio,"/")
    local scriptName=segments[#segments]
    local parentPath=table.concat(segments,"/",1,#segments-1)
    local parent=destination(parentPath)
    local old=parent:FindFirstChild(scriptName)
    if old and old:IsA(className) then old:Destroy() end
    local object=Instance.new(className)
    object.Name=scriptName
    if object:IsA("BaseScript") then object.Disabled=true end
    local ok,err=pcall(function()object.Source=item.source end)
    if not ok then error("Sem permissao para atribuir Source em "..item.studio..": "..tostring(err)) end
    object.Parent=parent
    if object:IsA("BaseScript") then table.insert(activeScripts,object) end
    countScripts+=1
end
pcall(function()Workspace.StreamingEnabled=true end)
pcall(function()StarterPlayer.LoadCharacterAppearance=false end)
local sourceScripts=HttpService:JSONDecode([=[[{"studio":"ServerScriptService/Ambience","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/Ambience (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Geometria original, sem malhas/texturas baixadas; decoracoes nao bloqueiam IA.\nlocal Ambience = {}\nfunction Ambience.build(ctx)\n    local gray = Color3.fromRGB(53, 61, 64)\n    local rust = Color3.fromRGB(104, 46, 34)\n    local function deco(name, size, pos, color, material)\n        return ctx.decoration(name, size, pos, color or gray, material or Enum.Material.Metal)\n    end\n    -- Mesas, papeis, armarios de arquivo e equipamento nas novas salas.\n    for _, center in ipairs({Vector3.new(-43, 0, -43), Vector3.new(36, 0, -8), Vector3.new(34, 0, 29)}) do\n        deco(\"MesaIndustrial\", Vector3.new(5.5, 0.3, 3), center+Vector3.new(0, 0.9, 0))\n        for _, dx in ipairs({-2.2,2.2}) do\n            deco(\"PeMesa\", Vector3.new(0.3, 0.9, 2.2), center+Vector3.new(dx, 0.45, 0))\n        end\n        deco(\"ArquivoAco\", Vector3.new(2.5, 6, 2), center+Vector3.new(-5.8, 3, 0), gray)\n        for h=1,4 do\n            deco(\"Gaveta\", Vector3.new(2, 0.07, 0.12), center+Vector3.new(-5.8, h*1.25, -1.1), rust)\n        end\n    end\n    for _, x in ipairs({-51, 51}) do\n        for _, z in ipairs({-27, 3, 34}) do\n            local pipe = deco(\"Tubulacao\", Vector3.new(0.6, 8, 0.6), Vector3.new(x, 8, z))\n            pipe.Shape = Enum.PartType.Cylinder\n            pipe.Orientation = Vector3.new(0, 0, 90)\n            deco(\"Abracadeira\", Vector3.new(0.2, 1, 1), Vector3.new(x, 8, z), rust)\n        end\n    end\n    -- Personagens 3D sao criados pelo modulo GuardVisuals apos o cenario.\n    -- O corpo invisivel do guarda permanece como hitbox e sensor.\n    -- Fontes posicionais limitadas; mixagem pelo cliente, sem assets de terceiros.\n    local motor = deco(\"GeradorAmbiente\", Vector3.new(3, 3, 3), Vector3.new(9, 1.5, -43), gray)\n    local sound = Instance.new(\"Sound\")\n    sound.Name = \"MotorPosto17\"\n    sound.SoundId = \"rbxasset://sounds/action_swim.mp3\"\n    sound.PlaybackSpeed = 0.45\n    sound.Volume = 0.035\n    sound.RollOffMinDistance, sound.RollOffMaxDistance = 4, 23\n    sound.Looped = true\n    sound.Parent = motor\n    sound:Play()\n    ctx.world:SetAttribute(\"ArtBudget\", \"Geometria simples; sem particulas, assets externos ou Humanoids NPC\")\nend\nreturn Ambience\n"},{"studio":"ServerScriptService/AnimationRange","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/AnimationRange (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Range = {}\n\nfunction Range.build(ctx)\n    local origin = Vector3.new(185, 0, 0)\n    local function part(name, size, position, color, collides)\n        local item = ctx.part(name, size, origin + position, color, Enum.Material.Metal, collides)\n        item.Parent = ctx.parent\n        return item\n    end\n    local gray = Color3.fromRGB(87, 106, 112)\n    part(\"Parede\", Vector3.new(15, 7.2, 1.3), Vector3.new(-15, 3.6, 13), gray, true)\n    local low = part(\"Caixa\", Vector3.new(15, 3.48, 1.3), Vector3.new(4, 1.74, 13), gray, true)\n    local terminal = part(\"BancadaAnimacoes\", Vector3.new(3, 3.2, 1.4),\n        Vector3.new(8, 1.6, -6), gray, true)\n    local locker = part(\"ArmarioTeste\", Vector3.new(3, 5.4, 2.1), Vector3.new(15, 2.7, -6), gray, true)\n    local panel = part(\"PortaArmarioTeste\", Vector3.new(2.85, 5.15, 0.2),\n        Vector3.new(15, 2.7, -4.87), Color3.fromRGB(123, 143, 135), false)\n    local closed = panel.CFrame\n    local side = ctx.ducts.build(ctx.parent, \"DutoLateralTeste\", origin + Vector3.new(-18, 1.15, -18),\n        origin + Vector3.new(1, 1.15, -18), false)\n    local ceiling = ctx.ducts.build(ctx.parent, \"DutoTetoTeste\", origin + Vector3.new(7, 6.5, -18),\n        origin + Vector3.new(25, 6.5, -18), true)\n    local dummyBody = part(\"VigiaEnsaio\", Vector3.new(2.2, 5, 1.6), Vector3.new(15, 2.3, 6), gray, false)\n    dummyBody.CanQuery = false\n    local guard = {id = 1, body = dummyBody, eyes = {}, state = \"PATROL\", life = \"ACTIVE\"}\n    ctx.guardVisuals.attach({guard}, ctx.part, ctx.parent)\n    local door = part(\"PortaEnsaio\", Vector3.new(3.4, 5.3, 0.35),\n        Vector3.new(1.4, 2.65, -5.7), gray, true)\n    local doorClosed = door.CFrame\n    local cueRemote = ctx.remote(\"Posto17AnimationReview\")\n    local running = {}\n    local runService = game:GetService(\"RunService\")\n\n    local function review(player)\n        local char, hum, root = ctx.motion.rig(player)\n        if not root or root.Anchored or running[player]\n            or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Dragging\")\n            or player:GetAttribute(\"Posto17Stance\") == \"VENT\"\n            or player:GetAttribute(\"Posto17InTestRange\") ~= true\n            or (root.Position - ctx.spawn.Position).Magnitude > 75 then return end\n        running[player] = true\n        local function same()\n            return player.Parent and player.Character == char and hum.Health > 0\n                and player:GetAttribute(\"Posto17InTestRange\") == true\n        end\n        local function scene(label, originOffset, direction, seconds, movement, vent)\n            if not same() then return false end\n            if originOffset then\n                local point = origin + originOffset + Vector3.yAxis\n                    * ((hum:GetAttribute(\"P17BaseHip\") or hum.HipHeight) + root.Size.Y * 0.5)\n                local face = direction or Vector3.xAxis\n                root.CFrame = CFrame.lookAt(point, point + face)\n                root.AssemblyLinearVelocity = Vector3.zero\n            end\n            cueRemote:FireClient(player, label, seconds, movement, vent)\n            return true\n        end\n        local function pause(seconds)\n            task.wait(seconds)\n            return same()\n        end\n        local function run()\n            local x, z = Vector3.xAxis, Vector3.zAxis\n            local route = Vector3.new(-27, 0, -2)\n            ctx.mobility.clear(player)\n            ctx.posture(player, \"STAND\")\n            scene(\"CORRIDA\", route, x, 2.15, x)\n            ctx.mobility.sprint(player, true)\n            if not pause(1.3) then return end\n            ctx.mobility.sprint(player, false)\n            if not pause(0.8) then return end\n            scene(\"AGACHAR PARADO\", route, x, 1.65)\n            ctx.posture(player, \"CROUCH\")\n            if not pause(1.65) then return end\n            scene(\"ANDAR AGACHADO\", nil, nil, 3.9, x)\n            if not pause(3.9) then return end\n            scene(\"PARAR E LEVANTAR\", nil, nil, 1.5)\n            if not pause(0.65) then return end\n            ctx.posture(player, \"STAND\")\n            if not pause(0.85) then return end\n            scene(\"RASTEJAR E LEVANTAR\", route, x, 5.7, x)\n            ctx.posture(player, \"PRONE\")\n            if not pause(4.3) then return end\n            ctx.posture(player, \"STAND\")\n            if not pause(1.15) then return end\n\n            scene(\"COBERTURA ALTA / ALTERNAR\", Vector3.new(-17, 0, 10.3), x, 4.1)\n            if not pause(1.05) then return end\n            ctx.posture(player, \"CROUCH\")\n            if not pause(1.25) then return end\n            if not scene(\"COBERTURA ALTA / PASSOS\", nil, nil, 1.68, x) then return end\n            ctx.posture(player, \"STAND\")\n            if not pause(1.6) then return end\n            if not scene(\"SAIR DA COBERTURA\", nil, nil, 0.4) then return end\n            if not pause(0.35) then return end\n            ctx.mobility.cover(player)\n            scene(\"COBERTURA BAIXA / TENTAR LEVANTAR\", Vector3.new(1, 0, 10.9), -z, 3.7, x)\n            ctx.mobility.cover(player, low)\n            if not pause(1.3) then return end\n            ctx.posture(player, \"STAND\")\n            if not pause(1.35) then return end\n            ctx.mobility.cover(player)\n            ctx.posture(player, \"STAND\")\n            if not pause(0.45) then return end\n\n            scene(\"EQUIPAR CAIXA\", route, x, 3.25)\n            ctx.mobility.equipBox(player)\n            if not pause(1.7) then return end\n            ctx.mobility.equipBox(player)\n            ctx.posture(player, \"STAND\")\n            if not pause(1.3) then return end\n\n            scene(\"ENTRAR NO DUTO LATERAL\", Vector3.new(-21.4, 0, -18), x, 2, nil, side.group)\n            side.enter(player, 1)\n            if not same() or player:GetAttribute(\"Posto17Stance\") ~= \"VENT\" then return end\n            scene(\"ENGATINHAR NO DUTO\", nil, nil, 5.0, x, side.group)\n            if not pause(4.97) then return end\n            scene(\"SAIR DO DUTO\", nil, nil, 2.05, nil, side.group)\n            side.leave(player, 2)\n            if not same() or player:GetAttribute(\"Posto17Stance\") == \"VENT\" then return end\n\n            scene(\"ABRIR O DUTO DE TETO\", Vector3.new(3.6, 0, -18), x, 2.55, nil, ceiling.group)\n            ceiling.enter(player, 1)\n            if not same() or player:GetAttribute(\"Posto17Stance\") ~= \"VENT\" then return end\n            scene(\"ENGATINHAR NO DUTO DE TETO\", nil, nil, 4.8, x, ceiling.group)\n            if not pause(4.78) then return end\n            scene(\"DESCER DO DUTO\", nil, nil, 2.1, nil, ceiling.group)\n            ceiling.leave(player, 2)\n            if not same() or player:GetAttribute(\"Posto17Stance\") == \"VENT\" then return end\n\n            for _, cue in ipairs({\n                {\"LOCK\", \"LOCKPICK\", 1.5}, {\"BUTTON\", \"BOTAO\", 0.58},\n                {\"TERMINAL\", \"TERMINAL\", 1.65}, {\"DOOR\", \"ABRIR PORTA\", 0.72},\n                {\"LOCKER\", \"DESLIZAR PORTA DO ARMARIO\", 0.93},\n            }) do\n                local isLocker = cue[1] == \"LOCKER\"\n                local isDoor = cue[1] == \"DOOR\"\n                local point = isLocker and locker.Position or isDoor and door.Position or terminal.Position\n                local distance = isLocker and 2.1 or 1.8\n                scene(cue[2], Vector3.new(point.X-origin.X, 0, point.Z + distance),\n                    -z, cue[3] + 0.65)\n                ctx.motion.play(player, cue[1], cue[3], point)\n                if isDoor then\n                    task.delay(0.21, function()\n                        ctx.tween:Create(door, TweenInfo.new(0.49), {CFrame = doorClosed * CFrame.new(0, 5.4, 0)}):Play()\n                    end)\n                end\n                if isLocker then\n                    ctx.tween:Create(panel, TweenInfo.new(0.45), {CFrame = closed * CFrame.new(2.8, 0, 0)}):Play()\n                end\n                if not pause(cue[3] + 0.5) then return end\n            end\n            panel.CFrame, door.CFrame = closed, doorClosed\n\n            scene(\"VIGIA / PATRULHA\", Vector3.new(9, 0, 5), x, 3.2)\n            local patrolAt = os.clock()\n            while same() and os.clock() - patrolAt < 2.8 do\n                local t = os.clock() - patrolAt\n                local pos = origin + Vector3.new(13 + t * 2.3, 2.29, 6)\n                dummyBody.CFrame = CFrame.lookAt(pos, pos + x)\n                guard.lastMoveAt = os.clock()\n                ctx.guardVisuals.animate(guard, os.clock())\n                task.wait(0.045)\n            end\n            for _, cue in ipairs({{\"STEAL\", \"PICKPOCKET\", 1.55}, {\"KO\", \"NEUTRALIZAR\", 1.05},\n                {\"KILL\", \"TAKEDOWN LETAL\", 1.3}}) do\n                if not same() then return end\n                local point = origin + Vector3.new(15.0, 2.29, 6)\n                dummyBody.CFrame = CFrame.lookAt(point, point + x)\n                ctx.guardVisuals.animate(guard, os.clock())\n                scene(cue[2], Vector3.new(12.7, 0, 6), x, cue[3] + 1.1)\n                ctx.motion.play(player, cue[1], cue[3], dummyBody.Position)\n                guard.reaction = cue[1] ~= \"STEAL\" and os.clock() or nil\n                local started = os.clock()\n                while same() and os.clock() - started < cue[3] + 0.9 do\n                    local elapsed = os.clock() - started\n                    if guard.reaction and elapsed > cue[3] * 0.65 then\n                        local alpha = math.clamp((elapsed - cue[3] * 0.65) / 0.38, 0, 1)\n                        dummyBody.CFrame = CFrame.lookAt(point, point + x):Lerp(\n                            CFrame.lookAt(point, point + x) * CFrame.new(0, -1.74, -0.6)\n                            * CFrame.Angles(math.pi / 2, 0, 0), alpha)\n                    end\n                    ctx.guardVisuals.animate(guard, os.clock())\n                    runService.Heartbeat:Wait()\n                end\n                guard.reaction = nil\n            end\n            scene(\"ENSAIO CONCLUIDO\", nil, nil, 1.7)\n        end\n        local ok, result = pcall(run)\n        guard.reaction = nil\n        running[player] = nil\n        if player.Parent then cueRemote:FireClient(player, \"FIM\", 0) end\n        if not ok then warn(\"[P17 ENSAIO]\", result) end\n    end\n    cueRemote.OnServerEvent:Connect(review)\nend\n\nreturn Range\n"},{"studio":"ServerScriptService/Ducts","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/Ducts (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Rotas retas no interior de dutos elevados. O servidor controla as entradas,\n-- as saidas e o estado de postura. Dentro do duto, o jogador anda normalmente.\nlocal Ducts = {}\nlocal metal = Color3.fromRGB(95, 106, 110)\nlocal trim = Color3.fromRGB(53, 65, 69)\n\nfunction Ducts.new(ctx)\n    local inside = {}\n    local entering = {}\n    local api = {}\n    local accumulator = 0\n    game:GetService(\"RunService\").Heartbeat:Connect(function(dt)\n        accumulator += dt\n        if accumulator < 0.5 then return end\n        accumulator = 0\n        for player, route in pairs(inside) do\n            local _, _, root = ctx.motion.rig(player)\n            if root and (root.Position - route.center).Magnitude <= route.radius then continue end\n            inside[player] = nil\n            ctx.posture(player, \"STAND\", true)\n        end\n    end)\n\n    local function clear(player)\n        inside[player], entering[player] = nil, nil\n    end\n    local function watch(player) player.CharacterRemoving:Connect(function() clear(player) end) end\n    for _, player in ipairs(ctx.players:GetPlayers()) do watch(player) end\n    ctx.players.PlayerAdded:Connect(watch)\n    ctx.players.PlayerRemoving:Connect(clear)\n\n    function api.build(parent, name, a, b, isCeiling)\n        local axis = (b - a).Unit\n        local length = (b - a).Magnitude\n        local frame = CFrame.lookAt((a + b) / 2, b)\n        local group = Instance.new(\"Model\")\n        group.Name = name\n        group.Parent = parent\n        local function block(label, size, offset, color, collides)\n            local item = ctx.part(label, size, (frame * CFrame.new(offset)).Position, color,\n                Enum.Material.Metal, collides)\n            item.CFrame = frame * CFrame.new(offset)\n            item.Parent = group\n            return item\n        end\n        local height, halfWidth = 4.8, 2.65\n        block(\"PisoDuto\", Vector3.new(5.7, 0.30, length), Vector3.new(0, -0.15, 0), trim, true)\n        local roof = block(\"TetoDuto\", Vector3.new(5.7, 0.28, length),\n            Vector3.new(0, height, 0), metal, true)\n        for _, side in ipairs({-1, 1}) do\n            block(\"LateralDuto\", Vector3.new(0.27, height, length),\n                Vector3.new(side * halfWidth, height/2, 0), metal, true)\n        end\n        local cabinLight = Instance.new(\"PointLight\")\n        cabinLight.Color, cabinLight.Range, cabinLight.Brightness = Color3.fromRGB(112, 193, 206), 14, 0.6\n        cabinLight.Parent = roof\n\n        local duct = {group = group, center = (a+b)/2, radius = length/2 + 6}\n        local ends = {{mouth = a, inward = axis}, {mouth = b, inward = -axis}}\n\n        local function heightOf(hum, root)\n            return math.max(2, (hum:GetAttribute(\"P17BaseHip\") or hum.HipHeight) + root.Size.Y * 0.5)\n        end\n        local function access(player, endpoint, leaving)\n            local character, hum, root = ctx.motion.rig(player)\n            if not root or root.Anchored or entering[player] or player:GetAttribute(\"Posto17Hidden\")\n                or player:GetAttribute(\"Posto17Dragging\") or player:GetAttribute(\"Posto17Won\")\n                or player:GetAttribute(\"Posto17Box\") then return end\n            if leaving and inside[player] ~= duct or not leaving and inside[player] then return end\n            local zone = leaving and endpoint.mouth or endpoint.ground\n            if (root.Position - zone).Magnitude > (leaving and 6.7 or 7.0) then return end\n            -- O personagem principal agora usa R6; ambos os rigs podem entrar.\n\n            entering[player] = true\n            ctx.clear(player)\n            local upright = heightOf(hum, root)\n            local crawlHeight = upright - ctx.drop(\"VENT\", hum:GetAttribute(\"P17BaseHip\") or hum.HipHeight, hum.RigType == Enum.HumanoidRigType.R15)\n            local floorHeight = Vector3.yAxis * crawlHeight\n            local walkPoint = endpoint.ground + Vector3.yAxis * upright\n            local mouthPoint = endpoint.mouth + endpoint.inward * 2.05 + floorHeight\n            local dir = endpoint.inward\n            local pre = leaving and mouthPoint or walkPoint\n            local face = leaving and -dir or dir\n            root.Anchored = true\n            root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero\n            local align = ctx.tween:Create(root, TweenInfo.new(0.29, Enum.EasingStyle.Sine),\n                {CFrame = CFrame.lookAt(pre, pre + face)})\n            align:Play()\n            align.Completed:Wait()\n\n            if player.Character ~= character or hum.Health <= 0 or not entering[player] then\n                if root.Parent then root.Anchored = false end\n                clear(player)\n                return\n            end\n            local isClimb = isCeiling and not leaving\n            ctx.motion.play(player, leaving and \"VENT_UP\" or (isClimb and \"VENT_UP\" or \"VENT_OPEN\"),\n                isClimb and 1.6 or 1.16)\n            if not leaving and endpoint.hatch.CanQuery then\n                endpoint.hatch.CanCollide, endpoint.hatch.CanQuery = false, false\n                ctx.tween:Create(endpoint.hatch, TweenInfo.new(0.42, Enum.EasingStyle.Sine),\n                    {CFrame = endpoint.hatch.CFrame * CFrame.new(0, height + 0.6, 0)}):Play()\n                for _, bar in ipairs(endpoint.bars) do bar.Transparency = 1 end\n            end\n            task.wait(0.23)\n            if isClimb then\n                local grip = endpoint.mouth - dir * 0.70 + Vector3.yAxis * (crawlHeight - 0.8)\n                local pull = ctx.tween:Create(root, TweenInfo.new(0.51, Enum.EasingStyle.Sine,\n                    Enum.EasingDirection.InOut), {CFrame = CFrame.lookAt(grip, grip + dir)})\n                pull:Play()\n                pull.Completed:Wait()\n            end\n            if player.Character ~= character or hum.Health <= 0 or not entering[player] then\n                if root.Parent then root.Anchored = false end\n                clear(player)\n                return\n            end\n            ctx.posture(player, \"VENT\", true)\n            local between = leaving and walkPoint or mouthPoint\n            local slide = ctx.tween:Create(root, TweenInfo.new(0.70, Enum.EasingStyle.Sine),\n                {CFrame = CFrame.lookAt(between, between + face)})\n            slide:Play()\n            slide.Completed:Wait()\n            if root.Parent then root.Anchored = false end\n            if player.Character ~= character or hum.Health <= 0 then clear(player); return end\n            entering[player] = nil\n            inside[player] = not leaving and duct or nil\n            if leaving then ctx.posture(player, \"STAND\", true) end\n        end\n\n        for _, endpoint in ipairs(ends) do\n            local worldY = a.Y\n            local groundY = worldY - (isCeiling and 6.5 or 1.15)\n            local mouth = endpoint.mouth\n            local dir = endpoint.inward\n            local at = mouth - dir * 3.4\n            endpoint.ground = Vector3.new(at.X, groundY, at.Z)\n            local hatch = block(\"GradeDuto\", Vector3.new(5.2, height - 0.24, 0.18),\n                frame:PointToObjectSpace(mouth + Vector3.yAxis * (height/2)), trim, true)\n            endpoint.hatch, endpoint.bars = hatch, {}\n            local barrier = block(\"LimiteDuto\", Vector3.new(5.2, height - 0.15, 0.2),\n                frame:PointToObjectSpace(mouth + Vector3.yAxis * height/2), trim, true)\n            barrier.Transparency, barrier.CanTouch = 1, false\n            for _, y in ipairs({0.65, 1.4, 2.15, 2.9, 3.65, 4.4}) do\n                local slat = block(\"TravessaGrade\", Vector3.new(4.7, 0.13, 0.21),\n                    frame:PointToObjectSpace(mouth + Vector3.yAxis * y), metal, false)\n                slat.CanQuery, slat.CanTouch = false, false\n                table.insert(endpoint.bars, slat)\n            end\n            local marker = block(\"AcessoDuto\", Vector3.one * 0.35,\n                frame:PointToObjectSpace(endpoint.ground + Vector3.yAxis * (isCeiling and 3.3 or 1.6)), metal, false)\n            marker.Transparency, marker.CanQuery = 1, false\n            local function prompt(parentPart, text, maxDistance, leaving)\n                local p = Instance.new(\"ProximityPrompt\")\n                p.ActionText = text\n                p.ObjectText = isCeiling and \"Duto de teto\" or \"Duto lateral\"\n                p.HoldDuration, p.MaxActivationDistance, p.RequiresLineOfSight = 0.28, maxDistance, false\n                p.Parent = parentPart\n                p.Triggered:Connect(function(player) access(player, endpoint, leaving) end)\n            end\n            prompt(marker, \"Abrir e entrar\", 5.1, false)\n            local exit = Instance.new(\"Attachment\")\n            local floor = group:FindFirstChild(\"PisoDuto\")\n            exit.Position = floor.CFrame:PointToObjectSpace(mouth + dir * 1.3 + Vector3.yAxis * 2)\n            exit.Parent = floor\n            prompt(exit, \"Sair do duto\", 3.4, true)\n        end\n        function duct.enter(player, side) access(player, ends[side or 1], false) end\n        function duct.leave(player, side) access(player, ends[side or 2], true) end\n        return duct\n    end\n\n    return api\nend\n\nreturn Ducts\n"},{"studio":"ServerScriptService/Facilities","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/Facilities (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Salas opcionais e acesso: codigo, cartao e alternativa por lockpick.\nlocal Rules = require(game:GetService(\"ReplicatedStorage\").Posto17Shared.Rules)\nlocal Facilities = {}\nfunction Facilities.new(ctx)\n    local self = {doors = {}, sessions = {}, attempts = {}, codeFailures = {}}\n    local event = ctx.remote(\"Posto17Access\")\n    local code = tostring(Random.new():NextInteger(1000, 9999))\n    local radio = ctx.part(\"CentralRadio\", Vector3.new(3, 4, 2), Vector3.new(36, 2, -7),\n        Color3.fromRGB(62, 77, 68), Enum.Material.Metal)\n    local led = ctx.part(\"LedRadio\", Vector3.new(1.8, 0.2, 0.15), radio.Position + Vector3.new(0, 1.1, -1.1),\n        Color3.fromRGB(95, 195, 139), Enum.Material.Neon, false)\n    led.CanQuery = false\n    ctx.world:SetAttribute(\"RadioOnline\", true)\n    ctx.world:SetAttribute(\"Reinforcements\", 0)\n    local function prompt(body, name, action, hold)\n        local p = Instance.new(\"ProximityPrompt\")\n        p.Name, p.ActionText, p.ObjectText = name, action, name\n        p.HoldDuration, p.MaxActivationDistance = hold, 7\n        p.RequiresLineOfSight = true\n        p.Parent = body\n        return p\n    end\n    local radioPrompt = prompt(radio, \"SabotarRadio\", \"Sabotar radio\", 2)\n    local holding = {}\n    radioPrompt.PromptButtonHoldBegan:Connect(function(player) holding[player] = os.clock() end)\n    radioPrompt.PromptButtonHoldEnded:Connect(function(player)\n        -- O Triggered pode chegar no mesmo ciclo que HoldEnded.\n        local started = holding[player]\n        task.delay(0.2, function() if holding[player] == started then holding[player] = nil end end)\n    end)\n    local ray = RaycastParams.new()\n    ray.FilterType = Enum.RaycastFilterType.Exclude\n    ray.RespectCanCollide = true\n    local function canUse(player, body)\n        local char = player.Character\n        local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n        if not root or not ctx.near(player, body.Position, 9)\n            or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Won\") then return false end\n        ray.FilterDescendantsInstances = {char, body}\n        return workspace:Raycast(root.Position, body.Position-root.Position, ray) == nil\n    end\n    radioPrompt.Triggered:Connect(function(player)\n        if not holding[player] or os.clock()-holding[player] < 1.9 or not canUse(player, radio) then return end\n        holding[player] = nil\n        ctx.world:SetAttribute(\"RadioOnline\", false)\n        radioPrompt.Enabled = false\n        led.Color = Color3.fromRGB(157, 43, 37)\n        ctx.cancelRadio()\n        ctx.world:SetAttribute(\"Reinforcements\", 0)\n        ctx.sound(radio, \"rbxasset://sounds/electronicpingshort.wav\", 0.3, 0.7)\n        ctx.state:FireClient(player, \"OPERACAO\", \"Radio sabotado. Reforcos e relatos remotos bloqueados.\")\n    end)\n    -- Salas inteiras possuem parede e entrada, sem bloquear as patrulhas originais.\n    local function registerDoor(id, name, body, method)\n        body:SetAttribute(\"AccessId\", id)\n        body:SetAttribute(\"AccessMethod\", method)\n        body:SetAttribute(\"Open\", false)\n        body:SetAttribute(\"RoomName\", name)\n        local panel = ctx.part(\"PainelAcesso_\" .. id, Vector3.new(0.8, 1.2, 0.4),\n            body.Position + Vector3.new(3.4, -0.5, 0.8), Color3.fromRGB(153, 125, 61), Enum.Material.Metal, false)\n        panel.CanQuery = false\n        local p = prompt(body, \"Acesso\", \"Abrir acesso\", 0)\n        local door = {id = id, body = body, panel = panel, prompt = p, closed = body.CFrame, method = method}\n        self.doors[id] = door\n        p.Triggered:Connect(function(player)\n            if canUse(player, body) and not body:GetAttribute(\"Open\") then\n                event:FireClient(player, \"MENU\", id, method, name)\n            end\n        end)\n        return door\n    end\n    local function room(id, name, center, width, depth, method)\n        local x, z = center.X, center.Z\n        local color = Color3.fromRGB(68, 76, 79)\n        ctx.part(\"Parede\", Vector3.new(width, 8, 1), Vector3.new(x, 4, z-depth/2), color)\n        for _, side in ipairs({-1, 1}) do\n            ctx.part(\"Parede\", Vector3.new(1, 8, depth), Vector3.new(x+side*width/2, 4, z), color)\n            ctx.part(\"Parede\", Vector3.new((width-6)/2, 8, 1),\n                Vector3.new(x+side*(width+6)/4, 4, z+depth/2), color)\n        end\n        local body = ctx.part(\"PortaAcesso_\" .. id, Vector3.new(6, 7.8, 0.7),\n            Vector3.new(x, 3.9, z+depth/2), Color3.fromRGB(88, 34, 32), Enum.Material.Metal)\n        return registerDoor(id, name, body, method)\n    end\n    room(1, \"Arquivo de manutencao\", Vector3.new(-43, 0, -40), 18, 14, \"LOCKPICK\")\n    room(2, \"Comunicacoes\", Vector3.new(34, 0, -5), 18, 18, \"CARD\")\n    room(3, \"Arquivo reservado\", Vector3.new(34, 0, 32), 18, 18, \"CODE\")\n    local shortcut = ctx.part(\"PortaAcesso_4\", Vector3.new(0.7, 8, 8),\n        Vector3.new(-12, 4, -20), Color3.fromRGB(88, 34, 32), Enum.Material.Metal)\n    registerDoor(4, \"Passagem tecnica\", shortcut, \"CARD\")\n    -- Nota fora das salas: codigo descoberto no mundo, aleatorio por operacao.\n    local note = ctx.part(\"NotaCodigo\", Vector3.new(1.8, 0.2, 1.4), Vector3.new(5, 2.15, 25),\n        Color3.fromRGB(197, 191, 166), Enum.Material.SmoothPlastic, false)\n    note.CanQuery = false\n    prompt(note, \"LerNota\", \"Ler documento\", 0).Triggered:Connect(function(player)\n        if not canUse(player, note) then return end\n        player:SetAttribute(\"Posto17DoorCode\", code)\n        ctx.state:FireClient(player, \"OPERACAO\", \"Arquivo reservado: codigo \" .. code .. \". Registrado no painel de acesso.\")\n    end)\n    local card = ctx.part(\"CartaoReserva\", Vector3.new(1.4, 0.15, 0.8), Vector3.new(-43, 1.2, -41),\n        Color3.fromRGB(169, 170, 145), Enum.Material.SmoothPlastic, false)\n    card.CanQuery = false\n    prompt(card, \"ObterCartao\", \"Pegar cartao\", 0).Triggered:Connect(function(player)\n        if canUse(player, card) and not player:GetAttribute(\"Posto17Keycard\") then\n            player:SetAttribute(\"Posto17Keycard\", true)\n            ctx.state:FireClient(player, \"OPERACAO\", \"Cartao de manutencao obtido. Acesso as comunicacoes.\")\n        end\n    end)\n    local dossier = ctx.part(\"DocumentoReservado\", Vector3.new(2, 0.3, 1.5), Vector3.new(34, 1.3, 29),\n        Color3.fromRGB(157, 143, 99), Enum.Material.SmoothPlastic, false)\n    dossier.CanQuery = false\n    prompt(dossier, \"DocumentoReservado\", \"Ler documento\", 0).Triggered:Connect(function(player)\n        if not canUse(player, dossier) or player:GetAttribute(\"Posto17SecretIntel\") then return end\n        player:SetAttribute(\"Posto17SecretIntel\", true)\n        ctx.state:FireClient(player, \"OPERACAO\", \"Relatorio reservado recuperado. Bonus de inteligencia na extracao.\")\n    end)\n    local function open(door, player)\n        if door.body:GetAttribute(\"Open\") then return end\n        ctx.motion.play(player, \"DOOR\", 0.62, door.body.Position)\n        door.body:SetAttribute(\"Open\", true)\n        door.body.CanCollide = false\n        door.prompt.Enabled = false\n        ctx.tween:Create(door.body, TweenInfo.new(0.6), {CFrame = door.closed * CFrame.new(0, 8.5, 0)}):Play()\n        ctx.sound(door.body, \"rbxasset://sounds/action_get_up.mp3\", 0.25, 0.65)\n    end\n    event.OnServerEvent:Connect(function(player, action, id, value)\n        if action == \"CANCEL\" then self.sessions[player] = nil; ctx.motion.cancel(player, \"LOCK\"); return end\n        if type(id) ~= \"number\" or id % 1 ~= 0 then return end\n        local door = self.doors[id]\n        if not door or door.body:GetAttribute(\"Open\") or not canUse(player, door.body) then\n            self.sessions[player] = nil\n            return\n        end\n        local now = os.clock()\n        if now - (self.attempts[player] or -100) < 0.25 then return end\n        self.attempts[player] = now\n        if action == \"CARD\" and door.method == \"CARD\" then\n            if player:GetAttribute(\"Posto17Keycard\") then open(door, player)\n            else event:FireClient(player, \"STATUS\", id, \"Encontre ou furte um cartao. Lockpick tambem abre.\") end\n        elseif action == \"CODE\" and door.method == \"CODE\" then\n            local failures = self.codeFailures[player]\n            if failures and failures.door == id and now < failures.lockUntil then\n                event:FireClient(player, \"STATUS\", id,\n                    \"Painel bloqueado: aguarde \" .. math.ceil(failures.lockUntil-now) .. \" s.\")\n                return\n            end\n            if Rules.validCode(value) and value == code then\n                self.codeFailures[player] = nil\n                open(door, player)\n            else\n                if not failures or failures.door ~= id then\n                    failures = {door = id, strikes = 0, lockUntil = 0}\n                end\n                failures.strikes += 1\n                if failures.strikes >= Rules.CODE_MAX_FAILURES then\n                    failures.strikes = 0\n                    failures.lockUntil = now + Rules.CODE_LOCK_SECONDS\n                    ctx.noise(door.body.Position, now, 14)\n                    ctx.sound(door.body, \"rbxasset://sounds/electronicpingshort.wav\", 0.25, 0.7)\n                    event:FireClient(player, \"STATUS\", id,\n                        \"Muitas tentativas. Painel bloqueado e ruido registrado.\")\n                else\n                    event:FireClient(player, \"STATUS\", id,\n                        \"Codigo incorreto. \" .. (Rules.CODE_MAX_FAILURES-failures.strikes)\n                        .. \" tentativa(s) restantes antes do bloqueio.\")\n                end\n                self.codeFailures[player] = failures\n            end\n        elseif action == \"PICK\" then\n            ctx.motion.play(player, \"LOCK\", 1.45, door.body.Position)\n            self.sessions[player] = {door = door, step = 0, phase = Random.new():NextInteger(1, 3), at = now, deadline = now+8}\n            event:FireClient(player, \"PIN\", id, self.sessions[player].phase, 1)\n        elseif action == \"PIN\" then\n            local s = self.sessions[player]\n            if not s or s.door ~= door then return end\n            if now > s.deadline or now-s.at < 0.65 or not Rules.lockpick(s.phase, value) then\n                self.sessions[player] = nil\n                ctx.noise(door.body.Position, now, 14)\n                event:FireClient(player, \"FAIL\", id, \"Pino falhou. O ruido pode atrair vigias.\")\n                return\n            end\n            s.step += 1\n            if s.step == 3 then\n                self.sessions[player] = nil\n                open(door, player)\n                event:FireClient(player, \"OPEN\", id)\n            else\n                ctx.motion.play(player, \"LOCK\", 1.3, door.body.Position)\n                s.at, s.deadline, s.phase = now, now+8, Random.new():NextInteger(1, 3)\n                event:FireClient(player, \"PIN\", id, s.phase, s.step+1)\n            end\n        end\n    end)\n    function self:observe(guard, now)\n        if guard.state == \"CHASE\" or guard.state == \"WATCH\" then return end\n        guard.doorsSeen = guard.doorsSeen or {}\n        for _, door in ipairs(self.doors) do\n            if door.body:GetAttribute(\"Open\") and not guard.doorsSeen[door.id] then\n                local point = door.closed.Position\n                local delta = point-guard.body.Position\n                local flat = Vector3.new(delta.X, 0, delta.Z)\n                ray.FilterDescendantsInstances = {guard.body, door.body}\n                if flat.Magnitude > 0.1 and flat.Magnitude < 18\n                    and guard.forward:Dot(flat.Unit) > 0.5\n                    and not workspace:Raycast(guard.body.Position, delta, ray) then\n                    guard.doorsSeen[door.id] = true\n                    ctx.inspect(guard, point, now)\n                    return\n                end\n            end\n        end\n    end\n    function self:tick(now)\n        for player, session in pairs(self.sessions) do\n            if now > session.deadline or not canUse(player, session.door.body) then\n                self.sessions[player] = nil\n                event:FireClient(player, \"FAIL\", session.door.id, \"Acesso interrompido.\")\n            end\n        end\n    end\n    function self:reset()\n        table.clear(self.sessions)\n        table.clear(self.attempts)\n        table.clear(self.codeFailures)\n        code = tostring(Random.new():NextInteger(1000, 9999))\n        ctx.world:SetAttribute(\"RadioOnline\", true)\n        ctx.world:SetAttribute(\"Reinforcements\", 0)\n        led.Color = Color3.fromRGB(95, 195, 139)\n        radioPrompt.Enabled = true\n        for _, door in ipairs(self.doors) do\n            door.body.CFrame = door.closed\n            door.body.CanCollide = true\n            door.body:SetAttribute(\"Open\", false)\n            door.prompt.Enabled = true\n        end\n        for _, player in ipairs(ctx.players:GetPlayers()) do\n            player:SetAttribute(\"Posto17DoorCode\", nil)\n            player:SetAttribute(\"Posto17Keycard\", false)\n            player:SetAttribute(\"Posto17SecretIntel\", false)\n        end\n    end\n    function self:cleanup(player)\n        self.sessions[player], self.attempts[player], holding[player] = nil, nil, nil\n        self.codeFailures[player] = nil\n    end\n    return self\nend\nreturn Facilities\n"},{"studio":"ServerScriptService/Flashlight","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/Flashlight (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Flashlight = {}\nfunction Flashlight.new(ctx)\n    local event = ctx.remote(\"Posto17Flashlight\")\n    local last = {}\n    event.OnServerEvent:Connect(function(player, enabled)\n        if type(enabled) ~= \"boolean\" or os.clock()-(last[player] or -100) < 0.2 then return end\n        last[player] = os.clock()\n        local head = player.Character and player.Character:FindFirstChild(\"Head\")\n        local hum = player.Character and player.Character:FindFirstChildOfClass(\"Humanoid\")\n        if not head or not hum or hum.Health <= 0 or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Won\") then return end\n        local light = head:FindFirstChild(\"P17Lanterna\")\n        if not light then\n            light = Instance.new(\"SpotLight\")\n            light.Name, light.Range, light.Angle, light.Brightness = \"P17Lanterna\", 25, 42, 1.4\n            light.Face = Enum.NormalId.Front\n            light.Color = Color3.fromRGB(226,223,193)\n            light.Parent = head\n        end\n        light.Enabled = enabled\n        player:SetAttribute(\"Posto17Flashlight\", enabled)\n    end)\n    local function watch(player)\n        player.CharacterAdded:Connect(function() player:SetAttribute(\"Posto17Flashlight\", false) end)\n        for _, key in ipairs({\"Posto17Hidden\", \"Posto17Won\"}) do\n            player:GetAttributeChangedSignal(key):Connect(function()\n                if player:GetAttribute(key) then\n                    local head = player.Character and player.Character:FindFirstChild(\"Head\")\n                    local light = head and head:FindFirstChild(\"P17Lanterna\")\n                    if light then light.Enabled = false end\n                    player:SetAttribute(\"Posto17Flashlight\", false)\n                end\n            end)\n        end\n    end\n    for _, p in ipairs(ctx.players:GetPlayers()) do watch(p) end\n    ctx.players.PlayerAdded:Connect(watch)\n    ctx.players.PlayerRemoving:Connect(function(p) last[p] = nil end)\nend\nreturn Flashlight\n"},{"studio":"ServerScriptService/GuardOperations","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/GuardOperations (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Neutralizacao e corpos. Nenhum cliente escolhe vida, posicao ou duracao.\nlocal Rules = require(game:GetService(\"ReplicatedStorage\").Posto17Shared.Rules)\nlocal Ops = {}\nfunction Ops.new(ctx)\n    local self = {sessions = {}, dragging = {}, cooldown = {}}\n    local event = ctx.remote(\"Posto17Action\")\n    local guards, lockers = ctx.guards, ctx.lockers\n    local ray = RaycastParams.new()\n    ray.FilterType = Enum.RaycastFilterType.Exclude\n    ray.RespectCanCollide = true\n    local function rootOf(player)\n        local char = player.Character\n        local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n        local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n        if hum and hum.Health > 0 then return root, hum end\n        return nil, nil\n    end\n    local function clear(player, body)\n        local root = rootOf(player)\n        if not root then return false end\n        ray.FilterDescendantsInstances = {player.Character, body}\n        return not workspace:Raycast(root.Position, body.Position - root.Position, ray)\n    end\n    local function cancelRescue(observer)\n        if observer.rescueTarget then\n            observer.rescueTarget = nil\n            observer.rescueAt = nil\n            observer.body:SetAttribute(\"RescuingGuard\", nil)\n        end\n    end\n    local function setLife(guard, life)\n        if life == \"ACTIVE\" then\n            if ctx.stopRagdoll then ctx.stopRagdoll(guard) end\n            guard.shotHealth, guard.settledRagdoll = 100, nil\n            for _, bone in ipairs(guard.visualBones or {}) do bone.offset = bone.base end\n        end\n        if life ~= \"ACTIVE\" then cancelRescue(guard) end\n        guard.life = life\n        guard.body:SetAttribute(\"LifeState\", life)\n        guard.body:SetAttribute(\"AIState\", life == \"ACTIVE\" and guard.state or life)\n        guard.body.CanCollide = life == \"ACTIVE\"\n        guard.light.Enabled = life == \"ACTIVE\"\n        guard.awarenessGui.Enabled = false\n        if life ~= \"ACTIVE\" then\n            ctx.clearNavigation(guard)\n            guard.supportDue = nil\n            guard.targetPlayer = nil\n            guard.suspicion = 0\n            guard.radioDue = nil\n            guard.body:SetAttribute(\"CallingRadio\", false)\n        end\n    end\n    local function pose(guard)\n        if guard.ragdoll then return end\n        for _, eye in ipairs(guard.eyes) do\n            eye.part.CFrame = guard.body.CFrame * eye.offset\n        end\n    end\n    local groundRay = RaycastParams.new()\n    groundRay.FilterType = Enum.RaycastFilterType.Exclude\n    groundRay.RespectCanCollide = true\n    local function corpsePosition(guard, point)\n        local excluded = {guard.body}\n        for _, other in ipairs(guards) do table.insert(excluded, other.body) end\n        for _, player in ipairs(ctx.players:GetPlayers()) do\n            if player.Character then table.insert(excluded, player.Character) end\n        end\n        groundRay.FilterDescendantsInstances = excluded\n        local floor = workspace:Raycast(point + Vector3.new(0, 6, 0), Vector3.new(0, -30, 0), groundRay)\n        return Vector3.new(point.X, (floor and floor.Position.Y or 0) + 1.65, point.Z)\n    end\n    local function shown(guard, visible)\n        guard.body.Transparency = (visible and not guard.visualBones) and 0 or 1\n        for _, eye in ipairs(guard.eyes) do eye.part.Transparency = visible and 0 or 1 end\n        if guard.uniform then\n            for _, piece in ipairs(guard.uniform) do piece.part.Transparency = visible and 0 or 1 end\n        end\n    end\n    local function restoreSpeed(player)\n        local _, hum = rootOf(player)\n        if hum then\n            hum.WalkSpeed = player:GetAttribute(\"Posto17Prone\") and 4\n                or (player:GetAttribute(\"Posto17Crouched\") and 8 or 16)\n        end\n    end\n    function self:drop(player)\n        local guard = self.dragging[player]\n        if guard then\n            guard.carrier = nil\n            guard.body:SetAttribute(\"Carried\", false)\n            guard.body:SetAttribute(\"CarrierId\", nil)\n        end\n        self.dragging[player] = nil\n        player:SetAttribute(\"Posto17Dragging\", false)\n        restoreSpeed(player)\n    end\n    local function emptyLocker(locker)\n        if locker.occupant then return false end\n        for _, player in ipairs(ctx.players:GetPlayers()) do\n            local info = ctx.hiddenState[player]\n            if info and info.locker == locker then return false end\n        end\n        return true\n    end\n    local function behind(player, guard)\n        local root = rootOf(player)\n        if not root or guard.carrier or guard.locker then return false end\n        local delta = root.Position - guard.body.Position\n        local flat = Vector3.new(delta.X, 0, delta.Z)\n        local dot = flat.Magnitude > 0.01 and guard.forward:Dot(flat.Unit) or 1\n        return Rules.behind(dot, delta.Magnitude, clear(player, guard.body), guard.life)\n    end\n    local function actionBody(action, target)\n        return action == \"RELEASE\" and target.locker and target.locker.body or target.body\n    end\n    local function eligible(player, action, target)\n        local root = rootOf(player)\n        if not root or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Won\") then return false end\n        if action == \"DROP\" then return self.dragging[player] ~= nil end\n        if action == \"STOW\" then\n            return target and target.body and target.prompt and emptyLocker(target)\n                and self.dragging[player] ~= nil\n        end\n        if not target or not target.life then return false end\n        if action == \"KO\" or action == \"KILL\" or action == \"STEAL\" then\n            return not self.dragging[player] and behind(player, target)\n                and (action ~= \"STEAL\" or target.body:GetAttribute(\"HasCard\") == true)\n        elseif action == \"DRAG\" then\n            return not Rules.active(target.life) and not target.locker and not target.carrier\n                and not self.dragging[player] and target.life ~= \"TRAPPED\"\n        elseif action == \"RELEASE\" then\n            return target.locker ~= nil and target.life ~= \"ACTIVE\" and not self.dragging[player]\n        end\n        return false\n    end\n    local function giveCard(player, guard)\n        if guard.body:GetAttribute(\"HasCard\") then\n            guard.body:SetAttribute(\"HasCard\", false)\n            player:SetAttribute(\"Posto17Keycard\", true)\n        end\n    end\n    -- Quem acorda so lembra do que efetivamente presenciou.\n    -- Resgatador recebe um relato LOCAL; nao conhece a posicao atual do jogador.\n    local function reportIncident(guard, rescuer, now)\n        local uid = guard.knownUserId\n        local lastPoint = guard.incidentLastSeen or guard.incidentPosition or guard.body.Position\n        local suspect = nil\n        if uid then\n            for _, player in ipairs(ctx.players:GetPlayers()) do\n                if player.UserId == uid then suspect = player; break end\n            end\n        end\n        local function inform(receiver, search)\n            receiver.targetPlayer = nil\n            receiver.lastSeen = lastPoint\n            receiver.lastMotion = Vector3.zero\n            receiver.lastNoiseAt = now\n            receiver.suspicion = math.max(receiver.suspicion or 0,\n                uid and 0.65 or 0.34)\n            receiver.suspectedPlayer = suspect\n            receiver.body:SetAttribute(\"IncidentWitnessed\", uid ~= nil)\n            receiver.body:SetAttribute(\"IncidentAt\", now)\n            if uid then\n                receiver.knownUserId = uid\n                receiver.identifiedPlayers = receiver.identifiedPlayers or {}\n                receiver.identifiedPlayers[uid] = true\n            end\n            -- SEARCH nao tem alvo a seguir: precisa obter nova visao antes de CHASE.\n            ctx.setState(receiver, search and \"SEARCH\" or \"INVESTIGATE\", now)\n        end\n        inform(guard, true)\n        if rescuer and Rules.active(rescuer.life)\n            and rescuer.state ~= \"CHASE\" and rescuer.state ~= \"WATCH\" then\n            inform(rescuer, false)\n        end\n        if ctx.incident then ctx.incident(guard, rescuer, uid ~= nil, lastPoint, now) end\n    end\n    local function wakeGuard(guard, now, rescuer)\n        setLife(guard, \"ACTIVE\")\n        guard.body.CFrame = CFrame.new(guard.body.Position.X, 2, guard.body.Position.Z)\n        pose(guard)\n        reportIncident(guard, rescuer, now)\n    end\n    local function unstore(guard, now, rescuer)\n        local locker = guard.locker\n        if not locker then return end\n        locker.occupant = nil\n        locker.body:SetAttribute(\"BodyStored\", false)\n        guard.locker = nil\n        guard.body:SetAttribute(\"LockerId\", nil)\n        local point = (locker.body.CFrame * CFrame.new(0, -2.3, -5)).Position\n        guard.body.CFrame = CFrame.new(corpsePosition(guard, point)) * CFrame.Angles(math.pi/2, 0, 0)\n        shown(guard, true)\n        pose(guard)\n        ctx.animateDoor(locker)\n        if guard.life == \"TRAPPED\" then\n            wakeGuard(guard, now, rescuer)\n        end\n    end\n    local function finish(player, action, target, now)\n        if action == \"DROP\" then self:drop(player); return end\n        if action == \"STEAL\" then\n            giveCard(player, target)\n            ctx.state:FireClient(player, \"OPERACAO\", \"Cartao furtado sem neutralizar o vigia.\")\n        elseif action == \"KO\" or action == \"KILL\" or action == \"SHOT\" then\n            target.knownUserId = target.identifiedPlayers and target.identifiedPlayers[player.UserId]\n                and player.UserId or nil\n            target.incidentPosition = target.body.Position\n            -- Memoria do ultimo contato visual ANTERIOR ao golpe; nao cria um\n            -- rastreador da posicao do jogador ao longo do nocaute.\n            target.incidentLastSeen = target.knownUserId\n                and now - (target.lastVisualAt or -100) <= 8\n                and target.lastSeen or target.incidentPosition\n            target.wakeAt = now + Rules.KO_SECONDS\n            setLife(target, action == \"KO\" and \"UNCONSCIOUS\" or \"DEAD\")\n            local pos = target.body.Position\n            if not ctx.ragdoll or not ctx.ragdoll(target) then\n                target.visualFall = {from = target.body.CFrame, at = now}\n                target.body.CFrame = CFrame.new(corpsePosition(target, pos)) * CFrame.Angles(math.pi/2, 0, 0)\n                pose(target)\n            end\n            target.body.Color = action == \"KO\" and Color3.fromRGB(77, 88, 102) or Color3.fromRGB(52, 54, 59)\n            player:SetAttribute(action == \"KO\" and \"Posto17Knockouts\" or \"Posto17Kills\",\n                (player:GetAttribute(action == \"KO\" and \"Posto17Knockouts\" or \"Posto17Kills\") or 0) + 1)\n            if action ~= \"SHOT\" then\n                giveCard(player, target)\n                ctx.sound(target.body, \"rbxasset://sounds/action_jump_land.mp3\", 0.25, 0.6)\n                ctx.noise(target.body.Position, now, 9)\n                ctx.state:FireClient(player, \"OPERACAO\", action == \"KO\" and \"Vigia nocauteado. Pode acordar em 60 s.\" or \"Vigia morto. Nao voltara nesta operacao.\")\n            end\n        elseif action == \"DRAG\" then\n            if ctx.stopRagdoll then ctx.stopRagdoll(target) end\n            target.carrier = player\n            target.body:SetAttribute(\"Carried\", true)\n            target.body:SetAttribute(\"CarrierId\", player.UserId)\n            self.dragging[player] = target\n            player:SetAttribute(\"Posto17Dragging\", true)\n            local _, hum = rootOf(player)\n            if hum then hum.WalkSpeed = 5 end\n        elseif action == \"STOW\" then\n            local guard = self.dragging[player]\n            self:drop(player)\n            guard.locker = target\n            guard.body:SetAttribute(\"LockerId\", table.find(lockers, target))\n            target.occupant = guard\n            target.body:SetAttribute(\"BodyStored\", true)\n            guard.body.CFrame = target.body.CFrame\n            if guard.life == \"UNCONSCIOUS\" then guard.wakeAt = now + Rules.LOCKER_SECONDS end\n            shown(guard, false)\n            ctx.animateDoor(target)\n            ctx.state:FireClient(player, \"OPERACAO\", \"Corpo oculto. Armario ocupado.\")\n        elseif action == \"RELEASE\" then\n            unstore(target, now)\n        end\n    end\n    function self:shot(player, guard, headshot, amount, now)\n        if not Rules.active(guard.life) then return false end\n        guard.shotHealth = headshot and 0 or math.max(0, (guard.shotHealth or 100)-amount)\n        guard.body:SetAttribute(\"ShotHealth\",guard.shotHealth)\n        if guard.shotHealth == 0 then\n            finish(player,\"SHOT\",guard,now)\n        else\n            guard.suspicion = math.max(guard.suspicion or 0,.55)\n        end\n        return true\n    end\n    -- IDs sao resolvidos no servidor. A mesma sessao valida inicio, duracao e fim.\n    event.OnServerEvent:Connect(function(player, phase, action, id)\n        local now = os.clock()\n        if phase == \"CANCEL\" then\n            local previous = self.sessions[player]\n            self.sessions[player] = nil\n            if previous then ctx.motion.cancel(player, previous.action) end\n            return\n        end\n        if type(action) ~= \"string\" or not Rules.HOLD[action] then return end\n        if type(id) ~= \"number\" or id % 1 ~= 0 then return end\n        local target = action == \"STOW\" and lockers[id] or guards[id]\n        if action == \"DROP\" then target = self.dragging[player] end\n        if not target then return end\n        if phase == \"BEGIN\" then\n            if now - (self.cooldown[player] or -100) < 0.2 then return end\n            self.cooldown[player] = now\n            if eligible(player, action, target) and ctx.near(player, actionBody(action, target).Position, 8)\n                and clear(player, actionBody(action, target)) then\n                self.sessions[player] = {action = action, target = target, at = now}\n                if action == \"STEAL\" or action == \"KO\" or action == \"KILL\" then\n                    ctx.motion.play(player, action, Rules.HOLD[action] + 0.24, target.body.Position)\n                    if action ~= \"STEAL\" then target.reaction = now end\n                end\n            end\n        elseif phase == \"FINISH\" then\n            local session = self.sessions[player]\n            self.sessions[player] = nil\n            local root, hum = rootOf(player)\n            if not session or session.action ~= action or session.target ~= target or not root then return end\n            local elapsed = now - session.at\n            local valid = Rules.canFinish(action, elapsed,\n                (root.Position-actionBody(action, target).Position).Magnitude,\n                clear(player, actionBody(action, target)), hum.Health > 0,\n                player:GetAttribute(\"Posto17Hidden\"), player:GetAttribute(\"Posto17Won\"))\n                and eligible(player, action, target)\n            if valid then\n                if action == \"KO\" or action == \"KILL\" then\n                    ctx.motion.play(player, action, 0.52, target.body.Position)\n                end\n                finish(player, action, target, now)\n            elseif action == \"STEAL\" and elapsed < 4 then\n                ctx.state:FireClient(player, \"OPERACAO\",\n                    \"Furto falhou: solte o botao entre 1,8 e 2,4 segundos.\")\n            end\n        end\n    end)\n    for _, guard in ipairs(guards) do\n        guard.light = guard.body:FindFirstChildOfClass(\"SpotLight\")\n        guard.body:SetAttribute(\"GuardId\", guard.id)\n        guard.body:SetAttribute(\"HasCard\", guard.id == 2)\n        setLife(guard, \"ACTIVE\")\n    end\n    function self:tick(now)\n        for player, session in pairs(self.sessions) do\n            if now-session.at > 8 or not eligible(player, session.action, session.target)\n                or not ctx.near(player, actionBody(session.action, session.target).Position, 8)\n                or not clear(player, actionBody(session.action, session.target)) then\n                self.sessions[player] = nil\n            end\n        end\n        for player, guard in pairs(self.dragging) do\n            local root, hum = rootOf(player)\n            if not root or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Won\") then\n                self:drop(player)\n            else\n                hum.WalkSpeed = math.min(hum.WalkSpeed, 5)\n                local back = (root.CFrame * CFrame.new(0, 0, 3)).Position\n                local desired = corpsePosition(guard, back)\n                ray.FilterDescendantsInstances = {player.Character, guard.body}\n                local delta = desired - guard.body.Position\n                local hit = delta.Magnitude > 0.001 and workspace:Blockcast(CFrame.new(guard.body.Position),\n                    Vector3.new(3.2, 3.1, 4.9), delta, ray) or nil\n                if delta.Magnitude > 10 or hit then self:drop(player)\n                else\n                    guard.body.CFrame = CFrame.new(desired) * CFrame.Angles(math.pi/2, 0, 0)\n                    pose(guard)\n                end\n            end\n        end\n        for _, guard in ipairs(guards) do\n            local recovery = Rules.recovery(guard.life, now, guard.wakeAt or math.huge, guard.locker ~= nil)\n            if recovery == \"TRAPPED\" then\n                setLife(guard, \"TRAPPED\")\n                guard.nextNoise = now\n            elseif recovery == \"ACTIVE\" then\n                if guard.carrier then self:drop(guard.carrier) end\n                wakeGuard(guard, now, nil)\n            end\n            if guard.life == \"TRAPPED\" and now >= (guard.nextNoise or 0) then\n                guard.nextNoise = now + 6\n                ctx.sound(guard.locker.body, \"rbxasset://sounds/action_jump_land.mp3\", 0.4, 0.8)\n                -- Som mecanico local e anuncio para microfones em funcionamento.\n                ctx.noise(guard.locker.body.Position, now, 19, \"LOCKER\", guard.locker.body)\n            end\n        end\n    end\n    -- Descoberta exige cone, distancia e raio livre; nao conhece quem deixou o corpo.\n    function self:observe(observer, now)\n        if not Rules.active(observer.life) or observer.state == \"CHASE\"\n            or observer.state == \"WATCH\" then\n            cancelRescue(observer)\n            return\n        end\n        observer.bodyChecks = observer.bodyChecks or {}\n        local continuingRescue = false\n        for _, body in ipairs(guards) do\n            if body ~= observer and not Rules.active(body.life) then\n                local point = body.locker and body.locker.body.Position or body.body.Position\n                local delta = Vector3.new(point.X-observer.body.Position.X, 0, point.Z-observer.body.Position.Z)\n                local trapped = body.life == \"TRAPPED\"\n                if delta.Magnitude < 18 and delta.Magnitude > 0.1\n                    and (trapped or (not body.locker and observer.forward:Dot(delta.Unit) > 0.5)) then\n                    ray.FilterDescendantsInstances = {observer.body, body.body, body.locker and body.locker.body or body.body}\n                    if not workspace:Raycast(observer.body.Position, point-observer.body.Position, ray) then\n                        if body.locker and trapped and delta.Magnitude < 6 then\n                            continuingRescue = true\n                            if observer.rescueTarget ~= body then\n                                cancelRescue(observer)\n                                observer.rescueTarget = body\n                                observer.rescueAt = now + 1.6\n                                observer.body:SetAttribute(\"RescuingGuard\", body.id)\n                                observer.lastSeen = point\n                                ctx.setState(observer, \"INVESTIGATE\", now)\n                            elseif now >= (observer.rescueAt or math.huge) then\n                                cancelRescue(observer)\n                                unstore(body, now, observer)\n                                ctx.sound(body.body, \"rbxasset://sounds/action_get_up.mp3\", 0.27, 0.9)\n                            end\n                            return\n                        elseif not body.locker and body.life == \"UNCONSCIOUS\" and delta.Magnitude < 4.5 then\n                            body.wakeAt = math.min(body.wakeAt, now + 2)\n                        end\n                        if now - (observer.bodyChecks[body] or -100) > 20 then\n                            observer.bodyChecks[body] = now\n                            if observer.state ~= \"CHASE\" and observer.state ~= \"WATCH\" then\n                                observer.lastSeen = point\n                                ctx.setState(observer, \"INVESTIGATE\", now)\n                            end\n                        end\n                    end\n                end\n            end\n        end\n        if not continuingRescue then cancelRescue(observer) end\n    end\n    function self:recognizes(guard, player)\n        return Rules.recognizes(guard.knownUserId, player.UserId)\n    end\n    function self:reset()\n        for player in pairs(self.dragging) do self:drop(player) end\n        table.clear(self.sessions)\n        for _, guard in ipairs(guards) do\n            if guard.locker then\n                guard.locker.occupant = nil\n                guard.locker.body:SetAttribute(\"BodyStored\", false)\n            end\n            guard.locker, guard.carrier, guard.knownUserId = nil, nil, nil\n            guard.incidentLastSeen, guard.incidentPosition = nil, nil\n            guard.body:SetAttribute(\"IncidentWitnessed\", nil)\n            guard.body:SetAttribute(\"IncidentAt\", nil)\n            guard.body:SetAttribute(\"LockerId\", nil)\n            guard.body:SetAttribute(\"Carried\", false)\n            guard.body:SetAttribute(\"CarrierId\", nil)\n            cancelRescue(guard)\n            guard.bodyChecks = {}\n            guard.identifiedPlayers = {}\n            guard.doorsSeen = {}\n            guard.wakeAt = nil\n            guard.body:SetAttribute(\"HasCard\", guard.id == 2)\n            shown(guard, true)\n            setLife(guard, \"ACTIVE\")\n            guard.body.CFrame = guard.homeCFrame or CFrame.new(guard.body.Position.X, 2, guard.body.Position.Z)\n            guard.forward = guard.homeForward or guard.forward\n            guard.progress = 0\n            guard.state = \"RESET\"\n            ctx.setState(guard, \"PATROL\", os.clock())\n            pose(guard)\n        end\n    end\n    function self:cleanup(player)\n        self:drop(player)\n        self.sessions[player], self.cooldown[player] = nil, nil\n    end\n    return self\nend\nreturn Ops\n"},{"studio":"ServerScriptService/GuardRagdoll","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/GuardRagdoll (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal PhysicsService = game:GetService(\"PhysicsService\")\nlocal Ragdoll = {}\nlocal GROUP = \"P17Ragdoll\"\n\nlocal function colliderGroup()\n    if not PhysicsService:IsCollisionGroupRegistered(GROUP) then\n        PhysicsService:RegisterCollisionGroup(GROUP)\n        PhysicsService:CollisionGroupSetCollidable(GROUP, GROUP, false)\n    end\nend\n\nfunction Ragdoll.finish(guard)\n    local rag = guard.ragdoll\n    if not rag then return end\n    guard.ragdoll = nil\n    for _, part in ipairs(rag.parts) do\n        part.Anchored, part.CanCollide = true, false\n        part.CollisionGroup = \"Default\"\n    end\n    for _, joint in ipairs(rag.joints) do joint:Destroy() end\n    if not guard.body.Parent then return end\n    local center = rag.torso.Position\n    guard.body.CFrame = CFrame.new(center.X, math.max(0.75, center.Y), center.Z)\n        * CFrame.Angles(math.pi/2,0,0)\n    for _, bone in ipairs(guard.visualBones) do\n        bone.offset = guard.body.CFrame:ToObjectSpace(bone.part.CFrame)\n    end\n    guard.settledRagdoll = true\n    guard.body:SetAttribute(\"Ragdoll\", false)\nend\n\nfunction Ragdoll.start(guard)\n    if guard.ragdoll or not guard.visualBones then return false end\n    local named = {}\n    for _, bone in ipairs(guard.visualBones) do named[bone.part.Name] = bone.part end\n    local torso = named.Jaqueta\n    if not torso then return false end\n    colliderGroup()\n    local status = {torso=torso, parts={}, joints={}}\n    guard.ragdoll, guard.settledRagdoll, guard.visualFall = status, nil, nil\n    local function constrain(parent, child, worldPoint, swing)\n        if not parent or not child then return end\n        local first = Instance.new(\"Attachment\")\n        first.Position = parent.CFrame:PointToObjectSpace(worldPoint)\n        first.Parent = parent\n        local second = Instance.new(\"Attachment\")\n        second.Position = child.CFrame:PointToObjectSpace(worldPoint)\n        second.Parent = child\n        local joint = Instance.new(\"BallSocketConstraint\")\n        joint.Attachment0,joint.Attachment1 = first,second\n        joint.LimitsEnabled,joint.UpperAngle = true,swing\n        joint.TwistLimitsEnabled,joint.TwistLowerAngle,joint.TwistUpperAngle = true,-32,32\n        joint.Parent = child\n        for _, object in ipairs({first, second, joint}) do table.insert(status.joints,object) end\n    end\n    local cores = {[torso]=true,[named.Cabeca]=true}\n    constrain(torso,named.Cabeca, named.Cabeca.Position - Vector3.yAxis*.58, 25)\n    for _, side in ipairs({\"E\",\"D\"}) do\n        local arm, forearm = named[\"Braco\"..side], named[\"Antebraco\"..side]\n        local leg, shin = named[\"Perna\"..side], named[\"Canela\"..side]\n        cores[arm],cores[forearm],cores[leg],cores[shin] = true,true,true,true\n        constrain(torso,arm,arm.Position+arm.CFrame.UpVector*.43,62)\n        constrain(arm,forearm,(arm.Position+forearm.Position)/2,68)\n        constrain(torso,leg,leg.Position+leg.CFrame.UpVector*.42,56)\n        constrain(leg,shin,(leg.Position+shin.Position)/2,68)\n    end\n    for _, bone in ipairs(guard.visualBones) do\n        local part = bone.part\n        if not cores[part] then\n            local role = bone.role or \"\"\n            local side = role:sub(1,4) == \"LEFT\" and \"E\" or \"D\"\n            local host = role == \"HEAD\" and named.Cabeca\n                or role:find(\"FOREARM\",1,true) and named[\"Antebraco\"..side]\n                or role:find(\"SHIN\",1,true) and named[\"Canela\"..side]\n                or role:find(\"_ARM\",1,true) and named[\"Braco\"..side] or torso\n            local weld = Instance.new(\"WeldConstraint\")\n            weld.Part0, weld.Part1 = host, part\n            weld.Parent = part\n            table.insert(status.joints,weld)\n        end\n        part.Massless = not cores[part]\n        part.CollisionGroup = GROUP\n        part.CanCollide = cores[part] == true\n        table.insert(status.parts, part)\n    end\n    for _, part in ipairs(status.parts) do part.Anchored = false end\n    for part in pairs(cores) do if part:CanSetNetworkOwnership() then part:SetNetworkOwner(nil) end end\n    torso.AssemblyAngularVelocity = torso.CFrame.RightVector * 1.9\n    guard.body:SetAttribute(\"Ragdoll\", true)\n    task.delay(1.65,function()\n        if guard.ragdoll == status then Ragdoll.finish(guard) end\n    end)\n    return true\nend\n\nreturn Ragdoll\n"},{"studio":"ServerScriptService/GuardVisuals","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/GuardVisuals (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Guarda low-poly com geometria original; sem animacoes pagas nem Humanoids extras.\n-- So as hitboxes existentes colidem; roupa/ossos usam CFrame em lote (8 Hz).\nlocal Visuals = {}\nlocal STEEL = Color3.fromRGB(48, 57, 64)\nlocal DARK = Color3.fromRGB(24, 29, 36)\nlocal CLOTH = Color3.fromRGB(60, 70, 66)\nlocal BRASS = Color3.fromRGB(203, 167, 89)\nlocal VISOR = Color3.fromRGB(246, 194, 93)\n\nfunction Visuals.attach(guards, part, world)\n    local folder = Instance.new(\"Folder\")\n    folder.Name = \"Personagens3D\"\n    folder.Parent = world\n    local total = 0\n    for _, guard in ipairs(guards) do\n        local model = Instance.new(\"Model\")\n        model.Name = \"Vigia_\" .. guard.id .. \"_Visual\"\n        model.Parent = folder\n        local color = guard.id == 2 and Color3.fromRGB(65, 68, 79)\n            or (guard.id == 4 and Color3.fromRGB(64, 69, 62) or CLOTH)\n        guard.visualBones = {}\n        local function bone(name, size, base, shade, material, role)\n            local p = part(name, size, guard.body.Position,\n                shade or color, material or Enum.Material.SmoothPlastic, false)\n            p.CanQuery, p.CanTouch, p.CanCollide = false, false, false\n            p.Parent = model\n            local entry = {part = p, offset = base, base = base,\n                role = role, isRigPart = true}\n            guard.visualBones[#guard.visualBones+1] = entry\n            guard.eyes[#guard.eyes+1] = entry\n            total += 1\n            return p\n        end\n        bone(\"Jaqueta\", Vector3.new(2.15, 2.15, 1.05),\n            CFrame.new(0, 0.55, 0), color)\n        bone(\"ColeteBalistico\", Vector3.new(2.23, 1.48, 0.43),\n            CFrame.new(0, 0.65, -0.67), DARK)\n        bone(\"ColeteCostas\", Vector3.new(1.8, 1.5, 0.29),\n            CFrame.new(0, 0.6, 0.69), STEEL)\n        bone(\"CintoTatico\", Vector3.new(2.19, 0.34, 1.2),\n            CFrame.new(0, -0.61, 0), DARK)\n        bone(\"Pochete\", Vector3.new(0.64, 0.78, 0.42),\n            CFrame.new(0.83, -0.85, -0.56), STEEL)\n        bone(\"Cabeca\", Vector3.new(1.43, 1.46, 1.32),\n            CFrame.new(0, 2.31, 0.03), color, nil, \"HEAD\")\n        bone(\"Mascara\", Vector3.new(1.21, 0.67, 0.24),\n            CFrame.new(0, 2.03, -0.75), DARK, nil, \"HEAD\")\n        local visor = bone(\"Viseira\", Vector3.new(1.5, 0.32, 0.2),\n            CFrame.new(0, 2.46, -0.77), VISOR, Enum.Material.Neon, \"HEAD\")\n        visor:SetAttribute(\"HelmetVisor\", true)\n        bone(\"Capacete\", Vector3.new(1.69, 0.52, 1.52),\n            CFrame.new(0, 3.07, 0.03), STEEL, nil, \"HEAD\")\n        bone(\"LanternaCapacete\", Vector3.new(0.3, 0.3, 0.35),\n            CFrame.new(0.69, 2.88, -0.64), BRASS, Enum.Material.Metal, \"HEAD\")\n        bone(\"OmbreiraE\", Vector3.new(0.66, 0.44, 1.15),\n            CFrame.new(-1.23, 1.35, 0.06), STEEL, nil, \"LEFT_ARM\")\n        bone(\"OmbreiraD\", Vector3.new(0.66, 0.44, 1.15),\n            CFrame.new(1.23, 1.35, 0.06), STEEL, nil, \"RIGHT_ARM\")\n        for _, side in ipairs({{\"E\", -1, \"LEFT\"}, {\"D\", 1, \"RIGHT\"}}) do\n            local suffix, sign, role = side[1], side[2], side[3]\n            bone(\"Braco\" .. suffix, Vector3.new(0.67, 1.02, 0.76),\n                CFrame.new(1.29 * sign, 0.81, 0.03), color, nil, role .. \"_ARM\")\n            bone(\"Antebraco\" .. suffix, Vector3.new(0.65, 0.91, 0.72),\n                CFrame.new(1.29 * sign, -0.12, 0.03), color, nil, role .. \"_FOREARM\")\n            bone(\"Luva\" .. suffix, Vector3.new(0.75, 0.57, 0.88),\n                CFrame.new(1.29 * sign, -0.83, -0.06), DARK, nil, role .. \"_FOREARM\")\n            bone(\"Perna\" .. suffix, Vector3.new(0.92, 0.99, 0.94),\n                CFrame.new(0.58 * sign, -0.99, 0), color, nil, role .. \"_LEG\")\n            bone(\"Canela\" .. suffix, Vector3.new(0.84, 0.83, 0.86),\n                CFrame.new(0.58 * sign, -1.83, 0), color, nil, role .. \"_SHIN\")\n            bone(\"Bota\" .. suffix, Vector3.new(0.96, 0.43, 1.2),\n                CFrame.new(0.58 * sign, -2.06, -0.19), DARK, nil, role .. \"_SHIN\")\n        end\n        bone(\"RadioCostas\", Vector3.new(0.67, 0.95, 0.45),\n            CFrame.new(-0.5, 0.4, 0.89), STEEL)\n        bone(\"AntenaRadio\", Vector3.new(0.11, 1.55, 0.11),\n            CFrame.new(-0.5, 1.65, 1.01), DARK)\n        -- A colisao e detecao permanecem no cubo original, agora invisivel.\n        guard.body.Transparency = 1\n        guard.body:SetAttribute(\"VisualRig\", \"LOWPOLY-RIG-1\")\n        guard.body:SetAttribute(\"VisualParts\", #guard.visualBones)\n        for _, feature in ipairs(guard.eyes) do\n            feature.part.CFrame = guard.body.CFrame * feature.offset\n        end\n    end\n    world:SetAttribute(\"GuardVisualParts\", total)\n    return total\nend\n\nfunction Visuals.animate(guard, now)\n    local bones = guard.visualBones\n    if guard.ragdoll or guard.settledRagdoll then return end\n    if not bones then return end\n    local active = guard.life == \"ACTIVE\" or guard.life == nil\n    local moving = active and now - (guard.lastMoveAt or -100) < 0.25\n        and guard.state ~= \"WATCH\" and not guard.body:GetAttribute(\"RepairingPower\")\n    local pace = guard.state == \"CHASE\" and 12 or 7.0\n    local dt = math.clamp(now - (guard.poseAt or now), 0, 0.2)\n    guard.poseAt = now\n    guard.poseWeight = (guard.poseWeight or 0)\n        + ((moving and 1 or 0) - (guard.poseWeight or 0)) * (1 - math.exp(-dt * 11))\n    guard.posePhase = ((guard.posePhase or guard.id * 0.8) + dt * pace) % (2 * math.pi)\n    local weight, phase = guard.poseWeight, guard.posePhase\n    local look = active and math.sin(now * 1.4 + guard.id)\n        * ((guard.state == \"SEARCH\" or guard.state == \"INVESTIGATE\") and 0.24 or 0.12) or 0\n    local react = active and guard.reaction and math.clamp((now-guard.reaction) * 5, 0, 1)\n        * math.clamp((guard.reaction + 1.55 - now) * 5, 0, 1) or 0\n    local torso = CFrame.new(0, weight * math.abs(math.cos(phase)) * 0.065, 0)\n        * CFrame.Angles(-react * 0.20, math.sin(phase) * weight * 0.055, react * 0.09)\n    local function pivot(x, y, pitch, roll)\n        local joint = CFrame.new(x, y, 0)\n        return joint * CFrame.Angles(pitch, 0, roll or 0) * joint:Inverse()\n    end\n    local visualFrame = guard.body.CFrame\n    if guard.visualFall then\n        local alpha = math.clamp((now - guard.visualFall.at) / 0.38, 0, 1)\n        if alpha >= 1 or guard.carrier or guard.locker or active then\n            guard.visualFall = nil\n        else\n            visualFrame = guard.visualFall.from:Lerp(visualFrame, alpha * alpha * (3 - 2 * alpha))\n        end\n    end\n    local left = math.sin(phase)\n    for _, b in ipairs(bones) do\n        local role = b.role or \"\"\n        local side = role:sub(1, 4) == \"LEFT\" and -1 or 1\n        local step = left * side\n        local offset = torso * b.base\n        if role:find(\"ARM\", 1, true) then\n            local radio = guard.body:GetAttribute(\"CallingRadio\")\n            local repair = guard.body:GetAttribute(\"RepairingPower\")\n            local swing = -step * weight * 0.29 + react * 0.66\n            if radio and side == 1 then swing = 1.05 end\n            if repair then swing = 0.65 end\n            local shoulder = pivot(side * 1.24, 1.43, swing, side * react * 0.22)\n            local elbow = role:find(\"FOREARM\", 1, true) and pivot(side * 1.29, 0.35,\n                0.18 + weight * math.max(0, -step) * 0.24 + react * 0.32) or CFrame.identity\n            offset = torso * shoulder * elbow * b.base\n        elseif role:find(\"LEG\", 1, true) or role:find(\"SHIN\", 1, true) then\n            local hip = pivot(side * 0.58, -0.50, step * weight * 0.42)\n            local knee = role:find(\"SHIN\", 1, true) and pivot(side * 0.58, -1.44,\n                -weight * (math.max(0, step) * 0.51 + 0.08)) or CFrame.identity\n            offset = hip * knee * b.base\n        elseif role == \"HEAD\" then\n            local neck = CFrame.new(0, 1.75, 0)\n            offset = torso * neck * CFrame.Angles(-react * 0.18, look, 0) * neck:Inverse() * b.base\n        end\n        b.offset = offset\n        b.part.CFrame = visualFrame * offset\n    end\nend\n\nreturn Visuals\n"},{"studio":"ServerScriptService/P17BlockyOperator","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/P17BlockyOperator (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto 17: reconstrução leve, por partes, da silhueta original do Blockbench.\n-- O R15 permanece como rig, colisão e ponto de integração com os sistemas legados.\nlocal Operator = {}\n\nlocal shirt = Color3.fromRGB(85, 99, 88)\nlocal trousers = Color3.fromRGB(51, 62, 67)\nlocal dark = Color3.fromRGB(37, 42, 44)\nlocal hair = Color3.fromRGB(35, 41, 45)\nlocal eyes = Color3.fromRGB(21, 25, 28)\n\nfunction Operator.apply(character, visual, look, skin)\n    local hum = character:FindFirstChildOfClass(\"Humanoid\")\n    if not hum or hum.RigType ~= Enum.HumanoidRigType.R15 then return false end\n    local body = {}\n    for _, name in ipairs({\n        \"Head\", \"UpperTorso\", \"LowerTorso\", \"LeftUpperArm\", \"LeftLowerArm\",\n        \"LeftHand\", \"RightUpperArm\", \"RightLowerArm\", \"RightHand\",\n        \"LeftUpperLeg\", \"LeftLowerLeg\", \"LeftFoot\", \"RightUpperLeg\",\n        \"RightLowerLeg\", \"RightFoot\"\n    }) do\n        body[name] = character:FindFirstChild(name)\n        if not body[name] or not body[name]:IsA(\"BasePart\") then return false end\n    end\n    local slim = look.style == 2 and 0.93 or 1\n    local function part(name, anchorName, size, offset, color, nearFace)\n        local anchor = body[anchorName]\n        local p = Instance.new(\"Part\")\n        p.Name, p.Size, p.Color = name, size, color\n        p.Material = Enum.Material.SmoothPlastic\n        p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth\n        p.CastShadow = true\n        p.CanCollide, p.CanQuery, p.CanTouch, p.Massless = false, false, false, true\n        p.CFrame = anchor.CFrame * CFrame.new(offset)\n        p:SetAttribute(\"P17HeadVisual\", nearFace == true)\n        local weld = Instance.new(\"WeldConstraint\")\n        weld.Part0, weld.Part1, weld.Parent = anchor, p, p\n        p.Parent = visual\n        return p\n    end\n    -- Corpo: altura de ~5,5 studs, mesma relação geral do .bbmodel (44 unidades).\n    part(\"TroncoSuperior\", \"UpperTorso\", Vector3.new(1.60*slim,1.18,1.20),\n        Vector3.new(0,0,0), shirt)\n    part(\"TroncoInferior\", \"LowerTorso\", Vector3.new(1.56*slim,0.82,1.19),\n        Vector3.new(0,0,0), shirt)\n    for _, side in ipairs({\"Left\",\"Right\"}) do\n        local upper = side..\"UpperArm\"\n        local lower = side..\"LowerArm\"\n        part(\"BracoSuperior_\"..side,upper,Vector3.new(.79*slim,.91,.80),\n            Vector3.new(0,-.03,0),shirt)\n        part(\"Antebraco_\"..side,lower,Vector3.new(.77*slim,.86,.79),\n            Vector3.new(0,0,0),shirt)\n        part(\"Mao_\"..side,side..\"Hand\",Vector3.new(.72*slim,.36,.74),\n            Vector3.new(0,0,0),shirt)\n        part(\"Coxa_\"..side,side..\"UpperLeg\",Vector3.new(.80,1.05,.82),\n            Vector3.new(0,0,0),trousers)\n        part(\"Canela_\"..side,side..\"LowerLeg\",Vector3.new(.80,1.03,.82),\n            Vector3.new(0,0,0),dark)\n        part(\"Bota_\"..side,side..\"Foot\",Vector3.new(.83,.36,1.26),\n            Vector3.new(0,-.01,-.18),dark)\n    end\n    -- Cabeça, cabelo e olhos usam as cores medidas no atlas de 64px do Blockbench.\n    part(\"Cabeca_Blockbench\",\"Head\",Vector3.new(1.60,1.60,1.60),\n        Vector3.new(0,.18,0),skin,true)\n    part(\"Cabelo_Blockbench\",\"Head\",Vector3.new(1.64,.30,1.65),\n        Vector3.new(0,.92,0),hair,true)\n    for _, side in ipairs({-1,1}) do\n        part(\"Olho_\"..tostring(side),\"Head\",Vector3.new(.17,.15,.04),\n            Vector3.new(side*.36,.19,-.81),eyes,true)\n    end\n    -- Expressões discretas preservam as três opções do menu.\n    local mouth = look.face or 1\n    part(\"Expressao\",\"Head\",Vector3.new(mouth==2 and .24 or .17,.025,.035),\n        Vector3.new(0,-.36+(mouth==3 and .04 or 0),-.807),\n        Color3.fromRGB(91,65,57),true)\n\n    -- O rig real continua com colisões e juntas; só sua aparência é substituída.\n    for _, item in pairs(body) do\n        item.Transparency = 1\n        for _, decal in ipairs(item:GetChildren()) do\n            if decal:IsA(\"Decal\") then decal.Transparency = 1 end\n        end\n    end\n    character:SetAttribute(\"P17BodyStyle\",\"BLOCKBENCH_CC0\")\n    character:SetAttribute(\"P17BodyParts\",#visual:GetChildren())\n    return true\nend\n\nreturn Operator\n"},{"studio":"ServerScriptService/P17CosmeticModels","class":"Script","source":"-- Local no Studio: ServerScriptService/P17CosmeticModels (Script)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Modelos low-poly visuais no personagem R6 do Posto 17.\n-- Peças sem colisão e sem alterar as mecânicas existentes.\nlocal Players=game:GetService(\"Players\")\nlocal ReplicatedStorage=game:GetService(\"ReplicatedStorage\")\nlocal Models=require(ReplicatedStorage:WaitForChild(\"Posto17Shared\"):WaitForChild(\"Posto17Modelos\"))\n\nlocal function outfit(player,character)\n    local humanoid=character:WaitForChild(\"Humanoid\",10)\n    if not humanoid or humanoid.RigType~=Enum.HumanoidRigType.R6 then return end\n    local torso=character:WaitForChild(\"Torso\",8)\n    local leg=character:WaitForChild(\"Right Leg\",8)\n    if not torso or not leg or player.Character~=character then return end\n    if character:FindFirstChild(\"P17ItensVisuais\") then return end\n    local folder=Instance.new(\"Folder\")\n    folder.Name=\"P17ItensVisuais\"\n    folder.Parent=character\n    for _,kind in ipairs({\"pistola\",\"submetralhadora\",\"fuzil\"}) do\n        if player.Character~=character then break end\n        local model=Models.stowed(character,kind)\n        if model then model.Parent=folder end\n    end\nend\n\nlocal function watch(player)\n    player.CharacterAdded:Connect(function(character) task.defer(outfit,player,character) end)\n    if player.Character then task.defer(outfit,player,player.Character) end\nend\nfor _,player in ipairs(Players:GetPlayers()) do watch(player) end\nPlayers.PlayerAdded:Connect(watch)\n"},{"studio":"ServerScriptService/PistolRules","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/PistolRules (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Players = game:GetService(\"Players\")\n\nlocal Pistol = {\n    Name = \"Pistola\",\n    Durability = 12,\n    QuietRange = 13,\n    LoudRange = 42,\n    BodyDamage = 34,\n}\n\nlocal listeners = {}\nlocal lastShot = setmetatable({}, {__mode=\"k\"})\n\nfunction Pistol.attach(listener)\n    table.insert(listeners, listener)\nend\n\nlocal function finite(v)\n    return typeof(v) == \"Vector3\" and v.X == v.X and v.Y == v.Y and v.Z == v.Z and v.Magnitude < 10000\nend\n\n-- O kit controla câmera, animação, efeitos e munição. Este gancho decide\n-- ruído e impacto no servidor, antes de retransmitir o disparo do kit.\nfunction Pistol.fire(player, tool, shot)\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if not root or not humanoid or humanoid.Health <= 0\n        or typeof(tool) ~= \"Instance\" or tool.Parent ~= character\n        or not tool:GetAttribute(\"P17Pistol\")\n        or player:GetAttribute(\"P17Queued\") or player:GetAttribute(\"Posto17Hidden\")\n        or player:GetAttribute(\"Posto17Won\") then return false end\n    if type(shot) ~= \"table\" or not finite(shot.origin) or not finite(shot.dir)\n        or (shot.origin-root.Position).Magnitude > 14\n        or shot.dir.Magnitude < .7 or shot.dir.Magnitude > 1.3 then return false end\n    local now = os.clock()\n    if now - (lastShot[player] or -100) < .15 then return false end\n    lastShot[player] = now\n    local wear = tool:GetAttribute(\"P17Suppressor\") or 0\n    if wear > 0 then tool:SetAttribute(\"P17Suppressor\", wear-1) end\n    local muffled = wear > 0\n    local muzzle = tool:FindFirstChild(\"TipAttachment\",true)\n    local origin = muzzle and muzzle.WorldPosition or root.Position\n    local params = RaycastParams.new()\n    params.FilterDescendantsInstances = {character}\n    local head = character:FindFirstChild(\"Head\")\n    local basis = head and head.Position or root.Position\n    local toMuzzle = origin-basis\n    local barrier = toMuzzle.Magnitude > .01 and workspace:Raycast(basis,toMuzzle,params)\n    local dir = shot.dir.Unit\n    if finite(shot.aimPoint) then\n        local intent = shot.aimPoint-shot.origin\n        local distance = intent:Dot(dir)\n        local adjusted = shot.aimPoint-origin\n        if distance > 2 and distance <= 510 and (intent-dir*distance).Magnitude < .5\n            and adjusted:Dot(dir) > .5 then\n            dir = adjusted.Unit\n        end\n    end\n    local hit = barrier or workspace:Raycast(origin,dir*180,params)\n    for _, listener in ipairs(listeners) do listener(player, origin, hit, muffled) end\n    return true\nend\n\nfunction Pistol.playerFromPart(part)\n    local node = part\n    while node and node ~= workspace do\n        if node:IsA(\"Model\") then\n            local player = Players:GetPlayerFromCharacter(node)\n            if player then return player end\n        end\n        node = node.Parent\n    end\nend\n\nreturn Pistol\n"},{"studio":"ServerScriptService/Posto17","class":"Script","source":"-- Local no Studio: ServerScriptService/Posto17 (Script)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto 17: protótipo de infiltração, mapa gerado em tempo de execução.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Lighting = game:GetService(\"Lighting\")\nlocal PathfindingService = game:GetService(\"PathfindingService\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Debris = game:GetService(\"Debris\")\nlocal Rules = require(ReplicatedStorage:WaitForChild(\"Posto17Shared\"):WaitForChild(\"Rules\"))\nlocal VisualIdentity = require(ReplicatedStorage:WaitForChild(\"Posto17Shared\"):WaitForChild(\"VisualIdentity\"))\nlocal PoseLibrary = require(ReplicatedStorage:WaitForChild(\"Posto17Shared\"):WaitForChild(\"PoseLibrary\"))\nlocal operations, facilities, powerGrid\nlocal GuardVisuals = require(script.Parent.GuardVisuals)\nlocal Motion = require(script.Parent.TacticalMotion)\nlocal old = workspace:FindFirstChild(\"Posto17\")\nif old then old:Destroy() end\nlocal world = Instance.new(\"Folder\")\nworld.Name = \"Posto17\"\nworld.Parent = workspace\n\nlocal state = ReplicatedStorage:FindFirstChild(\"Posto17State\") or Instance.new(\"RemoteEvent\")\nstate.Name = \"Posto17State\"\nstate.Parent = ReplicatedStorage\n\nlocal crouchRemote = ReplicatedStorage:FindFirstChild(\"Posto17Crouch\")\nif not crouchRemote then\n    crouchRemote = Instance.new(\"RemoteEvent\")\n    crouchRemote.Name = \"Posto17Crouch\"\n    crouchRemote.Parent = ReplicatedStorage\nend\n\nlocal function remote(name)\n    local previous = ReplicatedStorage:FindFirstChild(name)\n    if previous then return previous end\n    local event = Instance.new(\"RemoteEvent\")\n    event.Name = name\n    event.Parent = ReplicatedStorage\n    return event\nend\n\nlocal stoneRemote = remote(\"Posto17Stone\")\nlocal hideRemote = remote(\"Posto17HideToggle\")\nlocal restartRemote = remote(\"Posto17Restart\")\nlocal proneRemote = remote(\"Posto17Prone\")\n\n-- Estado de postura validado no servidor: mesmo estado para mobilidade,\n-- audicao e volume visivel. Oculos/cameras nao leem a GUI do jogador.\nlocal function syncSpeed(player)\n    local _, hum = Motion.rig(player)\n    if not hum then return end\n    local stance = player:GetAttribute(\"Posto17Stance\")\n    local cover = player:GetAttribute(\"Posto17CoverHeight\")\n    local speed = stance == \"PRONE\" and 4 or stance == \"VENT\" and 4\n        or stance == \"CROUCH\" and 8 or player:GetAttribute(\"Posto17Sprint\") and 21 or 16\n    if cover then speed = math.min(speed, stance == \"CROUCH\" and 5 or 6) end\n    if player:GetAttribute(\"Posto17Dragging\") then speed = 5 end\n    if player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Won\") then speed = 0 end\n    hum.WalkSpeed = speed\nend\n\nlocal function setPosture(player, stance, fromDuct)\n    local character = player.Character\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if not humanoid then return end\n    if stance ~= \"STAND\" and stance ~= \"CROUCH\" and stance ~= \"PRONE\" and stance ~= \"VENT\" then return end\n    if not fromDuct and (stance == \"VENT\" or player:GetAttribute(\"Posto17Stance\") == \"VENT\") then return end\n    if stance == \"STAND\" and (player:GetAttribute(\"Posto17CoverHeight\") == \"LOW\"\n        or player:GetAttribute(\"Posto17Box\")) then return end\n    if stance ~= \"STAND\" then player:SetAttribute(\"Posto17Sprint\", nil) end\n    if player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Dragging\") then return end\n\n    local baseHip = humanoid:GetAttribute(\"P17BaseHip\")\n    if baseHip == nil then\n        baseHip = humanoid.HipHeight\n        humanoid:SetAttribute(\"P17BaseHip\", baseHip)\n        humanoid:SetAttribute(\"P17BaseJump\", humanoid.JumpPower)\n        humanoid:SetAttribute(\"P17BaseJumpHeight\", humanoid.JumpHeight)\n        humanoid:SetAttribute(\"P17BaseAutoJump\", humanoid.AutoJumpEnabled)\n    end\n    -- Atributos sincronizam a pose em Postura.client (AJU e Motor6D).\n    player:SetAttribute(\"Posto17Prone\", stance == \"PRONE\" or stance == \"VENT\")\n    player:SetAttribute(\"Posto17Crouched\", stance ~= \"STAND\")\n    player:SetAttribute(\"Posto17Stance\", stance)\n    if not character:GetAttribute(\"P17CoverMeasured\") then\n        local head = character:FindFirstChild(\"Head\")\n        local root = humanoid.RootPart\n        if head and root then\n            character:SetAttribute(\"P17UprightHead\",\n                head.Position.Y - root.Position.Y + head.Size.Y * 0.5)\n            character:SetAttribute(\"P17CoverMeasured\", true)\n        end\n    end\n    syncSpeed(player)\n    -- O antigo drop 1,7 afundava pernas e provocava saltos da fisica.\n    -- Abaixar o Humanoid suavemente sem girar o RootPart de colisao.\n    local drop = PoseLibrary.hipDrop(stance, baseHip,\n        humanoid.RigType == Enum.HumanoidRigType.R15)\n    TweenService:Create(humanoid,\n        TweenInfo.new(0.22, Enum.EasingStyle.Sine, Enum.EasingDirection.Out),\n        {HipHeight = math.max(0, baseHip - drop)}):Play()\n    local canJump = PoseLibrary.jumpAllowed(stance)\n    humanoid.JumpPower = canJump\n        and (humanoid:GetAttribute(\"P17BaseJump\") or 50) or 0\n    humanoid.JumpHeight = canJump\n        and (humanoid:GetAttribute(\"P17BaseJumpHeight\") or 7.2) or 0\n    if not canJump then humanoid.Jump = false end\nend\n\nlocal mobility = Motion.install({players = Players, world = world, remote = remote,\n    posture = setPosture, speed = syncSpeed})\n\ncrouchRemote.OnServerEvent:Connect(function(player, isCrouching)\n    if type(isCrouching) ~= \"boolean\" then return end\n    if player:GetAttribute(\"Posto17Prone\") then return end\n    setPosture(player, isCrouching and \"CROUCH\" or \"STAND\")\nend)\n\nproneRemote.OnServerEvent:Connect(function(player, isProne)\n    if type(isProne) ~= \"boolean\" then return end\n    setPosture(player, isProne and \"PRONE\" or \"STAND\")\nend)\n\nPlayers.PlayerAdded:Connect(function(player)\n    player:SetAttribute(\"Posto17Crouched\", false)\n    player:SetAttribute(\"Posto17Prone\", false)\n    player:SetAttribute(\"Posto17Stance\", \"STAND\")\n    player:SetAttribute(\"Posto17Hidden\", false)\n    player:SetAttribute(\"Posto17Data\", false)\n    player:SetAttribute(\"Posto17Won\", false)\n    player:SetAttribute(\"Posto17Stones\", 3)\n    player:SetAttribute(\"Posto17Sabotage\", false)\n    player:SetAttribute(\"Posto17BonusIntel\", false)\n    player:SetAttribute(\"Posto17Rank\", \"\")\n    player:SetAttribute(\"Posto17Score\", 0)\n    player.CharacterAdded:Connect(function(character)\n        player:SetAttribute(\"Posto17Crouched\", false)\n        player:SetAttribute(\"Posto17Prone\", false)\n        player:SetAttribute(\"Posto17Stance\", \"STAND\")\n        player:SetAttribute(\"Posto17Hidden\", false)\n        local humanoid = character:WaitForChild(\"Humanoid\", 8)\n        if humanoid then humanoid.WalkSpeed = 16 end\n    end)\nend)\n\nlocal function part(name, size, pos, color, material, collide)\n    local x = Instance.new(\"Part\")\n    x.Name = name\n    x.Size = size\n    x.Position = pos\n    x.Anchored = true\n    x.Material = material or Enum.Material.Concrete\n    x.Color = color\n    x.CanCollide = collide ~= false\n    x.Parent = world\n    return x\nend\n\nlocal steel = Color3.fromRGB(47, 55, 62)\nlocal wall = Color3.fromRGB(84, 95, 98)\nlocal accent = Color3.fromRGB(148, 35, 31)\npart(\"Piso\",Vector3.new(110,1,100),Vector3.new(0,-.5,0),steel,Enum.Material.Metal)\nfor _,v in ipairs({\n    {Vector3.new(110,16,2),Vector3.new(0,8,-50)},\n    {Vector3.new(110,16,2),Vector3.new(0,8,50)},\n    {Vector3.new(2,16,100),Vector3.new(-55,8,0)},\n    {Vector3.new(2,16,100),Vector3.new(55,8,0)},\n    {Vector3.new(3,11,26),Vector3.new(-12,5.5,-37)},\n    {Vector3.new(3,11,28),Vector3.new(-12,5.5,-2)},\n    {Vector3.new(3,11,56),Vector3.new(17,5.5,22)},\n    {Vector3.new(18,9,3),Vector3.new(-30,4.5,19)},\n    {Vector3.new(17,9,3),Vector3.new(35,4.5,-17)}\n}) do part(\"Parede\",v[1],v[2],wall) end\n\nfor _,v in ipairs({\n    Vector3.new(-35,2,-26),Vector3.new(4,2,-12),\n    Vector3.new(31,2,14),Vector3.new(-25,2,36)\n}) do part(\"Caixa\",Vector3.new(10,4,7),v,Color3.fromRGB(101,78,57),Enum.Material.Wood) end\n\nlocal spawn = Instance.new(\"SpawnLocation\")\nspawn.Name = \"Entrada\"\nspawn.Size = Vector3.new(9,1,9)\nspawn.Position = Vector3.new(-42,.5,38)\nspawn.Anchored = true\nspawn.Neutral = true\nspawn.Material = Enum.Material.Metal\nspawn.Color = Color3.fromRGB(45,101,80)\nspawn.Parent = world\n\n-- Local de testes separado: o jogador nasce aqui nesta experiencia\n-- privada, com portais para entrar na missao ou voltar.\nlocal testRange = require(script.Parent.TestRange).build({\n    world = world,\n    part = part,\n    missionSpawn = spawn,\n    identity = VisualIdentity,\n    players = Players,\n    runService = RunService,\n    placeId = game.PlaceId,\n})\n\nlocal objective = part(\"Terminal\",Vector3.new(5,7,3),Vector3.new(43,3.5,-39),accent,Enum.Material.Metal)\nlocal prompt = Instance.new(\"ProximityPrompt\")\nprompt.ActionText = \"Coletar dados\"\nprompt.ObjectText = \"Terminal de acesso\"\nprompt.HoldDuration = 2\nprompt.MaxActivationDistance = 9\nprompt.Parent = objective\n\nlocal terminalLed = part(\"LedTerminal\", Vector3.new(1.2, 0.27, 0.14),\n    objective.Position + Vector3.new(0, 2.7, -1.58),\n    Color3.fromRGB(76, 194, 143), Enum.Material.Neon, false)\nterminalLed.CanQuery = false\nterminalLed.CanTouch = false\n\n-- Missao em duas fases: obter os dados E retornar ao ponto de extracao.\nlocal completed = {}\nlocal dataTaken = {}\nlocal missionStart = {}\nlocal captures = {}\nlocal alertsByPlayer = {}\n-- O terminal registra a invasao com atraso, sem revelar onde o agente esta.\nlocal terminalInspectionDue = {}\nlocal TERMINAL_INSPECTION_DELAY = 7\n\nlocal function initializePlayerMission(player)\n    player:GetAttributeChangedSignal(\"P17Queued\"):Connect(function()\n        if player:GetAttribute(\"P17Queued\") == false then missionStart[player] = os.clock() end\n    end)\n    missionStart[player] = os.clock()\n    captures[player] = 0\n    alertsByPlayer[player] = 0\nend\nfor _, player in ipairs(Players:GetPlayers()) do\n    initializePlayerMission(player)\nend\nPlayers.PlayerAdded:Connect(initializePlayerMission)\n\nlocal extraction = part(\"Extracao\", Vector3.new(8, 0.2, 8),\n    Vector3.new(-42, 0.12, 29), Color3.fromRGB(34, 112, 88),\n    Enum.Material.Neon, false)\nextraction.CanQuery = false\n\nlocal exitPrompt = Instance.new(\"ProximityPrompt\")\nexitPrompt.Name = \"Extrair\"\nexitPrompt.ActionText = \"Solicitar extracao\"\nexitPrompt.ObjectText = \"Ponto de fuga / apos os dados\"\nexitPrompt.MaxActivationDistance = 8\nexitPrompt.HoldDuration = 1.2\nexitPrompt.RequiresLineOfSight = false\nexitPrompt.Parent = extraction\n\nlocal function playerNear(player, point, maximum)\n    if player:GetAttribute(\"P17Queued\") then return false end\n    local char = player.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n    if not root or not hum or hum.Health <= 0 then return false end\n    return (root.Position - point).Magnitude <= maximum\nend\n\nlocal function promptMotion(prompt, name, point)\n    prompt.PromptButtonHoldBegan:Connect(function(player)\n        if playerNear(player, point.Position, prompt.MaxActivationDistance + 2)\n            and not player:GetAttribute(\"Posto17Hidden\") and not player:GetAttribute(\"Posto17Won\")\n            and player:GetAttribute(\"Posto17Stance\") ~= \"VENT\" then\n            Motion.play(player, name, prompt.HoldDuration + 0.2, point.Position)\n        end\n    end)\n    prompt.PromptButtonHoldEnded:Connect(function(player) Motion.cancel(player, name) end)\nend\n\npromptMotion(prompt, \"TERMINAL\", objective)\nprompt.Triggered:Connect(function(player)\n    if completed[player] or dataTaken[player] or player:GetAttribute(\"Posto17Hidden\")\n        or player:GetAttribute(\"Posto17Stance\") == \"VENT\" then\n        return\n    end\n    if not playerNear(player, objective.Position, 12) then return end\n    Motion.play(player, \"TERMINAL\", 0.6, objective.Position)\n    dataTaken[player] = true\n    player:SetAttribute(\"Posto17Data\", true)\n    if world:GetAttribute(\"CamerasOnline\") ~= false then\n        terminalInspectionDue[player] = os.clock() + TERMINAL_INSPECTION_DELAY\n        terminalLed.Color = Color3.fromRGB(237, 170, 65)\n    else\n        -- Cortar o rele antes da copia evita o registro do terminal.\n        terminalInspectionDue[player] = nil\n        terminalLed.Color = Color3.fromRGB(76, 194, 143)\n    end\n    state:FireClient(player, \"DADOS\", \"Dados copiados. Volte ao ponto verde de extracao.\")\n    -- Som local curto vem dos arquivos de sons padrao do Roblox.\n    local tone = Instance.new(\"Sound\")\n    tone.SoundId = \"rbxasset://sounds/action_get_up.mp3\"\n    tone.Volume = 0.45\n    tone.PlaybackSpeed = 1.45\n    tone.Parent = objective\n    tone:Play()\n    Debris:AddItem(tone, 3)\n    print(\"[POSTO17 MISSAO] DADOS:\", player.Name)\nend)\n\nexitPrompt.Triggered:Connect(function(player)\n    if completed[player] then return end\n    if not playerNear(player, extraction.Position, 11) then return end\n    if not dataTaken[player] then\n        state:FireClient(player, \"SEM_DADOS\", \"Primeiro acesse o terminal vermelho.\")\n        return\n    end\n    if player:GetAttribute(\"Posto17Hidden\") then return end\n    completed[player] = true\n    terminalInspectionDue[player] = nil\n    local seconds = math.max(1, math.floor(os.clock() - (missionStart[player] or os.clock())))\n    local caught = captures[player] or 0\n    local alertCount = alertsByPlayer[player] or 0\n    if operations then operations:drop(player) end\n    local bonus = (player:GetAttribute(\"Posto17SecretIntel\") and 150 or 0)\n        + (player:GetAttribute(\"Posto17BonusIntel\") and 200 or 0)\n        + (player:GetAttribute(\"Posto17Sabotage\") and 120 or 0)\n        + (player:GetAttribute(\"Posto17Blackout\") and 70 or 0)\n    local score = math.max(0, 1000 + bonus - seconds * 2\n        - caught * 160 - alertCount * 40 - (player:GetAttribute(\"Posto17Kills\") or 0) * 80)\n    local rank = \"C\"\n    if score >= 1000 then rank = \"S\"\n    elseif score >= 830 then rank = \"A\"\n    elseif score >= 650 then rank = \"B\" end\n    player:SetAttribute(\"Posto17Score\", score)\n    player:SetAttribute(\"Posto17Rank\", rank)\n    player:SetAttribute(\"Posto17Won\", true)\n    state:FireClient(player, \"VITÓRIA\",\n        string.format(\"Extracao concluida - classe %s, %d pontos.\", rank, score))\n    print(\"[POSTO17 RANK]\", player.Name, rank, score, \"tempo\", seconds,\n        \"capturas\", caught, \"alertas\", alertCount)\n    local fanfare = Instance.new(\"Sound\")\n    fanfare.SoundId = \"rbxasset://sounds/action_get_up.mp3\"\n    fanfare.Volume = 0.5\n    fanfare.PlaybackSpeed = 1.1\n    fanfare.Parent = extraction\n    fanfare:Play()\n    Debris:AddItem(fanfare, 3)\n    print(\"[POSTO17 MISSAO] EXTRACAO:\", player.Name)\nend)\n\nlocal lockers = {}\nlocal hiddenState = {}\n\nlocal function buildLocker(index, position)\n    local locker = part(\"Armario_\" .. index, Vector3.new(4, 6.2, 3.2),\n        position, Color3.fromRGB(47, 67, 68), Enum.Material.Metal)\n    locker:SetAttribute(\"HideSpot\", true)\n    local door = part(\"PortaArmario_\" .. index, Vector3.new(3.6, 5.5, 0.12),\n        position + Vector3.new(0, 0, -1.65),\n        Color3.fromRGB(65, 85, 85), Enum.Material.Metal, false)\n    door.CanQuery = false\n    local band = part(\"FaixaArmario_\" .. index, Vector3.new(2.3, 0.12, 0.15),\n        position + Vector3.new(0, 1.8, -1.73),\n        Color3.fromRGB(142, 40, 38), Enum.Material.Neon, false)\n    band.CanQuery = false\n    local lp = Instance.new(\"ProximityPrompt\")\n    lp.Name = \"Esconder\"\n    lp.ActionText = \"Entrar no armario\"\n    lp.ObjectText = \"Esconderijo \" .. index\n    lp.MaxActivationDistance = 8\n    lp.RequiresLineOfSight = false\n    lp.HoldDuration = 0.3\n    lp.Parent = locker\n    table.insert(lockers, {body = locker, door = door, closed = door.CFrame, band = band, bandClosed = band.CFrame, prompt = lp})\nend\n\nbuildLocker(1, Vector3.new(-45, 3.1, 12))\nbuildLocker(2, Vector3.new(5, 3.1, 34))\nbuildLocker(3, Vector3.new(37, 3.1, 36))\n\n-- Zonas de sombra: so protegem se estiver agachado.\nlocal shadows = {}\nfor i, pos in ipairs({\n    Vector3.new(-32, 0.04, -10),\n    Vector3.new(0, 0.04, 23),\n    Vector3.new(42, 0.04, -23),\n}) do\n    local zone = part(\"Sombra_\" .. i, Vector3.new(12, 0.06, 12),\n        pos, Color3.fromRGB(16, 22, 29), Enum.Material.SmoothPlastic, false)\n    zone.CanQuery = false\n    table.insert(shadows, zone)\nend\n\nlocal function inShadow(position)\n    for _, zone in ipairs(shadows) do\n        if math.abs(position.X - zone.Position.X) < zone.Size.X / 2\n            and math.abs(position.Z - zone.Position.Z) < zone.Size.Z / 2 then\n            return true\n        end\n    end\n    return false\nend\n\nlocal function animateDoor(locker)\n    local door = locker and locker.door\n    if not door or not door.Parent or locker.sliding then return end\n    locker.sliding = true\n    task.spawn(function()\n        local closed = locker.closed\n        local opened = closed * CFrame.new(2.8, 0, 0)\n        local a = TweenService:Create(door,\n            TweenInfo.new(0.23, Enum.EasingStyle.Quad), {CFrame = opened})\n        a:Play()\n        TweenService:Create(locker.band, TweenInfo.new(0.23, Enum.EasingStyle.Quad),\n            {CFrame = locker.bandClosed * CFrame.new(2.8, 0, 0)}):Play()\n        a.Completed:Wait()\n        task.wait(0.2)\n        if door.Parent then\n            TweenService:Create(door,\n                TweenInfo.new(0.24, Enum.EasingStyle.Quad),\n                {CFrame = closed}):Play()\n            TweenService:Create(locker.band, TweenInfo.new(0.24, Enum.EasingStyle.Quad),\n                {CFrame = locker.bandClosed}):Play()\n            task.wait(0.24)\n        end\n        locker.sliding = false\n    end)\nend\n\nlocal function leaveLocker(player)\n    local info = hiddenState[player]\n    if not info then return end\n    hiddenState[player] = nil\n    animateDoor(info.locker)\n    local char = player.Character\n    if char then\n        for obj, original in pairs(info.transparencies) do\n            if obj.Parent then obj.Transparency = original end\n        end\n        local root = char:FindFirstChild(\"HumanoidRootPart\")\n        local hum = char:FindFirstChildOfClass(\"Humanoid\")\n        if root then\n            root.CFrame = info.locker.body.CFrame * CFrame.new(0, -0.2, -5)\n            root.Anchored = false\n        end\n        if hum then hum.WalkSpeed = 16 end\n    end\n    player:SetAttribute(\"Posto17Hidden\", false)\n    state:FireClient(player, \"SAIU\", \"Voce saiu do esconderijo.\")\nend\n\nlocal function enterLocker(player, chosen)\n    if chosen.occupant or chosen.pending\n        or player:GetAttribute(\"Posto17Dragging\") or player:GetAttribute(\"Posto17Stance\") == \"VENT\" then return end\n    for _, info in pairs(hiddenState) do if info.locker == chosen then return end end\n    if hiddenState[player] or completed[player] then return end\n    local char = player.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n    if not root or not hum or hum.Health <= 0 then return end\n    if (root.Position - chosen.body.Position).Magnitude > 9 then return end\n    chosen.pending = player\n    mobility.clear(player)\n    Motion.play(player, \"LOCKER\", 0.65, chosen.body.Position)\n    animateDoor(chosen)\n    task.wait(0.36)\n    chosen.pending = nil\n    if player.Character ~= char or hum.Health <= 0 or completed[player]\n        or hiddenState[player] or (root.Position - chosen.body.Position).Magnitude > 9 then return end\n    local originals = {}\n    for _, obj in ipairs(char:GetDescendants()) do\n        if obj:IsA(\"BasePart\") or obj:IsA(\"Decal\") then\n            originals[obj] = obj.Transparency\n            obj.Transparency = 1\n        end\n    end\n    hiddenState[player] = {locker = chosen, transparencies = originals}\n    setPosture(player, \"STAND\")\n    player:SetAttribute(\"Posto17Hidden\", true)\n    player:SetAttribute(\"Posto17Crouched\", false)\n    player:SetAttribute(\"Posto17Prone\", false)\n    player:SetAttribute(\"Posto17Stance\", \"STAND\")\n    root.CFrame = chosen.body.CFrame * CFrame.new(0, 0, 0)\n    root.Anchored = true\n    hum.WalkSpeed = 0\n    state:FireClient(player, \"ESCONDIDO\", \"Escondido. Aperte F para sair.\")\nend\n\nfor _, locker in ipairs(lockers) do\n    locker.prompt.Triggered:Connect(function(player)\n        if hiddenState[player] then\n            leaveLocker(player)\n        else\n            enterLocker(player, locker)\n        end\n    end)\nend\n\nhideRemote.OnServerEvent:Connect(function(player)\n    if hiddenState[player] then\n        leaveLocker(player)\n        return\n    end\n    local char = player.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    if not root then return end\n    for _, locker in ipairs(lockers) do\n        if (root.Position - locker.body.Position).Magnitude <= 8 then\n            enterLocker(player, locker)\n            return\n        end\n    end\nend)\n\n-- Roblox Reset Character também reinicia a tentativa; impede usar Reset\n-- como atalho gratuito para preservar dados roubados.\nlocal function monitorCharacter(player)\n    player.CharacterRemoving:Connect(function()\n        if operations then operations:cleanup(player) end\n        if facilities then facilities:cleanup(player) end\n        if powerGrid then powerGrid:cleanup(player) end\n        hiddenState[player] = nil\n    end)\n    player.CharacterAdded:Connect(function()\n        if missionStart[player] then\n            missionStart[player] = os.clock()\n            captures[player] = (captures[player] or 0) + 1\n            completed[player] = nil\n            dataTaken[player] = nil\n            terminalInspectionDue[player] = nil\n            terminalLed.Color = Color3.fromRGB(76, 194, 143)\n            player:SetAttribute(\"Posto17Data\", false)\n            player:SetAttribute(\"Posto17Won\", false)\n            player:SetAttribute(\"Posto17BonusIntel\", false)\n            player:SetAttribute(\"Posto17Sabotage\", false)\n            player:SetAttribute(\"Posto17Blackout\", false)\n            player:SetAttribute(\"Posto17Rank\", \"\")\n            player:SetAttribute(\"Posto17Score\", 0)\n            player:SetAttribute(\"Posto17Stones\", 3)\n        end\n    end)\nend\nfor _, player in ipairs(Players:GetPlayers()) do monitorCharacter(player) end\nPlayers.PlayerAdded:Connect(monitorCharacter)\n\nPlayers.PlayerRemoving:Connect(function(player)\n    if operations then operations:cleanup(player) end\n    if facilities then facilities:cleanup(player) end\n    if powerGrid then powerGrid:cleanup(player) end\n    completed[player] = nil\n    dataTaken[player] = nil\n    hiddenState[player] = nil\n    missionStart[player] = nil\n    captures[player] = nil\n    alertsByPlayer[player] = nil\n    terminalInspectionDue[player] = nil\nend)\n\n-- Missao secundária: recuperar prova digital na ala leste.\nlocal extraIntel = part(\"Dossie\", Vector3.new(2.5, 0.7, 2),\n    Vector3.new(28, 0.45, -32), Color3.fromRGB(51, 157, 182),\n    Enum.Material.Neon, false)\nextraIntel.CanQuery = false\nlocal intelPrompt = Instance.new(\"ProximityPrompt\")\nintelPrompt.Name = \"ColetarDossie\"\nintelPrompt.ActionText = \"Copiar dossie\"\nintelPrompt.ObjectText = \"Documento opcional / ala leste\"\nintelPrompt.HoldDuration = 1.2\nintelPrompt.MaxActivationDistance = 8\nintelPrompt.RequiresLineOfSight = false\nintelPrompt.Parent = extraIntel\nintelPrompt.Triggered:Connect(function(player)\n    if completed[player] or player:GetAttribute(\"Posto17BonusIntel\") then return end\n    if not playerNear(player, extraIntel.Position, 10)\n        or player:GetAttribute(\"Posto17Hidden\") then return end\n    player:SetAttribute(\"Posto17BonusIntel\", true)\n    state:FireClient(player, \"DOSSIE\", \"Dossie opcional obtido. Bonus ao extrair.\")\n    print(\"[POSTO17 EXTRA] DOSSIE:\", player.Name)\nend)\n\n-- Caixa de suprimentos: recarregar distrações sem precisar ser capturado.\nlocal supply = part(\"Suprimentos\", Vector3.new(3, 2, 3),\n    Vector3.new(5, 1, 25), Color3.fromRGB(90, 107, 65), Enum.Material.Metal)\nlocal supplyPrompt = Instance.new(\"ProximityPrompt\")\nsupplyPrompt.Name = \"ReporPedras\"\nsupplyPrompt.ActionText = \"Pegar pedras\"\nsupplyPrompt.ObjectText = \"Caixa de suprimentos\"\nsupplyPrompt.HoldDuration = 0.6\nsupplyPrompt.MaxActivationDistance = 8\nsupplyPrompt.RequiresLineOfSight = false\nsupplyPrompt.Parent = supply\n\n-- Relé único, recarregável, reduz a vigilância por tempo limitado.\nlocal relay = part(\"ReleCameras\", Vector3.new(3, 5, 2),\n    Vector3.new(3, 2.5, -29), Color3.fromRGB(49, 108, 135),\n    Enum.Material.Metal)\nlocal relayLight = part(\"LedRele\", Vector3.new(1.5, 0.3, 0.15),\n    relay.Position + Vector3.new(0, 1, -1.1),\n    Color3.fromRGB(47, 218, 203), Enum.Material.Neon, false)\nrelayLight.CanQuery = false\nlocal relayPrompt = Instance.new(\"ProximityPrompt\")\nrelayPrompt.Name = \"SabotarCameras\"\nrelayPrompt.ActionText = \"Cortar vigilancia\"\nrelayPrompt.ObjectText = \"Relé / cameras e rastreio\"\nrelayPrompt.HoldDuration = 1.1\nrelayPrompt.RequiresLineOfSight = false\nrelayPrompt.MaxActivationDistance = 8\nrelayPrompt.Parent = relay\n\nlocal cameraDisabledUntil = -100\nlocal relayCooldownUntil = -100\nlocal cameras = {}\nworld:SetAttribute(\"CamerasOnline\", true)\nworld:SetAttribute(\"CameraSeconds\", 0)\n\npromptMotion(relayPrompt, \"BUTTON\", relay)\nrelayPrompt.Triggered:Connect(function(player)\n    local now = os.clock()\n    if completed[player] or player:GetAttribute(\"Posto17Hidden\") then return end\n    if not playerNear(player, relay.Position, 11) then return end\n    if now < relayCooldownUntil then\n        state:FireClient(player, \"RELE_COOLDOWN\", \"Rele recarregando. Tente depois.\")\n        return\n    end\n    Motion.play(player, \"BUTTON\", 0.55, relay.Position)\n    cameraDisabledUntil = now + 40\n    relayCooldownUntil = now + 75\n    -- Janela de oportunidade: hacking do rele tambem cancela rastreio pendente.\n    for playerWithTrace in pairs(terminalInspectionDue) do\n        terminalInspectionDue[playerWithTrace] = nil\n        state:FireClient(playerWithTrace, \"RASTREIO_CANCELADO\",\n            \"Verificacao do terminal cancelada.\")\n    end\n    terminalLed.Color = Color3.fromRGB(76, 194, 143)\n    world:SetAttribute(\"CamerasOnline\", false)\n    world:SetAttribute(\"CameraSeconds\", 40)\n    player:SetAttribute(\"Posto17Sabotage\", true)\n    relayLight.Color = Color3.fromRGB(229, 69, 53)\n    state:FireClient(player, \"RELE\", \"Cameras desativadas por 40 segundos.\")\n    print(\"[POSTO17 CAMERA] RELE CORTADO:\", player.Name)\nend)\n\nlocal function cameraPart(index, position, baseDirection, phase)\n    local body = part(\"Camera_\" .. index, Vector3.new(2.3, 1.7, 1.9),\n        position, Color3.fromRGB(80, 97, 110), Enum.Material.Metal, false)\n    body.CanQuery = false\n    body.CanTouch = false\n    local lens = part(\"LenteCamera_\" .. index, Vector3.new(0.8, 0.65, 0.15),\n        position, Color3.fromRGB(241, 92, 70), Enum.Material.Neon, false)\n    lens.CanQuery = false\n    lens.CanTouch = false\n    local beam = Instance.new(\"SpotLight\")\n    beam.Face = Enum.NormalId.Front\n    beam.Angle = 48\n    beam.Range = 21\n    beam.Brightness = 1.1\n    beam.Color = Color3.fromRGB(226, 77, 64)\n    beam.Parent = body\n    body:SetAttribute(\"Active\", true)\n    body:SetAttribute(\"Detection\", 0)\n    body:SetAttribute(\"CameraId\", index)\n    table.insert(cameras, {id = \"CAM\" .. index, body = body, lens = lens,\n        light = beam, direction = baseDirection, phase = phase,\n        progress = {}, lastReported = {}})\nend\n\ncameraPart(1, Vector3.new(-37, 7, 0), Vector3.new(0, 0, 1), 0)\ncameraPart(2, Vector3.new(39, 7, 29), Vector3.new(0, 0, -1), 1.7)\n\nLighting.ClockTime=1.7\nLighting.Brightness=1.35\nLighting.FogStart=66\nLighting.FogEnd=180\nLighting.FogColor=Color3.fromRGB(23, 34, 47)\nLighting.Ambient=Color3.fromRGB(53, 67, 78)\nLighting.OutdoorAmbient=Color3.fromRGB(39, 50, 63)\nlocal cc = Lighting:FindFirstChild(\"Posto17Color\")\nif not cc then\n    cc = Instance.new(\"ColorCorrectionEffect\")\n    cc.Name = \"Posto17Color\"\n    cc.Parent = Lighting\nend\ncc.Saturation = -0.12\ncc.Contrast = 0.065\ncc.Brightness = 0.025\nlocal legacyLamps = {}\nfor _,pos in ipairs({\n    Vector3.new(-38,10,-31),Vector3.new(3,10,25),\n    Vector3.new(42,10,-34),Vector3.new(-40,10,33)\n}) do\n    local lamp=part(\"Luminária\",Vector3.new(2,.5,2),pos,Color3.fromRGB(220,205,145),Enum.Material.Neon,false)\n    local light=Instance.new(\"PointLight\")\n    light.Range=25\n    light.Brightness=1.3\n    light.Color=Color3.fromRGB(246,221,158)\n    light.Parent=lamp\n    table.insert(legacyLamps, {part = lamp, light = light})\nend\n\n-- Acabamento PS1 industrial: apenas pecas simples; nao interfere nas rotas.\nlocal function decoration(name, size, pos, color, material)\n    local item = part(name, size, pos, color, material, false)\n    item.CanQuery = false\n    item.CanTouch = false\n    return item\nend\n\nfor _, z in ipairs({-42, -15, 14, 40}) do\n    decoration(\"TrilhoLateral\", Vector3.new(0.5, 0.09, 11),\n        Vector3.new(-52.5, 0.1, z), Color3.fromRGB(106, 45, 42),\n        Enum.Material.Neon)\n    decoration(\"TrilhoLateral\", Vector3.new(0.5, 0.09, 11),\n        Vector3.new(52.5, 0.1, z), Color3.fromRGB(106, 45, 42),\n        Enum.Material.Neon)\nend\nfor _, z in ipairs({-37, -25, -13, -1, 11, 23, 35}) do\n    decoration(\"GradeDePiso\", Vector3.new(5, 0.08, 0.18),\n        Vector3.new(1, 0.1, z), Color3.fromRGB(61, 73, 82),\n        Enum.Material.Metal)\nend\nfor _, x in ipairs({-47, -39, -31}) do\n    decoration(\"SinalExtracao\", Vector3.new(2.5, 0.08, 0.22),\n        Vector3.new(x, 0.19, 29), Color3.fromRGB(63, 198, 139),\n        Enum.Material.Neon)\nend\nfor _, x in ipairs({38, 43, 48}) do\n    decoration(\"SinalDePerigo\", Vector3.new(1.5, 0.08, 0.25),\n        Vector3.new(x, 0.15, -44.5), Color3.fromRGB(197, 64, 46),\n        Enum.Material.Neon)\nend\n\nlocal function billboard(name, parentPart, words, color, offset)\n    local gui = Instance.new(\"BillboardGui\")\n    gui.Name = name\n    gui.Size = UDim2.fromOffset(112, 18)\n    gui.StudsOffsetWorldSpace = offset or Vector3.new(0, 4, 0)\n    gui.MaxDistance = 17\n    gui.AlwaysOnTop = false\n    gui.Parent = parentPart\n    local textLabel = Instance.new(\"TextLabel\")\n    textLabel.Size = UDim2.fromScale(1, 1)\n    textLabel.BackgroundTransparency = 1\n    textLabel.BorderSizePixel = 0\n    textLabel.Font = Enum.Font.GothamMedium\n    textLabel.TextSize = 11\n    textLabel.TextTransparency = 0.18\n    textLabel.TextColor3 = Color3.fromRGB(230, 233, 232)\n    textLabel.Text = words\n    textLabel.Parent = gui\nend\n\nbillboard(\"PlacaTerminal\", objective, \"TERMINAL\",\n    Color3.fromRGB(230, 230, 230), Vector3.new(0, 4, 0))\nbillboard(\"PlacaExtracao\", extraction, \"EXTRACAO\",\n    Color3.fromRGB(230, 230, 230), Vector3.new(0, 2.2, 0))\n\n-- Sentinelas com patrulhas em formato de capsula: duas retas e curvas nas extremidades.\n-- A frente (e os olhos) acompanha SEMPRE a tangente da rota.\nlocal VISUAL_RANGE = 22\nlocal CROUCH_RANGE = 12\nlocal HALF_FOV_COS = math.cos(math.rad(30))\n\nlocal patrols = {\n    {centerX = -24, radius = 3, lowZ = -36, highZ = 5, speed = 5},\n    {centerX = -6, radius = 2, lowZ = -34, highZ = 31, speed = 5},\n    {centerX = 49, radius = 1.5, lowZ = -32, highZ = 31, speed = 5},\n    -- Ronda do perímetro oeste: longe das portas do arquivo e da extração.\n    {centerX = -47, radius = 1.6, lowZ = -21, highZ = 2, speed = 4.4},\n}\n\nlocal function capsuleAt(patrol, distance)\n    local r = patrol.radius\n    local straight = patrol.highZ - patrol.lowZ\n    local arc = math.pi * r\n    local perimeter = 2 * straight + 2 * arc\n    local s = distance % perimeter\n    local x, z, dx, dz\n\n    if s < straight then\n        x, z, dx, dz = patrol.centerX + r, patrol.lowZ + s, 0, 1\n    elseif s < straight + arc then\n        local theta = (s - straight) / r\n        x, z = patrol.centerX + r * math.cos(theta), patrol.highZ + r * math.sin(theta)\n        dx, dz = -math.sin(theta), math.cos(theta)\n    elseif s < 2 * straight + arc then\n        local u = s - straight - arc\n        x, z, dx, dz = patrol.centerX - r, patrol.highZ - u, 0, -1\n    else\n        local theta = math.pi + (s - 2 * straight - arc) / r\n        x, z = patrol.centerX + r * math.cos(theta), patrol.lowZ + r * math.sin(theta)\n        dx, dz = -math.sin(theta), math.cos(theta)\n    end\n\n    return Vector3.new(x, 2, z), Vector3.new(dx, 0, dz)\nend\n\nlocal guards = {}\nfor i, patrol in ipairs(patrols) do\n    local initialPos, initialForward = capsuleAt(patrol, 0)\n    local g = part(\"Sentinela_\" .. i, Vector3.new(3,4,3), initialPos,\n        Color3.fromRGB(77, 89, 99), Enum.Material.Metal, false)\n    -- O corpo solido bloqueia o jogador; olhos e pupilas nao colidem.\n    g.CanCollide = true\n    g.CanQuery = false\n    g.CanTouch = false\n    local modifier = Instance.new(\"PathfindingModifier\")\n    modifier.PassThrough = true\n    modifier.Parent = g\n    g.CFrame = CFrame.lookAt(initialPos, initialPos + initialForward)\n\n    local eyes = {}\n    for _, x in ipairs({-0.62, 0.62}) do\n        local eye = part(\"Olho_\" .. i, Vector3.new(0.48, 0.48, 0.24),\n            initialPos, Color3.fromRGB(252, 198, 73), Enum.Material.Neon, false)\n        eye.Shape = Enum.PartType.Ball\n        eye.CanQuery = false\n        eye.CanTouch = false\n        table.insert(eyes, {part = eye, offset = CFrame.new(x, 2.46, -0.87)})\n\n        local pupil = part(\"Pupila_\" .. i, Vector3.new(0.18, 0.20, 0.10),\n            initialPos, Color3.fromRGB(25, 29, 35), Enum.Material.SmoothPlastic, false)\n        pupil.Shape = Enum.PartType.Ball\n        pupil.CanQuery = false\n        pupil.CanTouch = false\n        table.insert(eyes, {part = pupil, offset = CFrame.new(x, 2.46, -1.04)})\n    end\n\n    local light = Instance.new(\"SpotLight\")\n    light.Face = Enum.NormalId.Front\n    light.Angle = 60\n    light.Range = VISUAL_RANGE\n    light.Brightness = 0.75\n    light.Color = Color3.fromRGB(244, 204, 114)\n    light.Parent = g\n\n    local debugGui = Instance.new(\"BillboardGui\")\n    debugGui.Name = \"EstadoIA\"\n    debugGui.Enabled = false -- debug disponivel no Studio, oculto na missao real\n    debugGui.Size = UDim2.fromOffset(128, 26)\n    debugGui.StudsOffset = Vector3.new(0, 3.6, 0)\n    debugGui.AlwaysOnTop = false\n    debugGui.MaxDistance = 38\n    debugGui.Parent = g\n\n    local debugText = Instance.new(\"TextLabel\")\n    debugText.BackgroundColor3 = Color3.fromRGB(10, 15, 19)\n    debugText.BackgroundTransparency = 0.25\n    debugText.BorderSizePixel = 0\n    debugText.Size = UDim2.fromScale(1, 1)\n    debugText.Font = Enum.Font.Code\n    debugText.TextSize = 13\n    debugText.TextColor3 = Color3.fromRGB(245, 193, 103)\n    debugText.Text = \"PATRULHA\"\n    debugText.Parent = debugGui\n\n    -- Linguagem visual de infiltracao: ? percebeu algo, ! confirmou o alvo.\n    -- O simbolo pertence a cada sentinela, sem janelas ou avisos na tela.\n    local awarenessGui = Instance.new(\"BillboardGui\")\n    awarenessGui.Name = \"IndicadorPercepcao\"\n    awarenessGui.Adornee = g\n    awarenessGui.Size = UDim2.fromOffset(56, 64)\n    awarenessGui.StudsOffsetWorldSpace = Vector3.new(0, 3.55, 0)\n    awarenessGui.AlwaysOnTop = false\n    awarenessGui.MaxDistance = 58\n    awarenessGui.LightInfluence = 0\n    awarenessGui.Enabled = false\n    awarenessGui.Parent = g\n\n    local awarenessText = Instance.new(\"TextLabel\")\n    awarenessText.Name = \"Simbolo\"\n    awarenessText.Size = UDim2.fromScale(1, 1)\n    awarenessText.BackgroundTransparency = 1\n    awarenessText.Font = Enum.Font.GothamBlack\n    awarenessText.Text = \"?\"\n    awarenessText.TextScaled = true\n    awarenessText.TextColor3 = Color3.fromRGB(255, 204, 96)\n    awarenessText.TextStrokeColor3 = Color3.fromRGB(18, 14, 15)\n    awarenessText.TextStrokeTransparency = 0.05\n    awarenessText.Parent = awarenessGui\n\n    g:SetAttribute(\"AIState\", \"PATROL\")\n    local guard = {\n        body = g, patrol = patrol, progress = 0, eyes = eyes,\n        homeCFrame = g.CFrame, homeForward = initialForward,\n        id = i, state = \"PATROL\", stateSince = os.clock(), label = debugText,\n        forward = initialForward, targetPlayer = nil,\n        awarenessGui = awarenessGui, awarenessText = awarenessText,\n        suspicion = 0, suspectedPlayer = nil, lastMotion = Vector3.zero,\n        sweepPauseUntil = 0, lastNoticeAt = -100,\n        supportDue = nil, supportGeneration = 0, reportedPosition = nil,\n        sectorGoal = nil,\n        sweepIndex = 1, sweepGoal = nil, sweepDeadline = 0,\n        lastSeen = nil, lastVisualAt = -100, lastNoiseAt = -100,\n        nav = {}, navIndex = 1, navGoal = nil, navBusy = false,\n        navAt = -100, navRevision = 0, stuckTime = 0,\n        lastObstacle = \"-\", lastMoveAt = os.clock(), failedRoutes = 0,\n    }\n    table.insert(guards, guard)\nend\n\n-- IA de furtividade: patrulha -> investiga -> persegue -> busca -> retorna.\n-- Percepcao e movimento a 8 Hz; rotas recalculadas no maximo a cada 2s.\n-- PathfindingService cuida de desvios e Blockcast impede atravessar obstaculos.\nlocal VISION_COS = math.cos(math.rad(30))\nlocal VISION_STANDING = 22\nlocal VISION_CROUCHING = 12\nlocal HEARING_DISTANCE = 10\nlocal ALERT_LOST_AFTER = 2.6\nlocal SQUAD_SEARCH_DURATION = 15\nlocal AI_INTERVAL = 0.125\nlocal RADIO_UPDATE_INTERVAL = 1.5\nlocal REINFORCEMENT_DELAY = 0.8\nlocal NOTICE_THRESHOLD = 0.22\nlocal CONFIRM_THRESHOLD = 1\nlocal SUSPICION_FADE_RATE = 0.36\nlocal SOLO_SEARCH_DURATION = 13\n\n-- Apos cada alerta, os vigias ficam mais atentos; o nivel cai se\n-- houver tempo suficiente sem novas ocorrencias (limite 0 a 3).\nlocal alertLevel = 0\nlocal lastAlertAt = -100\nworld:SetAttribute(\"AlertLevel\", 0)\nworld:SetAttribute(\"MissionVersion\", \"2.9.1-visual-polish\")\nworld:SetAttribute(\"IncidentReports\", 0)\nworld:SetAttribute(\"RadarJammed\", false)\n\n-- O grupo compartilha apenas a ULTIMA observacao real.\n-- Nenhum guarda recebe a posicao atual se ninguem estiver vendo o jogador.\nlocal squad = {\n    active = false,\n    target = nil,\n    lastKnown = nil,\n    lastSeenAt = -100,\n    lastReportAt = -100,\n    generation = 0,\n}\n\nlocal COLOR_BY_STATE = {\n    PATROL = Color3.fromRGB(77, 89, 99),\n    INVESTIGATE = Color3.fromRGB(145, 118, 69),\n    CHASE = Color3.fromRGB(165, 72, 60),\n    WATCH = Color3.fromRGB(166, 103, 65),\n    SEARCH = Color3.fromRGB(125, 105, 154),\n    REINFORCE = Color3.fromRGB(158, 108, 58),\n    RETURN = Color3.fromRGB(78, 103, 106),\n}\n\nlocal TEXT_BY_STATE = {\n    PATROL = \"PATRULHA\",\n    INVESTIGATE = \"INVESTIGANDO\",\n    CHASE = \"PERSEGUINDO\",\n    WATCH = \"CERCANDO\",\n    SEARCH = \"PROCURANDO\",\n    REINFORCE = \"REFORCO\",\n    RETURN = \"RETORNANDO\",\n}\n\n-- Pontos de interceptacao deste mapa: mais util do que mandar um\n-- reforco atravessar a instalacao inteira antes que o alerta termine.\nlocal sectorIntercept = {\n    [1] = Vector3.new(-18, 2, 15),\n    [2] = Vector3.new(-3, 2, 12),\n    [3] = Vector3.new(22, 2, -28),\n    [4] = Vector3.new(-40, 2, 1),\n}\n\nlocal lastCaught = {}\nlocal lastMessage = {}\n\nlocal function horizontal(vector)\n    return Vector3.new(vector.X, 0, vector.Z)\nend\n\nlocal function flatDistance(a, b)\n    return horizontal(a-b).Magnitude\nend\n\nlocal function clearNavigation(guard)\n    guard.navRevision += 1\n    guard.nav = {}\n    guard.navIndex = 1\n    guard.navGoal = nil\n    guard.stuckTime = 0\nend\n\nlocal function setState(guard, name, now)\n    if not Rules.active(guard.life) then return end\n    if guard.state == name then return end\n    guard.state = name\n    guard.stateSince = now\n    guard.body:SetAttribute(\"AIState\", name)\n    if name == \"SEARCH\" then\n        if guard.stateSince and guard.lastSeen\n            and (guard.targetPlayer ~= nil) and guard.lastMotion then\n            local drift = horizontal(guard.lastMotion) * 0.35\n            if drift.Magnitude > 6 then drift = drift.Unit * 6 end\n            guard.lastSeen += drift\n        end\n        guard.scanForward = guard.forward\n        guard.sweepIndex = 1\n        guard.sweepGoal = nil\n        guard.sweepDeadline = 0\n        guard.sweepPauseUntil = 0\n    end\n    guard.body.Color = COLOR_BY_STATE[name]\n    guard.label.Text = TEXT_BY_STATE[name]\n    guard.label.TextColor3 = name == \"CHASE\"\n        and Color3.fromRGB(245, 120, 100)\n        or Color3.fromRGB(245, 193, 103)\n    clearNavigation(guard)\nend\n\nlocal function updateAwarenessIcon(guard)\n    local serious = guard.state == \"CHASE\" or guard.state == \"WATCH\"\n    local suspicious = guard.state == \"INVESTIGATE\"\n        or guard.state == \"SEARCH\" or guard.state == \"REINFORCE\"\n        or guard.suspicion >= NOTICE_THRESHOLD\n    guard.awarenessGui.Enabled = serious or suspicious\n    guard.awarenessText.Text = serious and \"!\" or \"?\"\n    guard.awarenessText.TextColor3 = serious\n        and Color3.fromRGB(255, 79, 73)\n        or Color3.fromRGB(255, 205, 100)\nend\n\nlocal function messagePlayer(player, kind, detail, cooldown)\n    local now = os.clock()\n    local key = tostring(player.UserId) .. kind\n    if now - (lastMessage[key] or -100) >= (cooldown or 4) then\n        lastMessage[key] = now\n        state:FireClient(player, kind, detail)\n    end\nend\n\n-- Pedra sonora, nunca causa dano: desvia os vigias para o impacto.\nlocal lastStoneAt = {}\nlocal stoneCount = {}\nlocal lastResupplyAt = {}\nlocal function resetInventory(player)\n    stoneCount[player], lastStoneAt[player], lastResupplyAt[player] = 3, -100, -100\n    player:SetAttribute(\"Posto17Keycard\", false)\n    player:SetAttribute(\"Posto17DoorCode\", nil)\n    player:SetAttribute(\"Posto17SecretIntel\", false)\n    player:SetAttribute(\"Posto17Knockouts\", 0)\n    player:SetAttribute(\"Posto17Kills\", 0)\n    player:SetAttribute(\"Posto17Dragging\", false)\n    player:SetAttribute(\"Posto17Blackout\", false)\nend\nlocal function watchInventory(player)\n    resetInventory(player)\n    player.CharacterAdded:Connect(function() resetInventory(player) end)\nend\nfor _, player in ipairs(Players:GetPlayers()) do watchInventory(player) end\nPlayers.PlayerAdded:Connect(watchInventory)\nPlayers.PlayerRemoving:Connect(function(player)\n    stoneCount[player], lastStoneAt[player], lastResupplyAt[player], lastCaught[player] = nil, nil, nil, nil\n    for _, device in ipairs(cameras) do\n        device.progress[player], device.lastReported[player] = nil, nil\n    end\nend)\n\nsupplyPrompt.Triggered:Connect(function(player)\n    if completed[player] or player:GetAttribute(\"Posto17Hidden\") then return end\n    if not playerNear(player, supply.Position, 10) then return end\n    local count = stoneCount[player] or 3\n    if count >= 3 then\n        state:FireClient(player, \"PEDRAS_CHEIAS\", \"Voce ja possui 3 pedras.\")\n        return\n    end\n    local now = os.clock()\n    if now - (lastResupplyAt[player] or -100) < 60 then\n        state:FireClient(player, \"RECARGA\", \"Caixa sem mais pedras por enquanto.\")\n        return\n    end\n    lastResupplyAt[player] = now\n    count = math.min(3, count + 2)\n    stoneCount[player] = count\n    player:SetAttribute(\"Posto17Stones\", count)\n    state:FireClient(player, \"SUPRIMENTOS\", \"Pedras recuperadas: \" .. count .. \"/3.\")\n    print(\"[POSTO17 SUPRIMENTOS]\", player.Name, count)\nend)\n\nlocal function playLocalSound(parent, soundId, volume, speed)\n    local sound = Instance.new(\"Sound\")\n    sound.Name = \"EfeitoPosto17\"\n    sound.SoundId = soundId\n    sound.Volume = volume\n    sound.PlaybackSpeed = speed or 1\n    sound.RollOffMaxDistance = 36\n    sound.Parent = parent\n    sound:Play()\n    Debris:AddItem(sound, 3)\nend\n\nlocal noiseRay = RaycastParams.new()\nnoiseRay.FilterType = Enum.RaycastFilterType.Exclude\nnoiseRay.RespectCanCollide = true\n\nlocal sensors -- criado quando todos os sistemas de seguranca estiverem registrados\nlocal function noiseAt(point, now, maxRange, kind, sourceBody)\n    local reached = 0\n    for _, guard in ipairs(guards) do\n        if Rules.active(guard.life) and guard.state ~= \"CHASE\" and guard.state ~= \"WATCH\" then\n            local distance = flatDistance(guard.body.Position, point)\n            local from = guard.body.Position + Vector3.new(0, 0.5, 0)\n            noiseRay.FilterDescendantsInstances = {guard.body}\n            local obstacle = workspace:Raycast(from, point - from, noiseRay)\n            local range = (maxRange or (27 + alertLevel * 2)) * (obstacle and 0.62 or 1)\n            if distance < range then\n                guard.lastSeen = point\n                guard.lastMotion = Vector3.zero\n                guard.lastNoiseAt = now\n                guard.suspicion = math.max(guard.suspicion, NOTICE_THRESHOLD)\n                guard.targetPlayer = nil\n                setState(guard, \"INVESTIGATE\", now)\n                reached += 1\n            end\n        end\n    end\n    if kind == \"LOCKER\" and sensors then\n        sensors:hearLocker(point, now, sourceBody)\n    end\n    print(\"[POSTO17 RUIDO] investigado por \" .. reached .. \" guardas\")\nend\n\nstoneRemote.OnServerEvent:Connect(function(player, aim)\n    if typeof(aim) ~= \"Vector3\" or aim.X ~= aim.X or aim.Y ~= aim.Y or aim.Z ~= aim.Z\n        or aim.Magnitude > 10000 then return end\n    if completed[player] or player:GetAttribute(\"Posto17Hidden\") then return end\n    local now = os.clock()\n    if now - (lastStoneAt[player] or -100) < 1.3 then return end\n    if (stoneCount[player] or 3) <= 0 then return end\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    local hum = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if not root or not hum or hum.Health <= 0 then return end\n\n    lastStoneAt[player] = now\n    stoneCount[player] = (stoneCount[player] or 3) - 1\n    player:SetAttribute(\"Posto17Stones\", stoneCount[player])\n    local origin = root.Position + Vector3.new(0, 1.4, 0)\n    local direction = Vector3.new(aim.X - origin.X, 0, aim.Z - origin.Z)\n    if direction.Magnitude < 1 then\n        direction = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)\n    end\n    if direction.Magnitude < 0.01 then return end\n    direction = direction.Unit * math.min(28, direction.Magnitude)\n    local cast = RaycastParams.new()\n    cast.FilterType = Enum.RaycastFilterType.Exclude\n    cast.FilterDescendantsInstances = {character}\n    cast.RespectCanCollide = true\n    local hit = workspace:Raycast(origin, direction, cast)\n    local point = hit and hit.Position - direction.Unit * 0.8 or origin + direction\n    local landing = Vector3.new(point.X, 0.6, point.Z)\n\n    local pebble = part(\"Distração\", Vector3.new(0.8, 0.8, 0.8),\n        origin, Color3.fromRGB(172, 180, 169), Enum.Material.Slate, false)\n    pebble.Shape = Enum.PartType.Ball\n    pebble.CanQuery = false\n    pebble.CanTouch = false\n    Debris:AddItem(pebble, 2.5)\n    local mid = (origin + landing) * 0.5 + Vector3.new(0, 5.5, 0)\n    task.spawn(function()\n        local going = TweenService:Create(pebble,\n            TweenInfo.new(0.25, Enum.EasingStyle.Quad, Enum.EasingDirection.Out),\n            {Position = mid})\n        going:Play()\n        going.Completed:Wait()\n        if not pebble.Parent then return end\n        local falling = TweenService:Create(pebble,\n            TweenInfo.new(0.32, Enum.EasingStyle.Quad, Enum.EasingDirection.In),\n            {Position = landing})\n        falling:Play()\n        falling.Completed:Wait()\n        if not pebble.Parent then return end\n        playLocalSound(pebble, \"rbxasset://sounds/action_jump_land.mp3\", 0.65, 0.72)\n        noiseAt(landing, os.clock())\n        state:FireClient(player, \"PEDRA\", \"Impacto: vigias proximos investigando.\")\n    end)\nend)\n\n-- O primeiro vigia que avista chama reforcos; os demais recebem somente\n-- um relato por radio, com atraso (em vez de teletransporte/conhecimento magico).\nlocal function broadcastSighting(spotter, player, position, now)\n    if not Rules.radioCanSend(world:GetAttribute(\"RadioOnline\") ~= false,\n        Rules.active(spotter.life), true) then return end\n    if not spotter.radioDue then\n        spotter.radioDue = now + 2\n        spotter.body:SetAttribute(\"CallingRadio\", true)\n    end\n    if now < spotter.radioDue then return end\n    spotter.body:SetAttribute(\"CallingRadio\", false)\n    local first = not squad.active or squad.target ~= player\n    if first then\n        squad.generation += 1\n        alertLevel = math.min(3, alertLevel + 1)\n        alertsByPlayer[player] = (alertsByPlayer[player] or 0) + 1\n        lastAlertAt = now\n        world:SetAttribute(\"AlertLevel\", alertLevel)\n        squad.active = true\n        world:SetAttribute(\"RadarJammed\", true)\n        squad.target = player\n        squad.lastKnown = position\n        squad.lastSeenAt = now\n        squad.lastReportAt = now\n        local dispatched = 0\n        for _, ally in ipairs(guards) do\n            if Rules.active(ally.life) and ally ~= spotter and ally.state ~= \"CHASE\"\n                and dispatched < Rules.MAX_REINFORCEMENTS then\n                dispatched += 1\n                ally.supportDue = now + REINFORCEMENT_DELAY + (ally.id - 1) * 0.7\n                ally.supportGeneration = squad.generation\n                if flatDistance(ally.body.Position, position) > 35 then\n                    -- Guardas distantes fecham corredores do seu setor.\n                    ally.sectorGoal = sectorIntercept[ally.id]\n                    ally.reportedPosition = ally.sectorGoal\n                else\n                    ally.sectorGoal = nil\n                    ally.reportedPosition = position\n                end\n            end\n        end\n        world:SetAttribute(\"Reinforcements\", dispatched)\n        messagePlayer(player, \"REFORCOS\", \"Alerta por radio! Reforcos a caminho.\", 12)\n        playLocalSound(spotter.body, \"rbxasset://sounds/action_jump.mp3\", 0.35, 1.45)\n        print(\"[POSTO17 RADIO] ALERTA: sentinela \" .. spotter.id .. \" chamou reforcos\")\n    else\n        squad.lastSeenAt = now\n        if now - squad.lastReportAt >= RADIO_UPDATE_INTERVAL then\n            squad.lastKnown = position\n            squad.lastReportAt = now\n        end\n    end\nend\n\nlocal function endSquadAlert(now)\n    if not squad.active then return end\n    squad.active = false\n    -- Evita liberar o radar por um frame se ainda ha perseguidor local.\n    world:SetAttribute(\"RadarJammed\", Rules.radarBlocked(false, guards))\n    world:SetAttribute(\"Reinforcements\", 0)\n    squad.target = nil\n    squad.lastKnown = nil\n    for _, ally in ipairs(guards) do\n        ally.supportDue = nil\n        ally.reportedPosition = nil\n        ally.sectorGoal = nil\n        if ally.state == \"REINFORCE\" or ally.state == \"SEARCH\" then\n            setState(ally, \"RETURN\", now)\n        end\n    end\n    print(\"[POSTO17 RADIO] AREA LIBERADA: retomando patrulha\")\nend\n\nlocal visionParams = RaycastParams.new()\nvisionParams.FilterType = Enum.RaycastFilterType.Exclude\nvisionParams.RespectCanCollide = true\n\n-- Volumes de visibilidade: amostras dentro do corpo e baixas para\n-- postura deitada. Uma caixa realmente oculta o avatar deitado atras dela.\nlocal groundParams = RaycastParams.new()\ngroundParams.FilterType = Enum.RaycastFilterType.Exclude\ngroundParams.RespectCanCollide = true\n\nlocal function visibleBodyPoints(player, character, root)\n    groundParams.FilterDescendantsInstances = {character}\n    local ground = workspace:Raycast(root.Position + Vector3.new(0, 2, 0),\n        Vector3.new(0, -9, 0), groundParams)\n    local floorY = ground and ground.Position.Y or (root.Position.Y - 2.5)\n    local right = horizontal(root.CFrame.RightVector)\n    local ahead = horizontal(root.CFrame.LookVector)\n    local p = Vector3.new(root.Position.X, floorY, root.Position.Z)\n    local isProne = player:GetAttribute(\"Posto17Prone\") == true\n    local isCrouched = player:GetAttribute(\"Posto17Crouched\") == true\n\n    if isProne then\n        return {\n            p + Vector3.new(0, 0.72, 0),\n            p + Vector3.new(0, 1.12, 0) + ahead * 1.1,\n            p + Vector3.new(0, 0.8, 0) - ahead * 1.1,\n            p + Vector3.new(0, 0.9, 0) + right * 0.42,\n        }\n    elseif isCrouched then\n        return {\n            p + Vector3.new(0, 0.75, 0),\n            p + Vector3.new(0, 1.22, 0),\n            p + Vector3.new(0, 1.67, 0),\n            p + Vector3.new(0, 1.12, 0) + right * 0.36,\n        }\n    else\n        local head = character:FindFirstChild(\"Head\")\n        local torso = character:FindFirstChild(\"UpperTorso\")\n            or character:FindFirstChild(\"Torso\")\n        return {\n            head and head.Position or p + Vector3.new(0, 4.5, 0),\n            torso and torso.Position or p + Vector3.new(0, 3.0, 0),\n            root.Position,\n            p + Vector3.new(0, 2.4, 0) + right * 0.5,\n        }\n    end\nend\n\nlocal function seesPlayer(guard, player)\n    if not Rules.active(guard.life) then return false, nil end\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if not root or not humanoid or humanoid.Health <= 0 or completed[player]\n        or player:GetAttribute(\"Posto17Hidden\") == true then\n        return false, nil\n    end\n\n    local eyeOrigin = guard.body.Position + Vector3.new(0, 0.5, 0)\n        + guard.forward * 1.55\n    local offset = horizontal(root.Position - eyeOrigin)\n    local distance = offset.Magnitude\n    local crouched = player:GetAttribute(\"Posto17Crouched\") == true\n    local prone = player:GetAttribute(\"Posto17Prone\") == true\n    local range = (prone and 9 or (crouched and VISION_CROUCHING or VISION_STANDING))\n        + alertLevel * (crouched and 1 or 2)\n    if crouched and inShadow(root.Position) and not player:GetAttribute(\"Posto17Flashlight\") then\n        range = math.min(range, 5)\n    end\n    -- A escuridao diminui a visao das sentinelas. Lanternas portateis\n    -- continuam operantes, e equipamento de seguranca mantem bateria.\n    if world:GetAttribute(\"PowerOnline\") == false\n        and not player:GetAttribute(\"Posto17Flashlight\") then\n        range *= 0.72\n    end\n    -- Durante a perseguicao a rota pode exigir deslocamento lateral.\n    -- Um alvo ja identificado permanece acompanhado enquanto VISIVEL;\n    -- o primeiro avistamento continua exigindo o cone frontal de 60 graus.\n    local tracking = (guard.state == \"CHASE\" or guard.state == \"WATCH\")\n        and guard.targetPlayer == player\n    if distance < 0.1 or distance > range\n        or (not tracking and guard.forward:Dot(offset.Unit) < VISION_COS) then\n        return false, root\n    end\n\n    -- Testar apenas o HumanoidRootPart fazia a caixa esconder o jogador\n    -- mesmo quando cabeca e ombros estavam totalmente visiveis.\n    -- Uma amostra visivel basta, mas paredes/caixas continuam bloqueando.\n    if math.abs(root.Position.Y - eyeOrigin.Y) > 12 then\n        return false, root\n    end\n    visionParams.FilterDescendantsInstances = {character, guard.body}\n\n    for _, targetPoint in ipairs(visibleBodyPoints(player, character, root)) do\n        local sightVector = targetPoint - eyeOrigin\n        if sightVector.Magnitude > 0.1\n            and workspace:Raycast(eyeOrigin, sightVector, visionParams) == nil then\n            return true, root\n        end\n    end\n    return false, root\nend\n\nlocal function nearestPatrolPoint(guard)\n    local p = guard.patrol\n    local length = 2 * (p.highZ - p.lowZ) + 2 * math.pi * p.radius\n    local bestD, bestPos, bestProgress = math.huge, nil, 0\n    for i = 0, 32 do\n        local progress = length * i / 32\n        local pos = capsuleAt(p, progress)\n        local distance = flatDistance(pos, guard.body.Position)\n        if distance < bestD then\n            bestD, bestPos, bestProgress = distance, pos, progress\n        end\n    end\n    return bestPos, bestProgress\nend\n\n-- Uma rota nova so e solicitada quando o destino muda significativamente,\n-- ou quando o caminho anterior ficou velho. ComputeAsync roda em outra tarefa.\n-- Quando o alvo fica no alto de uma caixa, a posicao X/Z dele nao e\n-- alcancavel no chao. Planeje para uma borda ACESSIVEL, nunca para o\n-- centro da caixa. O guarda fica em alerta enquanto continuar vendo.\nlocal function reachableTarget(guard, targetPosition)\n    for _, item in ipairs(world:GetChildren()) do\n        if item:IsA(\"BasePart\") and item.Name == \"Caixa\" then\n            local localPoint = item.CFrame:PointToObjectSpace(targetPosition)\n            local halfX, halfZ = item.Size.X / 2, item.Size.Z / 2\n            local top = item.Position.Y + item.Size.Y / 2\n            if math.abs(localPoint.X) <= halfX + 0.6\n                and math.abs(localPoint.Z) <= halfZ + 0.6\n                and targetPosition.Y > top + 0.5\n                and targetPosition.Y < top + 8 then\n\n                local margin = 2.9\n                local x = math.clamp(localPoint.X, -halfX, halfX)\n                local z = math.clamp(localPoint.Z, -halfZ, halfZ)\n                local options = {\n                    Vector3.new(halfX + margin, 0, z),\n                    Vector3.new(-halfX - margin, 0, z),\n                    Vector3.new(x, 0, halfZ + margin),\n                    Vector3.new(x, 0, -halfZ - margin),\n                }\n                local best = nil\n                local bestDistance = math.huge\n                for _, offset in ipairs(options) do\n                    local waypoint = item.CFrame:PointToWorldSpace(offset)\n                    waypoint = Vector3.new(waypoint.X, 2, waypoint.Z)\n                    local distance = flatDistance(guard.body.Position, waypoint)\n                    if distance < bestDistance then\n                        best, bestDistance = waypoint, distance\n                    end\n                end\n                return best\n            end\n        end\n    end\n    return Vector3.new(targetPosition.X, 2, targetPosition.Z)\nend\n\nlocal function requestRoute(guard, goal, now, force)\n    if guard.navBusy or guard.state == \"PATROL\" then return end\n    local changes = not guard.navGoal or flatDistance(goal, guard.navGoal) > 5\n    if not force and not changes and #guard.nav > 0 and now-guard.navAt < 4 then return end\n    -- Limite rigido evita pedidos de rota incessantes ao esbarrar.\n    if now - guard.navAt < 2.5 then return end\n\n    guard.navAt = now\n    guard.navGoal = goal\n    guard.navBusy = true\n    guard.navRevision += 1\n    local revision = guard.navRevision\n    local origin = guard.body.Position\n    task.spawn(function()\n        local route = PathfindingService:CreatePath({\n            AgentRadius = 2,\n            AgentHeight = 5,\n            AgentCanJump = false,\n            WaypointSpacing = 4,\n        })\n        local ok = pcall(function()\n            route:ComputeAsync(origin, goal)\n        end)\n        if guard.navRevision == revision then\n            if ok and route.Status == Enum.PathStatus.Success then\n                guard.failedRoutes = 0\n                guard.body:SetAttribute(\"NavStatus\", \"SUCCESS\")\n                local nextPoints = {}\n                for _, wp in ipairs(route:GetWaypoints()) do\n                    nextPoints[#nextPoints+1] = Vector3.new(wp.Position.X, 2, wp.Position.Z)\n                end\n                guard.nav = nextPoints\n                guard.navIndex = math.min(2, #nextPoints)\n                guard.body:SetAttribute(\"NavPoints\", #nextPoints)\n            else\n                -- Nunca atravessa a parede quando nao encontra caminho.\n                guard.failedRoutes += 1\n                guard.body:SetAttribute(\"NavStatus\", ok and tostring(route.Status) or \"ERROR\")\n                guard.nav = {}\n                guard.navIndex = 1\n                guard.body:SetAttribute(\"NavPoints\", 0)\n            end\n        end\n        guard.navBusy = false\n    end)\nend\n\nlocal collisionParams = RaycastParams.new()\ncollisionParams.FilterType = Enum.RaycastFilterType.Exclude\ncollisionParams.RespectCanCollide = true\n\nlocal function moveBody(guard, destination, speed, dt)\n    speed *= world:GetAttribute(\"GuardSpeedMultiplier\") or 1\n    local body = guard.body\n    local from = body.Position\n    local displacement = horizontal(destination - from)\n    local length = displacement.Magnitude\n    if length < 0.08 then return true end\n\n    local direction = displacement.Unit\n    local step = direction * math.min(length, speed*dt)\n    collisionParams.FilterDescendantsInstances = {body}\n    -- O cubo bloqueia jogadores. O teste de volume evita passar atraves de\n    -- paredes e caixas mesmo que o PathfindingService falhe.\n    local hit = workspace:Blockcast(\n        CFrame.new(from), Vector3.new(2.7, 3.55, 2.7), step, collisionParams\n    )\n    if hit then\n        guard.stuckTime += dt\n        guard.lastObstacle = hit.Instance.Name\n        guard.body:SetAttribute(\"BlockedBy\", hit.Instance.Name)\n        if guard.stuckTime > 0.65 then\n            guard.nav = {}\n            guard.navIndex = 1\n            guard.navGoal = nil\n            guard.stuckTime = 0\n            -- IMPORTANTE: manter navAt; sem isso ComputeAsync podia ser\n            -- chamado continuamente e travar a CPU.\n        end\n        return false\n    end\n\n    guard.lastMoveAt = os.clock()\n    guard.lastObstacle = \"-\"\n    guard.body:SetAttribute(\"BlockedBy\", \"-\")\n    guard.stuckTime = 0\n    local nextPos = from + step\n    guard.forward = direction\n    body.CFrame = CFrame.lookAt(nextPos, nextPos + direction)\n    return length <= speed * dt + 0.15\nend\n\nlocal function followRoute(guard, destination, speed, dt, now)\n    destination = reachableTarget(guard, destination)\n    local current = guard.body.Position\n    local direct = horizontal(destination-current)\n    local canDirect = false\n    if direct.Magnitude > 0.05 then\n        collisionParams.FilterDescendantsInstances = {guard.body}\n        canDirect = workspace:Blockcast(\n            CFrame.new(current), Vector3.new(2.7, 3.55, 2.7),\n            direct, collisionParams\n        ) == nil\n    end\n\n    if canDirect then\n        return moveBody(guard, destination, speed, dt)\n    end\n\n    requestRoute(guard, destination, now, false)\n    local waypoint = guard.nav[guard.navIndex]\n    while waypoint and flatDistance(current, waypoint) < 2 do\n        guard.navIndex += 1\n        waypoint = guard.nav[guard.navIndex]\n    end\n    if waypoint then\n        local reached = moveBody(guard, waypoint, speed, dt)\n        if reached then guard.navIndex += 1 end\n    end\n    return flatDistance(guard.body.Position, destination) < 2.4\nend\n\nlocal function catchPlayer(guard, player, now)\n    if player:GetAttribute(\"P17Queued\") then return false end\n    if operations then operations:drop(player) end\n    if now - (lastCaught[player] or -100) < 4 then return end\n    lastCaught[player] = now\n    local char = player.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    if not root then return end\n    captures[player] = (captures[player] or 0) + 1\n    dataTaken[player] = nil\n    terminalInspectionDue[player] = nil\n    terminalLed.Color = Color3.fromRGB(76, 194, 143)\n    player:SetAttribute(\"Posto17BonusIntel\", false)\n    stoneCount[player] = 3\n    player:SetAttribute(\"Posto17Stones\", 3)\n    mobility.clear(player)\n    setPosture(player, \"STAND\", true)\n    player:SetAttribute(\"Posto17Data\", false)\n    state:FireClient(player, \"DETECTADO\", \"A sentinela alcancou voce. Dados perdidos.\")\n    root.CFrame = spawn.CFrame + Vector3.new(0, 4, 0)\n    -- Captura encerra a busca coletiva: o jogador reinicia a missao.\n    endSquadAlert(now)\n    guard.targetPlayer = nil\n    guard.lastSeen = nil\n    setState(guard, \"RETURN\", now)\nend\n\n-- A visibilidade acumula suspeita. Uma espiada nao confirma a identidade\n-- imediatamente: movimento, distancia, agachamento e alerta alteram a taxa.\n-- Ouvindo passos, o vigia vai investigar, mas nunca ganha visao por som.\nlocal hearingRay = RaycastParams.new()\nhearingRay.FilterType = Enum.RaycastFilterType.Exclude\nhearingRay.RespectCanCollide = true\nlocal surfaceRay = RaycastParams.new()\nsurfaceRay.FilterType = Enum.RaycastFilterType.Exclude\nsurfaceRay.RespectCanCollide = true\n-- Cache de superficie evita recalcular a cada vigia (somente a cada 0.4s).\nlocal stepSurface = {}\nlocal function footstepMultiplier(player, root, now)\n    local cached = stepSurface[player]\n    if cached and now - cached.at < 0.4 then return cached.factor end\n    surfaceRay.FilterDescendantsInstances = {root.Parent}\n    local contact = workspace:Raycast(root.Position, Vector3.new(0, -6, 0), surfaceRay)\n    local material = contact and contact.Material and contact.Material.Name or \"Concrete\"\n    local factor = Rules.hearingMultiplier(material)\n    stepSurface[player] = {at = now, factor = factor}\n    return factor\nend\nPlayers.PlayerRemoving:Connect(function(player) stepSurface[player] = nil end)\n\nlocal function updateSenses(guard, dt, now)\n    local visiblePlayer, visibleRoot\n    local noisePlayer, noiseRoot\n    local nearestSight, nearestNoise = math.huge, math.huge\n    for _, player in ipairs(Players:GetPlayers()) do\n        if now - (lastCaught[player] or -100) > 4 then\n            local visible, root = seesPlayer(guard, player)\n            if root then\n                local distance = flatDistance(root.Position, guard.body.Position)\n                -- Se ja persegue alguem, nao troca de alvo por um passante.\n                local priority = (guard.targetPlayer == player\n                    and (guard.state == \"CHASE\" or guard.state == \"WATCH\"))\n                    and -1 or distance\n                if visible and priority < nearestSight then\n                    visiblePlayer, visibleRoot, nearestSight = player, root, priority\n                end\n\n                local humanoid = root.Parent:FindFirstChildOfClass(\"Humanoid\")\n                local moving = humanoid and humanoid.MoveDirection.Magnitude > 0.3\n                local quiet = player:GetAttribute(\"Posto17Crouched\") == true\n                local hearingRange = HEARING_DISTANCE + alertLevel * 1.5\n                if moving and not quiet and not completed[player]\n                    and not player:GetAttribute(\"Posto17Hidden\") then\n                    -- Metal repercute mais; superficies macias abafam passos.\n                    hearingRange *= footstepMultiplier(player, root, now)\n                    -- Obstaculos abafam os passos. Nao detecta pelo mapa todo.\n                    local source = guard.body.Position + Vector3.new(0, 0.5, 0)\n                    hearingRay.FilterDescendantsInstances = {guard.body, root.Parent}\n                    if workspace:Raycast(source, root.Position - source, hearingRay) then\n                        hearingRange *= 0.48\n                    end\n                    if distance < hearingRange and distance < nearestNoise then\n                        noisePlayer, noiseRoot, nearestNoise = player, root, distance\n                    end\n                end\n            end\n        end\n    end\n\n    if visiblePlayer and visibleRoot then\n        if guard.suspectedPlayer ~= visiblePlayer then\n            guard.suspectedPlayer = visiblePlayer\n            guard.suspicion = math.min(guard.suspicion, 0.14)\n        end\n        local d = flatDistance(visibleRoot.Position, guard.body.Position)\n        local character = visiblePlayer.Character\n        local hum = character and character:FindFirstChildOfClass(\"Humanoid\")\n        local moving = hum and hum.MoveDirection.Magnitude > 0.15\n        local crouched = visiblePlayer:GetAttribute(\"Posto17Crouched\") == true\n        local exposure = math.clamp(1.42 - d / 28, 0.36, 1.4)\n        exposure *= world:GetAttribute(\"DetectionMultiplier\") or 1\n        if world:GetAttribute(\"PowerOnline\") == false\n            and not visiblePlayer:GetAttribute(\"Posto17Flashlight\") then\n            exposure *= 0.63\n        end\n        if visiblePlayer:GetAttribute(\"Posto17Flashlight\") then exposure *= 1.5 end\n        if moving then exposure *= 1.28 end\n        if crouched then exposure *= 0.57 end\n        if visiblePlayer:GetAttribute(\"Posto17Prone\") then exposure *= 0.68 end\n        if alertLevel > 0 then exposure *= 1 + 0.15 * alertLevel end\n\n        if (operations and operations:recognizes(guard, visiblePlayer))\n            or ((guard.state == \"CHASE\" or guard.state == \"WATCH\")\n            and guard.targetPlayer == visiblePlayer) then\n            guard.suspicion = CONFIRM_THRESHOLD\n        else\n            guard.suspicion = math.min(CONFIRM_THRESHOLD,\n                guard.suspicion + dt * exposure)\n        end\n        guard.lastSeen = visibleRoot.Position\n        guard.lastMotion = horizontal(visibleRoot.AssemblyLinearVelocity)\n        guard.lastVisualAt = now\n        local elevated = visibleRoot.Position.Y - guard.body.Position.Y > 3.5\n\n        if guard.suspicion >= CONFIRM_THRESHOLD then\n            guard.identifiedPlayers = guard.identifiedPlayers or {}\n            guard.identifiedPlayers[visiblePlayer.UserId] = true\n            guard.targetPlayer = visiblePlayer\n            if guard.state == \"WATCH\" and not elevated then\n                setState(guard, \"CHASE\", now)\n            elseif guard.state ~= \"CHASE\" and guard.state ~= \"WATCH\" then\n                setState(guard, \"CHASE\", now)\n            end\n            broadcastSighting(guard, visiblePlayer, visibleRoot.Position, now)\n        elseif guard.suspicion >= NOTICE_THRESHOLD then\n            guard.lastNoticeAt = now\n            if guard.state == \"PATROL\" or guard.state == \"RETURN\"\n                or guard.state == \"SEARCH\"\n                or guard.state == \"REINFORCE\" then\n                setState(guard, \"INVESTIGATE\", now)\n            end\n        end\n    else\n        guard.suspicion = math.max(0, guard.suspicion - dt * SUSPICION_FADE_RATE)\n        if guard.suspicion == 0 then guard.suspectedPlayer = nil end\n        if (guard.state == \"PATROL\" or guard.state == \"RETURN\")\n            and noisePlayer and noiseRoot\n            and now - guard.lastNoiseAt > 4.5 then\n            guard.lastNoiseAt = now\n            guard.lastSeen = noiseRoot.Position\n            guard.lastMotion = Vector3.zero\n            guard.targetPlayer = nil\n            setState(guard, \"INVESTIGATE\", now)\n        end\n    end\n    guard.body:SetAttribute(\"Awareness\", math.floor(guard.suspicion * 100))\nend\n\n-- Setores deterministas, economicos e diferentes por sentinela.\nlocal sweepOffsets = {\n    {Vector3.new(7, 0, 1), Vector3.new(8, 0, 8),\n        Vector3.new(0, 0, 9), Vector3.new(-5, 0, 5)},\n    {Vector3.new(-7, 0, -1), Vector3.new(-8, 0, -8),\n        Vector3.new(0, 0, -9), Vector3.new(5, 0, -5)},\n    {Vector3.new(1, 0, 9), Vector3.new(9, 0, 0),\n        Vector3.new(-1, 0, -9), Vector3.new(-9, 0, 0)},\n    {Vector3.new(6, 0, 4), Vector3.new(0, 0, 9),\n        Vector3.new(-6, 0, 3), Vector3.new(0, 0, -7)},\n}\n\nlocal function sweepArea(guard, dt, now)\n    -- Investiga varios pontos ao redor da ULTIMA pista, parando para olhar.\n    -- Reforcos cobrem setores diferentes, sem receber posicao oculta.\n    local center = guard.lastSeen\n    if squad.active and guard.sectorGoal then\n        center = guard.sectorGoal\n    elseif squad.active and squad.lastKnown then\n        center = squad.lastKnown\n    end\n    if not center then\n        setState(guard, \"RETURN\", now)\n        return\n    end\n\n    if now < guard.sweepPauseUntil then\n        local baseline = guard.scanForward or guard.forward\n        local angle = math.atan2(baseline.Z, baseline.X)\n            + math.sin((now - guard.stateSince) * 2.8 + guard.id)\n            * math.rad(65)\n        local look = Vector3.new(math.cos(angle), 0, math.sin(angle))\n        guard.forward = look\n        guard.body.CFrame = CFrame.lookAt(guard.body.Position,\n            guard.body.Position + look)\n        return\n    end\n\n    local offsets = sweepOffsets[guard.id]\n    if guard.sweepIndex > #offsets then\n        if not squad.active then\n            setState(guard, \"RETURN\", now)\n            return\n        end\n        guard.sweepIndex = 1\n    end\n\n    if not guard.sweepGoal then\n        local offset = offsets[guard.sweepIndex]\n        guard.sweepGoal = Vector3.new(center.X + offset.X, 2, center.Z + offset.Z)\n        guard.sweepDeadline = now + 4.25\n    end\n    local reached = followRoute(guard, guard.sweepGoal, 6, dt, now)\n    if reached or now >= guard.sweepDeadline then\n        guard.sweepIndex += 1\n        guard.sweepGoal = nil\n        guard.sweepPauseUntil = now + (reached and 0.9 or 0.15)\n        -- Novo destino precisa de uma rota nova, nao herdar caminho velho.\n        clearNavigation(guard)\n    end\nend\n\nlocal function updateGuard(guard, dt, now)\n    if RunService:IsStudio() and guard.body:GetAttribute(\"StudioFreeze\") then return end\n    if not Rules.active(guard.life) then return end\n    updateSenses(guard, dt, now)\n    -- Enquanto repara o disjuntor, fica parado, mas continua percebendo o\n    -- jogador. Perseguicao ganha prioridade e cancela o conserto.\n    if guard.body:GetAttribute(\"RepairingPower\")\n        and guard.state ~= \"CHASE\" and guard.state ~= \"WATCH\" then return end\n    if now - guard.lastVisualAt > 1 then\n        guard.radioDue = nil\n        guard.body:SetAttribute(\"CallingRadio\", false)\n    end\n    if operations then operations:observe(guard, now) end\n    if facilities then facilities:observe(guard, now) end\n    if guard.supportDue and now >= guard.supportDue then\n        guard.supportDue = nil\n        if world:GetAttribute(\"RadioOnline\") ~= false and squad.active and guard.supportGeneration == squad.generation\n            and guard.state ~= \"CHASE\" then\n            guard.lastSeen = guard.reportedPosition\n            setState(guard, \"REINFORCE\", now)\n        end\n    end\n    local stateName = guard.state\n    if stateName == \"PATROL\" then\n        local nextProgress = guard.progress + dt * guard.patrol.speed\n        local pos, forward = capsuleAt(guard.patrol, nextProgress)\n        if moveBody(guard, pos, guard.patrol.speed + 0.5, dt) then\n            guard.progress = nextProgress\n        else\n            -- Avanca apenas se nao esbarrou em uma parede.\n            if guard.stuckTime == 0 then guard.progress = nextProgress end\n        end\n    elseif stateName == \"REINFORCE\" then\n        local destination = guard.reportedPosition or guard.lastSeen\n        if not squad.active or not destination then\n            setState(guard, \"RETURN\", now)\n        elseif followRoute(guard, destination, 7.4 + alertLevel * 0.4, dt, now)\n            or now - guard.stateSince > 8 then\n            -- Procura o setor da ultima observacao, nunca a posicao atual oculta.\n            guard.lastSeen = guard.sectorGoal or squad.lastKnown or destination\n            setState(guard, \"SEARCH\", now)\n        end\n    elseif stateName == \"INVESTIGATE\" then\n        local destination = guard.lastSeen\n        if not destination then\n            setState(guard, \"RETURN\", now)\n        elseif now - guard.stateSince < 0.65\n            and now - guard.lastVisualAt < 0.7 then\n            -- Primeiro confirma olhando; nao corre automaticamente ate quem\n            -- viu apenas de relance.\n            local gaze = horizontal(destination - guard.body.Position)\n            if gaze.Magnitude > 0.1 then\n                guard.forward = gaze.Unit\n                guard.body.CFrame = CFrame.lookAt(\n                    guard.body.Position, guard.body.Position + guard.forward)\n            end\n        elseif followRoute(guard, destination, 6.8, dt, now)\n            or now-guard.stateSince > 9 then\n            setState(guard, \"SEARCH\", now)\n        end\n    elseif stateName == \"WATCH\" then\n        local target = guard.targetPlayer\n        local character = target and target.Character\n        local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n        if not root or (target and completed[target])\n            or now - guard.lastVisualAt > ALERT_LOST_AFTER then\n            setState(guard, \"SEARCH\", now)\n        elseif root.Position.Y - guard.body.Position.Y <= 3.5 then\n            setState(guard, \"CHASE\", now)\n        else\n            -- Alvo elevado e visivel: manter cerco, sem correr contra a caixa.\n            local gaze = horizontal(root.Position - guard.body.Position)\n            if gaze.Magnitude > 0.1 then\n                guard.forward = gaze.Unit\n                guard.body.CFrame = CFrame.lookAt(\n                    guard.body.Position, guard.body.Position + guard.forward)\n            end\n        end\n    elseif stateName == \"CHASE\" then\n        local target = guard.targetPlayer\n        local character = target and target.Character\n        local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n        if target and completed[target] then\n            setState(guard, \"RETURN\", now)\n        elseif not root then\n            setState(guard, \"SEARCH\", now)\n        elseif now-guard.lastVisualAt > ALERT_LOST_AFTER then\n            setState(guard, \"SEARCH\", now)\n            messagePlayer(target, \"BUSCA\", \"O guarda perdeu voce e esta procurando.\", 7)\n        else\n            -- Persiste no ultimo local visto, ate obter uma nova linha de visao.\n            local destination = guard.lastSeen or root.Position\n            followRoute(guard, destination, 13.2 + alertLevel * 0.55, dt, now)\n            local elevated = root.Position.Y - guard.body.Position.Y > 3.5\n            local edge = reachableTarget(guard, destination)\n            if elevated and (flatDistance(guard.body.Position, edge) <= 4\n                or now - guard.lastMoveAt > 3) then\n                setState(guard, \"WATCH\", now)\n            end\n            -- Ao contornar caixas, o cubo continua OLHANDO para o alvo,\n            -- sem confundir direcao de caminhada com a direcao dos olhos.\n            local gaze = horizontal(destination - guard.body.Position)\n            if gaze.Magnitude > 0.1 then\n                guard.forward = gaze.Unit\n                guard.body.CFrame = CFrame.lookAt(\n                    guard.body.Position, guard.body.Position + guard.forward)\n            end\n            -- Nao capturar alguem EM CIMA da caixa de dentro do chao.\n            if flatDistance(guard.body.Position, root.Position) <= 3.4\n                and math.abs(guard.body.Position.Y - root.Position.Y) <= 3.5\n                and now - guard.lastVisualAt <= 0.5 then\n                visionParams.FilterDescendantsInstances = {character, guard.body}\n                if not workspace:Raycast(guard.body.Position,\n                    root.Position - guard.body.Position, visionParams) then\n                    catchPlayer(guard, target, now)\n                end\n            end\n        end\n    elseif stateName == \"SEARCH\" then\n        if squad.active or now - guard.stateSince < SOLO_SEARCH_DURATION then\n            sweepArea(guard, dt, now)\n        else\n            setState(guard, \"RETURN\", now)\n        end\n    elseif stateName == \"RETURN\" then\n        local home, progress = nearestPatrolPoint(guard)\n        if home and (flatDistance(guard.body.Position, home) < 2.6\n            or followRoute(guard, home, 6.5, dt, now)) then\n            guard.progress = progress\n            guard.targetPlayer = nil\n            guard.lastSeen = nil\n            setState(guard, \"PATROL\", now)\n        end\n    end\n    if now - guard.lastMoveAt < 0.3 and now - (guard.lastStepAt or -100) > 0.65 then\n        guard.lastStepAt = now\n        local footRay = RaycastParams.new()\n        footRay.FilterType = Enum.RaycastFilterType.Exclude\n        footRay.FilterDescendantsInstances = {guard.body}\n        footRay.RespectCanCollide = true\n        local floor = workspace:Raycast(guard.body.Position, Vector3.new(0,-5,0), footRay)\n        local wood = floor and (floor.Material == Enum.Material.Wood or floor.Material == Enum.Material.WoodPlanks)\n        playLocalSound(guard.body, \"rbxasset://sounds/action_footsteps_plastic.mp3\", 0.045, wood and 0.75 or 1.15)\n    end\n    updateAwarenessIcon(guard)\n    for _, eye in ipairs(guard.eyes) do\n        if not eye.isRigPart then\n            eye.part.CFrame = guard.body.CFrame * eye.offset\n        end\n    end\nend\n\n-- Protocolo de terminal: relatorio local, nunca uma localizacao magica\n-- do jogador. So dois guardas livres verificam o terminal comprometido.\nlocal function dispatchTerminalInspection(player, now)\n    if completed[player] or not dataTaken[player] then return end\n    if world:GetAttribute(\"CamerasOnline\") == false or world:GetAttribute(\"RadioOnline\") == false then return end\n    local available = {}\n    for _, guard in ipairs(guards) do\n        if Rules.active(guard.life) and guard.state ~= \"CHASE\" and guard.state ~= \"WATCH\"\n            and guard.state ~= \"REINFORCE\" and guard.supportDue == nil then\n            table.insert(available, {\n                guard = guard,\n                distance = flatDistance(guard.body.Position, objective.Position)\n            })\n        end\n    end\n    table.sort(available, function(a, b)\n        return a.distance < b.distance\n    end)\n    local assigned = 0\n    for i = 1, math.min(2, #available) do\n        local guard = available[i].guard\n        guard.targetPlayer = nil\n        guard.suspectedPlayer = nil\n        guard.suspicion = math.max(guard.suspicion, NOTICE_THRESHOLD)\n        guard.lastSeen = objective.Position\n        guard.lastMotion = Vector3.zero\n        guard.lastNoiseAt = now\n        setState(guard, \"INVESTIGATE\", now)\n        assigned += 1\n    end\n    terminalLed.Color = Color3.fromRGB(227, 80, 68)\n    state:FireClient(player, \"TERMINAL_CHECK\",\n        \"Verificacao no terminal iniciada.\")\n    print(\"[POSTO17 SEGURANCA] terminal verificado por\", assigned, \"guardas\")\nend\n\n-- Camera de seguranca: movimentacao lenta e investigacao pelo radio.\n-- Cada sensor exige 0.75 s de observacao continua para gerar alerta.\n-- Contato apenas por raio de visao real, nunca atraves de obstaculos.\nlocal cameraRay = RaycastParams.new()\ncameraRay.FilterType = Enum.RaycastFilterType.Exclude\ncameraRay.RespectCanCollide = true\n\nlocal function cameraSeesPlayer(device, player)\n    if completed[player] or player:GetAttribute(\"Posto17Hidden\") then return false end\n    local char = player.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    local head = char and char:FindFirstChild(\"Head\")\n    local humanoid = char and char:FindFirstChildOfClass(\"Humanoid\")\n    if not root or not humanoid or humanoid.Health <= 0 then return false end\n    if os.clock() - (lastCaught[player] or -100) <= 4 then return false end\n\n    local forward = device.body.CFrame.LookVector\n    local origin = device.body.Position + forward * 1.1\n    local direction = Vector3.new(root.Position.X - origin.X, 0,\n        root.Position.Z - origin.Z)\n    if direction.Magnitude < 0.1 then return false end\n    local crouched = player:GetAttribute(\"Posto17Crouched\") == true\n    local prone = player:GetAttribute(\"Posto17Prone\") == true\n    local range = (prone and 9 or (crouched and 13 or 21)) + alertLevel * 1.5\n    if crouched and inShadow(root.Position) and not player:GetAttribute(\"Posto17Flashlight\") then range = 5 end\n    if direction.Magnitude > range then return false end\n    if direction.Unit:Dot(forward) < math.cos(math.rad(24)) then return false end\n\n    cameraRay.FilterDescendantsInstances = {char, device.body, device.lens}\n    for _, point in ipairs(visibleBodyPoints(player, char, root)) do\n        if workspace:Raycast(origin, point - origin, cameraRay) == nil then\n            return true\n        end\n    end\n    return false\nend\n\nlocal function updateCameras(dt, now)\n    local active = now >= cameraDisabledUntil\n    if world:GetAttribute(\"CamerasOnline\") ~= active then\n        world:SetAttribute(\"CamerasOnline\", active)\n        if active then\n            relayLight.Color = Color3.fromRGB(47, 218, 203)\n            print(\"[POSTO17 CAMERA] REATIVADAS\")\n            for _, player in ipairs(Players:GetPlayers()) do\n                state:FireClient(player, \"CAMERAS_ON\", \"Vigilancia reativada.\")\n            end\n        end\n    end\n    for index, device in ipairs(cameras) do\n        local sweep = math.sin(now * 0.42 + device.phase) * math.rad(56)\n        local base = device.direction\n        local angle = math.atan2(base.Z, base.X) + sweep\n        local forward = Vector3.new(math.cos(angle), 0, math.sin(angle))\n        local cf = CFrame.lookAt(device.body.Position,\n            device.body.Position + forward)\n        device.body.CFrame = cf\n        device.lens.CFrame = cf * CFrame.new(0, 0, -1.02)\n        device.light.Enabled = active\n        device.body:SetAttribute(\"Active\", active)\n        device.lens.Color = active and Color3.fromRGB(245, 89, 69)\n            or Color3.fromRGB(63, 151, 137)\n        device.body.Color = active and Color3.fromRGB(80, 97, 110)\n            or Color3.fromRGB(43, 83, 80)\n        local greatest = 0\n        for _, player in ipairs(Players:GetPlayers()) do\n            local current = device.progress[player] or 0\n            if active and cameraSeesPlayer(device, player) then\n                current = math.min(1, current + dt / 0.75 * (world:GetAttribute(\"DetectionMultiplier\") or 1))\n            else\n                current = math.max(0, current - dt * 2)\n            end\n            device.progress[player] = current\n            greatest = math.max(greatest, current)\n            if active and current >= 1 then\n                local observedRoot = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n                if observedRoot then broadcastSighting(device, player, observedRoot.Position, now) end\n                local previous = device.lastReported[player] or -100\n                if now - previous > 3 then\n                    device.lastReported[player] = now\n                    local root = player.Character and\n                        player.Character:FindFirstChild(\"HumanoidRootPart\")\n                    if root then\n                        messagePlayer(player, \"CAMERA\",\n                            \"Camera \" .. index .. \" detectou voce!\", 4)\n                        print(\"[POSTO17 CAMERA] DETECTOU\", index, player.Name)\n                    end\n                end\n            end\n        end\n        if greatest == 0 then\n            device.radioDue = nil\n            device.body:SetAttribute(\"CallingRadio\", false)\n        end\n        device.body:SetAttribute(\"Detection\", math.floor(greatest * 100))\n    end\nend\n\n-- Reinicio somente depois de uma extracao concluida.\nrestartRemote.OnServerEvent:Connect(function(player)\n    if not completed[player] then return end\n    local char = player.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n    if not root or not hum or hum.Health <= 0 then return end\n    for _, other in ipairs(Players:GetPlayers()) do\n        if other ~= player and not completed[other] then\n            state:FireClient(player, \"OPERACAO\", \"Aguarde os outros agentes terminarem antes de reiniciar o posto.\")\n            return\n        end\n    end\n    if operations then operations:reset() end\n    world:SetAttribute(\"IncidentReports\", 0)\n    if facilities then facilities:reset() end\n    if powerGrid then powerGrid:reset() end\n    for _, other in ipairs(Players:GetPlayers()) do\n        if other ~= player then\n            completed[other] = nil\n            dataTaken[other] = nil\n            terminalInspectionDue[other] = nil\n            resetInventory(other)\n            other:SetAttribute(\"Posto17Won\", false)\n            other:SetAttribute(\"Posto17Data\", false)\n            missionStart[other] = os.clock()\n            captures[other], alertsByPlayer[other] = 0, 0\n            lastCaught[other] = os.clock()\n            other:SetAttribute(\"Posto17BonusIntel\", false)\n            other:SetAttribute(\"Posto17Sabotage\", false)\n            other:SetAttribute(\"Posto17Blackout\", false)\n            other:SetAttribute(\"Posto17Rank\", \"\")\n            other:SetAttribute(\"Posto17Score\", 0)\n            setPosture(other, \"STAND\")\n            local otherRoot = other.Character and other.Character:FindFirstChild(\"HumanoidRootPart\")\n            if otherRoot then otherRoot.CFrame = spawn.CFrame + Vector3.new(0, 4, 0) end\n            state:FireClient(other, \"REINICIO\", \"Nova operacao iniciada.\")\n        end\n    end\n    resetInventory(player)\n    completed[player] = nil\n    dataTaken[player] = nil\n    terminalInspectionDue[player] = nil\n    terminalLed.Color = Color3.fromRGB(76, 194, 143)\n    missionStart[player] = os.clock()\n    captures[player] = 0\n    alertsByPlayer[player] = 0\n    stoneCount[player] = 3\n    lastStoneAt[player] = -100\n    lastResupplyAt[player] = -100\n    lastCaught[player] = os.clock()\n    alertLevel = 0\n    lastAlertAt = -100\n    world:SetAttribute(\"AlertLevel\", 0)\n    for _, device in ipairs(cameras) do\n        table.clear(device.progress)\n        table.clear(device.lastReported)\n        device.radioDue = nil\n        device.body:SetAttribute(\"CallingRadio\", false)\n    end\n    cameraDisabledUntil = -100\n    relayCooldownUntil = -100\n    world:SetAttribute(\"CamerasOnline\", true)\n    world:SetAttribute(\"CameraSeconds\", 0)\n    relayLight.Color = Color3.fromRGB(47, 218, 203)\n    player:SetAttribute(\"Posto17Data\", false)\n    player:SetAttribute(\"Posto17BonusIntel\", false)\n    player:SetAttribute(\"Posto17Sabotage\", false)\n    player:SetAttribute(\"Posto17Blackout\", false)\n    player:SetAttribute(\"Posto17Stones\", 3)\n    player:SetAttribute(\"Posto17Won\", false)\n    player:SetAttribute(\"Posto17Rank\", \"\")\n    player:SetAttribute(\"Posto17Score\", 0)\n    setPosture(player, \"STAND\")\n    root.CFrame = spawn.CFrame + Vector3.new(0, 4, 0)\n    root.Anchored = false\n    hum.WalkSpeed = 16\n    -- Reinicio global permitido apenas quando todos terminaram a missao.\n    -- Entao nao pode deixar um alerta antigo bloqueando o radar do proximo turno.\n    if squad.active then\n        endSquadAlert(os.clock())\n    end\n    world:SetAttribute(\"RadarJammed\", false)\n    world:SetAttribute(\"Reinforcements\", 0)\n    for _, guard in ipairs(guards) do\n        guard.supportDue = nil\n        guard.radioDue = nil\n        guard.body:SetAttribute(\"CallingRadio\", false)\n        guard.reportedPosition = nil\n        guard.sectorGoal = nil\n        guard.targetPlayer = nil\n        guard.suspectedPlayer = nil\n        guard.suspicion = 0\n        guard.lastVisualAt = -100\n        guard.lastSeen = nil\n        if guard.state ~= \"PATROL\" then\n            setState(guard, \"RETURN\", os.clock())\n        end\n    end\n    state:FireClient(player, \"REINICIO\", \"Nova operacao iniciada.\")\n    print(\"[POSTO17 MISSAO] REINICIO:\", player.Name)\nend)\n\noperations = require(script.Parent.GuardOperations).new({\n    guards = guards, lockers = lockers, players = Players, hiddenState = hiddenState,\n    remote = remote, state = state, near = playerNear, clearNavigation = clearNavigation,\n    ragdoll = require(script.Parent.GuardRagdoll).start,\n    stopRagdoll = require(script.Parent.GuardRagdoll).finish,\n    motion = Motion, animateDoor = animateDoor, setState = setState, noise = noiseAt, sound = playLocalSound,\n    incident = function(witness, rescuer, recognized, point, now)\n        -- Relato individual, nao um broadcast global nem localizacao magica.\n        world:SetAttribute(\"IncidentReports\",\n            (world:GetAttribute(\"IncidentReports\") or 0) + 1)\n        if rescuer then\n            playLocalSound(rescuer.body, \"rbxasset://sounds/action_jump.mp3\", 0.16, 0.8)\n        end\n        print(\"[POSTO17 INCIDENTE] sentinela\", witness.id,\n            recognized and \"identificou intruso\" or \"viu so suspeita\",\n            rescuer and (\"relatou para \" .. rescuer.id) or \"acordou sem ajuda\")\n    end,\n})\nfacilities = require(script.Parent.Facilities).new({\n    world = world, part = part, remote = remote, near = playerNear, players = Players,\n    state = state, sound = playLocalSound, noise = noiseAt, tween = TweenService, motion = Motion,\n    inspect = function(guard, point, now)\n        guard.lastSeen = point\n        guard.targetPlayer = nil\n        guard.suspicion = math.max(guard.suspicion, NOTICE_THRESHOLD)\n        setState(guard, \"INVESTIGATE\", now)\n    end,\n    cancelRadio = function()\n        for _, guard in ipairs(guards) do\n            guard.supportDue, guard.radioDue = nil, nil\n            guard.body:SetAttribute(\"CallingRadio\", false)\n        end\n        for _, device in ipairs(cameras) do device.radioDue = nil end\n    end,\n})\nrequire(script.Parent.Ambience).build({\n    world = world, part = part, decoration = decoration, guards = guards\n})\nlocal environment = require(script.Parent.WorldDetail).build({\n    world = world, part = part, lighting = Lighting, identity = VisualIdentity\n})\nGuardVisuals.attach(guards, part, world)\ndo\n    local pistol = require(script.Parent.PistolRules)\n    local lookup = {}\n    for _, guard in ipairs(guards) do\n        lookup[guard.body] = {guard=guard,head=false}\n        for _, bone in ipairs(guard.visualBones or {}) do\n            if bone.part.Name == \"Cabeca\" or bone.part.Name == \"Capacete\" then\n                bone.part.CanQuery = true\n                lookup[bone.part] = {guard=guard,head=true}\n            end\n        end\n    end\n    pistol.attach(function(player,origin,hit,muffled)\n        if player:GetAttribute(\"Posto17InTestRange\") then return end\n        local now = os.clock()\n        noiseAt(origin,now,muffled and pistol.QuietRange or pistol.LoudRange,\"SHOT\")\n        local target = hit and lookup[hit.Instance]\n        if target then operations:shot(player,target.guard,target.head,pistol.BodyDamage,now) end\n    end)\nend\nlocal allLamps = legacyLamps\nfor _, lamp in ipairs(environment.lamps) do table.insert(allLamps, lamp) end\npowerGrid = require(script.Parent.PowerGrid).new({\n    world = world, part = part, players = Players, lighting = Lighting,\n    guards = guards, setState = setState, externalLamps = allLamps,\n    near = playerNear, state = state, noise = noiseAt, sound = playLocalSound, motion = Motion,\n})\n\nrequire(script.Parent.Settings).new({world = world, players = Players, spawn = spawn,\n    remote = remote, near = playerNear, state = state})\nrequire(script.Parent.Flashlight).new({players = Players, remote = remote})\nsensors = require(script.Parent.Sensors).new({world = world, part = part, players = Players,\n    cameras = cameras, noise = noiseAt, sound = playLocalSound})\nrequire(script.Parent.StudioAudit).install({world = world, guards = guards, players = Players,\n    facilities = facilities, operations = operations, posture = setPosture,\n    calm = function() endSquadAlert(os.clock()) end})\nlocal accumulator = 0\nlocal lastDiagnosticsAt = 0\nRunService.Heartbeat:Connect(function(dt)\n    accumulator += dt\n    if accumulator < AI_INTERVAL then return end\n    local step = math.min(accumulator, 0.18)\n    accumulator = 0\n    local now = os.clock()\n    operations:tick(now)\n    facilities:tick(now)\n    powerGrid:tick(now)\n    sensors:tick(now)\n    for player, due in pairs(terminalInspectionDue) do\n        if now >= due then\n            terminalInspectionDue[player] = nil\n            dispatchTerminalInspection(player, now)\n        end\n    end\n    -- O alerta termina apenas depois de 15 segundos sem nova observacao.\n    if squad.active and now - squad.lastSeenAt\n        > SQUAD_SEARCH_DURATION + (alertLevel - 1) * 2 then\n        endSquadAlert(now)\n    end\n    if not squad.active and alertLevel > 0 and now-lastAlertAt > 40 then\n        alertLevel -= 1\n        lastAlertAt = now\n        world:SetAttribute(\"AlertLevel\", alertLevel)\n    end\n    local cameraOk, cameraErr = pcall(updateCameras, step, now)\n    if not cameraOk and now-(world:GetAttribute(\"LastCameraError\") or -100)>4 then\n        world:SetAttribute(\"LastCameraError\", now)\n        warn(\"[POSTO17 CAMERA ERROR]\", cameraErr)\n    end\n    for _, guard in ipairs(guards) do\n        local ok, err = pcall(updateGuard, guard, step, now)\n        if not ok and now - (guard.lastErrorAt or -100) > 4 then\n            guard.lastErrorAt = now\n            warn(\"[POSTO17 AI ERROR] Guarda \" .. guard.id .. \": \" .. tostring(err))\n        end\n        GuardVisuals.animate(guard, now)\n    end\n    local radarBlocked = Rules.radarBlocked(squad.active, guards)\n    if world:GetAttribute(\"RadarJammed\") ~= radarBlocked then\n        world:SetAttribute(\"RadarJammed\", radarBlocked)\n    end\n    if now - lastDiagnosticsAt >= 1 then\n        lastDiagnosticsAt = now\n        world:SetAttribute(\"AIHeartbeat\", now)\n        world:SetAttribute(\"CameraSeconds\", math.max(0,\n            math.ceil(cameraDisabledUntil - now)))\n        for _, guard in ipairs(guards) do\n            guard.body:SetAttribute(\"SecondsWithoutMove\",\n                math.max(0, math.floor((now - guard.lastMoveAt) * 10) / 10))\n            guard.body:SetAttribute(\"RouteFailures\", guard.failedRoutes)\n        end\n    end\nend)\n\nprint(\"[POSTO17 IA] 4 sentinelas low-poly ativas: colisao, visao, audio, busca e perseguicao\")\n\ndo\n    local ducts = require(script.Parent.Ducts).new({\n        players = Players, part = part, tween = TweenService, motion = Motion,\n        clear = mobility.clear, posture = setPosture, drop = PoseLibrary.hipDrop,\n    })\n    ducts.build(world, \"DutoLateralOficina\", Vector3.new(-51, 1.15, -34),\n        Vector3.new(-51, 1.15, -17), false)\n    ducts.build(world, \"DutoTetoManutencao\", Vector3.new(50, 6.5, 14),\n        Vector3.new(50, 6.5, 32), true)\n    if testRange then\n        require(script.Parent.AnimationRange).build({\n            parent = testRange.root, spawn = testRange.spawn, part = part, ducts = ducts,\n            remote = remote, motion = Motion, mobility = mobility, posture = setPosture,\n            guardVisuals = GuardVisuals, tween = TweenService,\n        })\n    end\nend\n"},{"studio":"ServerScriptService/PowerGrid","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/PowerGrid (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Quadro de energia sabotavel. Independente do rele de cameras e do radio.\n-- Contramedida: fontes dos guardas seguem ativas e cameras tem bateria.\nlocal Rules = require(game:GetService(\"ReplicatedStorage\").Posto17Shared.Rules)\nlocal PowerGrid = {}\nfunction PowerGrid.new(ctx)\n    local self = {}\n    local offUntil, cooldownUntil = -100, -100\n    local holder = {}\n    local baseBrightness = ctx.lighting.Brightness\n    local baseAmbient = ctx.lighting.Ambient\n    local lamps = {}\n    -- Todas as luzes industriais do mapa usam a mesma rede eletrica.\n    for _, lamp in ipairs(ctx.externalLamps or {}) do\n        table.insert(lamps, lamp)\n    end\n    local online = true\n    local responder, repairAt = nil, nil\n\n    local breaker = ctx.part(\"QuadroEnergia\", Vector3.new(2.6, 4, 1.5),\n        Vector3.new(3, 2, -42), Color3.fromRGB(57, 69, 77),\n        Enum.Material.Metal)\n    breaker:SetAttribute(\"PowerControl\", true)\n    local indicator = ctx.part(\"LedEnergia\", Vector3.new(1.1, 0.25, 0.15),\n        breaker.Position + Vector3.new(0, 1, -0.8),\n        Color3.fromRGB(103, 225, 161), Enum.Material.Neon, false)\n    indicator.CanQuery = false\n    indicator.CanTouch = false\n\n    for i, pos in ipairs({\n        Vector3.new(-43, 10, -24), Vector3.new(-1, 10, -27),\n        Vector3.new(34, 10, -36), Vector3.new(42, 10, 12),\n        Vector3.new(0, 10, 24), Vector3.new(-36, 10, 26),\n    }) do\n        local panel = ctx.part(\"Luminaria_\" .. i, Vector3.new(3.4, 0.22, 0.75),\n            pos, Color3.fromRGB(189, 215, 207), Enum.Material.Neon, false)\n        panel.CanQuery = false\n        panel.CanTouch = false\n        local light = Instance.new(\"PointLight\")\n        light.Brightness = 0.9\n        light.Range = 15\n        light.Color = Color3.fromRGB(185, 216, 215)\n        light.Shadows = false\n        light.Parent = panel\n        lamps[#lamps+1] = {part = panel, light = light}\n    end\n\n    local function apply(enabled)\n        online = enabled\n        ctx.world:SetAttribute(\"PowerOnline\", enabled)\n        ctx.lighting.Brightness = enabled and baseBrightness\n            or math.max(0.7, baseBrightness * 0.45)\n        ctx.lighting.Ambient = enabled and baseAmbient or Color3.fromRGB(25, 27, 34)\n        indicator.Color = enabled and Color3.fromRGB(103, 225, 161)\n            or Color3.fromRGB(240, 81, 69)\n        for _, lamp in ipairs(lamps) do\n            lamp.light.Enabled = enabled\n            lamp.part.Material = enabled and Enum.Material.Neon or Enum.Material.Metal\n            lamp.part.Color = enabled and Color3.fromRGB(189, 215, 207)\n                or Color3.fromRGB(64, 71, 74)\n        end\n    end\n    -- Resposta LOCAL: apenas um guarda que ouviu o disjuntor recebe a ordem\n    -- de consertar. Nenhuma informacao sobre o jogador e compartilhada.\n    local function clearResponder()\n        if responder then\n            responder.body:SetAttribute(\"PowerResponding\", nil)\n            responder.body:SetAttribute(\"RepairingPower\", nil)\n        end\n        responder, repairAt = nil, nil\n    end\n    local function chooseResponder(now)\n        clearResponder()\n        local nearest = math.huge\n        for _, guard in ipairs(ctx.guards or {}) do\n            local dist = (guard.body.Position - breaker.Position).Magnitude\n            local heard = guard.lastSeen and\n                (guard.lastSeen - breaker.Position).Magnitude < 2\n                and math.abs(now - (guard.lastNoiseAt or -100)) < 0.2\n            if Rules.active(guard.life) and heard and dist < 20\n                and guard.state ~= \"CHASE\" and guard.state ~= \"WATCH\"\n                and dist < nearest then\n                responder, nearest = guard, dist\n            end\n        end\n        if responder then\n            responder.lastSeen = breaker.Position\n            responder.lastMotion = Vector3.zero\n            responder.suspicion = math.max(responder.suspicion or 0, 0.3)\n            responder.body:SetAttribute(\"PowerResponding\", true)\n            ctx.setState(responder, \"INVESTIGATE\", now)\n        end\n    end\n    local prompt = Instance.new(\"ProximityPrompt\")\n    prompt.Name = \"SabotarEnergia\"\n    prompt.ActionText = \"Cortar iluminacao\"\n    prompt.ObjectText = \"Quadro de energia / 32 s\"\n    prompt.HoldDuration = 1.5\n    prompt.MaxActivationDistance = 8\n    prompt.RequiresLineOfSight = true\n    prompt.Parent = breaker\n\n    prompt.PromptButtonHoldBegan:Connect(function(player)\n        holder[player] = os.clock()\n    end)\n    prompt.PromptButtonHoldEnded:Connect(function(player)\n        local started = holder[player]\n        task.delay(0.2, function()\n            if holder[player] == started then holder[player] = nil end\n        end)\n    end)\n    apply(true)\n    ctx.world:SetAttribute(\"PowerSeconds\", 0)\n    prompt.Triggered:Connect(function(player)\n        local now = os.clock()\n        local started = holder[player]\n        holder[player] = nil\n        if type(started) ~= \"number\" or now - started < 1.4\n            or now < cooldownUntil or not online\n            or player:GetAttribute(\"Posto17Hidden\")\n            or player:GetAttribute(\"Posto17Won\")\n            or player:GetAttribute(\"Posto17Dragging\")\n            or not ctx.near(player, breaker.Position, 8) then\n            return\n        end\n        ctx.motion.play(player, \"BUTTON\", 0.58, breaker.Position)\n        cooldownUntil = now + 70\n        offUntil = now + 32\n        apply(false)\n        ctx.world:SetAttribute(\"PowerSeconds\", 32)\n        player:SetAttribute(\"Posto17Blackout\", true)\n        ctx.noise(breaker.Position, now, 15)\n        chooseResponder(now)\n        ctx.sound(breaker, \"rbxasset://sounds/electronicpingshort.wav\", 0.3, 0.55)\n        ctx.state:FireClient(player, \"OPERACAO\",\n            \"Iluminacao cortada por 32 s. Cuidado com as lanternas dos vigias.\")\n    end)\n    local lastSecond = -1\n    function self:tick(now)\n        if not online and responder then\n            if not Rules.active(responder.life)\n                or responder.state == \"CHASE\" or responder.state == \"WATCH\" then\n                clearResponder()\n            else\n                local distance = (responder.body.Position - breaker.Position).Magnitude\n                if distance <= 5.5 then\n                    if not repairAt then\n                        repairAt = now + 3.2\n                        responder.body:SetAttribute(\"RepairingPower\", true)\n                    end\n                    if now >= repairAt then\n                        apply(true)\n                        offUntil = -100\n                        local guard = responder\n                        clearResponder()\n                        ctx.setState(guard, \"RETURN\", now)\n                        ctx.sound(breaker,\n                            \"rbxasset://sounds/electronicpingshort.wav\", 0.24, 1.2)\n                    end\n                elseif repairAt then\n                    repairAt = nil\n                    responder.body:SetAttribute(\"RepairingPower\", nil)\n                end\n            end\n        end\n        if not online and now >= offUntil then\n            apply(true)\n            clearResponder()\n            ctx.world:SetAttribute(\"PowerSeconds\", 0)\n        end\n        local second = online and 0 or math.ceil(math.max(0, offUntil - now))\n        if second ~= lastSecond then\n            lastSecond = second\n            ctx.world:SetAttribute(\"PowerSeconds\", second)\n        end\n    end\n    function self:reset()\n        offUntil, cooldownUntil = -100, -100\n        clearResponder()\n        table.clear(holder)\n        lastSecond = -1\n        apply(true)\n        ctx.world:SetAttribute(\"PowerSeconds\", 0)\n        for _, player in ipairs(ctx.players:GetPlayers()) do\n            player:SetAttribute(\"Posto17Blackout\", false)\n        end\n    end\n    function self:cleanup(player)\n        holder[player] = nil\n    end\n    self.breaker, self.lamps, self.prompt = breaker, lamps, prompt\n    return self\nend\nreturn PowerGrid\n"},{"studio":"ServerScriptService/Protagonista","class":"Script","source":"-- Local no Studio: ServerScriptService/Protagonista (Script)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal arsenal = require(RS:WaitForChild(\"Posto17Shared\"):WaitForChild(\"ArsenalCatalog\"))\nlocal BlockyOperator = require(script.Parent:WaitForChild(\"P17BlockyOperator\"))\nlocal remote = Instance.new(\"RemoteEvent\")\nremote.Name = \"Posto17Appearance\"\n\nlocal tones = {\n    Color3.fromRGB(226, 173, 133), Color3.fromRGB(164, 107, 77),\n    Color3.fromRGB(124, 76, 55), Color3.fromRGB(84, 50, 41),\n}\nlocal looks = {}\nlocal originalSizes = setmetatable({}, {__mode = \"k\"})\nlocal lockedRoots = {}\nlocal lastRequest = {}\n\n\nlocal cotton = Color3.fromRGB(30, 31, 33)\nlocal denim = Color3.fromRGB(37, 38, 41)\nlocal ribbing = Color3.fromRGB(22, 23, 25)\nlocal seam = Color3.fromRGB(57, 58, 61)\nlocal cap = Color3.fromRGB(20, 21, 23)\nlocal lens = Color3.fromRGB(21, 24, 29)\n\nlocal function attach(player, character)\n    local humanoid = character:WaitForChild(\"Humanoid\", 10)\n    local head = character:WaitForChild(\"Head\", 10)\n    if not humanoid or not head or player.Character ~= character then return end\n    local torso = character:FindFirstChild(\"UpperTorso\") or character:WaitForChild(\n        humanoid.RigType == Enum.HumanoidRigType.R15 and \"UpperTorso\" or \"Torso\", 10)\n    if not torso or player.Character ~= character then return end\n    local look = looks[player]\n    if not look then return end\n    local skin = tones[look.tone]\n    local previous = character:FindFirstChild(\"Posto17Visual\")\n    if previous then previous:Destroy() end\n    local original = originalSizes[character]\n    if not original then\n        original = {}\n        for _, part in ipairs(character:GetChildren()) do\n            if part:IsA(\"BasePart\") then original[part] = part.Size end\n        end\n        originalSizes[character] = original\n    end\n    for part, size in pairs(original) do\n        if humanoid.RigType == Enum.HumanoidRigType.R15 and (part.Name == \"Head\" or part.Name == \"UpperTorso\" or part.Name:find(\"Arm\")) then\n            local width = look.style == 2 and (part.Name == \"Head\" and 0.92 or 0.86) or 1\n            part.Size = Vector3.new(size.X * width, size.Y, size.Z)\n        end\n    end\n\n    local visual = Instance.new(\"Folder\")\n    visual.Name = \"Posto17Visual\"\n    visual.Parent = character\n\n    -- A roupa usa peças sem colisão, soldadas ao mesmo rig das animações.\n    local function surface(name, body, size, offset, color, shape)\n        local item = Instance.new(\"Part\")\n        item.Name = name\n        item.Size, item.CFrame, item.Color = size, body.CFrame * offset, color\n        item.Material = Enum.Material.SmoothPlastic\n        item.CanCollide, item.CanQuery, item.CanTouch, item.Massless = false, false, false, true\n        item.CastShadow = false\n        if shape == \"Round\" then\n            local mesh = Instance.new(\"SpecialMesh\")\n            mesh.MeshType = Enum.MeshType.Sphere\n            mesh.Parent = item\n        end\n        local weld = Instance.new(\"WeldConstraint\")\n        weld.Part0, weld.Part1 = body, item\n        weld.Parent = item\n        item.Parent = visual\n        return item\n    end\n\n    local function line(name, body, first, last, width, depth, color)\n        local diff = last - first\n        local angle = math.atan2(-diff.X, diff.Y)\n        surface(name, body, Vector3.new(width, diff.Magnitude + width * 0.55, depth),\n            CFrame.new((first + last) * 0.5) * CFrame.Angles(0, 0, angle), color)\n    end\n\n    local colors = character:FindFirstChildOfClass(\"BodyColors\") or Instance.new(\"BodyColors\")\n    colors.HeadColor3, colors.TorsoColor3 = skin, cotton\n    colors.LeftArmColor3, colors.RightArmColor3 = cotton, cotton\n    colors.LeftLegColor3, colors.RightLegColor3 = denim, denim\n    colors.Parent = character\n\n    local function colorBody(item)\n        if not item:IsA(\"BasePart\") then return end\n        local name = item.Name\n        if name == \"Head\" or name:find(\"Hand\") then item.Color = skin\n        elseif name:find(\"Foot\") then item.Color = ribbing\n        elseif name:find(\"Leg\") then item.Color = denim\n        elseif name:find(\"Torso\") or name:find(\"Arm\") then item.Color = cotton end\n    end\n    for _, item in ipairs(character:GetChildren()) do colorBody(item) end\n\n    -- Troca somente o visual. R15, Humanoid, hitboxes e animações legadas ficam.\n    if humanoid.RigType == Enum.HumanoidRigType.R15\n        and BlockyOperator.apply(character, visual, look, skin) then\n        character:SetAttribute(\"Posto17Protagonista\", true)\n        character:SetAttribute(\"P17LookRevision\", (character:GetAttribute(\"P17LookRevision\") or 0) + 1)\n        return\n    end\n\n    -- R6: manter a cabeca classica do Roblox, sem capuz ou objetos sobre o rosto.\n\n    local x, y, z = torso.Size.X, torso.Size.Y, torso.Size.Z\n    local front = -z * 0.502\n    surface(\"Ziper\", torso, Vector3.new(x * 0.023, y * 0.94, z * 0.025),\n        CFrame.new(0, 0, front), seam)\n    surface(\"Puxador\", torso, Vector3.new(x * 0.052, y * 0.105, z * 0.04),\n        CFrame.new(0, y * 0.27, front - z * 0.018), seam)\n    for _, side in ipairs({-1, 1}) do\n        line(\"Cordao\", torso, Vector3.new(x * side * 0.14, y * 0.46, front),\n            Vector3.new(x * side * 0.20, y * 0.075, front), x * 0.020, z * 0.041, ribbing)\n        line(\"AberturaBolso\", torso, Vector3.new(x * side * 0.15, -y * 0.23, front),\n            Vector3.new(x * side * 0.33, -y * 0.39, front), x * 0.014, z * 0.024, seam)\n        local foot = character:FindFirstChild(side == -1 and \"LeftFoot\" or \"RightFoot\")\n        if foot then\n            local size = foot.Size\n            surface(\"Sola\", foot, Vector3.new(size.X * 1.015, size.Y * 0.15, size.Z * 1.016),\n                CFrame.new(0, -size.Y * 0.415, 0), denim)\n        end\n    end\n    character:SetAttribute(\"Posto17Protagonista\", true)\n    character:SetAttribute(\"P17LookRevision\", (character:GetAttribute(\"P17LookRevision\") or 0) + 1)\nend\n\nlocal function watch(player)\n    if looks[player] then return end\n    looks[player] = {style=1, tone=2, face=1}\n    player:SetAttribute(\"P17Queued\", true)\n    for _, item in ipairs(arsenal) do player:SetAttribute(item.attribute,true) end\n    local function spawn(character)\n        local root = character:WaitForChild(\"HumanoidRootPart\", 10)\n        if root and player.Character == character and player:GetAttribute(\"P17Queued\") then\n            lockedRoots[player] = root\n            root.Anchored = true\n        end\n        attach(player, character)\n    end\n    player.CharacterAdded:Connect(spawn)\n    if player.Character then task.spawn(spawn, player.Character) end\nend\n\nlocal function valid(index, maximum)\n    return typeof(index) == \"number\" and index >= 1 and index <= maximum and index % 1 == 0\nend\n\nremote.OnServerEvent:Connect(function(player, command, style, tone, face)\n    if not looks[player] or not player:GetAttribute(\"P17Queued\") then return end\n    if command == \"LOADOUT\" then\n        if typeof(tone) ~= \"boolean\" then return end\n        for _, item in ipairs(arsenal) do\n            if item.id == style then\n                player:SetAttribute(item.attribute,tone)\n                return\n            end\n        end\n        return\n    end\n    if command == \"PLAY\" then\n        player:SetAttribute(\"P17Queued\", false)\n        local root = lockedRoots[player]\n        if root then root.Anchored = false end\n        lockedRoots[player] = nil\n        return\n    end\n    if command ~= \"LOOK\" or not valid(style,2) or not valid(tone,#tones) or not valid(face,3) then return end\n    local now = os.clock()\n    if now - (lastRequest[player] or -1) < .12 then return end\n    lastRequest[player] = now\n    looks[player] = {style=style, tone=tone, face=face}\n    if player.Character then attach(player, player.Character) end\nend)\nPlayers.PlayerRemoving:Connect(function(player)\n    looks[player], lockedRoots[player], lastRequest[player] = nil, nil, nil\nend)\nPlayers.PlayerAdded:Connect(watch)\nfor _, player in ipairs(Players:GetPlayers()) do watch(player) end\nremote.Parent = RS\n"},{"studio":"ServerScriptService/Sensors","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/Sensors (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Sensores de audio locais: apenas fontes audiveis sem dar identidade do agente.\n-- Microfones associados as cameras complementam o sensor de corredor.\nlocal Sensors = {}\nfunction Sensors.new(ctx)\n    local microphones = {}\n    local function register(body, radius)\n        body.CanQuery = false\n        body:SetAttribute(\"SensorKind\", \"AUDIO\")\n        microphones[#microphones + 1] = {body = body, radius = radius, lastAt = -100}\n        return body\n    end\n    register(ctx.part(\"Microfone_1\", Vector3.new(0.8, 1.2, 0.8),\n        Vector3.new(2, 3, 14), Color3.fromRGB(69, 83, 87), Enum.Material.Metal, false), 10)\n    for index, device in ipairs(ctx.cameras or {}) do\n        local microphone = ctx.part(\"MicrofoneCamera_\" .. index, Vector3.new(0.42, 0.28, 0.36),\n            device.body.Position + Vector3.new(0, -0.45, 0),\n            Color3.fromRGB(47, 61, 69), Enum.Material.Metal, false)\n        register(microphone, 19)\n        device.body:SetAttribute(\"HasMicrophone\", true)\n    end\n\n    local ray = RaycastParams.new()\n    ray.FilterType = Enum.RaycastFilterType.Exclude\n    ray.RespectCanCollide = true\n    local function active()\n        return ctx.world:GetAttribute(\"CamerasOnline\") ~= false\n    end\n    local function clear(mic, point, source)\n        local delta = point - mic.body.Position\n        if delta.Magnitude > mic.radius then return false end\n        ray.FilterDescendantsInstances = {mic.body, source}\n        return workspace:Raycast(mic.body.Position, delta, ray) == nil\n    end\n    local self = {}\n    function self:hearLocker(point, now, lockerBody)\n        if not active() then return false end\n        local heard = false\n        for _, mic in ipairs(microphones) do\n            if now - mic.lastAt >= 4 and clear(mic, point, lockerBody) then\n                mic.lastAt = now\n                mic.body:SetAttribute(\"LastNoiseAt\", now)\n                if not heard then\n                    -- O relatorio apenas aponta uma ocorrencia local, nunca um player.\n                    ctx.noise(point, now, 32)\n                    ctx.sound(mic.body, \"rbxasset://sounds/electronicpingshort.wav\", 0.13, 1.2)\n                end\n                heard = true\n            end\n        end\n        return heard\n    end\n    function self:tick(now)\n        local online = active()\n        for _, mic in ipairs(microphones) do\n            mic.body:SetAttribute(\"Active\", online)\n            if online and now - mic.lastAt >= 4 then\n                for _, player in ipairs(ctx.players:GetPlayers()) do\n                    local char = player.Character\n                    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n                    local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n                    if root and hum and hum.Health > 0\n                        and not player:GetAttribute(\"Posto17Won\")\n                        and not player:GetAttribute(\"Posto17Hidden\")\n                        and not player:GetAttribute(\"Posto17Crouched\")\n                        and root.AssemblyLinearVelocity.Magnitude > 3\n                        and clear(mic, root.Position, char) then\n                        mic.lastAt = now\n                        ctx.noise(mic.body.Position, now, 18)\n                        ctx.sound(mic.body, \"rbxasset://sounds/electronicpingshort.wav\", 0.14, 1.6)\n                        mic.body:SetAttribute(\"LastNoiseAt\", now)\n                        break\n                    end\n                end\n            end\n        end\n    end\n    return self\nend\nreturn Sensors\n"},{"studio":"ServerScriptService/Settings","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/Settings (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Rules = require(game:GetService(\"ReplicatedStorage\").Posto17Shared.Rules)\nlocal Settings = {}\nfunction Settings.new(ctx)\n    local event = ctx.remote(\"Posto17Settings\")\n    local cooldown = {}\n    ctx.world:SetAttribute(\"Difficulty\", \"NORMAL\")\n    ctx.world:SetAttribute(\"DetectionMultiplier\", 1)\n    ctx.world:SetAttribute(\"GuardSpeedMultiplier\", 1)\n    event.OnServerEvent:Connect(function(player, mode)\n        local now = os.clock()\n        if type(mode) ~= \"string\" or not Rules.DIFFICULTIES[mode] then return end\n        if now-(cooldown[player] or -100) < 1 then return end\n        cooldown[player] = now\n        if #ctx.players:GetPlayers() ~= 1 or (not player:GetAttribute(\"P17Queued\") and not ctx.near(player, ctx.spawn.Position, 13))\n            or ctx.world:GetAttribute(\"AlertLevel\") ~= 0 or player:GetAttribute(\"Posto17Data\")\n            or player:GetAttribute(\"Posto17Won\") or player:GetAttribute(\"Posto17Hidden\")\n            or (player:GetAttribute(\"Posto17Kills\") or 0) > 0\n            or (player:GetAttribute(\"Posto17Knockouts\") or 0) > 0\n            or player:GetAttribute(\"Posto17Keycard\") or player:GetAttribute(\"Posto17Sabotage\") then\n            ctx.state:FireClient(player, \"OPERACAO\", \"Dificuldade pode mudar apenas no inicio de uma operacao solo.\")\n            return\n        end\n        ctx.world:SetAttribute(\"Difficulty\", mode)\n        ctx.world:SetAttribute(\"DetectionMultiplier\", Rules.DIFFICULTIES[mode].detection)\n        ctx.world:SetAttribute(\"GuardSpeedMultiplier\", Rules.DIFFICULTIES[mode].speed)\n        ctx.state:FireClient(player, \"OPERACAO\", \"Dificuldade: \" .. mode)\n    end)\n    ctx.players.PlayerRemoving:Connect(function(player) cooldown[player] = nil end)\nend\nreturn Settings\n"},{"studio":"ServerScriptService/StoreAssets","class":"Script","source":"-- Local no Studio: ServerScriptService/StoreAssets (Script)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Modelos da Creator Store: cama 56449778, porta 67572258 e pistola 4842197274.\nlocal Players = game:GetService(\"Players\")\nlocal Pistol = require(script.Parent.PistolRules)\nlocal AssetService = game:GetService(\"AssetService\")\nlocal CollectionService = game:GetService(\"CollectionService\")\nlocal InsertService = game:GetService(\"InsertService\")\nlocal Clips = game:GetService(\"AnimationClipProvider\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal ServerStorage = game:GetService(\"ServerStorage\")\nlocal ServerScriptService = game:GetService(\"ServerScriptService\")\n\nlocal ready = Instance.new(\"Folder\")\nready.Name = \"Posto17StoreAssets\"\nready.Parent = RS\n\nlocal function strip(model)\n    for _, item in ipairs(model:GetDescendants()) do\n        if item:IsA(\"LuaSourceContainer\") or item:IsA(\"RemoteEvent\")\n            or item:IsA(\"RemoteFunction\") or item:IsA(\"Humanoid\") then\n            item:Destroy()\n        elseif item:IsA(\"BasePart\") then\n            item.Anchored, item.CanCollide, item.CanTouch, item.CanQuery = true, false, false, false\n        end\n    end\nend\n\nlocal function import(group, asset, owned)\n    local ok, model = pcall(function()\n        if owned then return InsertService:LoadAsset(asset) end\n        return AssetService:LoadAssetAsync(asset)\n    end)\n    if not ok then\n        ready:SetAttribute(group .. \"Status\", string.sub(tostring(model), 1, 160))\n        return\n    end\n    local animations, referenced = {}, {}\n    for _, item in ipairs(model:GetDescendants()) do\n        if item:IsA(\"KeyframeSequence\") or item:IsA(\"Animation\") then\n            local selected = item:Clone()\n            selected:SetAttribute(\"StoreAsset\", tostring(asset))\n            selected.Parent = ready:FindFirstChild(group) or ready\n            table.insert(animations, selected.ClassName .. \":\" .. selected.Name)\n            if item:IsA(\"Animation\") and item.AnimationId ~= \"\" then\n                table.insert(referenced, {id=item.AnimationId, name=item.Name})\n            end\n        end\n    end\n    if group == \"Cama\" or group == \"Mochila\" or group == \"Armario\" then\n        strip(model)\n        model.Name = group\n        model.Parent = ready\n    else\n        model:Destroy()\n    end\n    ready:SetAttribute(group .. \"Status\", \"OK \" .. table.concat(animations, \" | \"))\n    for i, reference in ipairs(referenced) do\n        if i > 6 then break end\n        if not reference.id:match(\"^rbxassetid://%d+$\") then continue end\n        local found, clip = pcall(Clips.GetAnimationClipAsync, Clips, reference.id)\n        if found and clip:IsA(\"KeyframeSequence\") then\n            clip.Name = reference.name\n            clip.Parent = ready:FindFirstChild(group) or ready\n        end\n    end\nend\n\nfor _, group in ipairs({\"Acordar\", \"AcordarAlternativa\", \"Pegar\", \"PegarAlternativa\", \"PegarObjeto\"}) do\n    local folder = Instance.new(\"Folder\")\n    folder.Name = group\n    folder.Parent = ready\nend\nlocal bundled = RS:WaitForChild(\"Posto17Shared\")\nfor source, name in pairs({StoreBed=\"Cama\",StoreDoor=\"Porta\"}) do\n    local asset = bundled:FindFirstChild(source)\n    if asset then\n        local model = asset:Clone()\n        strip(model)\n        model.Name, model.Parent = name, ready\n    end\nend\ntask.spawn(import, \"Acordar\", 14414936520, false)\ntask.spawn(import, \"AcordarAlternativa\", 7229994774, false)\ntask.spawn(import, \"Pegar\", 5706491203, false)\ntask.spawn(import, \"PegarAlternativa\", 9855839274, false)\ntask.spawn(import, \"PegarObjeto\", 9572441645, false)\ntask.spawn(import, \"Mochila\", 15202364951, false)\ntask.spawn(import, \"Armario\", 88040705380457, false)\n\nlocal pack = ServerStorage:WaitForChild(\"Posto17RobloxWeapons\", 12)\nif not pack then return end\nlocal template = pack:WaitForChild(\"Pistola de teste\")\n\nlocal function suppressor()\n    local piece = Instance.new(\"Part\")\n    piece.Name = \"Supressor\"\n    piece.Shape = Enum.PartType.Cylinder\n    piece.Material = Enum.Material.Metal\n    piece.Color = Color3.fromRGB(52,55,62)\n    piece.Size = Vector3.new(.54,.16,.16)\n    piece.CanCollide, piece.CanTouch, piece.CanQuery, piece.Massless = false,false,false,true\n    return piece\nend\n\nlocal function makeArsenalPreview()\n    local pistol = Instance.new(\"Model\")\n    pistol.Name = \"ArsenalPistol\"\n    local source = template:FindFirstChild(\"Pistol\")\n    if not source then return end\n    for _, object in ipairs(source:GetChildren()) do\n        if not object:IsA(\"BasePart\") then continue end\n        local part = object:Clone()\n        for _, child in ipairs(part:GetChildren()) do\n            if child.Name ~= \"TipAttachment\"\n                and not (child:IsA(\"SurfaceAppearance\") or child:IsA(\"Decal\") or child:IsA(\"Texture\")) then\n                child:Destroy()\n            end\n        end\n        part.Anchored,part.CanCollide,part.CanTouch,part.CanQuery = true,false,false,false\n        part.Parent = pistol\n        if part.Name == \"Pistol\" then pistol.PrimaryPart = part end\n    end\n    if not pistol.PrimaryPart then return end\n    pistol.Parent = ready\n    local attachment = suppressor()\n    attachment.Name, attachment.Anchored = \"ArsenalSuppressor\", true\n    attachment.Parent = ready\nend\nmakeArsenalPreview()\n\nlocal world = workspace:WaitForChild(\"Posto17\")\nlocal range = (game.PlaceId == 119377443515742 or game:GetService(\"RunService\"):IsStudio())\n    and world:WaitForChild(\"P17_CampoDeTestes\", 12) or nil\n\nlocal system = pack.WeaponsSystem:Clone()\nsystem.Parent = ServerScriptService\nlocal replicated = RS:WaitForChild(\"WeaponsSystem\", 15)\nif not replicated then return end\nlocal kit = require(replicated:WaitForChild(\"WeaponsSystem\"))\nkit.setDamageCallback(function() end)\n\nlocal function issue(player)\n    local bag = player:FindFirstChildOfClass(\"Backpack\")\n    local character = player.Character\n    if not bag or not character then return end\n    local existing = bag:FindFirstChild(Pistol.Name) or character:FindFirstChild(Pistol.Name)\n    if existing then return existing end\n    local tool = template:Clone()\n    tool.Name = Pistol.Name\n    tool:SetAttribute(\"P17Pistol\", true)\n    local installSuppressor = player:GetAttribute(\"P17LoadoutSuppressor\") ~= false\n    tool:SetAttribute(\"P17SuppressorInstalled\", installSuppressor)\n    tool:SetAttribute(\"P17Suppressor\", installSuppressor and Pistol.Durability or 0)\n    tool.CanBeDropped = false\n    local tip = tool:FindFirstChild(\"TipAttachment\",true)\n    local fired = tool:FindFirstChild(\"Fired\",true)\n    if fired and not fired:IsA(\"Sound\") then fired = nil end\n    if installSuppressor and tip and tip.Parent:IsA(\"BasePart\") then\n        local prop = suppressor()\n        prop.CFrame = tip.WorldCFrame * CFrame.new(0,0,-.25) * CFrame.Angles(0,math.pi/2,0)\n        prop.Parent = tip.Parent\n        local weld = Instance.new(\"WeldConstraint\")\n        weld.Part0,weld.Part1,weld.Parent = tip.Parent,prop,prop\n    end\n    local unsuppressedVolume = fired and fired.Volume\n    local function updateSuppressor()\n        local quiet = (tool:GetAttribute(\"P17Suppressor\") or 0) > 0\n        if fired and fired:IsA(\"Sound\") then fired.Volume = quiet and unsuppressedVolume*.24 or unsuppressedVolume end\n        local prop = tool:FindFirstChild(\"Supressor\", true)\n        if prop then prop.Transparency = quiet and 0 or 1 end\n    end\n    tool:GetAttributeChangedSignal(\"P17Suppressor\"):Connect(updateSuppressor)\n    updateSuppressor()\n    CollectionService:AddTag(tool,\"WeaponsSystemWeapon\")\n    tool.Parent = bag\n    return tool\nend\n\nlocal function watch(player)\n    local function check()\n        if player:GetAttribute(\"P17Queued\") == false and player:GetAttribute(\"P17LoadoutPistol\") ~= false then\n            issue(player)\n        end\n    end\n    player:GetAttributeChangedSignal(\"P17Queued\"):Connect(check)\n    player.CharacterAdded:Connect(function() task.defer(check) end)\n    check()\nend\nPlayers.PlayerAdded:Connect(watch)\nfor _, player in ipairs(Players:GetPlayers()) do watch(player) end\n\nif not range then return end\nlocal function part(name,size,pos,color)\n    local p = Instance.new(\"Part\")\n    p.Name,p.Size,p.Position,p.Color = name,size,pos,color\n    p.Anchored = true\n    p.Parent = range\n    return p\nend\nlocal stand = part(\"Bancada de tiro\",Vector3.new(4,2.3,2),Vector3.new(157,1.15,5.5),Color3.fromRGB(55,56,61))\nlocal prompt = Instance.new(\"ProximityPrompt\")\nprompt.ActionText,prompt.ObjectText = \"Equipar\",\"Pistola\"\nprompt.MaxActivationDistance,prompt.RequiresLineOfSight = 8,false\nprompt.Parent = stand\nlocal targets = {}\nfor i=1,2 do\n    local target = part(\"Alvo \"..i,Vector3.new(2.4,2.4,.5),Vector3.new(152+i*2.8,2.55,-15),Color3.fromRGB(156,42,47))\n    targets[target]=0\nend\nlocal ragdoll = require(script.Parent.GuardRagdoll)\nlocal visuals = require(script.Parent.GuardVisuals)\nlocal dummy = {id=0, eyes={}, life=\"ACTIVE\", body=part(\"Vigia de treino\",Vector3.new(2.15,3.7,1.45),\n    Vector3.new(161.1,2,-15),Color3.fromRGB(76,79,83))}\ndummy.body.CanCollide = false\ndummy.body.CFrame *= CFrame.Angles(0,math.pi,0)\nvisuals.attach({dummy},part,range)\nlocal head = {}\nfor _, bone in ipairs(dummy.visualBones) do\n    if bone.part.Name == \"Cabeca\" or bone.part.Name == \"Capacete\" then\n        bone.part.CanQuery = true\n        head[bone.part] = true\n    end\nend\nlocal startedAt = dummy.body.CFrame\nPistol.attach(function(player,_,hit)\n    local target = hit and hit.Instance\n    if not target or dummy.life ~= \"ACTIVE\" or not player:GetAttribute(\"Posto17InTestRange\") then return end\n    if target ~= dummy.body and not head[target] then return end\n    dummy.health = head[target] and 0 or math.max(0,(dummy.health or 100)-Pistol.BodyDamage)\n    dummy.body:SetAttribute(\"ShotHealth\",dummy.health)\n    if dummy.health > 0 then return end\n    dummy.life = \"DEAD\"\n    dummy.body.CanQuery = false\n    for piece in pairs(head) do piece.CanQuery = false end\n    ragdoll.start(dummy)\n    task.delay(5,function()\n        ragdoll.finish(dummy)\n        dummy.life,dummy.health,dummy.settledRagdoll = \"ACTIVE\",100,nil\n        dummy.body:SetAttribute(\"ShotHealth\",100)\n        dummy.body.CFrame, dummy.body.CanQuery = startedAt,true\n        for piece in pairs(head) do piece.CanQuery = true end\n        for _, bone in ipairs(dummy.visualBones) do\n            bone.offset = bone.base\n            bone.part.CFrame = startedAt * bone.offset\n        end\n    end)\nend)\nPistol.attach(function(player,_,hit)\n    local target = hit and hit.Instance\n    if not target or targets[target] == nil or not player:GetAttribute(\"Posto17InTestRange\") then return end\n    targets[target] += 1\n    local score = targets[target]\n    target:SetAttribute(\"Acertos\",score)\n    target.Color = Color3.fromRGB(132,208,156)\n    task.delay(.38,function()\n        if target.Parent and targets[target]==score then target.Color=Color3.fromRGB(156,42,47) end\n    end)\nend)\nprompt.Triggered:Connect(function(player)\n    if player:GetAttribute(\"P17Queued\") or not player:GetAttribute(\"Posto17InTestRange\") then return end\n    local character = player.Character\n    local hum = character and character:FindFirstChildOfClass(\"Humanoid\")\n    local root = hum and hum.RootPart\n    if not root or (root.Position-stand.Position).Magnitude>10 then return end\n    local tool = issue(player)\n    if tool then hum:EquipTool(tool) end\nend)\n"},{"studio":"ServerScriptService/StudioAudit","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/StudioAudit (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Ferramenta apenas de Studio; nao cria remotes nem existe em servidores publicados.\nlocal StudioAudit = {}\nfunction StudioAudit.install(ctx)\n    if not game:GetService(\"RunService\"):IsStudio() then return end\n    local service = game:GetService(\"ServerStorage\")\n    local old = service:FindFirstChild(\"Posto17Audit\")\n    if old then old:Destroy() end\n    local fn = Instance.new(\"BindableFunction\")\n    fn.Name = \"Posto17Audit\"\n    fn.Parent = service\n    local function vector(p) return {p.X, p.Y, p.Z} end\n    fn.OnInvoke = function(action, id, value)\n        local player = ctx.players:GetPlayers()[1]\n        local root = player and player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n        local guard = type(id) == \"number\" and ctx.guards[id]\n        if action == \"FREEZE\" then\n            for _, item in ipairs(ctx.guards) do item.body:SetAttribute(\"StudioFreeze\", value ~= false) end\n        elseif action == \"APPROACH\" and guard and root then\n            for _, item in ipairs(ctx.guards) do item.body:SetAttribute(\"StudioFreeze\", true) end\n            guard.body.CFrame = CFrame.lookAt(Vector3.new(-32,2,2), Vector3.new(-32,2,3))\n            guard.forward = Vector3.new(0,0,1)\n            for _, eye in ipairs(guard.eyes) do eye.part.CFrame = guard.body.CFrame * eye.offset end\n            root.CFrame = CFrame.lookAt(Vector3.new(-32,3,-1.5), guard.body.Position)\n        elseif action == \"TELEPORT\" and root and typeof(value) == \"Vector3\" then\n            root.CFrame = CFrame.new(value)\n        elseif action == \"WAKE\" and guard then\n            guard.wakeAt = os.clock() + 0.5\n        elseif action == \"RESET\" then\n            ctx.operations:reset()\n            ctx.facilities:reset()\n        elseif action == \"CALM\" then\n            ctx.calm()\n        elseif action == \"PRONE\" and player then\n            ctx.posture(player, value and \"PRONE\" or \"STAND\")\n        end\n        local data = {version = ctx.world:GetAttribute(\"MissionVersion\"), guards = {}, doors = {},\n            radio = ctx.world:GetAttribute(\"RadioOnline\"), radar = ctx.world:GetAttribute(\"RadarJammed\")}\n        if player then\n            local hum = player.Character and player.Character:FindFirstChildOfClass(\"Humanoid\")\n            data.player = {attributes = player:GetAttributes(), position = root and vector(root.Position),\n                hip = hum and hum.HipHeight, speed = hum and hum.WalkSpeed}\n        end\n        for _, item in ipairs(ctx.guards) do\n            table.insert(data.guards, {id = item.id, life = item.life, state = item.state,\n                pos = vector(item.body.Position), attributes = item.body:GetAttributes()})\n        end\n        for _, door in ipairs(ctx.facilities.doors) do\n            table.insert(data.doors, {id = door.id, open = door.body:GetAttribute(\"Open\")})\n        end\n        local json = game:GetService(\"HttpService\"):JSONEncode(data)\n        print(\"[POSTO17 AUDIT] \" .. json)\n        return json\n    end\nend\nreturn StudioAudit\n"},{"studio":"ServerScriptService/TacticalMotion","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/TacticalMotion (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Motion = {}\nlocal cues = setmetatable({}, {__mode = \"k\"})\n\nfunction Motion.rig(player)\n    local character = player.Character\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    local root = humanoid and humanoid.RootPart\n    if not root or humanoid.Health <= 0 then return end\n    return character, humanoid, root\nend\n\nfunction Motion.play(player, name, seconds, target)\n    local character = Motion.rig(player)\n    if not character then return end\n    local stamp = workspace:GetServerTimeNow()\n    cues[character] = stamp\n    character:SetAttribute(\"P17MotionTarget\", target)\n    character:SetAttribute(\"P17MotionDuration\", seconds)\n    character:SetAttribute(\"P17MotionStart\", stamp)\n    character:SetAttribute(\"P17Motion\", name)\n    task.delay(seconds, function()\n        if cues[character] ~= stamp then return end\n        cues[character] = nil\n        character:SetAttribute(\"P17Motion\", nil)\n        character:SetAttribute(\"P17MotionTarget\", nil)\n    end)\nend\n\nfunction Motion.cancel(player, name)\n    local character = player.Character\n    if character and (not name or character:GetAttribute(\"P17Motion\") == name) then\n        cues[character] = nil\n        character:SetAttribute(\"P17Motion\", nil)\n        character:SetAttribute(\"P17MotionTarget\", nil)\n    end\nend\n\nfunction Motion.coverTop(character, root, part)\n    local head = character:FindFirstChild(\"Head\")\n    if not head then return end\n    local axis = part.CFrame\n    local half = part.Size * 0.5\n    local top = axis.Position.Y + math.abs(axis.RightVector.Y) * half.X\n        + math.abs(axis.UpVector.Y) * half.Y + math.abs(axis.LookVector.Y) * half.Z\n    local upright = character:GetAttribute(\"P17UprightHead\")\n        or head.Position.Y - root.Position.Y + head.Size.Y * 0.5\n    local hum = character:FindFirstChildOfClass(\"Humanoid\")\n    local hip = hum:GetAttribute(\"P17BaseHip\") or hum.HipHeight\n    local height = hip + root.Size.Y * 0.5 + upright\n    local params = RaycastParams.new()\n    params.FilterDescendantsInstances = {character}\n    params.RespectCanCollide = true\n    local floor = workspace:Raycast(root.Position, -Vector3.yAxis * 8, params)\n    if not floor then return end\n    local clearance = top - floor.Position.Y\n    if clearance >= height - 0.12 then return \"HIGH\" end\n    if clearance >= height * 0.62 then return \"LOW\" end\nend\n\nfunction Motion.install(ctx)\n    local boxJobs, boxLooks = {}, {}\n    local coverRemote = ctx.remote(\"Posto17Cover\")\n    local mobility = ctx.remote(\"Posto17Mobility\")\n\n    local function clearCover(player)\n        player:SetAttribute(\"Posto17CoverHeight\", nil)\n        ctx.speed(player)\n    end\n\n    local function clearBox(player)\n        boxJobs[player] = nil\n        local look = boxLooks[player]\n        if look then\n            look.connection:Disconnect()\n            for part, original in pairs(look.parts) do\n                if part.Parent then part.Transparency = original end\n            end\n            boxLooks[player] = nil\n        end\n        local character = player.Character\n        local box = character and character:FindFirstChild(\"P17CaixaPortatil\")\n        if box then box:Destroy() end\n        player:SetAttribute(\"Posto17Box\", nil)\n    end\n\n    local function cover(player, wall)\n        if wall == nil then clearCover(player); return end\n        local character, hum, root = Motion.rig(player)\n        if not root or root.Anchored or player:GetAttribute(\"Posto17Hidden\")\n            or player:GetAttribute(\"Posto17Prone\") or player:GetAttribute(\"Posto17Dragging\")\n            or player:GetAttribute(\"Posto17Won\") or player:GetAttribute(\"Posto17Box\") then return end\n        if typeof(wall) ~= \"Instance\" or not wall:IsA(\"BasePart\")\n            or not wall:IsDescendantOf(ctx.world) or not wall.CanCollide\n            or (wall.Name ~= \"Parede\" and wall.Name ~= \"Caixa\") then return end\n\n        local p = wall.CFrame:PointToObjectSpace(root.Position)\n        local h = wall.Size * 0.5\n        local point = wall.CFrame:PointToWorldSpace(Vector3.new(\n            math.clamp(p.X, -h.X, h.X), math.clamp(p.Y, -h.Y, h.Y), math.clamp(p.Z, -h.Z, h.Z)))\n        if (point - root.Position).Magnitude > 4.05 then return end\n\n        local mode = Motion.coverTop(character, root, wall)\n        if not mode then return end\n        player:SetAttribute(\"Posto17Sprint\", nil)\n        player:SetAttribute(\"Posto17CoverHeight\", mode)\n        if mode == \"LOW\" then ctx.posture(player, \"CROUCH\") end\n        ctx.speed(player)\n    end\n    coverRemote.OnServerEvent:Connect(cover)\n\n    local function equipBox(player)\n        local character, hum, root = Motion.rig(player)\n        if not root or root.Anchored or boxJobs[player]\n            or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Dragging\")\n            or player:GetAttribute(\"Posto17Prone\") or player:GetAttribute(\"Posto17Won\")\n            or player:GetAttribute(\"Posto17Stance\") == \"VENT\" then return end\n        if player:GetAttribute(\"Posto17Box\") then\n            clearBox(player)\n            ctx.posture(player, \"STAND\")\n            return\n        end\n        clearCover(player)\n        player:SetAttribute(\"Posto17Sprint\", nil)\n        local job = {}\n        boxJobs[player] = job\n        Motion.play(player, \"BOX\", 0.8)\n        task.delay(0.40, function()\n            if boxJobs[player] ~= job then return end\n            boxJobs[player] = nil\n            if player.Character ~= character or hum.Health <= 0 or root.Anchored\n                or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Dragging\")\n                or player:GetAttribute(\"Posto17Prone\") or player:GetAttribute(\"Posto17Won\") then return end\n            ctx.posture(player, \"CROUCH\")\n            local box = Instance.new(\"Part\")\n            box.Name = \"P17CaixaPortatil\"\n            local extent = character:GetExtentsSize()\n            box.Size = Vector3.new(math.max(4.35, extent.X + 0.35), 3.85, 4.50)\n            box.CFrame = root.CFrame * CFrame.new(0, -0.43, -0.33)\n            box.Color = Color3.fromRGB(139, 103, 67)\n            box.Material = Enum.Material.SmoothPlastic\n            local tape = Instance.new(\"Part\")\n            tape.Name = \"Fita\"\n            tape.Size = Vector3.new(0.29, 0.025, box.Size.Z)\n            tape.Color = Color3.fromRGB(181, 150, 98)\n            tape.CFrame = box.CFrame * CFrame.new(0, box.Size.Y * 0.5, 0)\n            tape.CanCollide, tape.CanTouch, tape.CanQuery, tape.Massless = false, false, false, true\n            tape.Parent = box\n            local stripWeld = Instance.new(\"WeldConstraint\")\n            stripWeld.Part0, stripWeld.Part1, stripWeld.Parent = box, tape, tape\n            box.CanCollide, box.CanTouch, box.CanQuery = false, false, false\n            box.Massless = true\n            box.Parent = character\n            local weld = Instance.new(\"WeldConstraint\")\n            weld.Part0, weld.Part1, weld.Parent = root, box, box\n            local originals = {}\n            local function conceal(item)\n                if (item:IsA(\"BasePart\") or item:IsA(\"Decal\")) and item ~= box\n                    and not item:IsDescendantOf(box) and originals[item] == nil then\n                    originals[item] = item.Transparency\n                    item.Transparency = 1\n                end\n            end\n            for _, item in ipairs(character:GetDescendants()) do conceal(item) end\n            boxLooks[player] = {parts = originals, connection = character.DescendantAdded:Connect(conceal)}\n            player:SetAttribute(\"Posto17Box\", true)\n        end)\n    end\n\n    local function sprint(player, enabled)\n        local _, _, root = Motion.rig(player)\n        if not root then return end\n        if enabled and (root.Anchored or player:GetAttribute(\"Posto17Stance\") ~= \"STAND\"\n            or player:GetAttribute(\"Posto17CoverHeight\") or player:GetAttribute(\"Posto17Box\")\n            or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Dragging\")\n            or player:GetAttribute(\"Posto17Won\")) then return end\n        player:SetAttribute(\"Posto17Sprint\", enabled or nil)\n        ctx.speed(player)\n    end\n    mobility.OnServerEvent:Connect(function(player, action, enabled)\n        if action == \"BOX\" then equipBox(player) end\n        if action == \"SPRINT\" and type(enabled) == \"boolean\" then sprint(player, enabled) end\n    end)\n\n    local function clear(player)\n        if not player.Parent then return end\n        player:SetAttribute(\"Posto17Sprint\", nil)\n        clearCover(player)\n        clearBox(player)\n    end\n    local function watch(player)\n        player.CharacterRemoving:Connect(function()\n            boxJobs[player] = nil\n            clear(player)\n        end)\n        for _, key in ipairs({\"Posto17Hidden\", \"Posto17Dragging\", \"Posto17Won\", \"Posto17Prone\"}) do\n            player:GetAttributeChangedSignal(key):Connect(function()\n                if player:GetAttribute(key) then clear(player) end\n            end)\n        end\n    end\n    for _, player in ipairs(ctx.players:GetPlayers()) do watch(player) end\n    ctx.players.PlayerAdded:Connect(watch)\n    ctx.players.PlayerRemoving:Connect(clearBox)\n    return {sprint = sprint, cover = cover, equipBox = equipBox, clear = clear}\nend\n\nreturn Motion\n"},{"studio":"ServerScriptService/TestRange","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/TestRange (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto 17: area de ensaio permanente, isolada da missao.\n-- Somente no Studio ou no Place de testes. A experiencia original nao muda.\nlocal TestRange = {}\nlocal TEST_PLACE_ID = 119377443515742\nlocal ORIGIN = Vector3.new(185, 0, 0)\n\nfunction TestRange.enabled(runService, placeId)\n    return runService:IsStudio() or placeId == TEST_PLACE_ID\nend\n\nfunction TestRange.build(ctx)\n    if not TestRange.enabled(ctx.runService, ctx.placeId) then return nil end\n\n    local group = Instance.new(\"Model\")\n    group.Name = \"P17_CampoDeTestes\"\n    group.Parent = ctx.world\n\n    local function geometry(name, size, position, color, material, collides)\n        local item = ctx.part(name, size, ORIGIN + position, color,\n            material or Enum.Material.SmoothPlastic, collides)\n        item.Parent = group\n        if not collides then\n            item.CanCollide = false\n            item.CanTouch = false\n        end\n        return item\n    end\n    local RED = Color3.fromRGB(160, 48, 51)\n    local DARK = Color3.fromRGB(37, 43, 50)\n    local FLOOR = Color3.fromRGB(120, 132, 138)\n    local WHITE = Color3.fromRGB(221, 230, 227)\n    local TEAL = Color3.fromRGB(76, 161, 152)\n\n    geometry(\"PisoTeste\", Vector3.new(78, 1, 60),\n        Vector3.new(0, -0.5, 0), FLOOR, Enum.Material.Concrete, true)\n    for _, z in ipairs({-29.5, 29.5}) do\n        geometry(\"LimitePista\", Vector3.new(78, 1.8, 0.55),\n            Vector3.new(0, 0.9, z), DARK, Enum.Material.Metal, true)\n    end\n    for _, x in ipairs({-38.5, 38.5}) do\n        geometry(\"LimitePista\", Vector3.new(0.55, 1.8, 60),\n            Vector3.new(x, 0.9, 0), DARK, Enum.Material.Metal, true)\n    end\n\n    local function label(name, text, pos, tint, width)\n        local frame = geometry(name, Vector3.new(width or 14, 2.6, 0.3),\n            pos, DARK, Enum.Material.Metal, false)\n        local stripe = geometry(\"Faixa_\" .. name,\n            Vector3.new(width or 14, 0.2, 0.32),\n            pos + Vector3.new(0, 1.15, -0.03),\n            tint or RED, Enum.Material.Neon, false)\n        stripe.CanQuery = false\n        local gui = Instance.new(\"SurfaceGui\")\n        gui.Name = \"Identificacao\"\n        gui.Face = Enum.NormalId.Front\n        gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n        gui.PixelsPerStud = 23\n        gui.LightInfluence = 0.15\n        gui.Parent = frame\n        local textLabel = Instance.new(\"TextLabel\")\n        textLabel.Name = \"Texto\"\n        textLabel.Size = UDim2.fromScale(1, 1)\n        textLabel.BackgroundTransparency = 1\n        textLabel.Text = text\n        textLabel.TextColor3 = WHITE\n        textLabel.Font = Enum.Font.Code\n        textLabel.TextScaled = true\n        textLabel.Parent = gui\n        return frame\n    end\n\n    label(\"TituloTeste\", \"POSTO 17  /  AREA DE TESTES\", Vector3.new(-9, 7, -27),\n        RED, 28)\n    label(\"AvisoPista\", \"SO TESTAR POSTURAS  /  SEM INIMIGOS\",\n        Vector3.new(-10, 5, 25), TEAL, 26)\n    label(\"PontoAgachar\", \"01  AGACHAR  /  C OU BOTAO\",\n        Vector3.new(-9, 3.9, -18), RED, 23)\n    label(\"PontoRastejar\", \"02  RASTEJAR  /  Z OU BOTAO\",\n        Vector3.new(13, 3.9, -18), RED, 23)\n    label(\"PontoAndar\", \"03  CAMINHAR  /  COMPARAR ANIMACOES\",\n        Vector3.new(4, 3.9, 20), TEAL, 29)\n\n    for _, lane in ipairs({\n        {x = -11, color = RED}, {x = 12, color = TEAL}\n    }) do\n        for _, dx in ipairs({-5.7, 5.7}) do\n            geometry(\"LinhaPista\", Vector3.new(0.2, 0.05, 29),\n                Vector3.new(lane.x + dx, 0.08, -1), lane.color,\n                Enum.Material.Neon, false).CanQuery = false\n        end\n        for _, z in ipairs({-13, -4, 5, 14}) do\n            geometry(\"TracoPista\", Vector3.new(1.6, 0.06, 0.21),\n                Vector3.new(lane.x, 0.085, z), WHITE,\n                Enum.Material.SmoothPlastic, false).CanQuery = false\n        end\n    end\n\n    -- Travessia contextual em cenarios de QA. Frente livre da pista principal.\n    geometry(\"P17_BarreiraBaixa\", Vector3.new(7, 1.95, .65),\n        Vector3.new(-31, .975, -12), DARK, Enum.Material.Wood, true)\n    geometry(\"P17_BlocoEscalada\", Vector3.new(5.6, 4.2, 4.2),\n        Vector3.new(-21, 2.1, -11), FLOOR, Enum.Material.Concrete, true)\n    label(\"PlacaTravessia\", \"04 / PASSAR  G OU BOTAO\",\n        Vector3.new(-30, 3.1, -17.8), RED, 18)\n    label(\"PlacaEscalada\", \"05 / ESCALAR  G OU BOTAO\",\n        Vector3.new(-19.5, 5.0, -17.8), TEAL, 18)\n\n    -- Bancada de modelos e animacoes R6 (73 clipes acessiveis individualmente).\n    local bench=geometry(\"P17_BancadaR6\",Vector3.new(13.8,1.35,4.2),\n        Vector3.new(25,0.70,12.5),DARK,Enum.Material.Metal,true)\n    label(\"PlacaBancadaR6\",\"06 / 73 ANIMACOES  /  3 MODELOS\",\n        Vector3.new(25,4.05,9.15),TEAL,25)\n    local prompt=Instance.new(\"ProximityPrompt\")\n    prompt.ActionText=\"Abrir bancada R6\"\n    prompt.ObjectText=\"73 animacoes individuais\"\n    prompt.MaxActivationDistance=12\n    prompt.HoldDuration=0.2\n    prompt.RequiresLineOfSight=false\n    prompt.Parent=bench\n    -- Os modelos de exposicao sao os originais em peças, sem scripts externos.\n    local models=require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\")\n        :WaitForChild(\"Posto17Modelos\"))\n    for _,entry in ipairs({\n        {kind=\"pistola\",x=20.7},\n        {kind=\"submetralhadora\",x=25.0},\n        {kind=\"fuzil\",x=29.3},\n    }) do\n        local item=models.make(entry.kind)\n        if item then\n            item.Name=\"Exposicao_\"..entry.kind\n            item:PivotTo(CFrame.new(ORIGIN+Vector3.new(entry.x,2.0,12.5))\n                * CFrame.Angles(0,math.rad(90),0))\n            item.Parent=group\n        end\n    end\n\n    -- Luz independente: a sabotagem na missao nao apaga o local de teste.\n    for _, x in ipairs({-30, 30}) do\n        for _, z in ipairs({-21, 21}) do\n            geometry(\"PosteLuzTeste\", Vector3.new(0.65, 11.2, 0.65),\n                Vector3.new(x, 5.6, z), DARK, Enum.Material.Metal, false)\n            local lamp = geometry(\"LuzTeste\", Vector3.new(2.2, 0.28, 1.6),\n                Vector3.new(x, 10.9, z), WHITE, Enum.Material.Neon, false)\n            lamp.CanQuery = false\n            local light = Instance.new(\"PointLight\")\n            light.Name = \"LuzAreaTestes\"\n            light.Brightness = 1.8\n            light.Range = 39\n            light.Shadows = false\n            light.Color = WHITE\n            light.Parent = lamp\n        end\n    end\n\n    -- O destino padrao no Place de teste e esta sala, nunca o mapa normal.\n    local spawn = Instance.new(\"SpawnLocation\")\n    spawn.Name = \"SpawnCampoDeTestes\"\n    spawn.Size = Vector3.new(7, 1, 7)\n    spawn.Position = ORIGIN + Vector3.new(-31, 0.5, 0)\n    spawn.Anchored = true\n    spawn.Neutral = true\n    spawn.Enabled = true\n    spawn.Material = Enum.Material.Metal\n    spawn.Color = TEAL\n    spawn.Parent = group\n    ctx.missionSpawn.Enabled = false\n\n    local function gateway(name, actionText, pos, destination, destinationFlag)\n        local part = geometry(name, Vector3.new(5, 4, 2),\n            pos, destinationFlag and RED or TEAL,\n            Enum.Material.Metal, true)\n        label(\"Placa_\" .. name, actionText,\n            pos + Vector3.new(0, 3.5, -1.8), RED, 21)\n        local prompt = Instance.new(\"ProximityPrompt\")\n        prompt.Name = \"TransicaoTestes\"\n        prompt.ActionText = actionText\n        prompt.ObjectText = \"Posto 17\"\n        prompt.HoldDuration = 0.35\n        prompt.MaxActivationDistance = 10\n        prompt.RequiresLineOfSight = false\n        prompt.Parent = part\n        prompt.Triggered:Connect(function(player)\n            local char = player.Character\n            local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n            local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n            if not root or not hum or hum.Health <= 0 then return end\n            if (root.Position - part.Position).Magnitude > 11 then return end\n            player:SetAttribute(\"Posto17InTestRange\", destinationFlag)\n            player:SetAttribute(\"Posto17InVisualShowcase\",false)\n            root.CFrame = CFrame.new(destination)\n            root.AssemblyLinearVelocity = Vector3.zero\n            root.AssemblyAngularVelocity = Vector3.zero\n        end)\n    end\n\n    gateway(\"AcessoMissao\", \"IR PARA MISSAO\",\n        Vector3.new(31, 2.4, 0),\n        ctx.missionSpawn.Position + Vector3.new(0, 5, 0), false)\n\n    -- Portal reverso junto da entrada da missao. Sem teleportes automaticos.\n    local returnPart = ctx.part(\"VoltarAoCampoDeTestes\",\n        Vector3.new(3, 4, 2),\n        ctx.missionSpawn.Position + Vector3.new(9.1, 1.6, -1),\n        TEAL, Enum.Material.Metal, true)\n    returnPart.Parent = group\n    local returnPrompt = Instance.new(\"ProximityPrompt\")\n    returnPrompt.Name = \"VoltarTestes\"\n    returnPrompt.ActionText = \"Voltar ao campo de testes\"\n    returnPrompt.ObjectText = \"Area de testes\"\n    returnPrompt.HoldDuration = 0.35\n    returnPrompt.MaxActivationDistance = 9\n    returnPrompt.RequiresLineOfSight = false\n    returnPrompt.Parent = returnPart\n    returnPrompt.Triggered:Connect(function(player)\n        local char = player.Character\n        local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n        local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n        if not root or not hum or hum.Health <= 0 then return end\n        if (root.Position - returnPart.Position).Magnitude > 10 then return end\n        root.CFrame = spawn.CFrame + Vector3.new(0, 4, 0)\n        root.AssemblyLinearVelocity = Vector3.zero\n        root.AssemblyAngularVelocity = Vector3.zero\n        player:SetAttribute(\"Posto17InTestRange\", true)\n        player:SetAttribute(\"Posto17InVisualShowcase\", false)\n    end)\n\n    -- A showcase nao substitui a pista de animacoes nem a missao.\n    local showcase = require(script.Parent.VisualShowcase).build({\n        world = ctx.world,\n        part = ctx.part,\n        identity = ctx.identity,\n        players = ctx.players,\n        returnPosition = spawn.Position + Vector3.new(0, 4, 0),\n    })\n    local access = geometry(\"AcessoMostraVisual\",\n        Vector3.new(4, 3.8, 2), Vector3.new(-28, 2.1, 22),\n        RED, Enum.Material.Metal, true)\n    label(\"IdentificacaoMostra\", \"MOSTRA VISUAL / P17\",\n        Vector3.new(-27, 5.6, 20.4), RED, 20)\n    local openPrompt = Instance.new(\"ProximityPrompt\")\n    openPrompt.Name = \"EntrarMostraVisual\"\n    openPrompt.ObjectText = \"Area de testes\"\n    openPrompt.ActionText = \"Auditar identidade visual\"\n    openPrompt.HoldDuration = 0.35\n    openPrompt.MaxActivationDistance = 10\n    openPrompt.RequiresLineOfSight = false\n    openPrompt.Parent = access\n    openPrompt.Triggered:Connect(function(player)\n        local char = player.Character\n        local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n        local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n        if not hum or hum.Health <= 0 or not root\n            or (root.Position - access.Position).Magnitude > 11 then return end\n        player:SetAttribute(\"Posto17InVisualShowcase\", true)\n        player:SetAttribute(\"Posto17InTestRange\", true)\n        root.CFrame = CFrame.new(showcase.entryPosition)\n        root.AssemblyLinearVelocity = Vector3.zero\n        root.AssemblyAngularVelocity = Vector3.zero\n    end)\n\n    ctx.players.PlayerAdded:Connect(function(player)\n        player:SetAttribute(\"Posto17InTestRange\", true)\n        player:SetAttribute(\"Posto17InVisualShowcase\", false)\n        player.CharacterAdded:Connect(function()\n            player:SetAttribute(\"Posto17InTestRange\", true)\n            player:SetAttribute(\"Posto17InVisualShowcase\", false)\n        end)\n    end)\n    for _, player in ipairs(ctx.players:GetPlayers()) do\n        player:SetAttribute(\"Posto17InTestRange\", true)\n        player:SetAttribute(\"Posto17InVisualShowcase\", false)\n        player.CharacterAdded:Connect(function()\n            player:SetAttribute(\"Posto17InTestRange\", true)\n            player:SetAttribute(\"Posto17InVisualShowcase\", false)\n        end)\n    end\n\n    ctx.world:SetAttribute(\"TestRangeEnabled\", true)\n    ctx.world:SetAttribute(\"TestRangeVersion\", \"1\")\n    return {spawn = spawn, root = group, showcase = showcase}\nend\nreturn TestRange\n"},{"studio":"ServerScriptService/Traversal","class":"Script","source":"-- Local no Studio: ServerScriptService/Traversal (Script)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto 17: travessia contextual original para rig quadrado (R15 interno).\n-- O servidor valida a geometria antes de mover o personagem.\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Motion = require(script.Parent:WaitForChild(\"TacticalMotion\"))\nlocal world = workspace:WaitForChild(\"Posto17\", 30)\nif not world then return end\n\nlocal event = RS:FindFirstChild(\"Posto17Traversal\") or Instance.new(\"RemoteEvent\")\nevent.Name = \"Posto17Traversal\"\nevent.Parent = RS\nlocal active = {}\nlocal lastUse = {}\n\nlocal function smoother(t)\n    t = math.clamp(t, 0, 1)\n    return t * t * (3 - 2 * t)\nend\n\nlocal function scan(player)\n    local character, hum, root = Motion.rig(player)\n    if not root or not character or not hum or not world.Parent\n        or root.Anchored or hum.FloorMaterial == Enum.Material.Air\n        or player:GetAttribute(\"Posto17Hidden\")\n        or player:GetAttribute(\"Posto17Dragging\")\n        or player:GetAttribute(\"Posto17Prone\")\n        or player:GetAttribute(\"Posto17Box\")\n        or player:GetAttribute(\"Posto17Won\")\n        or player:GetAttribute(\"Posto17CoverHeight\")\n        or player:GetAttribute(\"Posto17Stance\") ~= \"STAND\"\n        or active[player] then return nil end\n    local forward = root.CFrame.LookVector * Vector3.new(1, 0, 1)\n    if forward.Magnitude < 0.85 then return nil end\n    forward = forward.Unit\n    local params = RaycastParams.new()\n    params.FilterType = Enum.RaycastFilterType.Exclude\n    params.FilterDescendantsInstances = {character}\n    params.RespectCanCollide = true\n    local ground = workspace:Raycast(root.Position, Vector3.new(0, -8, 0), params)\n    if not ground or ground.Normal.Y < .75 then return nil end\n    local floorY = ground.Position.Y\n    local footGap = root.Position.Y - floorY\n    if footGap < 1.7 or footGap > 4.5 then return nil end\n    local face\n    for _, height in ipairs({1.2, 1.8, 2.35}) do\n        local origin = Vector3.new(root.Position.X, floorY + height, root.Position.Z)\n        local hit = workspace:Raycast(origin, forward * 3.4, params)\n        if hit and hit.Normal.Y < .3 and hit.Normal.Y > -.3\n            and hit.Normal:Dot(forward) < -.7 then\n            face = hit\n            break\n        end\n    end\n    if not face then return nil end\n    local obstacle = face.Instance\n    if not obstacle:IsA(\"BasePart\") or not obstacle.Anchored\n        or not obstacle.CanCollide or not obstacle:IsDescendantOf(world)\n        or obstacle.Name == \"PisoTeste\" or obstacle.Name == \"LimitePista\" then return nil end\n    local topOrigin = face.Position - face.Normal * .18 + Vector3.new(0, 8, 0)\n    local top = workspace:Raycast(topOrigin, Vector3.new(0, -11, 0), params)\n    if not top or top.Instance ~= obstacle or top.Normal.Y < .82 then return nil end\n    local height = top.Position.Y - floorY\n    if height < 1.15 or height > 5.8 then return nil end\n    local localDirection = obstacle.CFrame:VectorToObjectSpace(forward)\n    local thickness = math.abs(localDirection.X)*obstacle.Size.X\n        + math.abs(localDirection.Z)*obstacle.Size.Z\n    local kind = height <= 2.7 and \"VAULT\" or \"CLIMB\"\n    if (kind == \"VAULT\" and thickness > 2.6)\n        or (kind == \"CLIMB\" and thickness > 7.5) then return nil end\n    local advance = kind == \"VAULT\" and thickness + 1.85\n        or math.clamp(thickness*.55, 1.05, 3.0)\n    local landingXZ = face.Position + forward * advance\n    local landingHit = workspace:Raycast(\n        landingXZ + Vector3.new(0, 9.5, 0), Vector3.new(0,-17,0), params)\n    if not landingHit or landingHit.Normal.Y < .8 then return nil end\n    if kind == \"CLIMB\" and landingHit.Instance ~= obstacle then return nil end\n    if kind == \"VAULT\" and landingHit.Position.Y > top.Position.Y - .25 then return nil end\n    if math.abs(landingHit.Position.Y - floorY) > 5.2 then return nil end\n    local landing = Vector3.new(landingXZ.X, landingHit.Position.Y + footGap, landingXZ.Z)\n    return {\n        player=player, character=character, hum=hum, root=root, forward=forward,\n        landing=landing, kind=kind, topY=top.Position.Y, start=root.Position,\n        obstacle=obstacle\n    }\nend\n\nlocal function traverse(info)\n    local player, character, hum, root = info.player, info.character, info.hum, info.root\n    if active[player] then return end\n    local duration = info.kind == \"CLIMB\" and 1.24 or .82\n    active[player] = true\n    local wasAnchored = root.Anchored\n    local speed = hum.WalkSpeed\n    local rotate = hum.AutoRotate\n    local start = root.Position\n    local destination = info.landing\n    local vector = info.forward\n    local top = math.max(start.Y, destination.Y) + (info.kind == \"CLIMB\" and .85 or 1.35)\n    local startStamp = os.clock()\n    root.AssemblyLinearVelocity = Vector3.zero\n    root.AssemblyAngularVelocity = Vector3.zero\n    hum.AutoRotate = false\n    hum.WalkSpeed = 0\n    root.Anchored = true\n    player:SetAttribute(\"Posto17Traversing\", true)\n    Motion.play(player, info.kind, duration, destination)\n    local binding\n    local function finish()\n        if binding then binding:Disconnect(); binding = nil end\n        if character.Parent and root.Parent then\n            root.CFrame = CFrame.lookAt(destination, destination + vector)\n            root.AssemblyLinearVelocity = Vector3.zero\n            root.AssemblyAngularVelocity = Vector3.zero\n            root.Anchored = wasAnchored\n        end\n        if hum.Parent then\n            hum.AutoRotate = rotate\n            hum.WalkSpeed = speed\n        end\n        player:SetAttribute(\"Posto17Traversing\", false)\n        Motion.cancel(player, info.kind)\n        active[player] = nil\n    end\n    binding = RunService.Heartbeat:Connect(function()\n        if player.Character ~= character or not root.Parent or hum.Health <= 0 then\n            if binding then binding:Disconnect(); binding = nil end\n            if root.Parent then root.Anchored = wasAnchored end\n            player:SetAttribute(\"Posto17Traversing\", false)\n            active[player] = nil\n            return\n        end\n        local t = math.clamp((os.clock() - startStamp) / duration, 0, 1)\n        if t >= 1 then finish(); return end\n        local travel\n        if info.kind == \"CLIMB\" then\n            travel = smoother((t - .18) / .63)\n        else\n            travel = smoother((t - .10) / .80)\n        end\n        local horizontal = start:Lerp(destination, travel)\n        local altitude\n        if t < .53 then\n            altitude = start.Y + (top - start.Y) * smoother(t / .53)\n        else\n            altitude = top + (destination.Y - top) * smoother((t - .53) / .47)\n        end\n        local position = Vector3.new(horizontal.X, altitude, horizontal.Z)\n        root.CFrame = CFrame.lookAt(position, position + vector)\n    end)\nend\n\nevent.OnServerEvent:Connect(function(player)\n    local now = os.clock()\n    if active[player] or now - (lastUse[player] or -100) < .65 then return end\n    lastUse[player] = now\n    local info = scan(player)\n    if info then traverse(info) end\nend)\n\nPlayers.PlayerRemoving:Connect(function(player)\n    lastUse[player] = nil\n    active[player] = nil\nend)\n\n-- Controles de auditoria apenas no Place privado; nao aparecem na missao real.\nif game.PlaceId == 119377443515742 or RunService:IsStudio() then\n    local demo = RS:FindFirstChild(\"P17TraversalDemo\") or Instance.new(\"RemoteEvent\")\n    demo.Name = \"P17TraversalDemo\"\n    demo.Parent = RS\n    demo.OnServerEvent:Connect(function(player, mode)\n        if mode ~= \"VAULT\" and mode ~= \"CLIMB\" then return end\n        if active[player] then return end\n        local char,hum,root = Motion.rig(player)\n        if not root or not hum or root.Anchored or not player:GetAttribute(\"Posto17InTestRange\") then return end\n        local p = mode == \"VAULT\" and Vector3.new(154, 3.1, -8.6)\n            or Vector3.new(164, 3.1, -6.0)\n        root.CFrame = CFrame.lookAt(p, p + Vector3.new(0,0,-1))\n        root.AssemblyLinearVelocity = Vector3.zero\n        task.delay(.55,function()\n            if player.Character ~= char or active[player] then return end\n            local info = scan(player)\n            if info then\n                player:SetAttribute(\"P17TraversalReview\",mode)\n                traverse(info)\n            else\n                player:SetAttribute(\"P17TraversalReview\",\"SEM_SUPERFICIE\")\n            end\n        end)\n    end)\nend\n"},{"studio":"ServerScriptService/VisualShowcase","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/VisualShowcase (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- P17 Visual Showcase: laboratorio de arte isolado da missao e da pista de animacao.\n-- Criado somente para a experiencia de testes. Geometria low-poly original.\nlocal VisualShowcase = {}\nlocal CENTER = Vector3.new(317,0,0)\nlocal modes = {\"BASE\", \"FOCO\", \"ALERTA\"}\n\nlocal function rgb(r,g,b) return Color3.fromRGB(r,g,b) end\nfunction VisualShowcase.build(ctx)\n    local p = ctx.identity and ctx.identity.Palette or {\n        Graphite=rgb(31,35,40), Charcoal=rgb(24,29,34), Armor=rgb(53,60,68),\n        BrushedSteel=rgb(90,100,109), Concrete=rgb(119,123,128),\n        TechnicalRubber=rgb(26,30,31), Canvas=rgb(67,78,70),\n        Oxide=rgb(123,79,62), BlackRed=rgb(139,0,0), AlertRed=rgb(162,57,52),\n        Amber=rgb(184,131,47), OperationalGreen=rgb(76,97,83),\n        LightCold=rgb(200,218,216), LightWarm=rgb(229,199,154),\n        Paper=rgb(227,228,219),\n    }\n    local model = Instance.new(\"Model\")\n    model.Name = \"P17_MostraVisual\"\n    model:SetAttribute(\"ArtRevision\", \"P17-VIS-1\")\n    model.Parent = ctx.world\n    local currentGroup = model\n    local pieces, lamps, lights = 0, {}, {}\n    local function group(name)\n        local result = Instance.new(\"Model\")\n        result.Name = name\n        result.Parent = model\n        currentGroup = result\n        return result\n    end\n    local function block(name, size, xyz, color, material, solid)\n        local obj = ctx.part(name, size, CENTER+xyz, color or p.Armor,\n            material or Enum.Material.Metal, solid == true)\n        obj.Parent = currentGroup\n        obj.CanCollide = solid == true\n        obj.CanTouch = false\n        if not solid then obj.CanQuery = false end\n        obj:SetAttribute(\"P17ArtPiece\",true)\n        pieces += 1\n        return obj\n    end\n    local function sign(name, text, xyz, width, tone)\n        local face = block(name, Vector3.new(width or 15,2.35,.25),\n            xyz, p.Graphite, Enum.Material.Metal)\n        local rail = block(name..\"_sinal\", Vector3.new(width or 15,.12,.27),\n            xyz+Vector3.new(0,1.05,.03),tone or p.Amber,Enum.Material.SmoothPlastic)\n        rail.CanQuery = false\n        for _, faceName in ipairs({Enum.NormalId.Front,Enum.NormalId.Back}) do\n            local gui = Instance.new(\"SurfaceGui\")\n            gui.Name = \"PlacaTecnica\"\n            gui.Face = faceName\n            gui.AlwaysOnTop = false\n            gui.PixelsPerStud = 19\n            gui.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n            gui.LightInfluence = .16\n            gui.Parent = face\n            local typeLabel = Instance.new(\"TextLabel\")\n            typeLabel.Name=\"Identificador\"\n            typeLabel.BackgroundTransparency=1\n            typeLabel.Size=UDim2.fromScale(1,1)\n            typeLabel.Font=Enum.Font.Code\n            typeLabel.TextScaled=true\n            typeLabel.TextColor3=p.Paper\n            typeLabel.Text=text\n            typeLabel.Parent=gui\n        end\n        return face\n    end\n    local function station(name, title, x, z, tint)\n        group(name)\n        block(\"Base_\"..name,Vector3.new(25,.18,25),\n            Vector3.new(x,.07,z),p.Graphite,Enum.Material.Concrete)\n        for _, xedge in ipairs({-12.1,12.1}) do\n            block(\"Guia_\"..name,Vector3.new(.2,.055,24),\n                Vector3.new(x+xedge,.17,z),p.BrushedSteel,Enum.Material.Metal)\n        end\n        sign(\"Setor_\"..name,title,Vector3.new(x,7.9,z-11.6),23,tint)\n    end\n    local function lamp(name, xyz, tint, intensity, dist)\n        local head = block(name,Vector3.new(2,.21,1.2),xyz,\n            tint or p.LightCold,Enum.Material.Neon)\n        local light = Instance.new(\"PointLight\")\n        light.Name=\"LuzDeInspecao\"\n        light.Range=dist or 16\n        light.Brightness=intensity or .85\n        light.Color=tint or p.LightCold\n        light.Shadows=false\n        light.Parent=head\n        lamps[#lamps+1]=light\n        lights[#lights+1]=head\n        return head\n    end\n    local function rubberCase(name, xyz, w)\n        local width=w or 5\n        block(name..\"_base\",Vector3.new(width,.48,3.3),\n            xyz+Vector3.new(0,.24,0),p.Graphite,Enum.Material.SmoothPlastic,true)\n        block(name..\"_espuma\",Vector3.new(width-.35,.13,2.9),\n            xyz+Vector3.new(0,.54,0),p.TechnicalRubber,Enum.Material.SmoothPlastic)\n        for _, x in ipairs({-width/2+.14,width/2-.14}) do\n            block(name..\"_beiral\",Vector3.new(.2,.29,3.35),\n                xyz+Vector3.new(x,.62,0),p.Armor)\n        end\n        for _, z in ipairs({-1.55,1.55}) do\n            block(name..\"_moldura\",Vector3.new(width,.22,.17),\n                xyz+Vector3.new(0,.62,z),p.Armor)\n        end\n        block(name..\"_tampa\",Vector3.new(width,.32,2.9),\n            xyz+Vector3.new(0,2.05,1.66),p.Armor)\n        block(name..\"_dobradica\",Vector3.new(width-.3,.1,.14),\n            xyz+Vector3.new(0,.78,1.6),p.BrushedSteel)\n    end\n    local function cabinet(name, xyz, w, h)\n        local width=w or 3.4\n        local height=h or 6.3\n        block(name..\"_corpo\",Vector3.new(width,height,2.1),\n            xyz+Vector3.new(0,height/2,0),p.Armor,Enum.Material.Metal,true)\n        for _, x in ipairs({-width*.25,width*.25}) do\n            block(name..\"_porta\",Vector3.new(width*.47,height-.28,.075),\n                xyz+Vector3.new(x,height/2,-1.08),p.Graphite)\n            block(name..\"_puxador\",Vector3.new(.08,.55,.12),\n                xyz+Vector3.new(x+width*.16,height*.47,-1.16),p.BrushedSteel)\n        end\n        block(name..\"_rodape\",Vector3.new(width,.17,2.2),\n            xyz+Vector3.new(0,.1,0),p.TechnicalRubber)\n    end\n    local function workbench(name,xyz,w)\n        local width = w or 9\n        block(name..\"_tampo\",Vector3.new(width,.32,4),\n            xyz+Vector3.new(0,2.65,0),p.BrushedSteel,Enum.Material.Metal,true)\n        for _, x in ipairs({-width*.44,width*.44}) do\n            block(name..\"_suporte\",Vector3.new(.4,2.55,3.4),\n                xyz+Vector3.new(x,1.25,0),p.Graphite)\n        end\n        block(name..\"_tapete\",Vector3.new(width*.82,.065,3.2),\n            xyz+Vector3.new(0,2.85,0),p.TechnicalRubber,\n            Enum.Material.SmoothPlastic)\n    end\n    local function plate(name,size,xyz,tone,material)\n        return block(name,size,xyz,tone,material or Enum.Material.Metal)\n    end\n\n    -- Circulacao e arquitetura: piso continuo, duas alas com tres bancadas.\n    group(\"00_Circulacao\")\n    block(\"PisoGeral\",Vector3.new(90,1,70),\n        Vector3.new(0,-.55,0),p.Concrete,Enum.Material.Concrete,true)\n    block(\"ParedeFundo\",Vector3.new(90,10,.7),\n        Vector3.new(0,4.7,-34.5),p.Graphite,Enum.Material.Concrete,true)\n    for _, x in ipairs({-44,44}) do\n        block(\"ParedeLateral\",Vector3.new(.75,10,70),\n            Vector3.new(x,4.7,0),p.Graphite,Enum.Material.Concrete,true)\n    end\n    for _, z in ipairs({-1.5,30.4}) do\n        block(\"LinhaDePercurso\",Vector3.new(84,.065,.16),\n            Vector3.new(0,.055,z),p.Amber,Enum.Material.SmoothPlastic)\n    end\n    sign(\"EntradaIdentidade\",\"P17  /  LABORATORIO DE IDENTIDADE\",\n        Vector3.new(0,9.2,-34),37,p.AlertRed)\n    for _, x in ipairs({-40,-20,0,20,40}) do\n        block(\"JuntaConcreto\",Vector3.new(.055,.07,64),\n            Vector3.new(x,.02,0),p.BrushedSteel,Enum.Material.Concrete)\n    end\n\n    -- A / Identidade: hierarquia, marca, paleta e sinalizacao.\n    station(\"A_Identidade\",\"A / IDENTIDADE E HIERARQUIA\",-28,-16,p.AlertRed)\n    plate(\"P17_Monograma\",Vector3.new(12,3.9,.22),\n        Vector3.new(-28,4.2,-23.5),p.Graphite)\n    sign(\"P17_Wordmark\",\"POSTO 17  /  OPERACOES\",\n        Vector3.new(-28,4.2,-23.32),11,p.AlertRed)\n    for i, spec in ipairs({\n        {p.Graphite, \"BASE\"}, {p.Armor,\"PINTURA\"},\n        {p.BrushedSteel,\"METAL\"}, {p.Amber,\"AVISO\"}, {p.AlertRed,\"RISCO\"},\n    }) do\n        plate(\"AmostraCor_\"..spec[2],Vector3.new(3.2,1.45,.3),\n            Vector3.new(-36+(i-1)*4.1,2.1,-10.9),\n            spec[1],Enum.Material.SmoothPlastic)\n    end\n    lamp(\"LuzMarca\",Vector3.new(-28,8,-14),p.LightCold,.68,15)\n\n    -- B / Arsenal: bancada funcional, hard case, protetores e divisorias.\n    station(\"B_Arsenal\",\"B / ARSENAL 3D E COMPOSICAO\",0,-16,p.Amber)\n    workbench(\"MesaArsenal\",Vector3.new(0,0,-13),10.4)\n    rubberCase(\"MaletaArsenal\",Vector3.new(-1,2.94,-13),5.6)\n    for _, x in ipairs({-3.2,-1.5,.25}) do\n        plate(\"DivisoriaEspuma\",Vector3.new(.12,.1,1.55),\n            Vector3.new(x,3.54,-13),p.Armor)\n    end\n    plate(\"SuporteDeEquipamento\",Vector3.new(1.3,.24,2),\n        Vector3.new(2.5,3.05,-13),p.BrushedSteel)\n    plate(\"EtiquetaInventario\",Vector3.new(1.3,.2,.55),\n        Vector3.new(2.5,3.32,-12),p.Paper,Enum.Material.SmoothPlastic)\n    cabinet(\"ArmarioArsenal\",Vector3.new(-8.1,0,-20),3.4,6.3)\n    cabinet(\"ArmarioManutencao\",Vector3.new(8.1,0,-20),3.4,6.3)\n    lamp(\"LuzBancadaArsenal\",Vector3.new(0,7.4,-13),\n        p.LightWarm,1.1,13)\n\n    -- C / Materiais: escala real e pares em parede para comparar resposta à luz.\n    station(\"C_Materiais\",\"C / PAINEL DE MATERIAIS\",28,-16,p.OperationalGreen)\n    local swatches={\n        {\"CONCRETO\",p.Concrete,Enum.Material.Concrete},\n        {\"ACO\",p.BrushedSteel,Enum.Material.Metal},\n        {\"PINTURA\",p.Armor,Enum.Material.Metal},\n        {\"BORRACHA\",p.TechnicalRubber,Enum.Material.SmoothPlastic},\n        {\"POLIMERO\",p.Graphite,Enum.Material.SmoothPlastic},\n        {\"TECIDO\",p.Canvas,Enum.Material.Fabric},\n        {\"OXIDO\",p.Oxide,Enum.Material.CorrodedMetal},\n    }\n    for i,item in ipairs(swatches) do\n        local column=(i-1)%4\n        local row=math.floor((i-1)/4)\n        local x=17.4+column*6.9\n        local z=-18+row*7\n        block(\"Material_\"..item[1],Vector3.new(3.9,3.2,3.9),\n            Vector3.new(x,1.6,z),item[2],item[3],true)\n        sign(\"NomeMaterial_\"..item[1],item[1],\n            Vector3.new(x,4.25,z-2.3),5.5,p.Amber)\n    end\n    lamp(\"LuzMaterialFria\",Vector3.new(28,8.5,-12),\n        p.LightCold,1.0,17)\n\n    -- D / Props: organizacao de oficio sem entulho decorativo.\n    station(\"D_Props\",\"D / OBJETOS E ESCALA\",-28,12,p.Amber)\n    cabinet(\"LockerTatico\",Vector3.new(-38,0,10),3.4,6.2)\n    workbench(\"MesaFerramental\",Vector3.new(-25,0,10),8)\n    rubberCase(\"CaseDeCampo\",Vector3.new(-25,2.94,10),4)\n    plate(\"BandejaDePecas\",Vector3.new(2,.1,1.15),\n        Vector3.new(-22,3.04,10),p.BrushedSteel)\n    for _, x in ipairs({-24.6,-23.9,-23.2}) do\n        plate(\"FerramentaAbstrata\",Vector3.new(.13,.13,.9),\n            Vector3.new(x,3.13,10.4),p.Concrete)\n    end\n    for index,pos in ipairs({\n        Vector3.new(-36,0,17),Vector3.new(-33,0,17),\n        Vector3.new(-34.5,2.1,17),\n    }) do\n        block(\"CaixaLogistica_\"..index,Vector3.new(2.8,1.9,2.8),\n            pos+Vector3.new(0,.95,0),p.Canvas,Enum.Material.Wood,true)\n    end\n    lamp(\"LuzProps\",Vector3.new(-28,8,12),p.LightWarm,.8,14)\n\n    -- E / Luz: interruptor de amostra alterna apenas a luz da showcase.\n    station(\"E_Iluminacao\",\"E / LUZ COM INTENCAO\",0,12,p.LightCold)\n    for i, item in ipairs({\n        {xyz=Vector3.new(-7,0,10),color=p.LightCold,name=\"FRIA\"},\n        {xyz=Vector3.new(0,0,10),color=p.LightWarm,name=\"TAREFA\"},\n        {xyz=Vector3.new(7,0,10),color=p.AlertRed,name=\"ALERTA\"},\n    }) do\n        block(\"PedestalLuz_\"..item.name,Vector3.new(5.9,2,5.5),\n            item.xyz+Vector3.new(0,1,0),p.Armor,Enum.Material.Metal,true)\n        block(\"AmostraLuz_\"..item.name,Vector3.new(3.4,.5,3.4),\n            item.xyz+Vector3.new(0,2.3,0),item.color,Enum.Material.Metal)\n    end\n    local switch=block(\"ChaveCenariosLuz\",Vector3.new(2.9,2.9,1.6),\n        Vector3.new(0,1.46,20),p.Graphite,Enum.Material.Metal,true)\n    local indicator=block(\"IndicadorCenaLuz\",Vector3.new(2,.24,.17),\n        Vector3.new(0,2.3,19.15),p.LightCold,Enum.Material.Neon)\n    local lightingPrompt=Instance.new(\"ProximityPrompt\")\n    lightingPrompt.Name=\"AlternarCenarioLuz\"\n    lightingPrompt.ObjectText=\"Ensaio de luz\"\n    lightingPrompt.ActionText=\"Alternar luz: BASE / FOCO / ALERTA\"\n    lightingPrompt.MaxActivationDistance=9\n    lightingPrompt.HoldDuration=.35\n    lightingPrompt.RequiresLineOfSight=false\n    lightingPrompt.Parent=switch\n    local mode=1\n    lamp(\"LuzComparativa\",Vector3.new(0,8,12),p.LightCold,.9,18)\n\n    local function applyMode()\n        local name=modes[mode]\n        ctx.world:SetAttribute(\"VisualShowcaseLighting\",name)\n        local color=name==\"BASE\" and p.LightCold or\n            (name==\"FOCO\" and p.LightWarm or p.AlertRed)\n        indicator.Color=color\n        for _, point in ipairs(lamps) do\n            point.Color=color\n            point.Brightness=name==\"FOCO\" and 1.25 or\n                (name==\"ALERTA\" and .65 or .9)\n        end\n    end\n    lightingPrompt.Triggered:Connect(function(player)\n        local character=player.Character\n        local hrp=character and character:FindFirstChild(\"HumanoidRootPart\")\n        if not hrp or (hrp.Position-switch.Position).Magnitude>10 then return end\n        mode=mode%3+1\n        applyMode()\n    end)\n    applyMode()\n\n    -- F / HUD: painel 3D usado junto da previsualizacao real de HUD local.\n    station(\"F_HUD\",\"F / INTERFACE EM CONTEXTO\",28,12,p.OperationalGreen)\n    local controlPanel=block(\"MesaDeTelemetria\",Vector3.new(15,5,.6),\n        Vector3.new(28,4.5,11),p.Graphite,Enum.Material.Metal)\n    sign(\"InstrucaoHUD\",\"CONTROLES DE HUD NO TOPO DA TELA\",\n        Vector3.new(28,4.2,10.6),13,p.OperationalGreen)\n    block(\"FaixaTelemetria\",Vector3.new(14,.2,.45),\n        Vector3.new(28,6.85,10.5),p.Amber)\n    lamp(\"LuzHUD\",Vector3.new(28,8,12),p.LightCold,.75,14)\n\n    -- Ultima zona: percurso de saida e terminal de retorno.\n    group(\"G_Retorno\")\n    local exit=block(\"TerminalVoltarTeste\",Vector3.new(4,3.8,1.8),\n        Vector3.new(37,1.9,27),p.OperationalGreen,Enum.Material.Metal,true)\n    sign(\"PlacaVoltarTeste\",\"VOLTAR AO CAMPO DE TESTES\",\n        Vector3.new(32,6.4,25.8),18,p.Amber)\n    local exitPrompt=Instance.new(\"ProximityPrompt\")\n    exitPrompt.Name=\"SairDaMostra\"\n    exitPrompt.ActionText=\"Voltar ao campo de testes\"\n    exitPrompt.ObjectText=\"Posto 17\"\n    exitPrompt.HoldDuration=.35\n    exitPrompt.MaxActivationDistance=9\n    exitPrompt.RequiresLineOfSight=false\n    exitPrompt.Parent=exit\n    exitPrompt.Triggered:Connect(function(player)\n        local char=player.Character\n        local hum=char and char:FindFirstChildOfClass(\"Humanoid\")\n        local hrp=char and char:FindFirstChild(\"HumanoidRootPart\")\n        if not hum or hum.Health<=0 or not hrp\n            or (hrp.Position-exit.Position).Magnitude>10 then return end\n        player:SetAttribute(\"Posto17InVisualShowcase\",false)\n        player:SetAttribute(\"Posto17InTestRange\",true)\n        hrp.CFrame=CFrame.new(ctx.returnPosition)\n        hrp.AssemblyLinearVelocity=Vector3.zero\n        hrp.AssemblyAngularVelocity=Vector3.zero\n    end)\n\n    ctx.world:SetAttribute(\"VisualShowcaseReady\",true)\n    ctx.world:SetAttribute(\"VisualShowcasePieces\",pieces)\n    ctx.world:SetAttribute(\"VisualShowcaseRevision\",\"P17-VIS-1\")\n    return {\n        model=model,\n        entryPosition=CENTER+Vector3.new(-37,4,26),\n        exitPosition=ctx.returnPosition,\n        lamps=lamps,\n        modes=modes,\n        pieceCount=pieces,\n    }\nend\nreturn VisualShowcase\n"},{"studio":"ServerScriptService/WorldDetail","class":"ModuleScript","source":"-- Local no Studio: ServerScriptService/WorldDetail (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto 17: ambiente industrial narrativo em pecas 3D originais.\n-- Sem MeshIds ou assets externos. Objetivos e rotas da missao sao preservados.\nlocal WorldDetail = {}\nfunction WorldDetail.build(ctx)\n    local world, light = ctx.world, ctx.lighting\n    local root = Instance.new(\"Folder\")\n    root.Name = \"Cenario3D\"\n    root.Parent = world\n    local palette = ctx.identity and ctx.identity.Palette\n    local colors = {\n        asphalt = palette and palette.Graphite or Color3.fromRGB(31,35,40),\n        concrete = palette and palette.Concrete or Color3.fromRGB(119,123,128),\n        dark = palette and palette.Charcoal or Color3.fromRGB(24,29,34),\n        metal = palette and palette.BrushedSteel or Color3.fromRGB(90,100,109),\n        rust = palette and palette.Oxide or Color3.fromRGB(123,79,62),\n        yellow = palette and palette.Amber or Color3.fromRGB(184,131,47),\n        red = palette and palette.AlertRed or Color3.fromRGB(162,57,52),\n        green = palette and palette.OperationalGreen or Color3.fromRGB(76,97,83),\n        blue = palette and palette.LightCold or Color3.fromRGB(200,218,216),\n        light = palette and palette.Paper or Color3.fromRGB(227,228,219),\n    }\n    local count = 0\n    local districtCount = 0\n    local lamps = {}\n    local zones = {\n        {name = \"01  PORTARIA\", pos = Vector3.new(-41, 0, 41), tone = colors.green},\n        {name = \"02  PATIO DE CARGA\", pos = Vector3.new(-34, 0, 23), tone = colors.yellow},\n        {name = \"03  MANUTENCAO\", pos = Vector3.new(-43, 0, -40), tone = colors.yellow},\n        {name = \"04  VIA TECNICA\", pos = Vector3.new(1, 0, -1), tone = colors.blue},\n        {name = \"05  COMUNICACOES\", pos = Vector3.new(34, 0, -5), tone = colors.blue},\n        {name = \"06  ARQUIVO\", pos = Vector3.new(34, 0, 32), tone = colors.red},\n        {name = \"07  NUCLEO DE DADOS\", pos = Vector3.new(43, 0, -39), tone = colors.red},\n    }\n    local function district(name)\n        local group = Instance.new(\"Model\")\n        group.Name = name\n        group.Parent = root\n        districtCount += 1\n        return group\n    end\n    local function block(group, name, size, pos, color, material, solid)\n        local piece = ctx.part(name, size, pos, color or colors.metal,\n            material or Enum.Material.Metal, solid == true)\n        piece.Parent = group\n        if not solid then piece.CanQuery = false end\n        piece.CanTouch = false\n        piece:SetAttribute(\"EnvironmentDetail\", true)\n        count += 1\n        return piece\n    end\n    local function shape(group, name, size, cf, color, material, solid)\n        local piece = block(group, name, size, cf.Position, color, material, solid)\n        piece.CFrame = cf\n        return piece\n    end\n    local function glow(group, partName, pos, color, range, brightness)\n        local bulb = block(group, partName, Vector3.new(1.8, 0.18, 0.52),\n            pos, color or colors.light, Enum.Material.Neon)\n        local lightPoint = Instance.new(\"PointLight\")\n        lightPoint.Name = \"LuzSetorial\"\n        lightPoint.Color = color or colors.light\n        lightPoint.Range = range or 14\n        lightPoint.Brightness = brightness or 0.65\n        lightPoint.Shadows = false\n        lightPoint.Parent = bulb\n        lamps[#lamps+1] = {part = bulb, light = lightPoint}\n        return bulb\n    end\n    local function stencil(group, title, pos, tone)\n        local board = block(group, \"PlacaSetor\", Vector3.new(10.2, 1.55, 0.17),\n            pos, colors.dark, Enum.Material.Metal)\n        local border = block(group, \"BarraSetor\", Vector3.new(0.25, 1.6, 0.18),\n            pos + Vector3.new(-5.15, 0, -0.03), tone, Enum.Material.Neon)\n        local canvas = Instance.new(\"SurfaceGui\")\n        canvas.Name = \"IdentificacaoSetor\"\n        canvas.Face = Enum.NormalId.Front\n        canvas.LightInfluence = 0.35\n        canvas.SizingMode = Enum.SurfaceGuiSizingMode.PixelsPerStud\n        canvas.PixelsPerStud = 17\n        canvas.Parent = board\n        local text = Instance.new(\"TextLabel\")\n        text.Name = \"NomeSetor\"\n        text.BackgroundTransparency = 1\n        text.Size = UDim2.fromScale(1, 1)\n        text.Font = Enum.Font.Code\n        text.TextScaled = true\n        text.TextColor3 = tone\n        text.Text = title\n        text.Parent = canvas\n    end\n    local function drum(group, pos, tone)\n        local cylinder = block(group, \"TamborIndustrial\", Vector3.new(2.3, 2.9, 2.3),\n            pos, tone, Enum.Material.Metal, true)\n        cylinder.Shape = Enum.PartType.Cylinder\n        for _, dy in ipairs({-1.05, 1.08}) do\n            local ring = block(group, \"AroTambor\", Vector3.new(2.45, 0.12, 2.45),\n                pos + Vector3.new(0, dy, 0), colors.dark, Enum.Material.Metal)\n            ring.Shape = Enum.PartType.Cylinder\n        end\n    end\n    local function pallet(group, pos, crates)\n        for _, z in ipairs({-1.15, 1.15}) do\n            block(group, \"PaleteTravessa\", Vector3.new(6.1, 0.24, 0.5),\n                pos + Vector3.new(0, 0.17, z), colors.rust, Enum.Material.Wood)\n        end\n        for _, x in ipairs({-2.35, 0, 2.35}) do\n            block(group, \"PaletePonte\", Vector3.new(0.45, 0.32, 3.3),\n                pos + Vector3.new(x, 0.4, 0), colors.concrete, Enum.Material.Wood)\n        end\n        for i = 1, crates do\n            local x = (i%2 == 0 and 1.35 or -1.35)\n            local y = i >= 3 and 3.0 or 1.55\n            block(group, \"CaixoteMetal\", Vector3.new(2.5, 2.35, 2.5),\n                pos + Vector3.new(x, y, 0),\n                i%2 == 0 and colors.metal or colors.concrete, Enum.Material.CorrodedMetal, true)\n        end\n    end\n\n    -- SETOR: perimetro, guaritas, refletores e portao. Plataformas aereas\n    -- de fachada sao cenograficas e nao interferem nos obstaculos da IA.\n    local perimeter = district(\"Perimetro\")\n    for _, location in ipairs({\n        Vector3.new(-49, 0, 44), Vector3.new(49, 0, 44),\n        Vector3.new(-49, 0, -44), Vector3.new(49, 0, -44),\n    }) do\n        for _, dx in ipairs({-2.25, 2.25}) do\n            for _, dz in ipairs({-2.25, 2.25}) do\n                block(perimeter, \"PilarGuarita\", Vector3.new(0.5, 13, 0.5),\n                    location + Vector3.new(dx, 6.5, dz), colors.metal)\n            end\n        end\n        block(perimeter, \"PisoGuarita\", Vector3.new(5.6, 0.55, 5.6),\n            location + Vector3.new(0, 12.9, 0), colors.concrete)\n        block(perimeter, \"TelhadoGuarita\", Vector3.new(6.5, 0.45, 6.5),\n            location + Vector3.new(0, 16.25, 0), colors.dark)\n        block(perimeter, \"GradeParapeito\", Vector3.new(5.8, 1.65, 0.25),\n            location + Vector3.new(0, 14, -2.65), colors.metal)\n        block(perimeter, \"GradeParapeito\", Vector3.new(5.8, 1.65, 0.25),\n            location + Vector3.new(0, 14, 2.65), colors.metal)\n        glow(perimeter, \"FarolGuarita\", location + Vector3.new(0, 15.6, -2.75),\n            colors.yellow, 23, 0.9)\n    end\n    for _, x in ipairs({-52, 52}) do\n        for _, z in ipairs({-34, -16, 2, 20, 38}) do\n            for dy = 1, 2 do\n                block(perimeter, \"FasquiaCerca\", Vector3.new(0.12, 0.1, 15),\n                    Vector3.new(x, 5 + dy*2.5, z), colors.metal)\n            end\n        end\n    end\n    local entryGate = district(\"PortariaExterna\")\n    for _, x in ipairs({-48, -35}) do\n        block(entryGate, \"PostePortao\", Vector3.new(0.7, 12, 0.7),\n            Vector3.new(x, 6, 46.7), colors.dark)\n    end\n    block(entryGate, \"BarraPortaoSuperior\", Vector3.new(14, 0.7, 0.7),\n        Vector3.new(-41.5, 12, 46.7), colors.rust)\n    stencil(entryGate, \"P17  /  ACESSO AO POSTO\", Vector3.new(-41.6, 9.7, 46.4), colors.green)\n    block(entryGate, \"FaixaAsfalto\", Vector3.new(13, 0.07, 23),\n        Vector3.new(-42, 0.08, 35.5), colors.asphalt, Enum.Material.Concrete)\n    for _, z in ipairs({26, 32, 38, 44}) do\n        block(entryGate, \"LinhaPista\", Vector3.new(0.26, 0.085, 2.3),\n            Vector3.new(-42, 0.15, z), colors.yellow, Enum.Material.Neon)\n    end\n    -- SETOR: circulacao, identificacao visual e pontes de cabos.\n    local road = district(\"ViasEPassagens\")\n    for _, x in ipairs({-24, -6, 48}) do\n        block(road, \"CorredorCimento\", Vector3.new(6.3, 0.06, 76),\n            Vector3.new(x, 0.065, -1), colors.concrete, Enum.Material.Concrete)\n        for _, z in ipairs({-35, -15, 5, 25}) do\n            block(road, \"GuiaPedestres\", Vector3.new(0.23, 0.08, 4.1),\n                Vector3.new(x + 2.8, 0.13, z), colors.yellow, Enum.Material.SmoothPlastic)\n        end\n    end\n    for _, z in ipairs({-24, 12, 39}) do\n        block(road, \"ViaTransversal\", Vector3.new(84, 0.045, 4.3),\n            Vector3.new(0, 0.075, z), colors.asphalt, Enum.Material.Concrete)\n    end\n    for _, x in ipairs({-35, 6, 35}) do\n        block(road, \"PassarelaCabos\", Vector3.new(0.32, 0.14, 30),\n            Vector3.new(x, 10.8, 0), colors.metal)\n        for _, z in ipairs({-14, 1, 15}) do\n            block(road, \"SuporteDeCabos\", Vector3.new(5.2, 0.18, 0.23),\n                Vector3.new(x, 10.8, z), colors.rust)\n        end\n    end\n    for _, spec in ipairs(zones) do\n        local height = spec.name:find(\"ARQUIVO\") and 9.9 or 7.5\n        stencil(road, spec.name, spec.pos + Vector3.new(0, height, -5.4), spec.tone)\n    end\n\n    -- SETOR: doca, carregamento e elevacao mecanica. Nenhum equipamento\n    -- grande bloqueia uma porta, armario, objetivo ou linha de patrulha.\n    local logistics = district(\"DocaELogistica\")\n    block(logistics, \"CaminhaoChassi\", Vector3.new(10, 1.1, 4.5),\n        Vector3.new(-33, 1.05, 32), colors.dark, Enum.Material.Metal, true)\n    block(logistics, \"CaminhaoBau\", Vector3.new(6, 5.2, 4.4),\n        Vector3.new(-34.7, 3.6, 32), colors.concrete, Enum.Material.Metal, true)\n    block(logistics, \"CabineCaminhao\", Vector3.new(3.4, 3.2, 4.3),\n        Vector3.new(-28, 2.6, 32), colors.rust, Enum.Material.Metal, true)\n    for _, x in ipairs({-36, -29}) do\n        for _, z in ipairs({29.7, 34.3}) do\n            local wheel = block(logistics, \"RodaCaminhao\", Vector3.new(2.25, 0.7, 2.25),\n                Vector3.new(x, 0.95, z), colors.dark, Enum.Material.Rubber)\n            wheel.Shape = Enum.PartType.Cylinder\n            wheel.Orientation = Vector3.new(90, 0, 0)\n        end\n    end\n    pallet(logistics, Vector3.new(-38, 0, 17), 3)\n    for _, pos in ipairs({\n        Vector3.new(-49, 1.5, 22), Vector3.new(-49, 1.5, 18),\n        Vector3.new(-31, 1.5, 16),\n    }) do drum(logistics, pos, colors.rust) end\n    block(logistics, \"EscadaArmazem\", Vector3.new(4, 0.26, 15),\n        Vector3.new(-35, 4.1, 15), colors.metal)\n    for _, z in ipairs({10, 15, 20}) do\n        block(logistics, \"CorrimaoDoca\", Vector3.new(0.17, 4, 0.17),\n            Vector3.new(-37, 6.1, z), colors.yellow)\n    end\n    glow(logistics, \"LuzDoca\", Vector3.new(-35, 9.1, 20), colors.yellow, 18, 0.7)\n\n    -- SETOR: passagem central com obstaculos DE COBERTURA fisicos em pontos\n    -- fora do trajeto das patrulhas. Identificados como Caixa pelo controlador.\n    local central = district(\"PatioCentral\")\n    for _, item in ipairs({\n        {x=-35, z=4, s=Vector3.new(3.8, 3.1, 2.2)},\n        {x=9, z=17, s=Vector3.new(4, 3, 2.1)},\n        {x=24, z=-28, s=Vector3.new(3.8, 3.1, 2.2)},\n    }) do\n        block(central, \"Caixa\", item.s, Vector3.new(item.x, item.s.Y/2, item.z),\n            colors.metal, Enum.Material.CorrodedMetal, true)\n        block(central, \"MarcaCobertura\", Vector3.new(item.s.X, 0.22, 0.23),\n            Vector3.new(item.x, item.s.Y-0.5, item.z-item.s.Z/2-0.02),\n            colors.yellow, Enum.Material.Neon)\n    end\n    for _, z in ipairs({-33, -17, 0, 17, 33}) do\n        glow(central, \"LuzCorredor\", Vector3.new(8, 11.1, z),\n            colors.blue, 15, 0.54)\n    end\n    for _, pos in ipairs({\n        Vector3.new(-31, 1.45, -18), Vector3.new(22, 1.45, 15)\n    }) do drum(central, pos, colors.concrete) end\n    local warning = block(central, \"SinalAmarelo\", Vector3.new(6, 0.08, 0.9),\n        Vector3.new(8.5, 0.15, -34), colors.yellow, Enum.Material.Neon)\n    warning.CanQuery = false\n\n    -- SETOR: manutencao, cabos, geradores e manutencao do sistema de energia.\n    local workshop = district(\"Manutencao\")\n    for _, x in ipairs({-49, -45, -41}) do\n        block(workshop, \"BancoFerramentas\", Vector3.new(3.8, 0.3, 1.5),\n            Vector3.new(x, 2.1, -43), colors.metal)\n        block(workshop, \"Gaveteiro\", Vector3.new(2.3, 3.4, 1.8),\n            Vector3.new(x, 1.7, -46), colors.dark, Enum.Material.Metal, true)\n    end\n    for _, x in ipairs({-50, -46, -42}) do\n        for i = 1, 3 do\n            block(workshop, \"GavetaFerramentas\", Vector3.new(2, 0.12, 0.1),\n                Vector3.new(x, i*0.8, -46.9), colors.rust)\n        end\n    end\n    glow(workshop, \"LuzManutencao\", Vector3.new(-43, 8.6, -40),\n        colors.blue, 16, 0.67)\n    for _, x in ipairs({-5, -3, -1}) do\n        block(workshop, \"DutoEnergia\", Vector3.new(0.3, 0.24, 16),\n            Vector3.new(x, 8.9, -41), colors.dark)\n    end\n\n    -- SETORES: comunicacoes e arquivo. Telhados parciais altos mantem\n    -- o ambiente legivel para cameras de terceira pessoa.\n    local communications = district(\"Comunicacoes\")\n    local archive = district(\"ArquivoReservado\")\n    for _, room in ipairs({\n        {group = workshop, x=-43, z=-40, w=18, d=14, color=colors.yellow},\n        {group = communications, x=34, z=-5, w=18, d=18, color=colors.blue},\n        {group = archive, x=34, z=32, w=18, d=18, color=colors.red},\n    }) do\n        for _, dx in ipairs({-room.w*0.32, room.w*0.32}) do\n            block(room.group, \"VigaTelhado\", Vector3.new(0.55, 0.45, room.d),\n                Vector3.new(room.x+dx, 9.4, room.z), colors.dark)\n        end\n        for _, dz in ipairs({-room.d*0.35, room.d*0.35}) do\n            block(room.group, \"VigaTransversal\", Vector3.new(room.w, 0.35, 0.58),\n                Vector3.new(room.x, 9.4, room.z+dz), colors.dark)\n        end\n        glow(room.group, \"LuzInterna\", Vector3.new(room.x, 8.9, room.z),\n            room.color, 12, 0.48)\n    end\n    for i = 1, 3 do\n        local x = 29 + (i-1)*4.4\n        local cabinet = block(communications, \"RackServidor\", Vector3.new(3.2, 6.8, 2),\n            Vector3.new(x, 3.4, -10.7), colors.dark, Enum.Material.Metal, true)\n        for j = 1, 4 do\n            block(communications, \"LedServidor\", Vector3.new(1.7, 0.12, 0.1),\n                cabinet.Position + Vector3.new(0, -2.4 + j*1.1, -1.04),\n                (j==1) and colors.red or colors.blue, Enum.Material.Neon)\n        end\n    end\n    block(communications, \"PainelTelecom\", Vector3.new(4, 2.2, 0.22),\n        Vector3.new(34, 5.5, -13.2), colors.metal)\n    block(communications, \"VisorOsciloscopio\", Vector3.new(2.8, 1.2, 0.12),\n        Vector3.new(34, 5.7, -13.34), colors.blue, Enum.Material.Neon)\n    for i=1,3 do\n        local z = 24 + (i-1)*5.7\n        for _, x in ipairs({28.1, 39.8}) do\n            block(archive, \"EstanteArquivo\", Vector3.new(1.6, 6.7, 3.3),\n                Vector3.new(x, 3.35, z), colors.dark, Enum.Material.Metal, true)\n            for level = 1, 4 do\n                block(archive, \"Prateleira\", Vector3.new(1.75, 0.12, 3.4),\n                    Vector3.new(x, level*1.33, z), colors.metal)\n            end\n        end\n    end\n    -- Terminal principal: superficie de console, observatorio e antenas.\n    local core = district(\"NucleoDeDados\")\n    block(core, \"PedestalServidor\", Vector3.new(8.6, 0.55, 7),\n        Vector3.new(43, 0.28, -39), colors.dark)\n    for _, x in ipairs({38, 48}) do\n        block(core, \"TorreRefrigeracao\", Vector3.new(2.7, 10, 3.2),\n            Vector3.new(x, 5, -45), colors.concrete, Enum.Material.Metal, true)\n        for _, y in ipairs({2, 4, 6, 8}) do\n            block(core, \"GradeVentilacao\", Vector3.new(2.5, 0.16, 0.15),\n                Vector3.new(x, y, -46.64), colors.dark)\n        end\n    end\n    glow(core, \"LuzTerminal\", Vector3.new(43, 11.8, -39),\n        colors.red, 19, 0.7)\n    local antenna = district(\"TorresDeTelecom\")\n    for _, x in ipairs({26, 35, 44}) do\n        block(antenna, \"AntenaVertical\", Vector3.new(0.3, 7, 0.3),\n            Vector3.new(x, 15.0, -10), colors.concrete)\n        block(antenna, \"AntenaSinal\", Vector3.new(0.9, 0.9, 0.9),\n            Vector3.new(x, 18.7, -10), colors.red, Enum.Material.Neon)\n    end\n    -- Pecas cinematograficas animadas somente no CLIENTE. Os rotores nao\n    -- participam da fisica, sao baratos e param durante falta de energia.\n    for index, center in ipairs({\n        Vector3.new(-43, 10.7, -40),\n        Vector3.new(34, 10.7, -5),\n        Vector3.new(34, 10.7, 32),\n        Vector3.new(9, 11.8, -43),\n    }) do\n        local fanModel = Instance.new(\"Model\")\n        fanModel.Name = \"Ventilador_\" .. index\n        fanModel:SetAttribute(\"Animation\", \"ROTATE\")\n        fanModel:SetAttribute(\"AngularSpeed\", index == 4 and 1.1 or 2.6)\n        fanModel.Parent = index == 4 and core or root\n        block(fanModel, \"EixoRotor\", Vector3.new(0.65, 0.44, 0.65),\n            center, colors.dark, Enum.Material.Metal)\n        block(fanModel, \"HeliceRotorE\", Vector3.new(3.4, 0.14, 0.44),\n            center + Vector3.new(0, 0.15, 0), colors.concrete)\n        block(fanModel, \"HeliceRotorD\", Vector3.new(0.44, 0.14, 3.4),\n            center + Vector3.new(0, 0.15, 0), colors.metal)\n        -- Grade permanece fixa para distinguir giro real de textura animada.\n        for _, delta in ipairs({\n            Vector3.new(-2.1, 0, 0), Vector3.new(2.1, 0, 0),\n        }) do\n            block(antenna, \"ProtecaoVentilador\", Vector3.new(0.18, 0.6, 4.35),\n                center + delta, colors.dark)\n        end\n    end\n    local dish = Instance.new(\"Model\")\n    dish.Name = \"RadarRotativo\"\n    dish:SetAttribute(\"Animation\", \"ROTATE\")\n    dish:SetAttribute(\"AngularSpeed\", 0.43)\n    dish.Parent = antenna\n    local dishPoint = Vector3.new(34, 15.2, -7)\n    local saucer = block(dish, \"AntenaParabolica\", Vector3.new(4.9, 0.25, 2.8),\n        dishPoint, colors.metal, Enum.Material.Metal)\n    saucer.Shape = Enum.PartType.Cylinder\n    block(dish, \"BaseRadar\", Vector3.new(0.25, 2.3, 0.25),\n        dishPoint + Vector3.new(0, -1.2, 0), colors.dark)\n    block(dish, \"ReceptorRadar\", Vector3.new(0.5, 0.5, 0.5),\n        dishPoint + Vector3.new(0, 0.9, -1.4), colors.blue, Enum.Material.Neon)\n\n    -- Fundo distante: morros de rocha fora do terreno jogavel,\n    -- sem colisao ou raycast. Da silhueta ao posto.\n    local background = district(\"Horizonte\")\n    for index, item in ipairs({\n        {-88, 30, -35, 38}, {-105, 38, 3, 48},\n        {95, 31, -22, 38}, {108, 41, 31, 34},\n        {-55, 29, -100, 40}, {21, 35, -105, 44},\n        {48, 30, 103, 43}, {-35, 28, 108, 32},\n    }) do\n        local x, height, z, width = item[1], item[2], item[3], item[4]\n        local cliff = Instance.new(\"WedgePart\")\n        cliff.Name = \"RochaDistante_\" .. index\n        cliff.Size = Vector3.new(width, height, width*0.6)\n        cliff.Position = Vector3.new(x, height/2-2, z)\n        cliff.Color = colors.dark\n        cliff.Material = Enum.Material.Slate\n        cliff.Anchored = true\n        cliff.CanCollide = false\n        cliff.CanQuery = false\n        cliff.CanTouch = false\n        cliff.Parent = background\n        count += 1\n    end\n\n    local atmosphere = light:FindFirstChild(\"Posto17Atmosphere\") or Instance.new(\"Atmosphere\")\n    atmosphere.Name = \"Posto17Atmosphere\"\n    atmosphere.Density = 0.31\n    atmosphere.Haze = 1.1\n    atmosphere.Offset = 0.08\n    atmosphere.Color = Color3.fromRGB(126, 145, 169)\n    atmosphere.Decay = Color3.fromRGB(39, 48, 65)\n    atmosphere.Parent = light\n    local bloom = light:FindFirstChild(\"Posto17Bloom\") or Instance.new(\"BloomEffect\")\n    bloom.Name = \"Posto17Bloom\"\n    bloom.Intensity = 0.19\n    bloom.Size = 15\n    bloom.Threshold = 1.65\n    bloom.Parent = light\n\n    world:SetAttribute(\"MapVersion\", \"3D-1\")\n    world:SetAttribute(\"MapDetailParts\", count)\n    world:SetAttribute(\"MapDistricts\", districtCount)\n    world:SetAttribute(\"ArtBudget\", \"low-poly / anchored / sem mesh externo\")\n    return {lamps = lamps, details = count, districts = districtCount, root = root}\nend\nreturn WorldDetail\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Acessos","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Acessos (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal UIS = game:GetService(\"UserInputService\")\nlocal player = Players.LocalPlayer\nlocal event = RS:WaitForChild(\"Posto17Access\")\nlocal world = workspace:WaitForChild(\"Posto17\")\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Acessos\"\ngui.ResetOnSpawn = false\ngui.DisplayOrder = 25\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal panel = Instance.new(\"Frame\")\npanel.AnchorPoint = Vector2.new(0.5, 0.5)\npanel.Position = UDim2.fromScale(0.5, 0.5)\npanel.Size = UDim2.fromOffset(310, 265)\npanel.BackgroundColor3 = Theme.Panel\npanel.BackgroundTransparency = 0.1\npanel.Visible = false\npanel.Parent = gui\nlocal scale = Instance.new(\"UIScale\")\nscale.Scale = 1\nscale.Parent = panel\nlocal function label(text, y)\n    local l = Instance.new(\"TextLabel\")\n    l.Position, l.Size = UDim2.fromOffset(12, y), UDim2.fromOffset(286, 40)\n    l.BackgroundTransparency, l.TextColor3 = 1, Theme.Text\n    l.Text, l.TextWrapped, l.TextSize, l.Font = text, true, 13, Enum.Font.GothamMedium\n    l.Parent = panel\n    return l\nend\nlocal title = label(\"ACESSO\", 4)\ntitle.Size = UDim2.fromOffset(286, 32)\nlocal status = label(\"\", 40)\nstatus.Size = UDim2.fromOffset(286, 36)\nlocal code = Instance.new(\"TextBox\")\ncode.Position, code.Size = UDim2.fromOffset(16, 84), UDim2.fromOffset(278, 40)\ncode.Text = \"\"\ncode.PlaceholderText = \"Codigo de quatro digitos\"\ncode.ClearTextOnFocus = false\ncode.TextColor3 = Theme.Text\ncode.BackgroundColor3 = Theme.Surface\ncode.TextSize = 18\ncode.Parent = panel\nlocal doorId, method, phase, pinAt\nlocal function close()\n    panel.Visible = false\n    event:FireServer(\"CANCEL\")\n    phase = nil\nend\nlocal function button(text, x, y, width, callback)\n    local b = Instance.new(\"TextButton\")\n    b.Name = \"Action_\" .. text\n    b.Text, b.Position, b.Size = text, UDim2.fromOffset(x, y), UDim2.fromOffset(width, 44)\n    b.BackgroundColor3, b.TextColor3 = Theme.Brand, Theme.Text\n    b.TextSize, b.Font = 13, Enum.Font.GothamMedium\n    b.Parent = panel\n    b.Activated:Connect(callback)\n    return b\nend\nlocal use = button(\"USAR\", 16, 132, 132, function()\n    if doorId then event:FireServer(method == \"CARD\" and \"CARD\" or \"CODE\", doorId, code.Text) end\nend)\nlocal pick = button(\"LOCKPICK\", 158, 132, 136, function()\n    if doorId then event:FireServer(\"PICK\", doorId) end\nend)\nlocal pins = {}\nfor i=1,3 do\n    pins[i] = button(tostring(i), 16+(i-1)*94, 84, 88, function()\n        if phase and os.clock() - pinAt >= 0.8 then event:FireServer(\"PIN\", doorId, i) end\n    end)\n    pins[i].Visible = false\nend\nbutton(\"FECHAR\", 16, 213, 278, close)\nlocal helper = label(\"\", 178)\nhelper.Size = UDim2.fromOffset(286, 28)\nevent.OnClientEvent:Connect(function(kind, id, value, extra)\n    if kind == \"MENU\" then\n        doorId, method, phase = id, value, nil\n        title.Text = string.upper(extra)\n        status.Text = value == \"CARD\" and \"Cartao ou lockpick\" or (value == \"CODE\" and \"Codigo ou lockpick\" or \"Fechadura mecanica: use lockpick\")\n        code.Text = player:GetAttribute(\"Posto17DoorCode\") or \"\"\n        code.Visible = value == \"CODE\"\n        use.Visible, pick.Visible = value ~= \"LOCKPICK\", true\n        for _, p in ipairs(pins) do p.Visible = false end\n        panel.Visible = true\n        helper.Text = \"Voce continua exposto enquanto abre o acesso.\"\n    elseif id == doorId and kind == \"PIN\" then\n        phase, pinAt = value, os.clock()\n        status.Text = \"Pino \" .. extra .. \"/3: aguarde o sinal e pressione \" .. value\n        code.Visible, use.Visible, pick.Visible = false, false, false\n        for _, p in ipairs(pins) do p.Visible = true end\n        helper.Text = \"Oito segundos por pino. Errar faz barulho.\"\n    elseif id == doorId and (kind == \"FAIL\" or kind == \"STATUS\") then\n        status.Text = value\n        phase = nil\n        pick.Visible = true\n        for _, p in ipairs(pins) do p.Visible = false end\n    elseif id == doorId and kind == \"OPEN\" then close() end\nend)\nUIS.InputBegan:Connect(function(input, consumed)\n    if not consumed and input.KeyCode == Enum.KeyCode.Escape and panel.Visible then close() end\nend)\nplayer.CharacterAdded:Connect(close)\ntask.spawn(function()\n    while gui.Parent do\n        if panel.Visible then\n            local root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n            local door = world:FindFirstChild(\"PortaAcesso_\" .. tostring(doorId))\n            if not root or not door or door:GetAttribute(\"Open\") or (root.Position-door.Position).Magnitude > 10\n                or player:GetAttribute(\"Posto17Hidden\") or player:GetAttribute(\"Posto17Won\") then close() end\n            if phase then\n                for i, p in ipairs(pins) do\n                    p.BackgroundColor3 = os.clock()-pinAt >= 0.8 and i == phase\n                        and Theme.Success or Theme.Brand\n                end\n            end\n        end\n        task.wait(0.1)\n    end\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/AnimacaoIndividual","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/AnimacaoIndividual (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto 17: bancada independente para visualizar UMA animacao R6 de cada vez.\n-- Inclui 47 sequencias corporais e 26 sequencias com os modelos originais.\n-- Previa local sem alterar o Humanoid do jogador ou o jogo principal.\nlocal Players=game:GetService(\"Players\")\nlocal RS=game:GetService(\"ReplicatedStorage\")\nlocal RunService=game:GetService(\"RunService\")\nlocal player=Players.LocalPlayer\nlocal shared=RS:WaitForChild(\"Posto17Shared\")\nlocal catalog=require(shared:WaitForChild(\"Posto17ShowcaseIndex\"))\nlocal Models=require(shared:WaitForChild(\"Posto17Modelos\"))\nlocal bodies=shared:WaitForChild(\"Posto17R6Corpo\")\nlocal weapons=shared:WaitForChild(\"Posto17R6Amostras\")\nlocal avatar=shared:WaitForChild(\"Posto17R6Preview\")\nlocal gui=Instance.new(\"ScreenGui\")\ngui.Name=\"P17AnimacaoIndividual\"\ngui.ResetOnSpawn=false\ngui.DisplayOrder=80\ngui.IgnoreGuiInset=true\ngui.Parent=player:WaitForChild(\"PlayerGui\")\n\nlocal DARK=Color3.fromRGB(16,18,22)\nlocal PANEL=Color3.fromRGB(27,30,36)\nlocal SURFACE=Color3.fromRGB(40,45,52)\nlocal RED=Color3.fromRGB(141,36,42)\nlocal LIGHT=Color3.fromRGB(236,238,240)\nlocal MUTED=Color3.fromRGB(163,172,181)\n\nlocal function create(class,parent,props)\n    local object=Instance.new(class)\n    for k,v in pairs(props or {}) do object[k]=v end\n    object.Parent=parent\n    return object\nend\nlocal function text(parent,name,value,position,size,textSize)\n    return create(\"TextLabel\",parent,{\n        Name=name,Text=value,Position=position,Size=size,\n        TextColor3=LIGHT,BackgroundTransparency=1,\n        Font=Enum.Font.Gotham,TextSize=textSize or 14,\n        TextXAlignment=Enum.TextXAlignment.Left,\n        TextYAlignment=Enum.TextYAlignment.Center,\n        TextTruncate=Enum.TextTruncate.AtEnd,\n    })\nend\nlocal function button(parent,name,value,position,size,color)\n    return create(\"TextButton\",parent,{\n        Name=name,Text=value,Position=position,Size=size,\n        TextColor3=LIGHT,BackgroundColor3=color or SURFACE,\n        Font=Enum.Font.GothamBold,TextSize=13,BorderSizePixel=0,\n        AutoButtonColor=true\n    })\nend\n\nlocal launch=button(gui,\"AbrirBancada\",\"ANIMACOES  73\",\n    UDim2.new(1,-201,0,105),UDim2.fromOffset(172,43),RED)\nlocal root=create(\"Frame\",gui,{\n    Name=\"BancadaR6\",Visible=false,\n    Size=UDim2.fromScale(.94,.83),Position=UDim2.fromScale(.03,.095),\n    BackgroundColor3=DARK,BorderSizePixel=0\n})\ncreate(\"UIStroke\",root,{Color=RED,Thickness=2})\nlocal heading=text(root,\"Titulo\",\"POSTO 17 / BANCADA R6   •   73 SEQUENCIAS\",\n    UDim2.new(.02,0,0,5),UDim2.new(.78,0,0,40),17)\nlocal close=button(root,\"Fechar\",\"FECHAR\",\n    UDim2.new(1,-108,0,7),UDim2.fromOffset(93,34),RED)\n\nlocal sidebar=create(\"Frame\",root,{\n    Name=\"Lista\",Position=UDim2.new(.015,0,0,55),\n    Size=UDim2.new(.35,-10,1,-67),BackgroundColor3=PANEL,BorderSizePixel=0\n})\nlocal search=create(\"TextBox\",sidebar,{\n    Name=\"Buscar\",Position=UDim2.new(0,9,0,10),\n    Size=UDim2.new(1,-18,0,36),BackgroundColor3=SURFACE,\n    Text=\"\",PlaceholderText=\"Buscar animacao...\",\n    TextColor3=LIGHT,PlaceholderColor3=MUTED,\n    Font=Enum.Font.Gotham,TextSize=14,ClearTextOnFocus=false,BorderSizePixel=0\n})\nlocal filters=create(\"Frame\",sidebar,{\n    Name=\"Categorias\",Position=UDim2.new(0,8,0,53),\n    Size=UDim2.new(1,-16,0,36),BackgroundTransparency=1\n})\nlocal filterOptions={\n    {\"Todas\",\"all\"},{\"Corpo\",\"Movimento\"},{\"Pistola\",\"pistola\"},\n    {\"Sub\",\"submetralhadora\"},{\"Fuzil\",\"fuzil\"}\n}\nlocal filterBtns={}\nlocal selectedCategory=\"all\"\nfor i,opt in ipairs(filterOptions) do\n    local item=button(filters,\"Filtro\"..i,opt[1],UDim2.new((i-1)/5,2,0,1),\n        UDim2.new(.2,-4,1,-2),i==1 and RED or SURFACE)\n    item.TextSize=11\n    filterBtns[i]=item\nend\nlocal scroll=create(\"ScrollingFrame\",sidebar,{\n    Name=\"TodasAsAnimacoes\",Position=UDim2.new(0,8,0,97),\n    Size=UDim2.new(1,-16,1,-106),BackgroundTransparency=1,\n    BorderSizePixel=0,ScrollBarThickness=5,CanvasSize=UDim2.fromOffset(0,0),\n    AutomaticCanvasSize=Enum.AutomaticSize.Y,ScrollingDirection=Enum.ScrollingDirection.Y\n})\ncreate(\"UIListLayout\",scroll,{Padding=UDim.new(0,4),SortOrder=Enum.SortOrder.LayoutOrder})\n\nlocal right=create(\"Frame\",root,{\n    Name=\"Previa\",Position=UDim2.new(.365,0,0,55),\n    Size=UDim2.new(.62,0,1,-67),BackgroundColor3=PANEL,BorderSizePixel=0\n})\nlocal clipTitle=text(right,\"ClipTitulo\",\"Escolha uma animacao...\",\n    UDim2.new(0,12,0,6),UDim2.new(1,-24,0,29),16)\nlocal clipInfo=text(right,\"Informacoes\",\"R6 / modelos P17\",\n    UDim2.new(0,12,0,35),UDim2.new(1,-24,0,24),12)\nclipInfo.TextColor3=MUTED\n\nlocal viewport=create(\"ViewportFrame\",right,{\n    Name=\"Modelo3D\",Position=UDim2.new(0,10,0,66),\n    Size=UDim2.new(1,-20,1,-167),BackgroundColor3=Color3.fromRGB(40,45,52),\n    BorderSizePixel=0,Ambient=Color3.fromRGB(178,181,191),\n    LightColor=Color3.fromRGB(242,242,248),LightDirection=Vector3.new(-1,-2,-3),\n    ImageColor3=Color3.new(1,1,1),\n})\nlocal previewWorld=create(\"WorldModel\",viewport,{Name=\"SalaDePrevia\"})\nlocal cam=create(\"Camera\",viewport,{FieldOfView=42})\nviewport.CurrentCamera=cam\nlocal cameraAngles={\n    CFrame.lookAt(Vector3.new(5.7,4.8,-9.0),Vector3.new(0,2.8,0)),\n    CFrame.lookAt(Vector3.new(10,4.8,0),Vector3.new(0,2.8,0)),\n    CFrame.lookAt(Vector3.new(5.7,4.8,9.0),Vector3.new(0,2.8,0)),\n}\nlocal viewIndex=1\ncam.CFrame=cameraAngles[viewIndex]\n\nlocal floor=create(\"Part\",previewWorld,{\n    Name=\"Piso\",Size=Vector3.new(15,.25,14),\n    CFrame=CFrame.new(0,-.13,0),Anchored=true,\n    Material=Enum.Material.Concrete,\n    Color=Color3.fromRGB(91,101,110),CanCollide=false\n})\nlocal coverWall=create(\"Part\",previewWorld,{\n    Name=\"ParedeDeReferencia\",Size=Vector3.new(7,5.5,.3),\n    CFrame=CFrame.new(0,2.75,1.55),Anchored=true,CanCollide=false,\n    Color=Color3.fromRGB(120,130,139),Material=Enum.Material.Concrete,\n    Transparency=1\n})\nlocal avatarClone=avatar:Clone()\navatarClone.Name=\"R6Previa\"\navatarClone.Parent=previewWorld\nlocal rigRoot=avatarClone:FindFirstChild(\"HumanoidRootPart\")\nassert(rigRoot,\"Preview R6 sem HumanoidRootPart\")\navatarClone:PivotTo(CFrame.new(0,3,0))\nrigRoot.Anchored=true\nfor _,obj in ipairs(avatarClone:GetDescendants()) do\n    if obj:IsA(\"BasePart\") then\n        obj.Anchored=true\n        obj.CanCollide=false\n        obj.CanTouch=false\n        obj.CanQuery=false\n    end\nend\nlocal joints={}\nlocal bodyParts={}\nlocal order={\"Torso\",\"Head\",\"Right Arm\",\"Left Arm\",\"Right Leg\",\"Left Leg\"}\nfor _,j in ipairs(avatarClone:GetDescendants()) do\n    if j:IsA(\"Motor6D\") and j.Part1 then joints[j.Part1.Name]=j end\nend\nfor _,name in ipairs(order) do\n    bodyParts[name]=avatarClone:FindFirstChild(name)\n    assert(joints[name] and bodyParts[name],\"Articulacao R6 ausente: \"..name)\nend\n\nlocal modelInstances={}\nfor _,kind in ipairs({\"pistola\",\"submetralhadora\",\"fuzil\"}) do\n    local m=Models.make(kind)\n    if m then\n        m.Parent=previewWorld\n        m.PrimaryPart.Anchored=true\n        modelInstances[kind]=m\n    end\nend\n\nlocal controls=create(\"Frame\",right,{\n    Name=\"Controles\",Position=UDim2.new(0,10,1,-90),\n    Size=UDim2.new(1,-20,0,76),\n    BackgroundTransparency=1\n})\nlocal previous=button(controls,\"Anterior\",\"<\",UDim2.new(0,0,0,0),UDim2.new(.16,-4,0,36))\nlocal playPause=button(controls,\"Reproduzir\",\"PAUSAR\",UDim2.new(.16,0,0,0),UDim2.new(.24,-4,0,36),RED)\nlocal nextClip=button(controls,\"Proximo\",\">\",UDim2.new(.40,0,0,0),UDim2.new(.16,-4,0,36))\nlocal speedButton=button(controls,\"Velocidade\",\"1x\",UDim2.new(.56,0,0,0),UDim2.new(.17,-4,0,36))\nlocal angleButton=button(controls,\"Angulo\",\"VISTA\",UDim2.new(.73,0,0,0),UDim2.new(.27,0,0,36))\nlocal timeline=create(\"Frame\",controls,{\n    Name=\"Progresso\",Position=UDim2.new(0,0,0,47),\n    Size=UDim2.new(1,0,0,6),BackgroundColor3=SURFACE,BorderSizePixel=0\n})\nlocal fill=create(\"Frame\",timeline,{\n    Name=\"Andamento\",Size=UDim2.fromScale(0,1),\n    BackgroundColor3=RED,BorderSizePixel=0\n})\nlocal timeLabel=text(controls,\"Tempo\",\"00:00 / 00:00\",\n    UDim2.new(0,2,0,56),UDim2.new(1,-4,0,20),12)\ntimeLabel.TextColor3=MUTED\n\nlocal records={}\nlocal chosen=1\nlocal activeClip=nil\nlocal elapsed=0\nlocal playing=true\nlocal speed=1\nlocal buttons={}\nlocal function included(row)\n    local category=selectedCategory==\"all\" or row.category==selectedCategory\n    local query=string.lower(search.Text)\n    local matching=query==\"\" or string.find(string.lower(row.name),query,1,true)~=nil\n    return category and matching\nend\nlocal function refreshList()\n    for _,entry in ipairs(records) do\n        entry.button.Visible=included(entry)\n        entry.button.BackgroundColor3=entry.index==chosen and RED or SURFACE\n    end\n    for i,btn in ipairs(filterBtns) do\n        btn.BackgroundColor3=filterOptions[i][2]==selectedCategory and RED or SURFACE\n    end\nend\nlocal clipCache={}\nlocal function readClip(row)\n    if clipCache[row.id] then return clipCache[row.id] end\n    local parent=row.category==\"Movimento\" and bodies or weapons\n    local seq=parent:FindFirstChild(row.id,true)\n    if not seq or not seq:IsA(\"KeyframeSequence\") then\n        warn(\"[P17 Bancada] Sem animacao: \",row.id)\n        return nil\n    end\n    local frames=seq:GetKeyframes()\n    table.sort(frames,function(a,b) return a.Time<b.Time end)\n    if #frames==0 then return nil end\n    local list={}\n    for _,keyframe in ipairs(frames) do\n        local pose={}\n        for _,obj in ipairs(keyframe:GetDescendants()) do\n            if obj:IsA(\"Pose\") and obj.Name~=\"HumanoidRootPart\" then\n                pose[obj.Name]=obj.CFrame\n            end\n        end\n        table.insert(list,{time=keyframe.Time,parts=pose})\n    end\n    local result={frames=list,duration=math.max(list[#list].time,.0333),loop=seq.Loop}\n    clipCache[row.id]=result\n    return result\nend\n\nlocal function choose(index)\n    if index<1 or index>#records then return end\n    chosen=index\n    local row=records[chosen]\n    activeClip=readClip(row)\n    elapsed=0\n    playing=true\n    playPause.Text=\"PAUSAR\"\n    clipTitle.Text=row.name\n    clipInfo.Text=(row.category==\"Movimento\" and \"CORPO R6\" or string.upper(row.category))\n        ..\"    |    \"..(activeClip and #activeClip.frames or 0)..\" quadros\"\n    local cover=string.find(string.lower(row.name),\"cobertura\",1,true)~=nil\n        or string.find(string.lower(row.name),\"cover\",1,true)~=nil\n    coverWall.Transparency=cover and .1 or 1\n    refreshList()\nend\n\nfor i,row in ipairs(catalog) do\n    local item=button(scroll,\"Animacao_\"..i,\n        string.format(\"%02d  %s\",i,row.name),\n        UDim2.fromOffset(0,0),UDim2.new(1,-5,0,35))\n    item.LayoutOrder=i\n    item.TextXAlignment=Enum.TextXAlignment.Left\n    item.TextSize=12\n    item.TextTruncate=Enum.TextTruncate.AtEnd\n    create(\"UIPadding\",item,{PaddingLeft=UDim.new(0,9)})\n    table.insert(records,{id=row.id,name=row.name,category=row.category,model=row.model,\n        button=item,index=i})\n    item.Activated:Connect(function()choose(i)end)\nend\nassert(#records==73,\"A lista da bancada deve conter 73 clipes\")\nfor i,opt in ipairs(filterOptions) do\n    filterBtns[i].Activated:Connect(function()\n        selectedCategory=opt[2]\n        refreshList()\n        local row=records[chosen]\n        if row and not included(row) then\n            for ix,x in ipairs(records) do if included(x) then choose(ix);break end end\n        end\n    end)\nend\nsearch:GetPropertyChangedSignal(\"Text\"):Connect(refreshList)\nlocal function step(direction)\n    local candidates={}\n    for i,row in ipairs(records) do if included(row) then table.insert(candidates,i) end end\n    if #candidates==0 then return end\n    local position=table.find(candidates,chosen) or 1\n    choose(candidates[((position-1+direction)%#candidates)+1])\nend\nprevious.Activated:Connect(function()step(-1)end)\nnextClip.Activated:Connect(function()step(1)end)\nplayPause.Activated:Connect(function()\n    if activeClip and elapsed>=activeClip.duration and not activeClip.loop then elapsed=0 end\n    playing=not playing\n    playPause.Text=playing and \"PAUSAR\" or \"PLAY\"\nend)\nspeedButton.Activated:Connect(function()\n    if speed==.5 then speed=1 elseif speed==1 then speed=2 else speed=.5 end\n    speedButton.Text=tostring(speed)..\"x\"\nend)\nangleButton.Activated:Connect(function()\n    viewIndex=viewIndex%#cameraAngles+1\n    cam.CFrame=cameraAngles[viewIndex]\nend)\n\nlocal function sample(clip,t)\n    if not clip then return nil end\n    local frames=clip.frames\n    if #frames==1 then return frames[1].parts end\n    local stamp=clip.loop and t%clip.duration or math.min(t,clip.duration)\n    local a,b=frames[1],frames[#frames]\n    if stamp<=a.time then return a.parts end\n    for i=2,#frames do\n        if stamp<=frames[i].time then a=frames[i-1];b=frames[i];break end\n    end\n    local alpha=math.clamp((stamp-a.time)/math.max(.00001,b.time-a.time),0,1)\n    local pose={}\n    for _,name in ipairs(order) do\n        local from=a.parts[name] or CFrame.identity\n        local to=b.parts[name] or from\n        pose[name]=from:Lerp(to,alpha)\n    end\n    return pose\nend\n\nlocal function drawPose(pose)\n    if not pose then return end\n    local frames={[rigRoot]=CFrame.new(0,3,0)}\n    rigRoot.CFrame=frames[rigRoot]\n    for _,name in ipairs(order) do\n        local j=joints[name]\n        local cf=frames[j.Part0]*j.C0*(pose[name] or CFrame.identity)*j.C1:Inverse()\n        j.Part1.CFrame=cf\n        frames[j.Part1]=cf\n    end\nend\nlocal function updateModels()\n    local row=records[chosen]\n    for kind,model in pairs(modelInstances) do\n        local placement=Models.placement(kind)\n        local bone=placement and bodyParts[placement.bone]\n        if bone then\n            local mount=bone.CFrame*placement.offset\n            if row and row.model==kind then\n                local progress=activeClip and elapsed/math.max(.001,activeClip.duration) or 0\n                local name=row.name:lower()\n                local active=true\n                if name:find(\"sacar\",1,true) then active=progress>=.54 end\n                if name:find(\"guardar\",1,true) then active=progress<=.46 end\n                if active then\n                    local rightArm=bodyParts[\"Right Arm\"]\n                    mount=rightArm.CFrame*CFrame.new(0,-1.06,-.22)\n                        * CFrame.Angles(math.rad(-90),math.pi,0)\n                end\n            end\n            model:PivotTo(mount)\n        end\n    end\nend\n\nlocal function visible()\n    return player:GetAttribute(\"Posto17InTestRange\")==true\n       and player:GetAttribute(\"P17InMainMenu\")~=true\n       and player:GetAttribute(\"Posto17InVisualShowcase\")~=true\nend\nlocal function openPanel(value)\n    if value and not visible() then return end\n    root.Visible=value\n    launch.Visible=not value and visible()\n    if value then\n        search.Text=\"\"\n        selectedCategory=\"all\"\n        choose(chosen)\n    end\nend\nlaunch.Activated:Connect(function()openPanel(true)end)\nclose.Activated:Connect(function()openPanel(false)end)\nfor _,signal in ipairs({\"Posto17InTestRange\",\"P17InMainMenu\",\"Posto17InVisualShowcase\"}) do\n    player:GetAttributeChangedSignal(signal):Connect(function()\n        if not visible() and root.Visible then openPanel(false) end\n        launch.Visible=not root.Visible and visible()\n    end)\nend\nlaunch.Visible=visible()\n-- A bancada pode ser acessada por botao ou pela placa no mapa de testes.\ntask.spawn(function()\n    local world=workspace:WaitForChild(\"Posto17\",30)\n    local area=world and world:WaitForChild(\"P17_CampoDeTestes\",30)\n    local terminal=area and area:WaitForChild(\"P17_BancadaR6\",30)\n    local prompt=terminal and terminal:FindFirstChildOfClass(\"ProximityPrompt\")\n    if prompt then prompt.Triggered:Connect(function()openPanel(true)end) end\nend)\n\nlocal accumulator=0\nchoose(1)\nRunService.RenderStepped:Connect(function(dt)\n    if not root.Visible then return end\n    accumulator+=dt\n    if accumulator<1/30 then return end\n    local stepDt=math.min(accumulator,.1)\n    accumulator=0\n    if activeClip and playing then\n        elapsed+=stepDt*speed\n        if not activeClip.loop and elapsed>=activeClip.duration then\n            elapsed=activeClip.duration\n            playing=false\n            playPause.Text=\"PLAY\"\n        end\n    end\n    drawPose(sample(activeClip,elapsed))\n    updateModels()\n    if activeClip then\n        fill.Size=UDim2.fromScale(math.clamp(elapsed/activeClip.duration,0,1),1)\n        timeLabel.Text=string.format(\"%.2f s  /  %.2f s    |    %s\",\n            elapsed,activeClip.duration,activeClip.loop and \"LOOP\" or \"UMA VEZ\")\n    end\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/AnimationReview","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/AnimationReview (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Camera de ensaio no campo de testes. O jogador real executa as poses.\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal player = Players.LocalPlayer\nlocal coverReview = player:WaitForChild(\"PlayerScripts\"):WaitForChild(\"P17CoverReview\", 6)\nlocal remote = RS:WaitForChild(\"Posto17AnimationReview\", 15)\nif not remote then return end\n\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Ensaio\"\ngui.ResetOnSpawn, gui.DisplayOrder = false, 21\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal button = Instance.new(\"TextButton\")\nbutton.Name, button.Text = \"Ensaio\", \"Rever animações\"\nbutton.AnchorPoint = Vector2.new(0.5, 0)\nbutton.Position, button.Size = UDim2.fromScale(0.5, 0.066), UDim2.fromOffset(150, 44)\nbutton.BackgroundColor3, button.TextColor3 = Theme.Surface, Theme.Text\nbutton.Font, button.TextSize = Enum.Font.GothamMedium, 12\nbutton.BackgroundTransparency = 0.94\nbutton.TextStrokeTransparency = 0.54\nbutton.BorderSizePixel = 0\nbutton.Parent = gui\nlocal title = Instance.new(\"TextLabel\")\ntitle.BackgroundColor3, title.TextColor3 = button.BackgroundColor3, button.TextColor3\ntitle.AnchorPoint = Vector2.new(0.5, 0)\ntitle.Position, title.Size = UDim2.fromScale(0.5, 0.79), UDim2.fromOffset(400, 32)\ntitle.Font, title.TextSize, title.Visible = Theme.Font, 15, false\ntitle.BackgroundTransparency = 0.76\ntitle.Parent = gui\n\nlocal fade = {}\nlocal active = false\nlocal touchLayout\nlocal function setTouchLayout(enabled)\n    player:SetAttribute(\"P17Reviewing\", not enabled)\n    touchLayout = touchLayout or gui.Parent:FindFirstChild(\"Posto17TouchLayout\")\n    if touchLayout then touchLayout.Enabled = enabled end\nend\nlocal function restore()\n    for item, transparency in pairs(fade) do\n        if item.Parent then item.LocalTransparencyModifier = transparency end\n    end\n    table.clear(fade)\nend\nlocal function finish()\n    player:SetAttribute(\"P17ReviewMove\", nil)\n    if coverReview then coverReview:Fire(false) end\n    restore()\n    RunService:UnbindFromRenderStep(\"P17EnsaioCamera\")\n    if workspace.CurrentCamera then workspace.CurrentCamera.CameraType = Enum.CameraType.Custom end\n    active = false\n    setTouchLayout(true)\n    title.Visible = false\n    button.Visible = player:GetAttribute(\"Posto17InTestRange\") == true\nend\nbutton.Activated:Connect(function()\n    if not active then remote:FireServer() end\nend)\nplayer:GetAttributeChangedSignal(\"Posto17InTestRange\"):Connect(function()\n    if not player:GetAttribute(\"Posto17InTestRange\") and active then finish() end\n    button.Visible = not active and player:GetAttribute(\"Posto17InTestRange\") == true\nend)\nplayer.CharacterAdded:Connect(function() if active then finish() end end)\nbutton.Visible = player:GetAttribute(\"Posto17InTestRange\") == true\n\nremote.OnClientEvent:Connect(function(label, seconds, direction, vent)\n    if label == \"FIM\" then\n        task.delay(1.25, function() if title.Text == \"ENSAIO CONCLUIDO\" then finish() end end)\n        if title.Text ~= \"ENSAIO CONCLUIDO\" then finish() end\n        return\n    end\n    restore()\n    player:SetAttribute(\"P17ReviewMove\", Vector3.zero)\n    if coverReview then\n        if label == \"COBERTURA ALTA / ALTERNAR\" then\n            -- Dá tempo para chegar a posição inicial replicada pelo servidor.\n            task.delay(0.16, function()\n                if title.Text == label then coverReview:Fire(true) end\n            end)\n        elseif label == \"SAIR DA COBERTURA\" then\n            coverReview:Fire(false)\n        end\n    end\n    title.Text, title.Visible, button.Visible, active = label, true, false, true\n    setTouchLayout(false)\n    local started = os.clock()\n    if vent then\n        for _, item in ipairs(vent:GetChildren()) do\n            if item:IsA(\"BasePart\") and (item.Name == \"LateralDuto\" or item.Name == \"TetoDuto\"\n                or item.Name == \"GradeDuto\" or item.Name == \"TravessaGrade\") then\n                fade[item] = item.LocalTransparencyModifier\n                item.LocalTransparencyModifier = 0.82\n            end\n        end\n    end\n    local camera = workspace.CurrentCamera\n    camera.CameraType = Enum.CameraType.Scriptable\n    RunService:UnbindFromRenderStep(\"P17EnsaioCamera\")\n    local previous\n    RunService:BindToRenderStep(\"P17EnsaioCamera\", Enum.RenderPriority.Camera.Value + 8, function(dt)\n        local char = player.Character\n        local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n        local root = hum and hum.RootPart\n        if not root then return end\n        local elapsed = os.clock() - started\n        if direction then\n            local velocity = root.AssemblyLinearVelocity\n            local speed = Vector3.new(velocity.X, 0, velocity.Z).Magnitude\n            title.Text = string.format(\"%s  |  %.1f studs/s\", label, speed)\n        end\n        local move = direction and elapsed > 0.45 and elapsed < seconds - 0.3\n        if label == \"RASTEJAR E LEVANTAR\" and elapsed > 3.6 then move = false end\n        local requestedMove = move and direction or Vector3.zero\n        player:SetAttribute(\"P17ReviewMove\", requestedMove)\n        if not player:GetAttribute(\"Posto17InCover\") then\n            hum:Move(requestedMove, false)\n        end\n        local low = player:GetAttribute(\"Posto17Prone\")\n        local focus = root.Position + Vector3.new(0, low and -1.0 or -0.35, 0)\n        local offset = Vector3.new(2.2, 1.45, 9.7)\n        if label == \"LOCKPICK\" or label == \"BOTAO\" or label == \"TERMINAL\"\n            or label == \"ABRIR PORTA\" or label == \"DESLIZAR PORTA DO ARMARIO\" then\n            offset = Vector3.new(8.1, 1.8, 0.4)\n            focus -= Vector3.zAxis * 0.72\n        end\n        if label:find(\"COBERTURA\", 1, true) then offset = Vector3.new(4.1, 1.4, -9.7) end\n        if label:find(\"COBERTURA ALTA\", 1, true) then offset = Vector3.new(6.4, 1.4, -7.2) end\n        if label == \"VIGIA / PATRULHA\" then focus += Vector3.xAxis * 7; offset *= 1.22 end\n        if label == \"PICKPOCKET\" or label == \"NEUTRALIZAR\" or label == \"TAKEDOWN LETAL\" then\n            focus += Vector3.xAxis * 1.15\n        end\n        local desired = CFrame.lookAt(focus + offset, focus)\n        previous = previous and previous:Lerp(desired, 1 - math.exp(-dt * 18)) or desired\n        camera.CFrame = previous\n    end)\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/AreaDeTestes","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/AreaDeTestes (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Identificacao discreta do campo de testes; nunca aparece na missao.\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\", 30)\nif not world then return end\nif not world:WaitForChild(\"P17_CampoDeTestes\", 30) then return end\n\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17PainelTestes\"\ngui.ResetOnSpawn = false\ngui.IgnoreGuiInset = false\ngui.DisplayOrder = 18\ngui.Parent = player:WaitForChild(\"PlayerGui\")\n\nlocal background = Instance.new(\"Frame\")\nbackground.Name = \"CampoTeste\"\nbackground.AnchorPoint = Vector2.new(0.5, 0)\nbackground.Position = UDim2.fromScale(0.5, 0.015)\nbackground.Size = UDim2.fromOffset(160, 20)\nbackground.BackgroundColor3 = Theme.Surface\nbackground.BackgroundTransparency = 1\nbackground.BorderSizePixel = 0\nbackground.Parent = gui\n\nlocal label = Instance.new(\"TextLabel\")\nlabel.BackgroundTransparency = 1\nlabel.Position = UDim2.fromOffset(0, 0)\nlabel.Size = UDim2.fromScale(1, 1)\nlabel.TextXAlignment = Enum.TextXAlignment.Center\nlabel.TextYAlignment = Enum.TextYAlignment.Center\nlabel.TextColor3 = Theme.Text\nlabel.Font = Theme.Font\nlabel.TextSize = 11\nlabel.TextStrokeTransparency = 0.57\nlabel.TextWrapped = true\nlabel.Parent = background\n\nlocal function update()\n    local inside = player:GetAttribute(\"Posto17InTestRange\") ~= false\n        and player:GetAttribute(\"Posto17InVisualShowcase\") ~= true\n    background.Visible = inside\n    if not inside then return end\n    label.Text = \"Campo de testes · \"\n        .. tostring(world:GetAttribute(\"MissionVersion\") or \"QA\")\nend\nplayer:GetAttributeChangedSignal(\"Posto17InTestRange\"):Connect(update)\nplayer:GetAttributeChangedSignal(\"Posto17InVisualShowcase\"):Connect(update)\nworld:GetAttributeChangedSignal(\"MissionVersion\"):Connect(update)\nupdate()\n"},{"studio":"StarterPlayer/StarterPlayerScripts/ArsenalBench","class":"ModuleScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/ArsenalBench (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal RunService = game:GetService(\"RunService\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Art = require(game:GetService(\"ReplicatedStorage\")\n    :WaitForChild(\"Posto17Shared\"):WaitForChild(\"VisualIdentity\"))\nlocal P = Art.Palette\n\nlocal ArsenalBench = {}\nArsenalBench.__index = ArsenalBench\n\nlocal function bottom(part)\n    local frame, size = part.CFrame, part.Size*.5\n    return frame.Position.Y - math.abs(frame.RightVector.Y)*size.X\n        - math.abs(frame.UpVector.Y)*size.Y - math.abs(frame.LookVector.Y)*size.Z\nend\n\nlocal function project(camera, size, point)\n    local localPoint = camera.CFrame:PointToObjectSpace(point)\n    if localPoint.Z >= 0 or size.Y < 1 then return end\n    local depth = -localPoint.Z * math.tan(math.rad(camera.FieldOfView*.5))\n    return Vector2.new(size.X*.5 + localPoint.X*size.Y/(2*depth),size.Y*.5 - localPoint.Y*size.Y/(2*depth))\nend\n\nlocal function itemBounds(camera, size, object)\n    local frame, dimensions\n    if object:IsA(\"Model\") then\n        frame, dimensions = object:GetBoundingBox()\n    else\n        frame, dimensions = object.CFrame, object.Size\n    end\n    local half = dimensions*.5\n    local left, right, top, bottom = math.huge, -math.huge, math.huge, -math.huge\n    for _, x in ipairs({-half.X,half.X}) do\n        for _, y in ipairs({-half.Y,half.Y}) do\n            for _, z in ipairs({-half.Z,half.Z}) do\n                local point = project(camera,size,frame:PointToWorldSpace(Vector3.new(x,y,z)))\n                if not point then return end\n                left,right = math.min(left,point.X),math.max(right,point.X)\n                top,bottom = math.min(top,point.Y),math.max(bottom,point.Y)\n            end\n        end\n    end\n    return UDim2.fromOffset((left+right)*.5,(top+bottom)*.5),\n        UDim2.fromOffset(math.max(36,right-left+10),math.max(34,bottom-top+8))\nend\n\nfunction ArsenalBench.new(stage, overlay, camera, store, theme, items, onSelect)\n    local group = Instance.new(\"Folder\")\n    group.Name = \"BancadaArsenal\"\n    local self = setmetatable({\n        stage=stage, overlay=overlay, camera=camera, store=store, group=group,\n        buttons={}, objects={}, stored={}, theme=theme,\n    }, ArsenalBench)\n    for _, item in ipairs(items) do\n        local button = Instance.new(\"TextButton\")\n        button.Name,button.Text = item.id,\"\"\n        button.AnchorPoint = Vector2.new(.5,.5)\n        local depth = item.id == \"Suppressor\" and 6 or 4\n        button.BackgroundTransparency,button.ZIndex = 1,depth\n        button.Visible = false\n        button.Parent = overlay\n        button.Activated:Connect(function() onSelect(item) end)\n\n        local border = Instance.new(\"UIStroke\")\n        border.ApplyStrokeMode = Enum.ApplyStrokeMode.Border\n        border.Thickness,border.Color = .8,theme.Active\n        border.Parent = button\n\n        local caption = Instance.new(\"TextLabel\")\n        caption.Text = item.label\n        caption.AnchorPoint = Vector2.new(.5,0)\n        caption.Position = UDim2.new(.5,0,1,3)\n        caption.Size = UDim2.fromOffset(92,15)\n        caption.ZIndex = depth+1\n        caption.BackgroundTransparency = 1\n        caption.Font,caption.TextSize = theme.Font,12\n        caption.TextColor3,caption.TextStrokeTransparency = theme.Text,.87\n        caption.Parent = button\n        self.buttons[item.id] = {button=button,border=border,caption=caption}\n    end\n    return self\nend\n\nfunction ArsenalBench:build()\n    local pistol = self.store and self.store:FindFirstChild(\"ArsenalPistol\")\n    local suppressor = self.store and self.store:FindFirstChild(\"ArsenalSuppressor\")\n    if not pistol or not suppressor then return false end\n    pistol,suppressor = pistol:Clone(),suppressor:Clone()\n    -- Bancada de preparacao: espuma dentro de maleta rigida.\n    -- Prop separado dos botoes de selecao: as armas mantem clique 3D.\n    local function prop(name,size,position,color,material)\n        local part=Instance.new(\"Part\")\n        part.Name=name\n        part.Size=size\n        part.Position=position\n        part.Color=color\n        part.Material=material or Enum.Material.Metal\n        part.Anchored=true\n        part.CanCollide=false\n        part.CanQuery=false\n        part.CanTouch=false\n        part.TopSurface,part.BottomSurface =\n            Enum.SurfaceType.Smooth,Enum.SurfaceType.Smooth\n        part.Parent=self.group\n        return part\n    end\n    prop(\"Hardcase / casco\",Vector3.new(4.35,.12,2.07),\n        Vector3.new(.13,2.52,3.15),P.Armor)\n    prop(\"Espuma recortada\",Vector3.new(4.05,.035,1.84),\n        Vector3.new(.13,2.58,3.15),P.TechnicalRubber,\n        Enum.Material.SmoothPlastic)\n    for _, x in ipairs({-1.98,2.24}) do\n        prop(\"Aro lateral\",Vector3.new(.10,.22,2.07),\n            Vector3.new(x,2.63,3.15),P.BrushedSteel)\n    end\n    prop(\"Aro dianteiro\",Vector3.new(4.34,.18,.09),\n        Vector3.new(.13,2.61,2.11),P.BrushedSteel)\n    prop(\"Aro traseiro\",Vector3.new(4.34,.18,.09),\n        Vector3.new(.13,2.61,4.19),P.BrushedSteel)\n    prop(\"Tampa aberta\",Vector3.new(4.35,1.18,.12),\n        Vector3.new(.13,3.25,4.35),P.Armor)\n    prop(\"Espuma da tampa\",Vector3.new(4.05,1.03,.08),\n        Vector3.new(.13,3.25,4.28),P.TechnicalRubber,\n        Enum.Material.SmoothPlastic)\n    for _, x in ipairs({-1.45,1.72}) do\n        prop(\"Fecho de pressao\",Vector3.new(.4,.11,.12),\n            Vector3.new(x,2.66,2.045),P.BrushedSteel)\n        prop(\"Dobradica da tampa\",Vector3.new(.32,.16,.14),\n            Vector3.new(x,2.66,4.26),P.Graphite)\n    end\n    -- Uma pequena marca de inventario, nunca faixa de neon continua.\n    prop(\"Selo identificacao P17\",Vector3.new(.55,.018,.045),\n        Vector3.new(-1.42,2.625,2.075),self.theme.Brand,\n        Enum.Material.SmoothPlastic)\n    -- Ferramentas de representacao cenografica, ordenadas junto a borda.\n    for i=1,3 do\n        prop(\"Ferramenta de revisao\",Vector3.new(.095,.09,.58),\n            Vector3.new(2.54,2.66,2.52+i*.35),\n            i==2 and P.Oxide or P.BrushedSteel)\n    end\n    prop(\"Bandeja de pecas\",Vector3.new(.55,.08,.55),\n        Vector3.new(2.52,2.62,3.9),P.Graphite)\n    local lid=prop(\"Etiqueta do hardcase\",Vector3.new(2.1,.48,.018),\n        Vector3.new(.13,3.35,4.205),P.Graphite)\n    local sign=Instance.new(\"SurfaceGui\")\n    sign.Name=\"IdentificacaoInventario\"\n    sign.Face=Enum.NormalId.Front\n    sign.PixelsPerStud=30\n    sign.SizingMode=Enum.SurfaceGuiSizingMode.PixelsPerStud\n    sign.Parent=lid\n    local serial=Instance.new(\"TextLabel\")\n    serial.Size=UDim2.fromScale(1,1)\n    serial.BackgroundTransparency=1\n    serial.Text=\"P17   /   EQUIPAMENTO 02\"\n    serial.TextColor3=P.Paper\n    serial.Font=Enum.Font.Code\n    serial.TextScaled=true\n    serial.Parent=sign\n\n    pistol:PivotTo(CFrame.new(.55,0,3.12)*CFrame.Angles(0,math.rad(-64),0)*CFrame.Angles(0,0,math.pi/2))\n    local floor = math.huge\n    for _, part in ipairs(pistol:GetChildren()) do floor = math.min(floor,bottom(part)) end\n    pistol:PivotTo(pistol:GetPivot()+Vector3.yAxis*(2.609-floor))\n    pistol.Parent = self.group\n    self.rest = CFrame.new(-.77,2.692,3.60)*CFrame.Angles(0,math.rad(12),0)\n    suppressor.CFrame = self.rest\n    suppressor.Parent = self.group\n    self.tip = pistol:FindFirstChild(\"TipAttachment\",true)\n    self.objects = {Pistol=pistol,Suppressor=suppressor}\n    return true\nend\n\nfunction ArsenalBench:layout()\n    for id, control in pairs(self.buttons) do\n        local object = self.objects[id]\n        if object then\n            local position, size = itemBounds(self.camera,self.overlay.AbsoluteSize,object)\n            control.button.Visible = position ~= nil\n            if position then control.button.Position,control.button.Size = position,size end\n        end\n    end\nend\n\nfunction ArsenalBench:setOpen(open)\n    if open == (self.connection ~= nil) then return end\n    if not open then\n        self.connection:Disconnect()\n        self.connection = nil\n        self.group.Parent = nil\n        for _, prop in ipairs(self.stored) do prop.Parent = self.stage end\n        table.clear(self.stored)\n        for _, control in pairs(self.buttons) do control.button.Visible = false end\n        return\n    end\n    if not self.objects.Pistol and not self:build() then return end\n    for _, name in ipairs({\"Caixa de ferramentas\",\"Bandeja\",\"Tela\",\"Terminal\"}) do\n        local prop = self.stage:FindFirstChild(name)\n        if prop then\n            table.insert(self.stored,prop)\n            prop.Parent = nil\n        end\n    end\n    self.group.Parent = self.stage\n    self.connection = RunService.RenderStepped:Connect(function() self:layout() end)\nend\n\nfunction ArsenalBench:update(selection, mounted, animate)\n    for id, control in pairs(self.buttons) do\n        local active = id == selection\n        -- A legenda muda de cor; a caixa de clique 3D nao deve virar moldura\n        -- enorme sobre o equipamento.\n        control.border.Transparency = active and .82 or 1\n        control.caption.TextColor3 = active and self.theme.Active or self.theme.Text\n    end\n    local suppressor = self.objects.Suppressor\n    if not suppressor or not self.tip then return end\n    local target = mounted and self.tip.WorldCFrame * CFrame.new(0,0,-.25)\n        * CFrame.Angles(0,math.pi/2,0) or self.rest\n    if self.attachmentTween then self.attachmentTween:Cancel() end\n    if animate then\n        self.attachmentTween = TweenService:Create(suppressor,TweenInfo.new(.29,Enum.EasingStyle.Quad),\n            {CFrame=target})\n        self.attachmentTween:Play()\n    else\n        suppressor.CFrame = target\n    end\nend\n\nreturn ArsenalBench\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Audio","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Audio (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Mixagem local leve. Apenas sons internos do Roblox; nenhum asset externo.\nlocal Players = game:GetService(\"Players\")\nlocal SoundService = game:GetService(\"SoundService\")\nlocal Debris = game:GetService(\"Debris\")\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\")\nlocal lastAlert = false\nlocal lastRadio = true\nlocal function cue(speed, volume)\n    local tone = Instance.new(\"Sound\")\n    tone.SoundId = \"rbxasset://sounds/electronicpingshort.wav\"\n    tone.Volume = volume\n    tone.PlaybackSpeed = speed\n    tone.Parent = SoundService\n    tone:Play()\n    Debris:AddItem(tone, 3)\nend\nworld:GetAttributeChangedSignal(\"RadarJammed\"):Connect(function()\n    local active = world:GetAttribute(\"RadarJammed\") == true\n    if active ~= lastAlert then cue(active and 0.65 or 1.4, active and 0.2 or 0.1) end\n    lastAlert = active\nend)\nworld:GetAttributeChangedSignal(\"PowerOnline\"):Connect(function()\n    local active = world:GetAttribute(\"PowerOnline\") ~= false\n    cue(active and 1.45 or 0.48, active and 0.1 or 0.16)\nend)\nworld:GetAttributeChangedSignal(\"RadioOnline\"):Connect(function()\n    local active = world:GetAttribute(\"RadioOnline\") ~= false\n    if active ~= lastRadio then cue(active and 1.1 or 0.45, 0.12) end\n    lastRadio = active\nend)\nplayer:GetAttributeChangedSignal(\"Posto17Instinct\"):Connect(function()\n    -- Entrada e saida tem um unico sinal; nao toca em loop nem revela NPCs por som.\n    cue(player:GetAttribute(\"Posto17Instinct\") and 0.8 or 1.25, 0.055)\nend)\n\ntask.spawn(function()\n    while script.Parent do\n        local char = player.Character\n        local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n        local hum = char and char:FindFirstChildOfClass(\"Humanoid\")\n        local running = root and root:FindFirstChild(\"Running\")\n        if running and running:IsA(\"Sound\") and hum then\n            local wood = hum.FloorMaterial == Enum.Material.Wood or hum.FloorMaterial == Enum.Material.WoodPlanks\n            running.PlaybackSpeed = wood and 0.8 or (hum.FloorMaterial == Enum.Material.Metal and 1.2 or 1)\n            running.Volume = player:GetAttribute(\"Posto17Crouched\") and 0.03 or 0.2\n        end\n        task.wait(0.25)\n    end\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Cobertura","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Cobertura (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- POSTO 17 // cobertura de parede e camera cinematografica leve.\n-- Segurar movimento junto a parede desloca paralelo a ela; no fim,\n-- a camera faz um peek sem atravessar o obstaculo.\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal ContextActionService = game:GetService(\"ContextActionService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\n\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\", 30)\nif not world then return end\n\nlocal remote = RS:WaitForChild(\"Posto17Cover\")\nlocal covering = false\nlocal wall = nil\nlocal normal = nil\nlocal tangent = nil\nlocal peek = 0\nlocal previousCameraType = nil\nlocal previousAutoRotate = nil\nlocal rayParams = RaycastParams.new()\nrayParams.FilterType = Enum.RaycastFilterType.Exclude\nrayParams.RespectCanCollide = true\n\nlocal function alive()\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    local humanoid = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if not character or not root or not humanoid or humanoid.Health <= 0 then\n        return nil, nil, nil\n    end\n    return character, root, humanoid\nend\n\nlocal function surfaceHit(character, from, direction)\n    rayParams.FilterDescendantsInstances = {character}\n    local hit = workspace:Raycast(from, direction, rayParams)\n    if hit and hit.Instance:IsDescendantOf(world)\n        and (hit.Instance.Name == \"Parede\" or hit.Instance.Name == \"Caixa\")\n        and math.abs(hit.Normal.Y) < 0.4 then\n        return hit\n    end\n    return nil\nend\n\nlocal function nearestSurface(character, root)\n    local best = nil\n    local bestDistance = math.huge\n    for i = 0, 7 do\n        local angle = i * math.pi / 4\n        local direction = Vector3.new(math.cos(angle), 0, math.sin(angle))\n        local hit = surfaceHit(character, root.Position,\n            direction * 3.9)\n        if not hit then hit = surfaceHit(character, root.Position - Vector3.yAxis * 1.1, direction * 3.9) end\n        if hit and hit.Distance < bestDistance then\n            bestDistance = hit.Distance\n            best = hit\n        end\n    end\n    return best\nend\n\nlocal function releaseCover()\n    if not covering then return end\n    covering = false\n    peek = 0\n    wall = nil\n    normal = nil\n    tangent = nil\n    player:SetAttribute(\"Posto17InCover\", false)\n    remote:FireServer()\n    local _, _, humanoid = alive()\n    if humanoid then\n        humanoid.AutoRotate = previousAutoRotate ~= false\n    end\n    local camera = workspace.CurrentCamera\n    if camera then\n        camera.CameraType = previousCameraType or Enum.CameraType.Custom\n    end\nend\n\nlocal function tryCover()\n    local character, root, humanoid = alive()\n    if not root or player:GetAttribute(\"Posto17Hidden\")\n        or player:GetAttribute(\"Posto17Dragging\")\n        or player:GetAttribute(\"Posto17Prone\")\n        or player:GetAttribute(\"Posto17Won\") or player:GetAttribute(\"Posto17Box\") then return end\n    local hit = nearestSurface(character, root)\n    if not hit then return end\n    local horizontal = Vector3.new(hit.Normal.X, 0, hit.Normal.Z)\n    if horizontal.Magnitude < 0.7 then return end\n    normal = horizontal.Unit\n    tangent = Vector3.new(-normal.Z, 0, normal.X)\n    wall = hit.Instance\n    peek = 0\n    covering = true\n    previousCameraType = workspace.CurrentCamera\n        and workspace.CurrentCamera.CameraType or Enum.CameraType.Custom\n    previousAutoRotate = humanoid.AutoRotate\n    humanoid.AutoRotate = false\n    remote:FireServer(wall)\n    task.delay(0.75, function()\n        if covering and wall == hit.Instance and not player:GetAttribute(\"Posto17CoverHeight\") then\n            releaseCover()\n        end\n    end)\n    player:SetAttribute(\"Posto17InCover\", true)\n    local camera = workspace.CurrentCamera\n    if camera then camera.CameraType = Enum.CameraType.Scriptable end\nend\n\nlocal function toggleCover(_, inputState)\n    if inputState ~= Enum.UserInputState.Begin then\n        return Enum.ContextActionResult.Pass\n    end\n    if covering then releaseCover() else tryCover() end\n    return Enum.ContextActionResult.Sink\nend\n\nContextActionService:BindAction(\"P17Cobertura\", toggleCover, false,\n    Enum.KeyCode.V)\n\n-- O ensaio aciona o mesmo controlador dos botoes de jogo.\nif game.PlaceId == 119377443515742 or RunService:IsStudio() then\n    local review = Instance.new(\"BindableEvent\")\n    review.Name = \"P17CoverReview\"\n    review.Parent = player:WaitForChild(\"PlayerScripts\")\n    review.Event:Connect(function(enabled)\n        if not player:GetAttribute(\"Posto17InTestRange\") then return end\n        if enabled and not covering then tryCover() end\n        if not enabled then releaseCover() end\n    end)\nend\n\n-- Botao pequeno no celular, proximo aos outros controles taticos.\nif UserInputService.TouchEnabled then\n    local gui = Instance.new(\"ScreenGui\")\n    gui.Name = \"Posto17CoberturaTouch\"\n    gui.IgnoreGuiInset = false\n    gui.DisplayOrder = 8\n    gui.ResetOnSpawn = false\n    gui.Parent = player:WaitForChild(\"PlayerGui\")\n    local button = Instance.new(\"TextButton\")\n    button.Name = \"BotaoCobertura\"\n    button.AnchorPoint = Vector2.new(1, 1)\n    button.Position = UDim2.new(1, -23, 1, -254)\n    button.Size = UDim2.fromOffset(75, 29)\n    button.BackgroundColor3 = Theme.Panel\n    button.BackgroundTransparency = 0.25\n    button.BorderSizePixel = 0\n    button.Text = \"COBERTURA\"\n    button.Font = Theme.Font\n    button.TextSize = 11\n    button.TextColor3 = Theme.Text\n    button.Parent = gui\n    local round = Instance.new(\"UICorner\")\n    round.CornerRadius = UDim.new(0, 5)\n    round.Parent = button\n    button.MouseButton1Click:Connect(function()\n        toggleCover(nil, Enum.UserInputState.Begin)\n        button.TextColor3 = covering\n            and Theme.Muted\n            or Theme.Text\n    end)\nend\n\nplayer.CharacterAdded:Connect(releaseCover)\nplayer:GetAttributeChangedSignal(\"Posto17CoverHeight\"):Connect(function()\n    if not player:GetAttribute(\"Posto17CoverHeight\") then releaseCover() end\nend)\nplayer:GetAttributeChangedSignal(\"Posto17Dragging\"):Connect(function()\n    if player:GetAttribute(\"Posto17Dragging\") then releaseCover() end\nend)\nplayer:GetAttributeChangedSignal(\"Posto17Prone\"):Connect(function()\n    if player:GetAttribute(\"Posto17Prone\") then releaseCover() end\nend)\nplayer:GetAttributeChangedSignal(\"Posto17Hidden\"):Connect(function()\n    if player:GetAttribute(\"Posto17Hidden\") then releaseCover() end\nend)\n\nRunService:BindToRenderStep(\"P17CoberturaCamera\",\n    Enum.RenderPriority.Camera.Value + 2, function(dt)\n    if not covering then return end\n    local character, root, humanoid = alive()\n    if not root or player:GetAttribute(\"Posto17Won\") then\n        releaseCover()\n        return\n    end\n    local origin = root.Position\n    if player:GetAttribute(\"Posto17CoverHeight\") == \"LOW\" then origin -= Vector3.yAxis * 1.05 end\n    local back = surfaceHit(character, origin, -normal * 5.4)\n        or surfaceHit(character, origin - Vector3.yAxis, -normal * 5.4)\n    if not back or back.Instance ~= wall then\n        releaseCover()\n        return\n    end\n    local isLow = player:GetAttribute(\"Posto17Crouched\") == true\n    local tight = player:GetAttribute(\"Posto17CoverHeight\") == \"HIGH\" and not isLow\n    local reviewMove = player:GetAttribute(\"P17Reviewing\") and player:GetAttribute(\"P17ReviewMove\")\n    local move = reviewMove or humanoid.MoveDirection\n    local parallel = move:Dot(tangent)\n    if math.abs(parallel) > 0.12 then\n        local sign = parallel > 0 and 1 or -1\n        local ahead = origin + tangent * sign * (tight and 0.85 or 2.6)\n        local stillWall = surfaceHit(character, ahead, -normal * 4.9)\n        if stillWall and stillWall.Instance == wall then\n            peek = 0\n            humanoid:Move(tangent * parallel, false)\n        else\n            -- Parar na quina: sem espiar, sem atravessar a parede.\n            peek = 0\n            humanoid:Move(Vector3.zero, false)\n        end\n    else\n        humanoid:Move(Vector3.zero, false)\n    end\n\n    -- Folga para tronco, bracos e acessorios. A antiga folga de .055\n    -- colocava o R6 para dentro do concreto.\n    local torso = character:FindFirstChild(\"UpperTorso\") or character:FindFirstChild(\"Torso\")\n    local depth = math.max(root.Size.Z, torso and torso.Size.Z or 0)\n    local gap = math.max(1.37, depth * 0.5 + 0.70)\n    local velocity = root.AssemblyLinearVelocity\n    root.AssemblyLinearVelocity = velocity - normal * velocity:Dot(normal)\n    local correction = normal * (gap - back.Distance)\n    if correction:Dot(normal) < -0.02 and correction.Magnitude > 0.02 then\n        local sweep = root.Size * Vector3.new(0.74, 0.82, 0.92)\n        local obstacle = workspace:Blockcast(root.CFrame, sweep, correction, rayParams)\n        if obstacle then\n            correction = correction.Unit * math.min(correction.Magnitude, math.max(0, obstacle.Distance - 0.025))\n        end\n    end\n    local position = root.Position + correction * (1 - math.exp(-dt * (tight and 22 or 15)))\n    -- Peito paralelo a parede, nunca olhando perpendicularmente para ela.\n    local orientation = CFrame.lookAt(root.Position, root.Position + tangent).Rotation\n    root.CFrame = CFrame.new(position) * root.CFrame.Rotation:Lerp(orientation, 1 - math.exp(-dt * 15))\n    local camera = workspace.CurrentCamera\n    if not camera then return end\n    local lookAhead = root.Position + tangent * (tight and 0.5 or 1.2)\n        + Vector3.new(0, isLow and -0.28 or 0.75, 0)\n    local cameraPos = root.Position + normal * (tight and 7.4 or 5.1) - tangent * (tight and 2.1 or 5.7)\n        + Vector3.new(0, isLow and 1.8 or 2.7, 0)\n    rayParams.FilterDescendantsInstances = {character}\n    local obstacle = workspace:Raycast(root.Position\n        + Vector3.new(0, 1.3, 0), cameraPos\n        - (root.Position + Vector3.new(0, 1.3, 0)), rayParams)\n    if obstacle then\n        cameraPos = obstacle.Position + obstacle.Normal * 0.4\n    end\n    local desired = CFrame.lookAt(cameraPos, lookAhead)\n    camera.CFrame = camera.CFrame:Lerp(desired, math.clamp(dt * 7, 0, 1))\nend)\n\nif UserInputService.TouchEnabled then\n    task.spawn(function()\n        while player.Parent do\n            local character, root = alive()\n            local nearby = false\n            if root and not covering and not player:GetAttribute(\"Posto17Hidden\")\n                and not player:GetAttribute(\"Posto17Prone\") and not player:GetAttribute(\"Posto17Box\")\n                and not player:GetAttribute(\"Posto17Dragging\") then\n                nearby = nearestSurface(character, root) ~= nil\n            end\n            player:SetAttribute(\"P17NearbyCover\", nearby)\n            task.wait(0.24)\n        end\n    end)\nend\n"},{"studio":"StarterPlayer/StarterPlayerScripts/CrouchLegs","class":"ModuleScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/CrouchLegs (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posiciona os pés e resolve quadril, joelho e tornozelo para o rig do jogador.\nlocal CrouchLegs = {}\n\nlocal function align(frame, bone, direction)\n    local current = frame:VectorToWorldSpace(bone.Unit)\n    local axis = current:Cross(direction)\n    if axis.Magnitude < 0.001 then return CFrame.identity end\n    local angle = math.acos(math.clamp(current:Dot(direction), -1, 1))\n    return frame.Rotation:Inverse() * CFrame.fromAxisAngle(axis.Unit, angle) * frame.Rotation\nend\n\nlocal function legTarget(chain, pelvis, root, floor, params, stride, phase, motion)\n    local hip, knee, ankle = chain[1], chain[2], chain[3]\n    if hip.Part0 == nil or knee.Part0 == nil or ankle.Part1 == nil then return end\n    local foot = ankle.Part1\n    local upper = (hip.C1:Inverse() * knee.C0).Position\n    local lower = (knee.C1:Inverse() * ankle.C0).Position\n    local upperLength, lowerLength = upper.Magnitude, lower.Magnitude\n    if upperLength < 0.1 or lowerLength < 0.1 then return end\n\n    local forward = root.CFrame.LookVector\n    local joint = pelvis * hip.C0\n    local spread = (joint.Position - root.Position):Dot(root.CFrame.RightVector) * 1.10\n    local support = 0.58\n    local travel, footLift\n    if phase < support then\n        -- Durante o apoio o pé percorre no personagem a mesma distância\n        -- que o personagem percorre no mundo.\n        travel = (support * 0.5 - phase) * stride\n        footLift = 0\n    else\n        local swing = (phase - support) / (1 - support)\n        local eased = swing * swing * (3 - 2 * swing)\n        travel = (eased - 0.5) * stride * support\n        footLift = math.sin(math.pi * swing) ^ 2 * 0.32\n    end\n\n    local point = root.Position + root.CFrame.RightVector * spread\n        + forward * (0.10 + travel * motion)\n    local step = workspace:Raycast(point + Vector3.yAxis, -Vector3.yAxis * 8, params)\n    local ground = step and step.Normal.Y > 0.65 and math.abs(step.Position.Y - floor.Position.Y) < 0.7\n        and step or floor\n    local footPosition = Vector3.new(point.X, ground.Position.Y, point.Z)\n        + ground.Normal * (foot.Size.Y * 0.5 + 0.027 + footLift * motion)\n    local heading = forward - ground.Normal * forward:Dot(ground.Normal)\n    local footFrame = CFrame.lookAt(footPosition, footPosition + heading, ground.Normal)\n    return {\n        hip = hip, knee = knee, ankle = ankle, upper = upper, lower = lower,\n        footFrame = footFrame, reach = (upperLength + lowerLength) * 0.66,\n    }\nend\n\nlocal function solve(leg, pelvis, forward, weight)\n    local hip, knee, ankle = leg.hip, leg.knee, leg.ankle\n    local hipFrame = pelvis * hip.C0\n    local target = leg.footFrame * ankle.C1\n    local ray = target.Position - hipFrame.Position\n    if ray.Magnitude < 0.05 then return end\n    local upper, lower = leg.upper.Magnitude, leg.lower.Magnitude\n    local distance = math.clamp(ray.Magnitude, math.abs(upper - lower) + 0.01, upper + lower - 0.012)\n    local line = ray.Unit\n    local bend = forward - line * forward:Dot(line)\n    if bend.Magnitude < 0.01 then return end\n    local along = (upper * upper - lower * lower + distance * distance) / (2 * distance)\n    local kneePosition = hipFrame.Position + line * along\n        + bend.Unit * math.sqrt(math.max(0, upper * upper - along * along))\n    local anklePosition = hipFrame.Position + line * distance\n\n    local hipOffset = align(hipFrame, leg.upper, (kneePosition - hipFrame.Position).Unit)\n    local kneeFrame = hipFrame * hipOffset * hip.C1:Inverse() * knee.C0\n    local kneeOffset = align(kneeFrame, leg.lower, (anklePosition - kneePosition).Unit)\n    local ankleFrame = kneeFrame * kneeOffset * knee.C1:Inverse() * ankle.C0\n    local ankleOffset = ankleFrame.Rotation:ToObjectSpace(target.Rotation)\n    hip.Transform = hip.Transform:Lerp(hipOffset, weight)\n    knee.Transform = knee.Transform:Lerp(kneeOffset, weight)\n    ankle.Transform = ankle.Transform:Lerp(ankleOffset, weight)\nend\n\nfunction CrouchLegs.apply(info, root, rootJoint, stride, weight)\n    local floor = workspace:Raycast(root.Position, -Vector3.yAxis * 7, info.rayParams)\n    if not floor or floor.Normal.Y < 0.65 then return end\n    local pelvis = root.CFrame * rootJoint.C0 * rootJoint.Transform * rootJoint.C1:Inverse()\n    local legs = {}\n    local correction = 0\n    for i, side in ipairs({\"left\", \"right\"}) do\n        local hip = info.joints[side .. \"hip\"]\n        local knee = info.joints[side .. \"knee\"]\n        local ankle = info.joints[side .. \"ankle\"]\n        if not hip or not knee or not ankle then return end\n        local phase = (info.cycle / (math.pi * 2) + (i - 1) * 0.5) % 1\n        local leg = legTarget({hip, knee, ankle}, pelvis, root, floor, info.rayParams, stride, phase, info.motion)\n        if not leg then return end\n        legs[i] = leg\n        local ankleHeight = (leg.footFrame * ankle.C1).Position.Y\n        correction += (ankleHeight + leg.reach - (pelvis * hip.C0).Position.Y) * 0.5\n    end\n    local shift = Vector3.yAxis * (math.clamp(correction, -1.3, 1.3) * weight)\n    local localShift = (root.CFrame * rootJoint.C0):VectorToObjectSpace(shift)\n    rootJoint.Transform = CFrame.new(localShift) * rootJoint.Transform\n    pelvis += shift\n\n    for _, leg in ipairs(legs) do\n        solve(leg, pelvis, root.CFrame.LookVector, weight)\n    end\nend\n\nreturn CrouchLegs\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Guia","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Guia (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- POSTO 17 // marcador tatico de objetivo e ajuda contextual (HUD v2).\n-- Nenhuma bussola fixa. Segurar Q mostra waypoint na cena.\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\", 30)\nif not world then return end\n\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Guia\"\ngui.ResetOnSpawn = false\ngui.IgnoreGuiInset = true\ngui.DisplayOrder = 9\ngui.Parent = player:WaitForChild(\"PlayerGui\")\n\nlocal mobileScale = UserInputService.TouchEnabled and 0.82 or 1\nlocal WHITE = Theme.Text\nlocal AMBER = Theme.Caution\nlocal GREEN = Theme.Success\nlocal DIM = Theme.Muted\n\n-- Um reticulo simples de quatro cantos (sem image assets e sem fundos solidos).\nlocal marker = Instance.new(\"Frame\")\nmarker.Name = \"MarcadorObjetivo\"\nmarker.AnchorPoint = Vector2.new(0.5, 0.75)\nmarker.Size = UDim2.fromOffset(176, 70)\nmarker.BackgroundTransparency = 1\nmarker.Visible = false\nmarker.Parent = gui\nlocal markerScale = Instance.new(\"UIScale\")\nmarkerScale.Scale = mobileScale\nmarkerScale.Parent = marker\n\nlocal markerText = Instance.new(\"TextLabel\")\nmarkerText.Name = \"Distancia\"\nmarkerText.Position = UDim2.fromOffset(0, 0)\nmarkerText.Size = UDim2.fromOffset(176, 25)\nmarkerText.BackgroundTransparency = 1\nmarkerText.Font = Theme.Font\nmarkerText.TextSize = 14\nmarkerText.TextStrokeTransparency = 0.5\nmarkerText.TextColor3 = AMBER\nmarkerText.Text = \"[OBJETIVO 0 m]\"\nmarkerText.Parent = marker\n\nlocal arrow = Instance.new(\"TextLabel\")\narrow.Name = \"Direcao\"\narrow.Size = UDim2.fromOffset(38, 24)\narrow.Position = UDim2.fromOffset(69, 43)\narrow.BackgroundTransparency = 1\narrow.Text = \"\"\narrow.TextColor3 = AMBER\narrow.TextSize = 21\narrow.Font = Theme.Font\narrow.Visible = false\narrow.Parent = marker\n\nlocal point = Instance.new(\"Frame\")\npoint.AnchorPoint = Vector2.new(0.5, 0.5)\npoint.Position = UDim2.fromOffset(88, 29)\npoint.Size = UDim2.fromOffset(5, 5)\npoint.BorderSizePixel = 0\npoint.Parent = marker\nlocal pointCorner = Instance.new(\"UICorner\")\npointCorner.CornerRadius = UDim.new(1, 0)\npointCorner.Parent = point\n\n-- Ajuda discreta: H ou toque abre os controles por alguns segundos.\nlocal help = Instance.new(\"Frame\")\nhelp.Name = \"AjudaContextual\"\nhelp.AnchorPoint = Vector2.new(0, 1)\nhelp.Position = UDim2.new(0, 26, 1, -60)\nhelp.Size = UDim2.fromOffset(350, 91)\nhelp.BackgroundColor3 = Theme.Panel\nhelp.BackgroundTransparency = 0.3\nhelp.BorderSizePixel = 0\nhelp.Visible = false\nhelp.Parent = gui\n\nlocal helpLine = Instance.new(\"Frame\")\nhelpLine.Size = UDim2.fromOffset(2, 69)\nhelpLine.Position = UDim2.fromOffset(9, 11)\nhelpLine.BackgroundColor3 = AMBER\nhelpLine.BorderSizePixel = 0\nhelpLine.Parent = help\n\nlocal helpText = Instance.new(\"TextLabel\")\nhelpText.Name = \"Texto\"\nhelpText.Position = UDim2.fromOffset(21, 8)\nhelpText.Size = UDim2.fromOffset(323, 77)\nhelpText.BackgroundTransparency = 1\nhelpText.TextColor3 = WHITE\nhelpText.TextSize = 13\nhelpText.TextWrapped = true\nhelpText.TextXAlignment = Enum.TextXAlignment.Left\nhelpText.TextYAlignment = Enum.TextYAlignment.Center\nhelpText.Font = Theme.Font\nhelpText.Text = \"C AGACHAR   Z DEITAR   V COBERTURA\\nG DISTRAIR  F ABRIGO   E INTERAGIR\\nQ INSTINTO  R REINICIAR  O OPÇÕES\"\nhelpText.Parent = help\n\nlocal helpSerial = 0\nlocal function setHelp(show)\n    helpSerial += 1\n    local serial = helpSerial\n    help.Visible = show\n    if show then\n        task.delay(7, function()\n            if helpSerial == serial and help.Parent then\n                help.Visible = false\n            end\n        end)\n    end\nend\nlocal instinct = player:GetAttribute(\"Posto17Instinct\") == true\nplayer:GetAttributeChangedSignal(\"Posto17Instinct\"):Connect(function()\n    instinct = player:GetAttribute(\"Posto17Instinct\") == true\nend)\nUserInputService.InputBegan:Connect(function(input, processed)\n    if processed then return end\n    if input.KeyCode == Enum.KeyCode.Q or input.KeyCode == Enum.KeyCode.LeftAlt then\n        instinct = true\n    elseif input.KeyCode == Enum.KeyCode.H then\n        setHelp(not help.Visible)\n    end\nend)\nUserInputService.InputEnded:Connect(function(input)\n    if input.KeyCode == Enum.KeyCode.Q or input.KeyCode == Enum.KeyCode.LeftAlt then\n        instinct = false\n        marker.Visible = false\n    end\nend)\n\nlocal function update()\n    if not instinct or player:GetAttribute(\"Posto17Won\") or player:GetAttribute(\"Posto17InTestRange\") then\n        marker.Visible = false\n        return\n    end\n\n    local target\n    local phase = player:GetAttribute(\"Posto17Data\") and \"EXTRACAO\" or \"OBJETIVO\"\n    local color = player:GetAttribute(\"Posto17Data\") and GREEN or AMBER\n    target = world:FindFirstChild(player:GetAttribute(\"Posto17Data\")\n        and \"Extracao\" or \"Terminal\")\n\n    local char = player.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    local camera = workspace.CurrentCamera\n    if not target or not root or not camera then\n        marker.Visible = false\n        return\n    end\n\n    local delta = Vector3.new(target.Position.X-root.Position.X, 0,\n        target.Position.Z-root.Position.Z)\n    local distance = delta.Magnitude * 0.28\n    local worldPos = target.Position + Vector3.new(0, 3.4, 0)\n    local pos, onScreen = camera:WorldToViewportPoint(worldPos)\n    local viewport = camera.ViewportSize\n    local edgeX, edgeY = 95, 78\n    local x = pos.X\n    local y = pos.Y\n\n    -- Quando o objetivo fica atras da camera, usa o vetor local para achar\n    -- a borda do quadro, em vez de perder o marcador.\n    if pos.Z <= 0 then\n        local localVector = camera.CFrame:VectorToObjectSpace(worldPos-camera.CFrame.Position)\n        local dx, dy = localVector.X, -localVector.Y\n        local biggest = math.max(math.abs(dx), math.abs(dy), 0.001)\n        x = viewport.X * 0.5 + dx / biggest * viewport.X * 0.8\n        y = viewport.Y * 0.5 + dy / biggest * viewport.Y * 0.8\n        onScreen = false\n    end\n\n    local boundedX = math.clamp(x, edgeX, math.max(edgeX, viewport.X - edgeX))\n    local boundedY = math.clamp(y, edgeY, math.max(edgeY, viewport.Y - edgeY))\n    local offscreen = not onScreen or x ~= boundedX or y ~= boundedY\n    marker.Position = UDim2.fromOffset(boundedX, boundedY)\n    markerText.Text = string.format(\"[%s %.0f m]\", phase, distance)\n    markerText.TextColor3 = color\n    point.BackgroundColor3 = color\n    point.Visible = not offscreen\n\n    -- Deslocamento da direcao, apontando para a borda correta.\n    arrow.Visible = offscreen\n    if offscreen then\n        local dx, dy = x - boundedX, y - boundedY\n        if math.abs(dx) > math.abs(dy) then\n            arrow.Text = dx > 0 and \">\" or \"<\"\n        else\n            arrow.Text = dy > 0 and \"v\" or \"^\"\n        end\n        arrow.TextColor3 = color\n    end\n    marker.Visible = true\nend\n\ntask.spawn(function()\n    while gui.Parent do\n        task.wait(0.1)\n        update()\n    end\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/HUD","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/HUD (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- POSTO 17 // HUD tatico v2 (mobile e desktop).\n-- Referencia aprovada: texto pequeno no canto, alerta apenas quando necessario.\n-- Controles, eventos, pontuacao e missao da v0.9 preservados.\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal ContextActionService = game:GetService(\"ContextActionService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal Lighting = game:GetService(\"Lighting\")\n\nlocal player = Players.LocalPlayer\nlocal normalMinZoom = player.CameraMinZoomDistance\nlocal stateRemote = ReplicatedStorage:WaitForChild(\"Posto17State\")\nlocal crouchRemote = ReplicatedStorage:WaitForChild(\"Posto17Crouch\")\nlocal stoneRemote = ReplicatedStorage:WaitForChild(\"Posto17Stone\")\nlocal hideRemote = ReplicatedStorage:WaitForChild(\"Posto17HideToggle\")\nlocal restartRemote = ReplicatedStorage:WaitForChild(\"Posto17Restart\")\nlocal proneRemote = ReplicatedStorage:WaitForChild(\"Posto17Prone\")\nlocal world = workspace:WaitForChild(\"Posto17\")\n\nlocal WHITE = Theme.Text\nlocal DIM = Theme.Muted\nlocal RED = Theme.Danger\nlocal AMBER = Theme.Caution\nlocal GREEN = Theme.Success\n\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17HUD\"\ngui.ResetOnSpawn = false\ngui.IgnoreGuiInset = false\ngui.DisplayOrder = 7\ngui.Parent = player:WaitForChild(\"PlayerGui\")\n\nlocal mobileScale = Instance.new(\"UIScale\")\nmobileScale.Name = \"EscalaAdaptativa\"\nmobileScale.Scale = UserInputService.TouchEnabled and 0.82 or 1\nmobileScale.Parent = gui\n\nlocal function txt(parent, name, value, pos, size, fontSize, color, font)\n    local t = Instance.new(\"TextLabel\")\n    t.Name = name\n    t.BackgroundTransparency = 1\n    t.BorderSizePixel = 0\n    t.Position = pos\n    t.Size = size\n    t.Text = value\n    t.TextColor3 = color or WHITE\n    t.TextStrokeColor3 = Theme.Stroke\n    t.TextStrokeTransparency = 0.52\n    t.TextSize = fontSize\n    t.TextXAlignment = Enum.TextXAlignment.Left\n    t.TextYAlignment = Enum.TextYAlignment.Center\n    t.Font = font or Theme.Font\n    t.TextTruncate = Enum.TextTruncate.AtEnd\n    t.Parent = parent\n    return t\nend\n\n-- Uma linha de objetivo, abaixo do menu nativo do Roblox.\nlocal mission = Instance.new(\"Frame\")\nmission.Name = \"MissaoMinima\"\nmission.BackgroundTransparency = 1\nmission.Size = UDim2.fromOffset(275, 22)\nmission.Position = UDim2.fromOffset(16, 9)\nmission.Parent = gui\nlocal phase = txt(mission, \"Phase\", \"Acessar o terminal\",\n    UDim2.fromOffset(0, 0), UDim2.fromScale(1, 1),\n    15, WHITE, Enum.Font.GothamMedium)\n\n-- Alerta e recursos: nao ha um bloco de dashboard permanente.\nlocal alert = txt(gui, \"Alerta\", \"\",\n    UDim2.new(1, -215, 0, 8), UDim2.fromOffset(200, 26),\n    15, RED, Enum.Font.GothamMedium)\nalert.TextXAlignment = Enum.TextXAlignment.Right\nalert.Visible = false\n\nlocal resources = txt(gui, \"Recursos\", \"\",\n    UDim2.new(1, -290, 0, 30), UDim2.fromOffset(280, 23),\n    12, DIM, Theme.Font)\nresources.TextXAlignment = Enum.TextXAlignment.Right\nresources.Visible = false\n\nlocal notice = Instance.new(\"Frame\")\nnotice.Name = \"AvisoContextual\"\nnotice.Size = UDim2.new(0.86, 0, 0, 34)\nnotice.Position = UDim2.new(0.5, 0, 1, -108)\nnotice.AnchorPoint = Vector2.new(0.5, 1)\nnotice.BackgroundTransparency = 1\nnotice.Visible = false\nnotice.Parent = gui\nlocal noticeText = txt(notice, \"Info\", \"\",\n    UDim2.fromOffset(0, 0), UDim2.fromScale(1, 1),\n    14, WHITE, Enum.Font.GothamMedium)\nnoticeText.TextXAlignment = Enum.TextXAlignment.Center\nnoticeText.TextTransparency = 1\nlocal noticeSerial = 0\n\nlocal function announce(value, color, duration)\n    noticeSerial += 1\n    local serial = noticeSerial\n    notice.Visible = true\n    noticeText.Text = value\n    noticeText.TextColor3 = color or WHITE\n    TweenService:Create(noticeText, TweenInfo.new(0.17), {\n        TextTransparency = 0}):Play()\n    task.delay(duration or 3.1, function()\n        if serial ~= noticeSerial or not notice.Parent then return end\n        TweenService:Create(noticeText, TweenInfo.new(0.37), {\n            TextTransparency = 1}):Play()\n        task.delay(0.4, function()\n            if serial == noticeSerial then notice.Visible = false end\n        end)\n    end)\nend\n\n-- Tela de resultado permanece funcional, mas aparece so ao concluir.\nlocal resultFrame = Instance.new(\"Frame\")\nresultFrame.Name = \"Results\"\nresultFrame.Size = UDim2.fromOffset(380, 250)\nresultFrame.Position = UDim2.fromScale(0.5, 0.48)\nresultFrame.AnchorPoint = Vector2.new(0.5, 0.5)\nresultFrame.BackgroundColor3 = Theme.Panel\nresultFrame.BackgroundTransparency = 0.17\nresultFrame.BorderSizePixel = 0\nresultFrame.Visible = false\nresultFrame.Parent = gui\nlocal resultLine = Instance.new(\"Frame\")\nresultLine.Size = UDim2.fromOffset(3, 182)\nresultLine.Position = UDim2.fromOffset(18, 16)\nresultLine.BackgroundColor3 = AMBER\nresultLine.BorderSizePixel = 0\nresultLine.Parent = resultFrame\nlocal resultTitle = txt(resultFrame, \"Finished\", \"OPERACAO CONCLUIDA\",\n    UDim2.fromOffset(38, 14), UDim2.fromOffset(318, 29), 13, GREEN, Enum.Font.GothamMedium)\nlocal resultGrade = txt(resultFrame, \"Grade\", \"CLASSE A\",\n    UDim2.fromOffset(38, 48), UDim2.fromOffset(318, 62), 36, WHITE, Enum.Font.GothamBold)\nlocal resultScore = txt(resultFrame, \"Score\", \"0000 PONTOS\",\n    UDim2.fromOffset(38, 112), UDim2.fromOffset(305, 29), 17, DIM, Theme.Font)\nlocal restartButton = Instance.new(\"TextButton\")\nrestartButton.Name = \"RestartButton\"\nrestartButton.Position = UDim2.fromOffset(38, 173)\nrestartButton.Size = UDim2.fromOffset(300, 54)\nrestartButton.BackgroundTransparency = 1\nrestartButton.BorderSizePixel = 0\nrestartButton.Font = Theme.Font\nrestartButton.Text = \"[ R ]  NOVA OPERACAO\"\nrestartButton.TextColor3 = WHITE\nrestartButton.TextSize = 16\nrestartButton.TextXAlignment = Enum.TextXAlignment.Left\nrestartButton.Parent = resultFrame\n\nlocal crouching = false\nlocal prone = false\nlocal completed = false\nlocal caught = 0\nlocal seconds = 0\nlocal instinct = false\n\nlocal function isHidden()\n    return player:GetAttribute(\"Posto17Hidden\") == true\nend\n\nlocal function refresh()\n    mission.Visible = player:GetAttribute(\"Posto17InTestRange\") ~= true and not completed\n    phase.Text = player:GetAttribute(\"Posto17Data\") and \"Voltar à extração\" or \"Acessar o terminal\"\n\n    local level = world:GetAttribute(\"AlertLevel\") or 0\n    if level >= 2 then\n        alert.Text = \"Alerta\"\n    elseif level == 1 then\n        alert.Text = \"Suspeita\"\n    else\n        alert.Text = \"\"\n    end\n    alert.TextColor3 = level >= 2 and RED or AMBER\n    alert.Visible = level > 0\n\n    local stones = player:GetAttribute(\"Posto17Stones\")\n    if type(stones) ~= \"number\" then stones = 3 end\n    local cameraOn = world:GetAttribute(\"CamerasOnline\") ~= false\n    local cameraSeconds = world:GetAttribute(\"CameraSeconds\") or 0\n    local powerOn = world:GetAttribute(\"PowerOnline\") ~= false\n    local powerSeconds = world:GetAttribute(\"PowerSeconds\") or 0\n    local indicators = {}\n    if instinct or stones < 3 then\n        indicators[#indicators + 1] = string.format(\"Pedras · %d\", stones)\n    end\n    if not cameraOn then\n        indicators[#indicators + 1] = string.format(\"Câmeras · %ds\", cameraSeconds)\n    end\n    if not powerOn then\n        indicators[#indicators + 1] = string.format(\"Escuro · %ds\", powerSeconds)\n    end\n    resources.Text = table.concat(indicators, \"  |  \")\n    resources.Visible = #indicators > 0\n\nend\n\n-- A articulacao de postura e replicada pelo servidor; cliente cuida apenas da camera.\n\nlocal function setCrouchCamera(enabled)\n    player.CameraMinZoomDistance = normalMinZoom\n    local character = player.Character\n    local hum = character and character:FindFirstChildOfClass(\"Humanoid\")\n    if hum then\n        -- O offset antigo deitado era +1.1: a camera subia como num pulo.\n        -- Agora acompanha o avatar para baixo, mantendo a cabeca visivel.\n        local cameraOffset = prone and Vector3.new(0.28, -1.1, 0)\n            or (enabled and Vector3.new(0.25, -0.62, 0)\n                or Vector3.new(0.6, 0.15, 0))\n        -- O controlador de camera aplica a transicao sem disputar tweens.\n        player:SetAttribute(\"P17CameraBaseOffset\", cameraOffset)\n    end\n    player:SetAttribute(\"P17CameraBaseFOV\", prone and 62 or (enabled and 65 or 68))\nend\n\nplayer:GetAttributeChangedSignal(\"Posto17Stance\"):Connect(function()\n    local st = player:GetAttribute(\"Posto17Stance\")\n    prone = st == \"PRONE\" or st == \"VENT\"\n    crouching = st == \"CROUCH\"\n    setCrouchCamera(crouching)\n    refresh()\nend)\n\nlocal instinctColor = Instance.new(\"ColorCorrectionEffect\")\ninstinctColor.Name = \"Posto17InstintoLocal\"\ninstinctColor.Saturation = 0\ninstinctColor.Contrast = 0\ninstinctColor.Brightness = 0\ninstinctColor.Parent = Lighting\n\nlocal function setInstinctColor(active)\n    TweenService:Create(instinctColor, TweenInfo.new(0.24,\n        Enum.EasingStyle.Sine), {\n        Saturation = active and -0.72 or 0,\n        Contrast = active and 0.09 or 0,\n        Brightness = active and -0.035 or 0,\n    }):Play()\nend\n\nlocal function setInstinct(active)\n    if instinct == active then return end\n    instinct = active\n    player:SetAttribute(\"Posto17Instinct\", active)\n    setInstinctColor(active)\n    refresh()\nend\n\nlocal function renderResults()\n    local grade = player:GetAttribute(\"Posto17Rank\") or \"?\"\n    local points = player:GetAttribute(\"Posto17Score\") or 0\n    resultGrade.Text = \"CLASSE \" .. tostring(grade)\n    resultGrade.TextColor3 = grade == \"S\" and AMBER or WHITE\n    resultScore.Text = tostring(points) .. \" PONTOS\"\n    resultFrame.Visible = true\nend\n\nlocal function onRestart(_, state)\n    if state == Enum.UserInputState.Begin and completed then\n        restartRemote:FireServer()\n        return Enum.ContextActionResult.Sink\n    end\n    return Enum.ContextActionResult.Pass\nend\n\nrestartButton.MouseButton1Click:Connect(function()\n    if completed then restartRemote:FireServer() end\nend)\n\nlocal function onCrouch(_, state)\n    if player:GetAttribute(\"Posto17InCover\") then\n        if state == Enum.UserInputState.Begin and player:GetAttribute(\"Posto17CoverHeight\") == \"HIGH\" then\n            crouchRemote:FireServer(player:GetAttribute(\"Posto17Stance\") ~= \"CROUCH\")\n        end\n        return Enum.ContextActionResult.Sink\n    end\n    if player:GetAttribute(\"Posto17Dragging\") then return Enum.ContextActionResult.Sink end\n    if completed or isHidden() or prone then return Enum.ContextActionResult.Pass end\n    if state == Enum.UserInputState.Begin then\n        crouching = true\n    elseif state == Enum.UserInputState.End\n        or state == Enum.UserInputState.Cancel then\n        crouching = false\n    else\n        return Enum.ContextActionResult.Pass\n    end\n    crouchRemote:FireServer(crouching)\n    setCrouchCamera(crouching)\n    refresh()\n    return Enum.ContextActionResult.Sink\nend\n\nlocal function onProne(_, inputState)\n    if player:GetAttribute(\"Posto17Dragging\") then return Enum.ContextActionResult.Sink end\n    if inputState ~= Enum.UserInputState.Begin then\n        return Enum.ContextActionResult.Pass\n    end\n    if completed or isHidden() or player:GetAttribute(\"Posto17Stance\") == \"VENT\" then return Enum.ContextActionResult.Pass end\n    prone = not prone\n    crouching = false\n    proneRemote:FireServer(prone)\n    setCrouchCamera(false)\n    refresh()\n    return Enum.ContextActionResult.Sink\nend\n\nlocal function onThrow(_, state)\n    if state ~= Enum.UserInputState.Begin then\n        return Enum.ContextActionResult.Pass\n    end\n    if completed or isHidden() or (player:GetAttribute(\"Posto17Stones\") or 0) <= 0 then\n        announce(\"SEM PEDRAS OU ACAO INDISPONIVEL\", AMBER)\n        return Enum.ContextActionResult.Sink\n    end\n    local root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n    if not root then return Enum.ContextActionResult.Pass end\n    local mouse = player:GetMouse()\n    local camera = workspace.CurrentCamera\n    local forward = camera and camera.CFrame.LookVector or root.CFrame.LookVector\n    local aim = root.Position + forward * 26\n    if mouse and mouse.Target then aim = mouse.Hit.Position end\n    stoneRemote:FireServer(aim)\n    return Enum.ContextActionResult.Sink\nend\n\nlocal function onHide(_, state)\n    if state ~= Enum.UserInputState.Begin then return Enum.ContextActionResult.Pass end\n    if not completed then hideRemote:FireServer() end\n    return Enum.ContextActionResult.Sink\nend\n\nlocal mobility = ReplicatedStorage:WaitForChild(\"Posto17Mobility\")\nContextActionService:BindAction(\"P17Correr\", function(_, input)\n    if input == Enum.UserInputState.Begin or input == Enum.UserInputState.End\n        or input == Enum.UserInputState.Cancel then\n        mobility:FireServer(\"SPRINT\", input == Enum.UserInputState.Begin)\n    end\n    return Enum.ContextActionResult.Pass\nend, false, Enum.KeyCode.LeftShift)\nContextActionService:BindAction(\"P17Caixa\", function(_, input)\n    if input == Enum.UserInputState.Begin then mobility:FireServer(\"BOX\") end\n    return Enum.ContextActionResult.Sink\nend, false, Enum.KeyCode.B)\n\nContextActionService:BindAction(\"P17Agachar\", onCrouch, false, Enum.KeyCode.C)\nContextActionService:BindAction(\"P17Deitar\", onProne, false, Enum.KeyCode.Z)\nContextActionService:BindAction(\"P17Pedra\", onThrow, false, Enum.KeyCode.G)\nContextActionService:BindAction(\"P17Esconder\", onHide, false, Enum.KeyCode.F)\nContextActionService:BindAction(\"P17Reiniciar\", onRestart, false, Enum.KeyCode.R)\n\nUserInputService.InputBegan:Connect(function(input, processed)\n    if not processed and (input.KeyCode == Enum.KeyCode.Q\n        or input.KeyCode == Enum.KeyCode.LeftAlt) then\n        setInstinct(true)\n    end\nend)\nUserInputService.InputEnded:Connect(function(input)\n    if input.KeyCode == Enum.KeyCode.Q or input.KeyCode == Enum.KeyCode.LeftAlt then\n        setInstinct(false)\n    end\nend)\n\n-- Teclas taticas pequenas para Android, sem sobrepor o minimapa quadrado.\nif UserInputService.TouchEnabled then\n    local actions = Instance.new(\"Frame\")\n    actions.Name = \"ControlesTaticos\"\n    actions.AnchorPoint = Vector2.new(1, 1)\n    actions.Position = UDim2.new(1, -22, 1, -209)\n    actions.Size = UDim2.fromOffset(216, 38)\n    actions.BackgroundTransparency = 1\n    actions.Parent = gui\n\n    local function touchKey(text, index)\n        local b = Instance.new(\"TextButton\")\n        b.Name = text\n        b.Position = UDim2.fromOffset((index-1)*73, 0)\n        b.Size = UDim2.fromOffset(68, 34)\n        b.BackgroundColor3 = Theme.Panel\n        b.BackgroundTransparency = 0.24\n        b.BorderSizePixel = 0\n        b.Text = text\n        b.TextColor3 = WHITE\n        b.Font = Theme.Font\n        b.TextSize = 12\n        b.Parent = actions\n        local corner = Instance.new(\"UICorner\")\n        corner.CornerRadius = UDim.new(0, 5)\n        corner.Parent = b\n        return b\n    end\n    local instinctButton = touchKey(\"INSTINTO\", 1)\n    local crouchButton = touchKey(\"AGACHAR\", 2)\n    local proneButton = touchKey(\"DEITAR\", 3)\n\n    instinctButton.InputBegan:Connect(function(input)\n        if input.UserInputType == Enum.UserInputType.Touch\n            or input.UserInputType == Enum.UserInputType.MouseButton1 then\n            setInstinct(true)\n        end\n    end)\n    instinctButton.InputEnded:Connect(function(input)\n        if input.UserInputType == Enum.UserInputType.Touch\n            or input.UserInputType == Enum.UserInputType.MouseButton1 then\n            setInstinct(false)\n        end\n    end)\n    crouchButton.MouseButton1Click:Connect(function()\n        if completed or isHidden() or player:GetAttribute(\"Posto17Stance\") == \"VENT\" then return end\n        if player:GetAttribute(\"Posto17InCover\") then\n            onCrouch(nil, Enum.UserInputState.Begin)\n            return\n        end\n        if prone then onProne(nil, Enum.UserInputState.Begin) end\n        crouching = not crouching\n        crouchRemote:FireServer(crouching)\n        setCrouchCamera(crouching)\n        refresh()\n    end)\n    proneButton.MouseButton1Click:Connect(function()\n        onProne(nil, Enum.UserInputState.Begin)\n    end)\nend\n\nstateRemote.OnClientEvent:Connect(function(kind, detail)\n    if kind == \"DETECTADO\" then\n        caught += 1\n        crouching = false\n        prone = false\n        setCrouchCamera(false)\n        announce(\"CAPTURADO  /  RETORNO A ENTRADA\", RED, 4.1)\n    elseif kind == \"DADOS\" then\n        announce(\"DADOS OBTIDOS  /  EXTRAIR\", GREEN)\n    elseif kind == \"VITÓRIA\" then\n        completed = true\n        crouching = false\n        prone = false\n        setCrouchCamera(false)\n        announce(\"EXTRACAO CONCLUIDA\", GREEN, 4.2)\n        renderResults()\n    elseif kind == \"ALERTA\" or kind == \"REFORCOS\"\n        or kind == \"SUSPEITA\" or kind == \"BUSCA\" then\n        -- Os simbolos ? e ! sobre os vigias substituem avisos invasivos.\n        -- O estado global continua no canto do HUD.\n    elseif kind == \"ESCONDIDO\" then\n        crouching = false\n        prone = false\n        setCrouchCamera(false)\n        announce(UserInputService.TouchEnabled and \"No abrigo\" or \"F · Sair do abrigo\", GREEN)\n    elseif kind == \"SAIU\" then\n        announce(\"ABRIGO DEIXADO\", WHITE, 1.8)\n    elseif kind == \"PEDRA\" then\n        announce(\"DISTRAÇÃO\", WHITE, 1.3)\n    elseif kind == \"SEM_DADOS\" then\n        announce(\"COLETE OS DADOS ANTES\", AMBER)\n    elseif kind == \"CAMERA\" then\n        announce(\"VIGILANCIA DETECTOU VOCE\", RED)\n    elseif kind == \"RELE\" then\n        announce(\"CAMERAS TEMPORARIAMENTE OFF\", GREEN)\n    elseif kind == \"RELE_COOLDOWN\" then\n        announce(\"RELE RECARREGANDO\", AMBER)\n    elseif kind == \"CAMERAS_ON\" then\n        announce(\"CAMERAS REATIVADAS\", RED)\n    elseif kind == \"DOSSIE\" then\n        announce(\"DOSSIE OBTIDO\", GREEN)\n    elseif kind == \"TERMINAL_CHECK\" then\n        announce(\"INSPECAO NO TERMINAL\", AMBER, 2.2)\n    elseif kind == \"RASTREIO_CANCELADO\" then\n        announce(\"RASTREIO CANCELADO\", GREEN, 1.8)\n    elseif kind == \"REINICIO\" then\n        completed = false\n        caught = 0\n        seconds = 0\n        crouching = false\n        prone = false\n        resultFrame.Visible = false\n        setCrouchCamera(false)\n        announce(\"OPERACAO INICIADA\", WHITE, 2)\n    else\n        announce(tostring(detail or kind), WHITE)\n    end\n    refresh()\nend)\n\nfor _, attribute in ipairs({\n    \"Posto17Stones\", \"Posto17Hidden\", \"Posto17Data\",\n    \"Posto17BonusIntel\", \"Posto17Sabotage\", \"Posto17Won\",\n    \"Posto17Rank\", \"Posto17Score\", \"Posto17InTestRange\",\n}) do\n    player:GetAttributeChangedSignal(attribute):Connect(refresh)\nend\nfor _, attribute in ipairs({\n    \"AlertLevel\", \"CamerasOnline\", \"CameraSeconds\",\n    \"PowerOnline\", \"PowerSeconds\",\n}) do\n    world:GetAttributeChangedSignal(attribute):Connect(refresh)\nend\nplayer:GetAttributeChangedSignal(\"Posto17Rank\"):Connect(function()\n    if completed then renderResults() end\nend)\nplayer:GetAttributeChangedSignal(\"Posto17Score\"):Connect(function()\n    if completed then renderResults() end\nend)\nplayer.CharacterAdded:Connect(function()\n    crouching = false\n    prone = false\n    crouchRemote:FireServer(false)\n    proneRemote:FireServer(false)\n    setInstinct(false)\n    refresh()\nend)\n\nrefresh()\ntask.spawn(function()\n    while gui.Parent do\n        task.wait(1)\n        if not completed then seconds += 1 end\n        refresh()\n    end\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Interacoes","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Interacoes (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- POSTO 17 | instinto branco + interacoes contextuais.\n-- Q segurado: contorno atraves de paredes em ate 8,4 metros (30 studs).\n-- Normal: contorno branco e tecla E somente no alcance da interacao.\n-- Prompts nativos seguem executando no servidor; so mudamos sua aparencia.\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal ProximityPromptService = game:GetService(\"ProximityPromptService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal GuiService = game:GetService(\"GuiService\")\n\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\", 30)\nif not world then return end\n\nlocal STUD_TO_METER = 0.28\nlocal INSTINCT_RADIUS = 30\nlocal COLOR = Theme.Highlight\nlocal instinct = false\nlocal tracked = {}\nlocal shown = {}\n\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Interacoes\"\ngui.ResetOnSpawn = false\ngui.IgnoreGuiInset = true\ngui.DisplayOrder = 12\ngui.Parent = player:WaitForChild(\"PlayerGui\")\n\n-- Instinto nao precisa de caixa na tela; o waypoint aparece com Q.\n\nlocal keyPrompt = Instance.new(\"TextButton\")\nkeyPrompt.Text = \"\"\nkeyPrompt.AutoButtonColor = false\nkeyPrompt.BackgroundTransparency = 1\nkeyPrompt.AnchorPoint = Vector2.new(0.5, 0.5)\nkeyPrompt.Name = \"BotaoInteragir\"\nkeyPrompt.Active = true\nkeyPrompt.Size = UDim2.fromOffset(158, 47)\nkeyPrompt.Visible = false\nkeyPrompt.Parent = gui\n\nlocal key = Instance.new(\"TextButton\")\nkey.Name = \"Tecla\"\nkey.Active = true\nkey.Size = UDim2.fromOffset(29, 29)\nkey.Position = UDim2.fromOffset(6, 3)\nkey.BackgroundColor3 = Theme.Panel\nkey.BackgroundTransparency = 0.84\nkey.BorderSizePixel = 0\nkey.TextColor3 = COLOR\nkey.Font = Enum.Font.GothamMedium\nkey.TextSize = 17\nkey.Text = \"E\"\nkey.Parent = keyPrompt\nif UserInputService.TouchEnabled then\n    key.Size = UDim2.fromOffset(44, 44)\n    keyPrompt.Size = UDim2.fromOffset(180, 60)\nend\n\nlocal corner = Instance.new(\"UICorner\")\ncorner.CornerRadius = UDim.new(0, 5)\ncorner.Parent = key\nlocal outline = Instance.new(\"UIStroke\")\noutline.Color = COLOR\noutline.Thickness = 1\noutline.Transparency = 0.48\noutline.Parent = key\n\nlocal actionText = Instance.new(\"TextLabel\")\nactionText.Name = \"Acao\"\nactionText.Position = UDim2.fromOffset(UserInputService.TouchEnabled and 58 or 42, 4)\nactionText.Size = UDim2.fromOffset(108, 27)\nactionText.BackgroundTransparency = 1\nactionText.TextColor3 = Theme.Text\nactionText.TextSize = 13\nactionText.TextStrokeTransparency = 0.52\nactionText.TextXAlignment = Enum.TextXAlignment.Left\nactionText.Font = Enum.Font.GothamMedium\nactionText.TextTruncate = Enum.TextTruncate.AtEnd\nactionText.Parent = keyPrompt\n\nlocal actionNames = {\n    [\"Coletar dados\"] = \"TERMINAL\",\n    [\"Solicitar extracao\"] = \"EXTRAIR\",\n    [\"Entrar no armario\"] = \"ESCONDER\",\n    [\"Copiar dossie\"] = \"DOSSIE\",\n    [\"Pegar pedras\"] = \"SUPRIMENTOS\",\n    [\"Cortar vigilancia\"] = \"SABOTAR\",\n}\n\n-- Pequena barra para mostrar interacoes que exigem segurar E.\nlocal progressTrack = Instance.new(\"Frame\")\nprogressTrack.Name = \"ProgressoFundo\"\nprogressTrack.Size = UDim2.fromOffset(138, 2)\nprogressTrack.Position = UDim2.fromOffset(7, UserInputService.TouchEnabled and 53 or 38)\nprogressTrack.BackgroundColor3 = Theme.Border\nprogressTrack.BorderSizePixel = 0\nprogressTrack.Visible = false\nprogressTrack.Parent = keyPrompt\n\nlocal progressFill = Instance.new(\"Frame\")\nprogressFill.Name = \"Progresso\"\nprogressFill.BackgroundColor3 = COLOR\nprogressFill.BorderSizePixel = 0\nprogressFill.Size = UDim2.fromScale(0, 1)\nprogressFill.Parent = progressTrack\n\nlocal holdStart = nil\nlocal holdDuration = 0\nlocal selected = nil\nlocal heldPrompt = nil\nlocal heldInput = nil\nlocal function beginInput(input)\n    if selected and (input.UserInputType == Enum.UserInputType.Touch\n        or input.UserInputType == Enum.UserInputType.MouseButton1) then\n        if heldPrompt then return end\n        heldInput = input\n        heldPrompt = selected\n        heldPrompt:InputHoldBegin()\n    end\nend\nlocal function endInput(input)\n    if heldPrompt and (input == heldInput or input.UserInputType == Enum.UserInputType.MouseButton1) then\n        if heldPrompt.Parent then heldPrompt:InputHoldEnd() end\n        heldPrompt = nil\n        heldInput = nil\n    end\nend\nkey.InputBegan:Connect(beginInput)\nkey.InputEnded:Connect(endInput)\nkeyPrompt.InputBegan:Connect(beginInput)\nkeyPrompt.InputEnded:Connect(endInput)\nUserInputService.InputEnded:Connect(endInput)\nUserInputService.WindowFocusReleased:Connect(function()\n    if heldPrompt then\n        if heldPrompt.Parent then heldPrompt:InputHoldEnd() end\n        heldPrompt, heldInput = nil, nil\n    end\nend)\nlocal function findPart(prox)\n    local parent = prox and prox.Parent\n    if parent and parent:IsA(\"Attachment\") then\n        parent = parent.Parent\n    end\n    if parent and parent:IsA(\"BasePart\") then return parent end\n    return nil\nend\n\nlocal function register(prox)\n    if tracked[prox] or not prox:IsA(\"ProximityPrompt\") then return end\n    if not prox:IsDescendantOf(world) then return end\n    local body = findPart(prox)\n    if not body then return end\n    -- Mantem o mecanismo nativo (HoldDuration / Activated) e so substitui UI.\n    prox.Style = Enum.ProximityPromptStyle.Custom\n    local highlight = body:FindFirstChild(\"InstintoBranco\")\n    if not highlight then\n    highlight = Instance.new(\"Highlight\")\n    highlight.Name = \"InstintoBranco\"\n    highlight.Adornee = body\n    highlight.FillColor = COLOR\n    highlight.OutlineColor = COLOR\n    highlight.FillTransparency = 0.75\n    highlight.OutlineTransparency = 0.06\n    highlight.DepthMode = Enum.HighlightDepthMode.Occluded\n    highlight.Enabled = false\n    highlight.Parent = body\n    end\n    tracked[prox] = {body = body, outline = highlight}\nend\n\nfor _, child in ipairs(world:GetDescendants()) do\n    if child:IsA(\"ProximityPrompt\") then register(child) end\nend\nworld.DescendantAdded:Connect(function(child)\n    if child:IsA(\"ProximityPrompt\") then register(child) end\nend)\n\nlocal function setInstinct(active)\n    instinct = active\n    -- O marcador de mundo e o highlight ja comunicam o instinto.\nend\nplayer:GetAttributeChangedSignal(\"Posto17Instinct\"):Connect(function()\n    setInstinct(player:GetAttribute(\"Posto17Instinct\") == true)\nend)\nUserInputService.InputBegan:Connect(function(input, consumed)\n    if consumed then return end\n    if input.KeyCode == Enum.KeyCode.Q or input.KeyCode == Enum.KeyCode.LeftAlt then\n        setInstinct(true)\n    end\nend)\nUserInputService.InputEnded:Connect(function(input)\n    if input.KeyCode == Enum.KeyCode.Q or input.KeyCode == Enum.KeyCode.LeftAlt then\n        setInstinct(false)\n    end\nend)\n\nProximityPromptService.PromptShown:Connect(function(prox)\n    if tracked[prox] then\n        prox.Style = Enum.ProximityPromptStyle.Custom\n        shown[prox] = true\n    end\nend)\nProximityPromptService.PromptHidden:Connect(function(prox)\n    shown[prox] = nil\n    if selected == prox then\n        selected = nil\n        keyPrompt.Visible = false\n    end\nend)\nProximityPromptService.PromptButtonHoldBegan:Connect(function(prox)\n    if prox == selected then\n        holdStart = os.clock()\n        holdDuration = math.max(prox.HoldDuration, 0.01)\n    end\nend)\nProximityPromptService.PromptButtonHoldEnded:Connect(function(prox)\n    if prox == selected then\n        holdStart = nil\n        progressFill.Size = UDim2.fromScale(0, 1)\n    end\nend)\n\nlocal promptRay = RaycastParams.new()\npromptRay.FilterType = Enum.RaycastFilterType.Exclude\npromptRay.RespectCanCollide = true\nlocal function update()\n    local character = player.Character\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    if not root then\n        keyPrompt.Visible = false\n        return\n    end\n\n    local best\n    local bestDistance = math.huge\n    local highlighted = {}\n    for _, item in pairs(tracked) do\n        if item.outline.Parent then item.outline.Enabled = false end\n    end\n    for prox, item in pairs(tracked) do\n        if not prox.Parent or not item.body.Parent then\n            if not item.body.Parent then item.outline:Destroy() end\n            tracked[prox] = nil\n            shown[prox] = nil\n        else\n            local distance = (item.body.Position - root.Position).Magnitude\n            local near = prox.Enabled and distance <= prox.MaxActivationDistance\n            local visible = prox.Enabled and (near or\n                (instinct and distance <= INSTINCT_RADIUS))\n            item.outline.Enabled = visible or highlighted[item.body] == true\n            if visible then highlighted[item.body] = true end\n            if visible then\n                item.outline.DepthMode = instinct and\n                    Enum.HighlightDepthMode.AlwaysOnTop or\n                    Enum.HighlightDepthMode.Occluded\n                item.outline.FillTransparency = near and 0.66 or 0.83\n                item.outline.OutlineTransparency = near and 0 or 0.12\n            end\n\n            -- PromptShown respeita alcance, visibilidade e disponibilidade;\n            -- o instinto nunca libera interacao de longe.\n            local nativeShown = near and shown[prox]\n            local fallback = near and not player:GetAttribute(\"Posto17Won\")\n                and not player:GetAttribute(\"Posto17Hidden\")\n            if fallback and prox.RequiresLineOfSight then\n                promptRay.FilterDescendantsInstances = {character, item.body}\n                fallback = workspace:Raycast(root.Position, item.body.Position-root.Position, promptRay) == nil\n            end\n            if (nativeShown or fallback) and distance < bestDistance then\n                bestDistance = distance\n                best = prox\n            end\n        end\n    end\n\n    if best ~= selected then\n        selected = best\n        holdStart = nil\n        progressFill.Size = UDim2.fromScale(0, 1)\n    end\n\n    if best then\n        local body = findPart(best)\n        keyPrompt.Visible = false\n        if body then\n            -- Acima do item, e nao na altura das costas do personagem\n            -- (especialmente em pads no chao, como a extracao).\n            local height = body.Size.Y <= 1 and 5.5\n                or math.min(body.Size.Y * 0.5 + 1.4, 5.5)\n            local camera = workspace.CurrentCamera\n            if camera then\n                local point, onScreen = camera:WorldToViewportPoint(body.Position + Vector3.new(0, height, 0))\n                local inset = GuiService:GetGuiInset()\n                local width, heightPixels = keyPrompt.Size.X.Offset, keyPrompt.Size.Y.Offset\n                local viewport = camera.ViewportSize\n                keyPrompt.Position = UDim2.fromOffset(\n                    math.clamp(point.X, width/2+8, math.max(width/2+8, viewport.X-width/2-8)),\n                    math.clamp(point.Y, inset.Y+heightPixels/2+8,\n                        math.max(inset.Y+heightPixels/2+8, viewport.Y-heightPixels/2-8)))\n                keyPrompt.Visible = onScreen and point.Z > 0\n            end\n        end\n        key.Text = best.KeyboardKeyCode == Enum.KeyCode.E\n            and \"E\" or best.KeyboardKeyCode.Name\n        actionText.Text = actionNames[best.ActionText]\n            or string.upper(best.ActionText)\n        progressTrack.Visible = best.HoldDuration > 0.05\n    else\n        keyPrompt.Visible = false\n    end\n\n    if best and holdStart then\n        local ratio = math.clamp((os.clock() - holdStart) / holdDuration, 0, 1)\n        progressFill.Size = UDim2.fromScale(ratio, 1)\n    end\nend\n\n-- Frequencia moderada: apenas sete objetos e sem renderizacao por frame.\ntask.spawn(function()\n    while gui.Parent do\n        update()\n        task.wait(0.08)\n    end\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Lanterna","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Lanterna (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Players = game:GetService(\"Players\")\nlocal CAS = game:GetService(\"ContextActionService\")\nlocal player = Players.LocalPlayer\nlocal event = game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Flashlight\")\nCAS:BindAction(\"P17Lanterna\", function(_, state)\n    if state == Enum.UserInputState.Begin then\n        event:FireServer(player:GetAttribute(\"Posto17Flashlight\") ~= true)\n    end\n    return Enum.ContextActionResult.Sink\nend, false, Enum.KeyCode.L)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/MenuInicial","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/MenuInicial (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal ReplicatedFirst = game:GetService(\"ReplicatedFirst\")\nlocal RunService = game:GetService(\"RunService\")\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal TweenService = game:GetService(\"TweenService\")\nlocal CAS = game:GetService(\"ContextActionService\")\nlocal shared = RS:WaitForChild(\"Posto17Shared\")\nlocal Theme = require(shared:WaitForChild(\"HudTheme\"))\nlocal Art = require(shared:WaitForChild(\"VisualIdentity\"))\nlocal P = Art.Palette\nlocal Motion = require(shared:WaitForChild(\"StoreMotion\"))\nlocal arsenalItems = require(shared:WaitForChild(\"ArsenalCatalog\"))\nlocal ArsenalBench = require(script.Parent.ArsenalBench)\nlocal store = RS:WaitForChild(\"Posto17StoreAssets\", 10)\nlocal player = Players.LocalPlayer\nlocal playerGui = player:WaitForChild(\"PlayerGui\")\nlocal appearance = RS:WaitForChild(\"Posto17Appearance\")\n\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Menu\"\ngui.ResetOnSpawn = false\ngui.DisplayOrder = 50\ngui.Parent = playerGui\nplayer:SetAttribute(\"P17InMainMenu\", true)\nlocal backdrop = Instance.new(\"ScreenGui\")\nbackdrop.Name = \"Posto17MenuCena\"\nbackdrop.ScreenInsets = Enum.ScreenInsets.None\nbackdrop.DisplayOrder = 49\nbackdrop.ResetOnSpawn = false\nbackdrop.Parent = playerGui\nlocal muted = {}\nlocal function hideHud(layer)\n    if not layer:IsA(\"ScreenGui\") or layer == gui or layer == backdrop or layer.Name == \"Posto17Opcoes\" then return end\n    if layer.Name:sub(1,7) ~= \"Posto17\" and layer.Name ~= \"TouchGui\" then return end\n    muted[layer] = layer.Enabled\n    layer.Enabled = false\nend\nlocal function showHud()\n    for layer, visible in pairs(muted) do\n        if layer.Parent then layer.Enabled = visible end\n    end\n    table.clear(muted)\nend\nlocal added = playerGui.ChildAdded:Connect(hideHud)\nfor _, layer in ipairs(playerGui:GetChildren()) do hideHud(layer) end\nlocal background = Instance.new(\"Frame\")\nbackground.Size = UDim2.fromScale(1, 1)\nbackground.BackgroundColor3 = Theme.Stroke\nbackground.Active = true\nbackground.Parent = backdrop\n\nlocal scene = Instance.new(\"ViewportFrame\")\nscene.Size = UDim2.fromScale(1, 1)\nscene.BackgroundColor3 = Theme.Panel\nscene.BorderSizePixel = 0\n-- A cena usa luz fria de oficina, nao a iluminacao generica de vitrine.\nscene.Ambient = Color3.fromRGB(123, 129, 134)\nscene.LightColor = Color3.fromRGB(239, 244, 242)\nscene.LightDirection = Vector3.new(-0.48, -1, -0.62)\nscene.Parent = background\nlocal stage = Instance.new(\"WorldModel\")\nstage.Parent = scene\nlocal camera = Instance.new(\"Camera\")\ncamera.FieldOfView = 43\ncamera.Parent = scene\nscene.CurrentCamera = camera\n\n-- Escala da sala: 3,5 studs por metro. Medidas finais em studs.\nlocal metre = 3.5\nlocal homePoint = Vector3.new(.2,0,1)\nlocal dressingPoint = Vector3.new(-8.85,0,1.36)\nlocal benchPoint = Vector3.new(.2,2.56,3.18)\nlocal doorway = Vector3.new(-17,0,5.05)\nlocal bedPoint = Vector3.new(8.25,0,2.1)\nlocal front = Vector3.new(.17,0,-1).Unit\nlocal iron = P.BrushedSteel\nlocal paint = P.Graphite\n\nlocal function prop(name, size, pos, color, material)\n    local p = Instance.new(\"Part\")\n    p.Name, p.Size, p.Color = name, size, color\n    p.Position, p.Anchored = pos, true\n    p.TopSurface, p.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth\n    p.Material = material or Enum.Material.SmoothPlastic\n    p.Parent = stage\nend\n\nprop(\"Piso\", Vector3.new(44,.24,26), Vector3.new(-5,-.12,2),\n    P.Concrete, Enum.Material.Concrete)\nprop(\"Parede\", Vector3.new(31.4,9.8,.35), Vector3.new(.75,4.9,5.25),\n    Theme.Panel, Enum.Material.Concrete)\nprop(\"Parede lateral\", Vector3.new(6,9.8,.35), Vector3.new(-21.7,4.9,5.25), Theme.Panel)\nprop(\"Viga da porta\", Vector3.new(4.1,2.8,.35), Vector3.new(-17,8.4,5.25), iron)\nprop(\"Fundo do corredor\", Vector3.new(8,9,.22), Vector3.new(-17,4.5,11), iron)\nprop(\"Piso do corredor\", Vector3.new(3.72,.024,5.6), Vector3.new(-17,.012,8.12),\n    Color3.fromRGB(65,63,66))\nfor _, side in ipairs({-1,1}) do\n    local x = doorway.X+side*1.75\n    prop(\"Luz da passagem\",Vector3.new(.075,5.9,.08),Vector3.new(x,3.2,5.84),\n        Color3.fromRGB(232,190,156),Enum.Material.Neon)\nend\nprop(\"Rodapé\", Vector3.new(31.4,.38,.19), Vector3.new(.75,.19,5.02), iron)\n-- Montagem realista: a faixa vermelha continua apenas na identificacao\n-- do setor. A parede possui uma guia utilitaria cinza, nao neon.\nprop(\"Guia tecnica\", Vector3.new(31.4,.09,.05),\n    Vector3.new(.75,4.05,5.02), P.BrushedSteel, Enum.Material.Metal)\nprop(\"Sinalizacao P17\", Vector3.new(.85,.13,.07),\n    Vector3.new(-9.0,4.05,4.98), P.AlertRed, Enum.Material.SmoothPlastic)\nfor i = -2, 3 do\n    local x = i * 4.7\n    prop(\"Painel acústico\", Vector3.new(4.58,4.6,.08), Vector3.new(x,6.72,5.03), paint)\n    prop(\"Junta do piso\", Vector3.new(.018,.006,21), Vector3.new(x,.003,-.8), iron)\nend\nprop(\"Bancada\", Vector3.new(5.3,.15,2.05), benchPoint-Vector3.yAxis*.075, iron)\nfor _, x in ipairs({-2.16,2.56}) do\n    prop(\"Suporte\", Vector3.new(.22,2.42,1.65), Vector3.new(x,1.21,3.18), paint)\nend\nprop(\"Gaveta\", Vector3.new(1.15,.76,1.42), Vector3.new(-1.69,1.99,3.18), iron)\nprop(\"Frente da bancada\", Vector3.new(5.24,.07,.045),\n    Vector3.new(.2,2.43,2.145),P.Armor,Enum.Material.Metal)\nprop(\"Bandeja\", Vector3.new(1.85,.07,.95), Vector3.new(.54,2.59,3.23), Theme.Stroke)\nprop(\"Caixa de ferramentas\", Vector3.new(1.05,.31,.62), Vector3.new(.54,2.77,3.23), iron)\nprop(\"Terminal\", Vector3.new(1,.62,.21), Vector3.new(-1.55,2.87,3.92), Theme.Stroke)\nprop(\"Tela\", Vector3.new(.86,.43,.04),\n    Vector3.new(-1.55,2.9,3.8), P.OperationalGreen, Enum.Material.SmoothPlastic)\n-- Efeito de manutencao: prateleira funcional, eletrodutos e recortes de\n-- parede. Objetos possuem escala plausivel e materiais consistentes.\nprop(\"Prateleira de ferramentas\",Vector3.new(4.2,.16,1.05),\n    Vector3.new(6.7,4.25,4.35),P.BrushedSteel,Enum.Material.Metal)\nfor _, x in ipairs({5.05,8.35}) do\n    prop(\"Suporte prateleira\",Vector3.new(.19,2.8,.25),\n        Vector3.new(x,2.83,4.7),P.Armor,Enum.Material.Metal)\nend\nfor i=0,3 do\n    prop(\"Caixa de mantimentos\",Vector3.new(.65,.56,.73),\n        Vector3.new(5.25+i*.88,4.59,4.35),\n        i==3 and P.Canvas or P.Armor,Enum.Material.Metal)\nend\nfor _, y in ipairs({5.8,6.12}) do\n    prop(\"Eletroduto\",Vector3.new(9,.10,.10),\n        Vector3.new(5.8,y,4.79),P.Graphite,Enum.Material.Metal)\nend\nfor _, x in ipairs({-10.2,-8.6,-7.0}) do\n    prop(\"Placa veneziana\",Vector3.new(1.25,2.15,.13),\n        Vector3.new(x,6.1,4.84),P.Armor,Enum.Material.Metal)\nend\nfor _, x in ipairs({-16.9,-10.1,.1,8.1}) do\n    prop(\"Trilho de luz\", Vector3.new(2.9,.17,.35), Vector3.new(x,7.72,4.89), iron)\n    prop(\"Luz de serviço\", Vector3.new(2.64,.045,.08), Vector3.new(x,7.63,4.76),\n        P.LightCold,Enum.Material.Neon)\nend\n\nlocal shade = Instance.new(\"Frame\")\nshade.BackgroundColor3 = Theme.Stroke\nshade.Size = UDim2.fromScale(1, 1)\nshade.BorderSizePixel = 0\nshade.Parent = background\nlocal fade = Instance.new(\"UIGradient\")\nfade.Transparency = NumberSequence.new({\n    NumberSequenceKeypoint.new(0, 0.02), NumberSequenceKeypoint.new(.40,.17),\n    NumberSequenceKeypoint.new(.72,.89), NumberSequenceKeypoint.new(1,1),\n})\nfade.Parent = shade\n\nlocal column = Instance.new(\"Frame\")\ncolumn.BackgroundTransparency = 1\ncolumn.Size = UDim2.fromOffset(238, 295)\ncolumn.Position = UDim2.new(.079, 0, .5, -145)\ncolumn.Parent = gui\nlocal stripe = Instance.new(\"Frame\")\nstripe.BackgroundColor3 = Theme.Brand\nstripe.BorderSizePixel = 0\nstripe.Position = UDim2.fromOffset(0, 13)\nstripe.Size = UDim2.fromOffset(52, 3)\nstripe.Parent = column\n\nlocal function text(class, caption, y, size, height)\n    local control = Instance.new(class)\n    control.Size = UDim2.new(1, 0, 0, height)\n    control.Position = UDim2.fromOffset(0, y)\n    control.Text = caption\n    control.TextColor3 = Theme.Text\n    control.TextXAlignment = Enum.TextXAlignment.Left\n    control.TextSize = size\n    control.Font = Theme.Font\n    control.BackgroundTransparency = 1\n    control.BorderSizePixel = 0\n    control.Parent = column\n    return control\nend\nlocal wordmark = 'POSTO <font color=\"#B95B57\">17</font>'\nlocal serial = text(\"TextLabel\", \"P17  /  OPERACOES RESERVADAS\", 0, 10, 19)\nserial.TextColor3 = Theme.Muted\nserial.Font = Theme.TechnicalFont\nlocal title = text(\"TextLabel\", wordmark, 20, 49, 61)\ntitle.Font = Enum.Font.GothamBlack\ntitle.RichText = true\n\nlocal views = {\n    Home = CFrame.lookAt(Vector3.new(4.3,4.9,-11.5),Vector3.new(4.4,3.0,2.8)),\n    Custom = CFrame.lookAt(Vector3.new(-7.5,4.2,-7.15),Vector3.new(-7.6,3.1,2.2)),\n    Bed = CFrame.lookAt(Vector3.new(4.25,6,-5.85),Vector3.new(7.26,1.9,1.95)),\n    Arsenal = CFrame.lookAt(Vector3.new(1.25,5.1,.42),\n        Vector3.new(.63,2.72,3.22)),\n    Exit = CFrame.lookAt(Vector3.new(-11,4.55,-5.55),Vector3.new(-16.8,3.0,4.3)),\n    Settings = CFrame.lookAt(Vector3.new(4.0,4.8,-8.4),Vector3.new(2.38,2.8,2.9)),\n}\ncamera.CFrame = views.Home\nlocal cameraTween\nlocal function focus(mode)\n    if cameraTween then cameraTween:Cancel() end\n    cameraTween = TweenService:Create(camera,TweenInfo.new(.52,Enum.EasingStyle.Quint),{CFrame=views[mode]})\n    cameraTween:Play()\nend\n\nlocal preview, previewRig, exitDoor, stride\nlocal sceneBusy, arsenalOpen = false, false\nlocal avatarPoint, avatarFacing = homePoint, front\nlocal function placeAvatar(point, facing, clip, t, floor, blend, bedContact)\n    avatarPoint, avatarFacing = point, facing\n    if not previewRig then return end\n    local position = point + Vector3.yAxis * previewRig.lift\n    Motion.apply(previewRig,CFrame.lookAt(position,position+facing),clip,t or 0,floor,blend,bedContact)\nend\n\nlocal function putStoreModel(name, point, dimensions)\n    local model = store and store:FindFirstChild(name)\n    if not model or not model:IsA(\"Model\") then return end\n    local clone = model:Clone()\n    clone:PivotTo(CFrame.identity)\n    local box, size = clone:GetBoundingBox()\n    if math.min(size.X,size.Y,size.Z) < .01 then clone:Destroy(); return end\n    local scale = dimensions / size\n    for _, item in ipairs(clone:GetDescendants()) do\n        if item:IsA(\"BasePart\") then\n            local cf = item.CFrame\n            local function along(axis) return (axis * scale).Magnitude end\n            item.Size *= Vector3.new(along(cf.RightVector),along(cf.UpVector),along(cf.LookVector))\n            item.CFrame = cf.Rotation + (cf.Position-box.Position)*scale + point\n                + Vector3.yAxis*(dimensions.Y*.5)\n            item.TopSurface, item.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth\n            if name == \"Armario\" or name == \"Porta\" or name == \"Mochila\" then\n                if item:IsA(\"MeshPart\") then item.TextureID = \"\" end\n                item.Color = item.Color:Lerp(iron,.79)\n                if name == \"Porta\" then\n                    local panel = item.Name\n                    if panel == \"Top\" then\n                        item.Size = Vector3.new(dimensions.X,.4,dimensions.Z)\n                        item.Position = point+Vector3.yAxis*(dimensions.Y+.2)\n                    elseif panel == \"Bottom\" then\n                        item.Size = Vector3.new(dimensions.X,.10,dimensions.Z)\n                        item.Position = point-Vector3.yAxis*.05\n                    elseif panel == \"DoorTop\" or panel == \"DoorBottom\" then\n                        local upper = panel == \"DoorTop\"\n                        item.Size = Vector3.new(dimensions.X*.84,dimensions.Y*.5,dimensions.Z*.33)\n                        item.Position = point+Vector3.yAxis*(dimensions.Y*(upper and .75 or .25))\n                    end\n                end\n            elseif name == \"Cama\" and item:IsA(\"Seat\") then\n                item.Color = Theme.Brand\n            end\n        elseif name == \"Armario\" or name == \"Porta\" or name == \"Mochila\" then\n            if item:IsA(\"SurfaceAppearance\") or item:IsA(\"Decal\") or item:IsA(\"Texture\") then\n                item:Destroy()\n            elseif item:IsA(\"SpecialMesh\") then\n                item.TextureId = \"\"\n            end\n        end\n    end\n    clone.PrimaryPart = nil\n    clone.WorldPivot = CFrame.new(point+Vector3.yAxis*(dimensions.Y*.5))\n    clone.Parent = stage\n    return clone\nend\n\nlocal function getClip(groups)\n    for _, group in ipairs(groups) do\n        local folder = store and store:FindFirstChild(group)\n        if folder then\n            for _, item in ipairs(folder:GetChildren()) do\n                local clip = Motion.read(item)\n                if clip then return clip end\n            end\n        end\n    end\nend\n\nlocal walk = Motion.read(shared:WaitForChild(\"StoreWalk\"))\nlocal function step(duration, update)\n    local start = os.clock()\n    repeat\n        local elapsed = math.min(os.clock()-start,duration)\n        update(elapsed/duration,elapsed)\n        if elapsed >= duration then break end\n        RunService.RenderStepped:Wait()\n    until not gui.Enabled\nend\nlocal function ease(value)\n    local x = math.clamp(value,0,1)\n    return x*x*(3-2*x)\nend\n\nlocal function walkTo(destination, finalFacing, carry)\n    local start, startFacing = avatarPoint, avatarFacing\n    local delta = destination-start\n    local distance = delta.Magnitude\n    if distance < .01 then return end\n    local direction = delta.Unit\n    local heading = math.atan2(direction.X,direction.Z)\n    local initial = math.atan2(startFacing.X,startFacing.Z)\n    local finish = finalFacing and math.atan2(finalFacing.X,finalFacing.Z) or heading\n    local turnIn = (initial-heading+math.pi)%(2*math.pi)-math.pi\n    local turnOut = (finish-heading+math.pi)%(2*math.pi)-math.pi\n    local duration = math.max(.48,distance/3.15+.23)\n    step(duration,function(alpha)\n        -- Acelera e freia sem um salto de velocidade no primeiro ou último frame.\n        local progress = alpha - math.sin(alpha*2*math.pi)*.115\n        local travelled = distance*progress\n        local arrive = ease((travelled-distance+.6)/.6)\n        local depart = ease(travelled/.54)\n        local yaw = heading+turnIn*(1-depart)+turnOut*arrive\n        local facing = Vector3.new(math.sin(yaw),0,math.cos(yaw))\n        local t = stride and Motion.walkTime(stride,travelled)\n            or walk and (travelled/3.3)%walk.duration or 0\n        local poseBlend = math.max(1-depart,arrive)\n        placeAvatar(start:Lerp(destination,progress),facing,walk,t,0,poseBlend)\n        if carry and previewRig then\n            carry:PivotTo(previewRig.root.CFrame * CFrame.new(0,.55,.67))\n        end\n    end)\n    placeAvatar(destination, finalFacing or direction, nil, 0, 0)\nend\n\nlocal refreshPending = false\nlocal function refreshAvatar()\n    if not gui.Enabled or sceneBusy then return end\n    local character = player.Character\n    if not character or not character:GetAttribute(\"Posto17Protagonista\") then return end\n    local archivable = character.Archivable\n    character.Archivable = true\n    local copy = character:Clone()\n    character.Archivable = archivable\n    if not copy then return end\n    for _, item in ipairs(copy:GetDescendants()) do\n        if item:IsA(\"BaseScript\") or item:IsA(\"Sound\") or item:IsA(\"ForceField\") then\n            item:Destroy()\n        elseif item:IsA(\"BasePart\") then\n            item.Anchored = true\n        elseif item:IsA(\"Humanoid\") then\n            item.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None\n        end\n    end\n    local _, original = copy:GetBoundingBox()\n    local scale = 1.75*metre/math.max(.01,original.Y)\n    copy:ScaleTo(copy:GetScale()*scale)\n    local bounds,size = copy:GetBoundingBox()\n    local pivot = copy:GetPivot()\n    local floor = bounds.Position.Y - size.Y/2\n    copy:PivotTo(CFrame.new(0,pivot.Position.Y-floor,0))\n    if preview then preview:Destroy() end\n    preview = copy\n    if not arsenalOpen then copy.Parent = stage end\n    previewRig = Motion.bind(copy,scale)\n    stride = previewRig and Motion.measureWalk(previewRig,walk)\n    placeAvatar(avatarPoint, avatarFacing, nil, 0, 0)\nend\nlocal function watch(character)\n    local function queueRefresh()\n        if refreshPending or not gui.Enabled then return end\n        refreshPending = true\n        task.delay(0.3, function()\n            refreshPending = false\n            refreshAvatar()\n        end)\n    end\n    character.DescendantAdded:Connect(function(item)\n        if item:IsA(\"BasePart\") then queueRefresh() end\n    end)\n    task.delay(1, queueRefresh)\n    task.delay(2.5, queueRefresh)\n    character:GetAttributeChangedSignal(\"Posto17Protagonista\"):Connect(function() task.delay(0.15, refreshAvatar) end)\n    character:GetAttributeChangedSignal(\"P17LookRevision\"):Connect(function() task.delay(0.12, refreshAvatar) end)\n    refreshAvatar()\nend\nplayer.CharacterAdded:Connect(watch)\nif player.Character then watch(player.Character) end\n\nlocal function action(name, y, callback, isPrimary)\n    local button = text(\"TextButton\", name, y, 16, 44)\n    button.Selectable = true\n    button.Activated:Connect(callback)\n    if isPrimary then\n        button.BackgroundColor3 = Theme.Surface\n        button.BackgroundTransparency = .46\n        button.Font = Enum.Font.GothamBold\n        local keyline = Instance.new(\"UIStroke\")\n        keyline.ApplyStrokeMode = Enum.ApplyStrokeMode.Border\n        keyline.Color = Theme.Border\n        keyline.Transparency = .48\n        keyline.Thickness = 1\n        keyline.Parent = button\n        local mark = Instance.new(\"Frame\")\n        mark.Name = \"IndicadorDeAcao\"\n        mark.Size = UDim2.fromOffset(3,24)\n        mark.Position = UDim2.fromOffset(0,10)\n        mark.BorderSizePixel = 0\n        mark.BackgroundColor3 = Theme.Brand\n        mark.Parent = button\n    end\n    local inset = Instance.new(\"UIPadding\")\n    inset.PaddingLeft = UDim.new(0,12)\n    inset.Parent = button\n    return button\nend\n\nlocal open, playing = true, false\nlocal home = {}\nlocal custom, arsenal = {}, {}\nlocal selected = {style=1, tone=2, face=1}\nlocal categories = {\n    {\"Modelo\",\"style\",{\"Masculino\",\"Feminino\"}},\n    {\"Tom de pele\",\"tone\",{\"Claro\",\"Médio\",\"Escuro\",\"Retinto\"}},\n    {\"Rosto\",\"face\",{\"Neutro\",\"Sério\",\"Sorriso\"}},\n}\n\nlocal selectedItem = arsenalItems[1]\nlocal selectedName, selectedState, selectedAction\nlocal bench\nlocal function updateArsenal(animate)\n    local item = selectedItem\n    local enabled = player:GetAttribute(item.attribute) ~= false\n    selectedName.Text = item.label\n    selectedState.Text = (enabled and item.on or item.off) .. \"\\n\" .. item.description\n    selectedAction.Text = enabled and item.disable or item.enable\n    bench:update(item.id,player:GetAttribute(\"P17LoadoutSuppressor\") ~= false,animate)\nend\nbench = ArsenalBench.new(stage,background,camera,store,Theme,arsenalItems,function(item)\n    selectedItem = item\n    updateArsenal(false)\nend)\n\nlocal function hideActions()\n    for _, item in ipairs(home) do item.Visible = false end\n    for _, item in ipairs(custom) do item.Visible = false end\n    for _, item in ipairs(arsenal) do item.Visible = false end\n    title.Visible, stripe.Visible = false, false\n    shade.BackgroundTransparency = .82\nend\nlocal function show(mode)\n    title.Visible, stripe.Visible = true, true\n    arsenalOpen = mode == \"Arsenal\"\n    -- Bancada deve estar VISIVEL: nao cobrir o equipamento com o gradiente.\n    shade.BackgroundTransparency = arsenalOpen and .58 or 0\n    bench:setOpen(arsenalOpen)\n    if preview then\n        if arsenalOpen then preview.Parent = nil else preview.Parent = stage end\n    end\n    if arsenalOpen then updateArsenal(false) end\n    for _, item in ipairs(home) do item.Visible = mode == \"Home\" end\n    for _, item in ipairs(custom) do item.Visible = mode == \"Custom\" end\n    for _, item in ipairs(arsenal) do item.Visible = mode == \"Arsenal\" end\n    title.Text = mode == \"Custom\" and \"PERSONALIZAR\" or mode == \"Arsenal\" and \"ARSENAL\" or wordmark\n    title.TextSize = mode == \"Home\" and 49 or 27\n    focus(mode)\nend\n\nhome[1] = action(\"Jogar\", 99, function()\n    if playing then return end\n    playing = true\n    sceneBusy = true\n    hideActions()\n    local backpack = putStoreModel(\"Mochila\",Vector3.new(1.53,2.56,3.37),Vector3.new(1.18,1.45,.72))\n    local clip = getClip({\"Pegar\",\"PegarAlternativa\",\"PegarObjeto\"})\n    if clip and backpack then\n        focus(\"Settings\")\n        walkTo(Vector3.new(.37,0,1.49),Vector3.zAxis)\n        local equipment = stage:FindFirstChild(\"Caixa de ferramentas\")\n        local equipmentStart = equipment and equipment.Position\n        local bagPoint = backpack:GetPivot().Position\n        step(clip.duration,function(alpha,elapsed)\n            local poseBlend = 1-ease(math.min(alpha,1-alpha)/.17)\n            placeAvatar(avatarPoint,Vector3.zAxis,clip,elapsed,0,poseBlend)\n            if equipment and preview then\n                local hand = preview:FindFirstChild(\"RightHand\")\n                if hand and alpha > .30 and alpha < .66 then\n                    equipment.Position = hand.Position\n                elseif alpha >= .66 then\n                    equipment.Position = bagPoint\n                    equipment.Transparency = 1\n                else equipment.Position = equipmentStart end\n            end\n        end)\n    end\n    focus(\"Exit\")\n    local approach = Vector3.new(doorway.X,0,1.4)\n    walkTo(approach,Vector3.zAxis,backpack)\n    if exitDoor then\n        for _, name in ipairs({\"DoorTop\",\"DoorBottom\",\"Center1\",\"Center2\"}) do\n            local panel = exitDoor:FindFirstChild(name,true)\n            if panel and panel:IsA(\"BasePart\") then\n                local shift = name == \"DoorBottom\" and -3.55 or 3.55\n                TweenService:Create(panel,TweenInfo.new(.52),{Position=panel.Position+Vector3.yAxis*shift}):Play()\n            end\n        end\n    end\n    walkTo(doorway+Vector3.zAxis*3.25,Vector3.zAxis,backpack)\n    appearance:FireServer(\"PLAY\")\n    open = false\n    gui.Enabled = false\n    backdrop.Enabled = false\n    added:Disconnect()\n    showHud()\n    player:SetAttribute(\"P17InMainMenu\", false)\n    if preview then preview:Destroy(); preview = nil end\n    CAS:UnbindAction(\"P17MenuMovement\")\nend, true)\nhome[2] = action(\"Personalizar\", 152, function()\n    if sceneBusy then return end\n    sceneBusy = true\n    hideActions()\n    focus(\"Custom\")\n    walkTo(dressingPoint,front)\n    sceneBusy = false\n    show(\"Custom\")\nend)\nhome[3] = action(\"Arsenal\", 195, function() show(\"Arsenal\") end)\nhome[4] = action(\"Configurações\", 237, function()\n    focus(\"Settings\")\n    player:SetAttribute(\"P17OptionsOpen\", true)\nend)\nselectedName = text(\"TextLabel\",\"\",82,21,32)\nselectedName.Font = Enum.Font.GothamBold\nselectedState = text(\"TextLabel\",\"\",112,13,45)\nselectedState.TextColor3 = Theme.Muted\nselectedState.TextWrapped = true\nselectedAction = action(\"\",165,function()\n    local item = selectedItem\n    appearance:FireServer(\"LOADOUT\",item.id,player:GetAttribute(item.attribute) == false)\nend,true)\narsenal[1],arsenal[2],arsenal[3] = selectedName,selectedState,selectedAction\narsenal[4] = action(\"‹  Voltar\",220,function() show(\"Home\") end)\nfor _, item in ipairs(arsenalItems) do\n    player:GetAttributeChangedSignal(item.attribute):Connect(function()\n        if arsenalOpen then updateArsenal(item.id == \"Suppressor\") end\n    end)\nend\nfor i, category in ipairs(categories) do\n    local caption, key, values = category[1], category[2], category[3]\n    local control\n    local function update() control.Text = caption .. \"  ·  \" .. values[selected[key]] .. \"  ›\" end\n    control = action(\"\", 79+(i-1)*42, function()\n        selected[key] = selected[key] % #values + 1\n        update()\n        appearance:FireServer(\"LOOK\", selected.style, selected.tone, selected.face)\n    end)\n    custom[i] = control\n    update()\nend\ncustom[4] = action(\"‹  Voltar\", 211, function()\n    if sceneBusy then return end\n    sceneBusy = true\n    hideActions()\n    focus(\"Home\")\n    walkTo(homePoint,front)\n    sceneBusy = false\n    show(\"Home\")\nend)\nplayer:GetAttributeChangedSignal(\"P17OptionsOpen\"):Connect(function()\n    if open and not player:GetAttribute(\"P17OptionsOpen\") then focus(\"Home\") end\nend)\nCAS:BindActionAtPriority(\"P17MenuMovement\", function() return Enum.ContextActionResult.Sink end, false, 3000,\n    Enum.PlayerActions.CharacterForward, Enum.PlayerActions.CharacterBackward,\n    Enum.PlayerActions.CharacterLeft, Enum.PlayerActions.CharacterRight, Enum.PlayerActions.CharacterJump)\nhideActions()\ntask.spawn(function()\n    if not game:IsLoaded() then game.Loaded:Wait() end\n    local starts = os.clock()\n    local wake\n    repeat\n        task.wait(.14)\n        wake = getClip({\"Acordar\",\"AcordarAlternativa\"})\n    until (previewRig and wake) or os.clock()-starts >= 5 or not gui.Enabled\n    if not gui.Enabled then return end\n    sceneBusy = true\n    local bed = putStoreModel(\"Cama\",bedPoint,Vector3.new(3.55,2.5,7.12))\n    putStoreModel(\"Armario\",Vector3.new(-11,0,4.05),Vector3.new(metre,2*metre,1.75))\n    exitDoor = putStoreModel(\"Porta\",doorway,Vector3.new(4.5,2*metre,1.12))\n    ReplicatedFirst:RemoveDefaultLoadingScreen()\n    if wake and bed and previewRig then\n        camera.CFrame = views.Bed\n        shade.Visible = false\n        local box,size = bed:GetBoundingBox()\n        local mattress = bed:FindFirstChildWhichIsA(\"Seat\",true)\n        local cushion = mattress and mattress.Position or box.Position\n        local surface = mattress and (cushion.Y+mattress.Size.Y/2) or box.Position.Y\n        local upper = preview:FindFirstChild(\"UpperTorso\")\n        local hips = preview:FindFirstChild(\"LowerTorso\")\n        local head = preview:FindFirstChild(\"Head\")\n        local feet = previewRig.feet\n        local facing = -Vector3.xAxis\n        local edge = box.Position.X-size.X*.5\n        local landing = Vector3.new(edge-1.2,0,cushion.Z-.25)\n        local contact = {parts={upper,hips},height=surface,floorWeight=0}\n\n        placeAvatar(Vector3.zero,facing,wake,0,0,nil,contact)\n        local footCenter = (feet[1].Position+feet[2].Position)*.5\n        local bodyAxis = head.Position-footCenter\n        local pillowOffset = Vector3.zero\n        for _, part in ipairs(bed:GetDescendants()) do\n            if part:IsA(\"BasePart\") and part.BrickColor.Number == 1 and part.Position.Y > surface then\n                pillowOffset += part.Position-cushion\n            end\n        end\n        local yaw = math.atan2(pillowOffset.X,pillowOffset.Z) - math.atan2(bodyAxis.X,bodyAxis.Z)\n        local lyingFacing = CFrame.Angles(0,yaw,0):VectorToWorldSpace(facing)\n        placeAvatar(Vector3.zero,lyingFacing,wake,0,0,nil,contact)\n        footCenter = (feet[1].Position+feet[2].Position)*.5\n        local center = (head.Position+footCenter)*.5\n        local towardPillow = math.sign(pillowOffset.Z) * .35\n        local startOnBed = Vector3.new(cushion.X-center.X,0,cushion.Z+towardPillow-center.Z)\n        placeAvatar(startOnBed,lyingFacing,wake,0,0,nil,contact)\n        task.wait(1.15)\n        local duration = math.clamp(wake.duration,2.8,4.5)\n        step(duration,function(alpha)\n            local slide = ease((alpha-.21)/.43)\n            local heading = math.atan2(lyingFacing.X,lyingFacing.Z)\n            local angle = (math.atan2(facing.X,facing.Z)-heading+math.pi)%(2*math.pi)-math.pi\n            local turn = CFrame.Angles(0,angle*ease((alpha-.18)/.37),0):VectorToWorldSpace(lyingFacing)\n            contact.floorWeight = ease((alpha-.34)/.31)\n            local blend = ease((alpha-.74)/.26)\n            placeAvatar(startOnBed:Lerp(landing,slide),turn,wake,alpha*wake.duration,0,blend,contact)\n        end)\n        placeAvatar(landing,facing,nil,0,0)\n        task.wait(.28)\n        focus(\"Home\")\n        walkTo(homePoint,front)\n    end\n    shade.Visible = true\n    sceneBusy = false\n    show(\"Home\")\nend)\ntask.delay(0.9, function()\n    if open then appearance:FireServer(\"LOOK\", selected.style, selected.tone, selected.face) end\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/MiniMapa","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/MiniMapa (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- POSTO 17 // minimapa quadrado minimo v2.\n-- Mesmo lugar (canto inferior direito), mais transparente e sem dashboard.\n-- Os marcadores de objetivos so aparecem a curta distancia.\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\", 30)\nif not world then return end\n\nlocal MAP_W, MAP_H = 112, 112\nlocal SCALE = MAP_W / 110\nlocal MAP_X_MIN, MAP_Z_MIN = -55, -55\nlocal FOV_HALF = math.rad(30)\nlocal SLICE_COUNT = 12\nlocal REFRESH = 0.32\nlocal DISCOVERY_RANGE = 30\n\nlocal WHITE = Theme.Text\nlocal RED = Theme.Danger\nlocal GOLD = Theme.Caution\nlocal GREEN = Theme.Success\n\nlocal function project(p)\n    return (p.X - MAP_X_MIN) * SCALE, (p.Z - MAP_Z_MIN) * SCALE\nend\n\nlocal function frame(name, parent, color, transparency)\n    local f = Instance.new(\"Frame\")\n    f.Name = name\n    f.BackgroundColor3 = color\n    f.BackgroundTransparency = transparency or 0\n    f.BorderSizePixel = 0\n    f.Parent = parent\n    return f\nend\n\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Radar\"\ngui.IgnoreGuiInset = false\ngui.ResetOnSpawn = false\ngui.DisplayOrder = 5\ngui.Parent = player:WaitForChild(\"PlayerGui\")\n\n\nlocal panel = frame(\"RadarPanel\", gui, Theme.Surface, 0.65)\npanel.AnchorPoint = Vector2.new(1, 1)\npanel.Position = UDim2.new(1, -12, 1, -12)\npanel.Size = UDim2.fromOffset(MAP_W, MAP_H)\nlocal outline = Instance.new(\"UIStroke\")\noutline.Color = Theme.Muted\noutline.Thickness = 0.8\noutline.Transparency = 0.72\noutline.Parent = panel\n\nlocal map = frame(\"PlantaBaixa\", panel, Theme.Surface, 0.74)\nmap.Size = UDim2.fromOffset(MAP_W, MAP_H)\nmap.ClipsDescendants = true\n\n-- Soliton: durante a procura coordenada, o radar nao transmite dados.\n-- Nenhum marcador pode ser visto atras deste painel.\nlocal jam = frame(\"RadarBloqueado\", panel, Theme.Panel, 0.07)\njam.Size = UDim2.fromScale(1, 1)\njam.ZIndex = 15\njam.Visible = false\n\nlocal jamTitle = Instance.new(\"TextLabel\")\njamTitle.Name = \"SinalInterrompido\"\njamTitle.Size = UDim2.new(1, -14, 0, 30)\njamTitle.Position = UDim2.fromOffset(7, 41)\njamTitle.Text = \"Sem sinal\"\njamTitle.BackgroundTransparency = 1\njamTitle.TextColor3 = Theme.Danger\njamTitle.Font = Theme.Font\njamTitle.TextSize = 13\njamTitle.ZIndex = 16\njamTitle.Parent = jam\n\nlocal function refreshRadarLock()\n    local blocked = player:GetAttribute(\"Posto17InTestRange\") ~= true\n        and world:GetAttribute(\"RadarJammed\") == true\n    jam.Visible = blocked\n    map.Visible = not blocked\n    panel.BackgroundColor3 = blocked\n        and Theme.Surface\n        or Theme.Surface\nend\nworld:GetAttributeChangedSignal(\"RadarJammed\"):Connect(refreshRadarLock)\nplayer:GetAttributeChangedSignal(\"Posto17InTestRange\"):Connect(refreshRadarLock)\nrefreshRadarLock()\nlocal function showRadar()\n    gui.Enabled = not player:GetAttribute(\"P17Reviewing\") and not player:GetAttribute(\"Posto17Won\")\nend\nfor _, attribute in ipairs({\"Posto17InTestRange\", \"P17Reviewing\", \"Posto17Won\"}) do\n    player:GetAttributeChangedSignal(attribute):Connect(showRadar)\nend\nshowRadar()\n\nlocal function marker(name, color, diameter)\n    local p = frame(name, map, color, 0)\n    p.Size = UDim2.fromOffset(diameter, diameter)\n    p.ZIndex = 6\n    p.AnchorPoint = Vector2.new(0.5, 0.5)\n    local round = Instance.new(\"UICorner\")\n    round.CornerRadius = UDim.new(1, 0)\n    round.Parent = p\n    return p\nend\n\nlocal objectiveMarkers = {}\nlocal shadowMarkers = {}\nlocal function trackObjective(part, name, color, size, kind)\n    if objectiveMarkers[part] then return end\n    local item = marker(name, color, size)\n    item.Visible = false\n    local x, y = project(part.Position)\n    item.Position = UDim2.fromOffset(x, y)\n    objectiveMarkers[part] = {icon = item, kind = kind}\nend\n\nlocal function drawPart(part)\n    if not part:IsA(\"BasePart\") then return end\n    if part.Name == \"Parede\" or part.Name == \"Caixa\" then\n        local x, y = project(part.Position)\n        local f = frame(\"Contorno_\" .. part.Name, map,\n            part.Name == \"Parede\" and Theme.MapLine\n                or Theme.MapLine,\n            part.Name == \"Parede\" and 0.58 or 0.78)\n        local w = math.max(1.2, part.Size.X * SCALE)\n        local h = math.max(1.2, part.Size.Z * SCALE)\n        f.Position = UDim2.fromOffset(x - w/2, y - h/2)\n        f.Size = UDim2.fromOffset(w, h)\n        f.ZIndex = 3\n    elseif part.Name == \"Terminal\" then\n        trackObjective(part, \"TerminalVermelho\", GOLD, 6, \"terminal\")\n    elseif part.Name == \"Extracao\" then\n        trackObjective(part, \"ExtracaoVerde\", GREEN, 6, \"extracao\")\n    elseif part.Name == \"Dossie\" then\n        trackObjective(part, \"Dossie\", WHITE, 4, \"dossie\")\n    elseif part.Name == \"ReleCameras\" then\n        trackObjective(part, \"ReleCameras\", WHITE, 4, \"rele\")\n    elseif part.Name:match(\"^Armario_%d+$\") then\n        trackObjective(part, \"Armario_\" .. part.Name, WHITE, 4, \"armario\")\n    elseif part.Name:match(\"^Sombra_%d+$\") then\n        local x, y = project(part.Position)\n        local f = frame(\"Sombra_\" .. part.Name, map,\n            Theme.ShadowZone, 0.83)\n        f.Position = UDim2.fromOffset(x - part.Size.X*SCALE/2,\n            y - part.Size.Z*SCALE/2)\n        f.Size = UDim2.fromOffset(part.Size.X*SCALE, part.Size.Z*SCALE)\n        f.ZIndex = 1\n        f.Visible = false\n        shadowMarkers[part] = f\n    end\nend\n\n-- StreamingEnabled pode trazer objetos depois que o cliente inicializar.\ntask.wait(0.65)\nfor _, child in ipairs(world:GetChildren()) do drawPart(child) end\nworld.ChildAdded:Connect(drawPart)\n\nlocal guardDisplay = {}\nfor id = 1, 5 do\n    local isCamera = id > 3\n    local count = isCamera and 8 or SLICE_COUNT\n    local sectors = {}\n    for side = -1, 1, 2 do\n        local strips = {}\n        for j = 1, count do\n            local strip = frame(\"Visao_\" .. id .. \"_\" .. side .. \"_\" .. j,\n                map, isCamera and RED or GOLD, 0.89)\n            strip.AnchorPoint = Vector2.new(0.5, 0.5)\n            strip.ZIndex = 2\n            strips[j] = strip\n        end\n        sectors[side] = strips\n    end\n    local dot = marker(isCamera and (\"Camera_\" .. (id-3))\n        or (\"Sentinela_\" .. id), isCamera and RED or GOLD, isCamera and 4 or 5)\n    guardDisplay[id] = {dot = dot, sectors = sectors,\n        isCamera = isCamera, count = count}\nend\n\n-- Triangulo branco de orientacao, fiel ao ultimo concept.\nlocal playerArrow = Instance.new(\"TextLabel\")\nplayerArrow.Name = \"Jogador\"\nplayerArrow.Size = UDim2.fromOffset(18, 18)\nplayerArrow.AnchorPoint = Vector2.new(0.5, 0.5)\nplayerArrow.BackgroundTransparency = 1\nplayerArrow.Text = \"▲\"\nplayerArrow.TextColor3 = WHITE\nplayerArrow.TextSize = 13\nplayerArrow.Font = Enum.Font.GothamBold\nplayerArrow.ZIndex = 9\nplayerArrow.Parent = map\n\nlocal params = RaycastParams.new()\nparams.FilterType = Enum.RaycastFilterType.Exclude\nparams.RespectCanCollide = true\n\nlocal field = frame(\"CampoDeTestes\", panel, Theme.Panel, 1)\nfield.Size = UDim2.fromScale(1, 1)\nfield.ClipsDescendants = true\nfield.Visible = false\n\nlocal qaScale = MAP_W / 82\nlocal function projectField(position)\n    return (position.X - 185) * qaScale + MAP_W * 0.5,\n        position.Z * qaScale + MAP_H * 0.5\nend\n\nlocal function drawTestPiece(part)\n    if not part:IsA(\"BasePart\") then return end\n    local name = part.Name\n    if name ~= \"LimitePista\" and name ~= \"Caixa\" and name ~= \"Parede\" then return end\n    local view = frame(\"Contorno_\" .. name, field, Theme.MapLine, 0.5)\n    local x, y = projectField(part.Position)\n    view.AnchorPoint = Vector2.new(0.5, 0.5)\n    view.Position = UDim2.fromOffset(x, y)\n    view.Size = UDim2.fromOffset(math.max(1, part.Size.X * qaScale), math.max(1, part.Size.Z * qaScale))\n    part.AncestryChanged:Connect(function()\n        if not part:IsDescendantOf(world) then view:Destroy() end\n    end)\nend\n\nlocal function bindTestField(group)\n    if group.Name ~= \"P17_CampoDeTestes\" then return end\n    for _, item in ipairs(group:GetChildren()) do drawTestPiece(item) end\n    group.ChildAdded:Connect(drawTestPiece)\nend\nlocal existingField = world:FindFirstChild(\"P17_CampoDeTestes\")\nif existingField then bindTestField(existingField) end\nworld.ChildAdded:Connect(bindTestField)\n\nlocal qaArrow = playerArrow:Clone()\nqaArrow.Name = \"JogadorNoCampo\"\nqaArrow.Parent = field\nlocal function update()\n    local inField = player:GetAttribute(\"Posto17InTestRange\") == true\n    field.Visible = inField\n    map.Visible = not inField and world:GetAttribute(\"RadarJammed\") ~= true\n    if inField then\n        local character = player.Character\n        local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n        qaArrow.Visible = root ~= nil\n        if root then\n            local x, y = projectField(root.Position)\n            qaArrow.Position = UDim2.fromOffset(x, y)\n            local forward = root.CFrame.LookVector\n            qaArrow.Rotation = math.deg(math.atan2(forward.X, -forward.Z))\n        end\n        return\n    end\n    if world:GetAttribute(\"RadarJammed\") == true then return end\n    local char = player.Character\n    local root = char and char:FindFirstChild(\"HumanoidRootPart\")\n    if not root then\n        playerArrow.Visible = false\n        for _, display in ipairs(guardDisplay) do\n            display.dot.Visible = false\n            for _, slices in pairs(display.sectors) do\n                for _, strip in ipairs(slices) do strip.Visible = false end\n            end\n        end\n        return\n    end\n\n    local x, y = project(root.Position)\n    playerArrow.Position = UDim2.fromOffset(x, y)\n    playerArrow.Visible = true\n    local forward = root.CFrame.LookVector\n    playerArrow.Rotation = math.deg(math.atan2(forward.X, -forward.Z))\n\n    -- Revelacao de informacao por proximidade, nao por onisciencia.\n    local dataTaken = player:GetAttribute(\"Posto17Data\") == true\n    local intelTaken = player:GetAttribute(\"Posto17BonusIntel\") == true\n    local sabotaged = player:GetAttribute(\"Posto17Sabotage\") == true\n    for part, info in pairs(objectiveMarkers) do\n        if not part.Parent then\n            info.icon:Destroy()\n            objectiveMarkers[part] = nil\n        else\n            local dist = (part.Position-root.Position).Magnitude\n            local relevant = (info.kind == \"terminal\" and not dataTaken)\n                or (info.kind == \"extracao\" and dataTaken)\n                or (info.kind == \"dossie\" and not intelTaken)\n                or (info.kind == \"rele\" and not sabotaged)\n                or info.kind == \"armario\"\n            info.icon.Visible = relevant and dist <= DISCOVERY_RANGE\n        end\n    end\n\n    for part, f in pairs(shadowMarkers) do\n        if part.Parent then\n            f.Visible = (part.Position-root.Position).Magnitude <= 22\n                and player:GetAttribute(\"Posto17Crouched\") == true\n        else\n            f:Destroy()\n            shadowMarkers[part] = nil\n        end\n    end\n\n    local crouching = player:GetAttribute(\"Posto17Crouched\") == true\n    local prone = player:GetAttribute(\"Posto17Prone\") == true\n    local alertLevel = world:GetAttribute(\"AlertLevel\") or 0\n    local range = (prone and 9 or (crouching and 12 or 22))\n        + alertLevel * (crouching and 1 or 2)\n    if crouching and not player:GetAttribute(\"Posto17Flashlight\") then\n        for part in pairs(shadowMarkers) do\n            if part.Parent\n                and math.abs(root.Position.X-part.Position.X) < part.Size.X/2\n                and math.abs(root.Position.Z-part.Position.Z) < part.Size.Z/2 then\n                range = 5\n                break\n            end\n        end\n    end\n    -- A distancia de deteccao usa as mesmas unidades do servidor,\n    -- mostradas ao jogador como metros no marcador de objetivo (x 0.28).\n    params.FilterDescendantsInstances = {char}\n\n    for id, display in ipairs(guardDisplay) do\n        local camera = display.isCamera\n        local body = world:FindFirstChild(camera\n            and (\"Camera_\" .. (id-3)) or (\"Sentinela_\" .. id))\n        local dist = body and (body.Position-root.Position).Magnitude or math.huge\n        local near = dist < (camera and 38 or 40)\n\n        if body and body:IsA(\"BasePart\") and near then\n            local gx, gy = project(body.Position)\n            local f = body.CFrame.LookVector\n            local angle = math.atan2(f.Z, f.X)\n            local state = body:GetAttribute(\"AIState\")\n            local active = camera and body:GetAttribute(\"Active\") ~= false\n                or (not camera and (body:GetAttribute(\"LifeState\") == nil or body:GetAttribute(\"LifeState\") == \"ACTIVE\"))\n            display.dot.Position = UDim2.fromOffset(gx, gy)\n            display.dot.Visible = body.Transparency < 1\n            display.dot.BackgroundColor3 = camera and (active and RED\n                    or Theme.Success)\n                or ((state == \"CHASE\" or state == \"WATCH\") and RED\n                    or (active and GOLD or Theme.MapLine))\n\n            local visibleRange = camera\n                and ((prone and 9 or (crouching and 13 or 21))+alertLevel*1.5)\n                or range\n            if camera and crouching and range == 5 then visibleRange = 5 end\n            if not active then visibleRange = 0 end\n\n            local showCone = dist <= 31 and visibleRange > 0\n            if showCone then\n                local halfFov = camera and math.rad(24) or FOV_HALF\n                local origin = body.Position\n                    + (camera and Vector3.zero or Vector3.new(0,0.5,0))\n                    + f * (camera and 1.1 or 1.55)\n                local ox, oy = project(origin)\n                local center = workspace:Raycast(origin, f*visibleRange, params)\n                local centerLimit = center and center.Distance or visibleRange\n                local length = visibleRange / display.count\n                for side = -1, 1, 2 do\n                    local halfAngle = angle + side*halfFov/2\n                    local dir = Vector3.new(math.cos(halfAngle),0,math.sin(halfAngle))\n                    local hit = workspace:Raycast(origin, dir*visibleRange, params)\n                    local limit = math.min(centerLimit,\n                        hit and hit.Distance or visibleRange)\n                    for j, strip in ipairs(display.sectors[side]) do\n                        local lengthAt = (j-0.5)*length\n                        if lengthAt <= limit then\n                            local width = lengthAt*math.tan(halfFov)\n                            local sideDist = side*width*0.5\n                            strip.Position = UDim2.fromOffset(\n                                ox+(f.X*lengthAt-f.Z*sideDist)*SCALE,\n                                oy+(f.Z*lengthAt+f.X*sideDist)*SCALE)\n                            strip.Rotation = math.deg(angle)\n                            strip.Size = UDim2.fromOffset(length*SCALE+1.25,\n                                math.max(1, width*SCALE+0.4))\n                            strip.BackgroundTransparency = (state == \"CHASE\")\n                                and 0.84 or 0.92\n                            strip.Visible = true\n                        else\n                            strip.Visible = false\n                        end\n                    end\n                end\n            else\n                for _, slices in pairs(display.sectors) do\n                    for _, strip in ipairs(slices) do strip.Visible = false end\n                end\n            end\n        else\n            display.dot.Visible = false\n            for _, slices in pairs(display.sectors) do\n                for _, strip in ipairs(slices) do strip.Visible = false end\n            end\n        end\n    end\nend\n\nwhile gui.Parent do\n    update()\n    task.wait(REFRESH)\nend\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Opcoes","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Opcoes (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal UIS = game:GetService(\"UserInputService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\")\nlocal event = RS:WaitForChild(\"Posto17Settings\")\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Opcoes\"\ngui.ResetOnSpawn = false\ngui.DisplayOrder = 51\ngui.Parent = player:WaitForChild(\"PlayerGui\")\n\nlocal panel = Instance.new(\"Frame\")\npanel.AnchorPoint = Vector2.new(0.5, 0.5)\npanel.Position = UDim2.fromScale(0.5, 0.48)\npanel.Size = UDim2.fromOffset(292, 158)\npanel.BackgroundColor3 = Theme.Panel\npanel.BackgroundTransparency = 0.12\npanel.BorderSizePixel = 0\npanel.Visible = false\npanel.Parent = gui\n\nlocal corner = Instance.new(\"UICorner\")\ncorner.CornerRadius = UDim.new(0, 8)\ncorner.Parent = panel\nlocal border = Instance.new(\"UIStroke\")\nborder.Color = Theme.Border\nborder.Transparency = 0.35\nborder.Parent = panel\n\nlocal function text(class, caption, x, y, width, height)\n    local item = Instance.new(class)\n    item.Text = caption\n    item.Position = UDim2.fromOffset(x, y)\n    item.Size = UDim2.fromOffset(width, height)\n    item.BackgroundTransparency = 1\n    item.BorderSizePixel = 0\n    item.TextColor3 = Theme.Text\n    item.Font = Theme.Font\n    item.TextSize = 13\n    item.Parent = panel\n    return item\nend\n\nlocal title = text(\"TextLabel\", \"Configurações\", 16, 11, 180, 27)\ntitle.TextXAlignment, title.TextSize = Enum.TextXAlignment.Left, 16\nlocal close = text(\"TextButton\", \"×\", 244, 4, 44, 44)\nclose.TextColor3, close.TextSize = Theme.Muted, 22\nlocal difficulty = text(\"TextLabel\", \"Dificuldade\", 16, 50, 248, 20)\ndifficulty.TextXAlignment, difficulty.TextColor3 = Enum.TextXAlignment.Left, Theme.Muted\n\nlocal options = {}\nfor i, option in ipairs({{\"EASY\",\"Fácil\"},{\"NORMAL\",\"Normal\"},{\"HARD\",\"Difícil\"}}) do\n    local b = text(\"TextButton\", option[2], 16 + (i-1)*88, 78, 84, 44)\n    b.BackgroundTransparency = 0.1\n    local radius = Instance.new(\"UICorner\")\n    radius.CornerRadius = UDim.new(0, 5)\n    radius.Parent = b\n    b.Activated:Connect(function() event:FireServer(option[1]) end)\n    options[option[1]] = b\nend\n\nlocal function selection()\n    local selected = world:GetAttribute(\"Difficulty\") or \"NORMAL\"\n    for choice, b in pairs(options) do\n        b.BackgroundColor3 = choice == selected and Theme.Brand or Theme.Surface\n        b.TextColor3 = Theme.Text\n    end\nend\nworld:GetAttributeChangedSignal(\"Difficulty\"):Connect(selection)\nselection()\n\nlocal function toggle()\n    player:SetAttribute(\"P17OptionsOpen\", not panel.Visible)\nend\nplayer:GetAttributeChangedSignal(\"P17OptionsOpen\"):Connect(function()\n    panel.Visible = player:GetAttribute(\"P17OptionsOpen\") == true\nend)\npanel.Visible = player:GetAttribute(\"P17OptionsOpen\") == true\nclose.Activated:Connect(toggle)\nUIS.InputBegan:Connect(function(input, consumed)\n    if not consumed and input.KeyCode == Enum.KeyCode.O then toggle() end\nend)\n\nif RunService:IsStudio() then\n    local debugToggle = text(\"TextButton\", \"Diagnóstico\", 16, 120, 130, 38)\n    debugToggle.TextColor3 = Theme.Muted\n    local diagnostic = text(\"TextLabel\", \"\", 0, 165, 390, 124)\n    diagnostic.TextXAlignment = Enum.TextXAlignment.Left\n    diagnostic.TextYAlignment = Enum.TextYAlignment.Top\n    diagnostic.BackgroundColor3 = Theme.Panel\n    diagnostic.BackgroundTransparency = 0.18\n    diagnostic.Visible = false\n    debugToggle.Activated:Connect(function() diagnostic.Visible = not diagnostic.Visible end)\n    task.spawn(function()\n        while gui.Parent do\n            if panel.Visible and diagnostic.Visible then\n                local lines = {tostring(world:GetAttribute(\"MissionVersion\")),\n                    \"Rádio \" .. tostring(world:GetAttribute(\"RadioOnline\"))\n                    .. \" · Radar \" .. tostring(world:GetAttribute(\"RadarJammed\"))}\n                for _, guard in ipairs(world:GetChildren()) do\n                    if guard.Name:match(\"^Sentinela_\") then\n                        lines[#lines+1] = guard.Name .. \" · \" .. tostring(guard:GetAttribute(\"LifeState\"))\n                            .. \" · \" .. tostring(guard:GetAttribute(\"AIState\"))\n                    end\n                end\n                diagnostic.Text = table.concat(lines, \"\\n\")\n            end\n            task.wait(0.35)\n        end\n    end)\nend\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Operacoes","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Operacoes (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Prompts locais escolhem acao; o servidor revalida distancia, angulo e tempo.\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal UIS = game:GetService(\"UserInputService\")\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\")\nlocal event = RS:WaitForChild(\"Posto17Action\")\nlocal Rules = require(RS:WaitForChild(\"Posto17Shared\"):WaitForChild(\"Rules\"))\nlocal records = {}\nlocal registered = {}\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Operacoes\"\ngui.ResetOnSpawn = false\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal hint = Instance.new(\"TextLabel\")\nhint.BackgroundTransparency = 1\nhint.AnchorPoint = Vector2.new(0.5, 1)\nhint.Position = UDim2.new(0.5, 0, 1, -92)\nhint.Size = UDim2.fromOffset(460, 24)\nhint.TextSize = 12\nhint.TextColor3 = Theme.Text\nhint.Font = Enum.Font.GothamMedium\nhint.Visible = false\nhint.Parent = gui\nlocal touch = Instance.new(\"Frame\")\ntouch.Name = \"AcoesTouch\"\ntouch.BackgroundTransparency = 1\ntouch.AnchorPoint = Vector2.new(0.5, 1)\ntouch.Position = UDim2.new(0.5, 0, 1, -118)\ntouch.Size = UDim2.fromOffset(310, 38)\ntouch.Visible = false\ntouch.Parent = gui\nlocal touchButtons = {}\nfor i = 1, 3 do\n    local button = Instance.new(\"TextButton\")\n    button.Name = \"Acao\" .. i\n    button.Size = UDim2.fromOffset(99, 36)\n    button.Position = UDim2.fromOffset((i-1)*104, 0)\n    button.BackgroundColor3 = Theme.Surface\n    button.BackgroundTransparency = 0.77\n    button.BorderSizePixel = 0\n    button.TextStrokeTransparency = 0.51\n    button.TextColor3 = Theme.Text\n    button.TextSize = 12\n    button.Font = Enum.Font.GothamMedium\n    button.Parent = touch\n    touchButtons[i] = button\nend\nlocal selected = {}\nlocal holding = {}\nlocal function begin(record)\n    if not record or holding[record] then return end\n    holding[record] = os.clock()\n    event:FireServer(\"BEGIN\", record.action, record.id)\nend\nlocal function cancel(record)\n    if record then holding[record] = nil end\n    event:FireServer(\"CANCEL\")\nend\nlocal function finish(record)\n    if not record or not holding[record] then return end\n    holding[record] = nil\n    event:FireServer(\"FINISH\", record.action, record.id)\nend\nfor i, button in ipairs(touchButtons) do\n    local active\n    button.InputBegan:Connect(function(input)\n        if input.UserInputType ~= Enum.UserInputType.Touch and input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end\n        active = selected[i]\n        if not active then return end\n        local record = active\n        begin(record)\n        -- O servidor mede o tempo; pequeno respiro cobre variacao de rede.\n        if record.action ~= \"STEAL\" then\n            task.delay(Rules.HOLD[record.action] + 0.15, function()\n                if active == record and holding[record] then finish(record) end\n            end)\n        end\n    end)\n    button.InputEnded:Connect(function(input)\n        if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then\n            if active and holding[active] then\n                if active.action == \"STEAL\" then finish(active)\n                else cancel(active) end\n            end\n            active = nil\n        end\n    end)\nend\nlocal function add(body, action, id, key, label)\n    local prox = Instance.new(\"ProximityPrompt\")\n    prox.Name = \"Acao_\" .. action\n    prox.ActionText = label\n    prox.ObjectText = \"Sentinela\"\n    prox.KeyboardKeyCode = key\n    -- Furto e realizado AO SOLTAR, dentro da janela de tempo, nao no\n    -- preenchimento automatico da barra do ProximityPrompt.\n    prox.HoldDuration = action == \"STEAL\" and (Rules.STEAL_WINDOW_END + 0.75)\n        or (Rules.HOLD[action] + 0.12)\n    prox.MaxActivationDistance = 7\n    prox.RequiresLineOfSight = true\n    prox.Enabled = false\n    prox.Parent = body\n    local record = {body = body, owner = body, action = action, id = id, prompt = prox, label = label}\n    records[#records+1] = record\n    prox.PromptButtonHoldBegan:Connect(function() begin(record) end)\n    prox.Triggered:Connect(function()\n        if Rules.HOLD[action] == 0 then\n            begin(record)\n            task.delay(0.05, function() finish(record) end)\n        else finish(record) end\n    end)\n    prox.PromptButtonHoldEnded:Connect(function()\n        task.delay(0.03, function()\n            if holding[record] then\n                if action == \"STEAL\" then finish(record)\n                else cancel(record) end\n            end\n        end)\n    end)\n    return record\nend\nlocal function register(body)\n    if not body:IsA(\"BasePart\") then return end\n    if registered[body] then return end\n    local id = body:GetAttribute(\"GuardId\") or tonumber(body.Name:match(\"^Sentinela_(%d+)$\"))\n    if id then\n        registered[body] = true\n        add(body, \"KO\", id, Enum.KeyCode.E, \"Nocautear\")\n        add(body, \"KILL\", id, Enum.KeyCode.X, \"Matar\")\n        add(body, \"STEAL\", id, Enum.KeyCode.T, \"Furtar: solte em 2s\")\n        add(body, \"DRAG\", id, Enum.KeyCode.B, \"Arrastar\")\n        add(body, \"DROP\", id, Enum.KeyCode.B, \"Soltar corpo\")\n        -- Recuperar corpo guardado usa o armario como suporte visual.\n        add(body, \"RELEASE\", id, Enum.KeyCode.E, \"Retirar corpo\")\n    elseif body.Name:match(\"^Armario_%d+$\") then\n        registered[body] = true\n        id = tonumber(body.Name:match(\"%d+\"))\n        add(body, \"STOW\", id, Enum.KeyCode.E, \"Ocultar corpo\")\n        -- RELEASE usa o ID do guarda, atualizado ao descobrir armario ocupado.\n    end\nend\nfor _, item in ipairs(world:GetChildren()) do register(item) end\nworld.ChildAdded:Connect(function(item)\n    task.defer(function() register(item) end)\nend)\nlocal ray = RaycastParams.new()\nray.FilterType = Enum.RaycastFilterType.Exclude\nray.RespectCanCollide = true\nwhile gui.Parent do\n    local root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n    local best, distance = nil, math.huge\n    local dragging = player:GetAttribute(\"Posto17Dragging\") == true\n    -- O prompt de entrar usa E tambem: desliga apenas a apresentacao local\n    -- enquanto guardar/retirar corpo e a acao disponivel. F continua no servidor.\n    for _, body in ipairs(world:GetChildren()) do\n        if body.Name:match(\"^Armario_%d+$\") then\n            local enter = body:FindFirstChild(\"Esconder\")\n            if enter then enter.Enabled = not dragging and body:GetAttribute(\"BodyStored\") ~= true end\n        end\n    end\n    for i = #records, 1, -1 do\n        local r = records[i]\n        if not r.owner.Parent then\n            if holding[r] then cancel(r) end\n            r.prompt:Destroy()\n            registered[r.owner] = nil\n            table.remove(records, i)\n        end\n    end\n    local sensed = {}\n    for _, r in ipairs(records) do\n        local enabled = false\n        if r.action == \"RELEASE\" then\n            local guard = world:FindFirstChild(\"Sentinela_\" .. r.id)\n            local locker = guard and guard:GetAttribute(\"LockerId\")\n            local body = locker and world:FindFirstChild(\"Armario_\" .. locker)\n            if body and body ~= r.body then r.body = body; r.prompt.Parent = body end\n        end\n        if root and r.body.Parent and not player:GetAttribute(\"Posto17Hidden\") and not player:GetAttribute(\"Posto17Won\") then\n            local sample = sensed[r.body]\n            if not sample then\n                local delta = root.Position - r.body.Position\n                local flat = Vector3.new(delta.X, 0, delta.Z)\n                local clear = false\n                if delta.Magnitude <= 8 then\n                    ray.FilterDescendantsInstances = {player.Character, r.body}\n                    clear = workspace:Raycast(root.Position, -delta, ray) == nil\n                end\n                sample = {delta = delta, clear = clear,\n                    dot = flat.Magnitude > 0.01 and r.body.CFrame.LookVector:Dot(flat.Unit) or 1}\n                sensed[r.body] = sample\n            end\n            local delta, clear, dot = sample.delta, sample.clear, sample.dot\n            local life = r.body:GetAttribute(\"LifeState\")\n            if r.action == \"KO\" or r.action == \"KILL\" or r.action == \"STEAL\" then\n                enabled = not dragging and Rules.behind(dot, delta.Magnitude, clear, life)\n                    and (r.action ~= \"STEAL\" or r.body:GetAttribute(\"HasCard\") == true)\n            elseif r.action == \"DRAG\" then\n                enabled = not dragging and life ~= nil and life ~= \"ACTIVE\" and life ~= \"TRAPPED\"\n                    and r.body.Transparency < 1 and not r.body:GetAttribute(\"Carried\") and delta.Magnitude <= 7 and clear\n            elseif r.action == \"DROP\" then\n                enabled = dragging and r.body:GetAttribute(\"CarrierId\") == player.UserId\n            elseif r.action == \"RELEASE\" then\n                local guard = world:FindFirstChild(\"Sentinela_\" .. r.id)\n                enabled = not dragging and guard and guard:GetAttribute(\"LockerId\") ~= nil\n                    and r.body.Name == \"Armario_\" .. tostring(guard:GetAttribute(\"LockerId\"))\n                    and delta.Magnitude <= 7 and clear\n            elseif r.action == \"STOW\" then\n                enabled = dragging and not r.body:GetAttribute(\"BodyStored\") and delta.Magnitude <= 7 and clear\n            end\n            if enabled and delta.Magnitude < distance then best, distance = r.body, delta.Magnitude end\n        end\n        r.prompt.Enabled = enabled\n    end\n    table.clear(selected)\n    for _, r in ipairs(records) do\n        if r.prompt.Enabled and r.body == best then selected[#selected+1] = r end\n    end\n    hint.Visible = #selected > 0 and not UIS.TouchEnabled\n    local words = {}\n    for _, r in ipairs(selected) do words[#words+1] = r.prompt.KeyboardKeyCode.Name .. \" \" .. r.label end\n    hint.Text = table.concat(words, \"   /   \")\n    touch.Visible = #selected > 0 and UIS.TouchEnabled\n    for i, button in ipairs(touchButtons) do\n        button.Visible = selected[i] ~= nil\n        local record = selected[i]\n        button.Text = record and record.label or \"\"\n        if record and holding[record] then\n            local elapsed = os.clock()-holding[record]\n            if record.action == \"STEAL\" then\n                local sweet = elapsed >= Rules.STEAL_WINDOW_START\n                    and elapsed <= Rules.STEAL_WINDOW_END\n                button.Text = sweet and \"SOLTE AGORA\" or string.format(\"FURTO %.1f s\", elapsed)\n                button.TextColor3 = sweet and Theme.Success\n                    or Theme.Text\n            else\n                button.Text = record.label .. \" \" .. math.floor(math.clamp(\n                    elapsed / math.max(Rules.HOLD[record.action], 0.01), 0, 1) * 100) .. \"%\"\n            end\n        else\n            button.TextColor3 = Theme.Text\n        end\n    end\n    task.wait(0.12)\nend\n"},{"studio":"StarterPlayer/StarterPlayerScripts/OperatorCamera","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/OperatorCamera (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Camera P17: usa o camera module nativo para mouse, toque e gamepad.\n-- Apenas suaviza offset/FOV e oculta a cabeca customizada de perto.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal player = Players.LocalPlayer\n\nlocal headVisuals = {}\nlocal tracked\nlocal humanoid\nlocal head\nlocal function watch(character)\n    tracked = character\n    table.clear(headVisuals)\n    humanoid = character:WaitForChild(\"Humanoid\", 8)\n    head = character:WaitForChild(\"Head\", 8)\n    local function add(item)\n        if item:IsA(\"BasePart\") and item:GetAttribute(\"P17HeadVisual\") == true then\n            headVisuals[item] = true\n        end\n    end\n    for _, item in ipairs(character:GetDescendants()) do add(item) end\n    character.DescendantAdded:Connect(add)\n    character.DescendantRemoving:Connect(function(item) headVisuals[item] = nil end)\nend\nplayer.CharacterAdded:Connect(watch)\nif player.Character then task.spawn(watch,player.Character) end\n\nlocal function active()\n    return player:GetAttribute(\"P17InMainMenu\") == false\n        and player:GetAttribute(\"P17Reviewing\") ~= true\n        and player:GetAttribute(\"Posto17InCover\") ~= true\n        and player:GetAttribute(\"Posto17Won\") ~= true\nend\nlocal function smooth(a, b, speed, dt)\n    return a + (b-a) * (1-math.exp(-math.min(dt,.06)*speed))\nend\nlocal function clearHead()\n    for p in pairs(headVisuals) do\n        if p.Parent then p.LocalTransparencyModifier = 0 end\n    end\nend\n\n-- Valores moderados: zoom nativo do Roblox permanece responsavel pela troca\n-- entre primeira e terceira pessoa e pela colisao da camera com paredes.\nplayer.CameraMinZoomDistance = 0.5\nplayer.CameraMaxZoomDistance = 12\nplayer.CameraMode = Enum.CameraMode.Classic\n\nRunService:BindToRenderStep(\"P17OperatorCamera\",Enum.RenderPriority.Camera.Value+3,function(dt)\n    local camera = workspace.CurrentCamera\n    if not camera or not humanoid or not humanoid.Parent or not head or not head.Parent\n        or tracked ~= player.Character then return end\n    if not active() or camera.CameraType ~= Enum.CameraType.Custom then\n        clearHead()\n        return\n    end\n\n    local distance = (camera.CFrame.Position-head.Position).Magnitude\n    local first = math.clamp((2.25-distance)/1.25,0,1)\n    -- Ease para impedir uma mudanca visual brusca ao cruzar 1a/3a pessoa.\n    first = first*first*(3-2*first)\n    for p in pairs(headVisuals) do\n        if p.Parent then p.LocalTransparencyModifier = first end\n    end\n\n    local base = player:GetAttribute(\"P17CameraBaseOffset\")\n    if typeof(base) ~= \"Vector3\" then base = Vector3.new(.6,.15,0) end\n    local offset = base + Vector3.new(.34*(1-first),0,0)\n    humanoid.CameraOffset = humanoid.CameraOffset:Lerp(offset,1-math.exp(-math.min(dt,.06)*13))\n    local fov = player:GetAttribute(\"P17CameraBaseFOV\") or 68\n    if player:GetAttribute(\"Posto17Sprint\") then fov += 3 end\n    fov -= first*1.2\n    camera.FieldOfView = smooth(camera.FieldOfView,fov,7,dt)\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/PistolHud","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/PistolHud (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal theme = require(RS:WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal player = Players.LocalPlayer\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17Pistola\"\ngui.ResetOnSpawn = false\ngui.DisplayOrder = 14\ngui.Parent = player:WaitForChild(\"PlayerGui\")\nlocal text = Instance.new(\"TextLabel\")\ntext.Position = UDim2.new(1,-186,0,56)\ntext.Size = UDim2.fromOffset(167,22)\ntext.BackgroundTransparency = 1\ntext.TextXAlignment = Enum.TextXAlignment.Right\ntext.TextStrokeTransparency = .45\ntext.Font = theme.Font\ntext.TextSize = 13\ntext.Visible = false\ntext.Parent = gui\n\nlocal function monitor(character)\n    local watched\n    local connection\n    local function redraw()\n        local wear = watched and watched:GetAttribute(\"P17Suppressor\")\n        text.Visible = wear ~= nil and watched:GetAttribute(\"P17SuppressorInstalled\") ~= false\n            and not player:GetAttribute(\"P17InMainMenu\")\n        if not wear then return end\n        text.Text = wear > 0 and (\"Supressor · %d/12\"):format(wear) or \"Supressor gasto\"\n        text.TextColor3 = wear > 3 and theme.Text or theme.Caution\n    end\n    local function update()\n        if connection then connection:Disconnect(); connection = nil end\n        watched = character:FindFirstChild(\"Pistola\")\n        if watched then connection = watched:GetAttributeChangedSignal(\"P17Suppressor\"):Connect(redraw) end\n        redraw()\n    end\n    local a = character.ChildAdded:Connect(function(item) if item:IsA(\"Tool\") then update() end end)\n    local b = character.ChildRemoved:Connect(function(item) if item:IsA(\"Tool\") then update() end end)\n    character.Destroying:Once(function()\n        a:Disconnect()\n        b:Disconnect()\n        if connection then connection:Disconnect() end\n    end)\n    update()\nend\nplayer.CharacterAdded:Connect(monitor)\nif player.Character then monitor(player.Character) end\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Postura","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Postura (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal PoseLibrary = require(ReplicatedStorage:WaitForChild(\"Posto17Shared\"):WaitForChild(\"PoseLibrary\"))\nlocal active = {}\nlocal CrouchLegs = require(script.Parent.CrouchLegs)\nlocal R6Frames = require(script.Parent:WaitForChild(\"R6Frames\"))\nlocal tracks = {\"CROUCH\", \"PRONE\", \"VENT\", \"COVER_LOW\", \"COVER_HIGH\", \"SPRINT\"}\nlocal rates = {CROUCH = {8, 4.6}, PRONE = {4, 3.05}, VENT = {4, 3.1},\n    COVER_LOW = {5, 4.1}, COVER_HIGH = {6, 4.7}, SPRINT = {21, 9.4},\n    STAND = {16, 7.1}}\n\nlocal function isJoint(item)\n    return item:IsA(\"AnimationConstraint\") or item:IsA(\"Motor6D\")\nend\n\nlocal function registerCharacter(player, character)\n    local humanoid = character:WaitForChild(\"Humanoid\", 8)\n    if not humanoid then return end\n    local info = {\n        player = player,\n        character = character,\n        humanoid = humanoid,\n        isR15 = humanoid.RigType == Enum.HumanoidRigType.R15,\n        joints = {},\n        groundOffset = 0,\n        motion = 0,\n        frames = {},\n        chain = {},\n        rayParams = RaycastParams.new(),\n        baseline = {},\n        weights = {},\n        cycle = 0,\n        idleTime = 0,\n        baseAutoJump = humanoid.AutoJumpEnabled,\n    }\n    if player.Character ~= character then return end\n    info.rayParams.FilterDescendantsInstances = {character}\n    info.rayParams.RespectCanCollide = true\n    active[player] = info\n\n    local function addJoint(item)\n        if not isJoint(item) then return end\n        info.rebuild = true\n        local key = string.lower(item.Name):gsub(\"%s+\", \"\")\n        local previous = info.joints[key]\n        if not previous or (item:IsA(\"AnimationConstraint\")\n            and not previous:IsA(\"AnimationConstraint\")) then\n            info.joints[key] = item\n        end\n    end\n    for _, item in ipairs(character:GetDescendants()) do addJoint(item) end\n    local function updateJointCount()\n        if player == Players.LocalPlayer then\n            local count = 0\n            for _ in pairs(info.joints) do count += 1 end\n            player:SetAttribute(\"Posto17PoseJoints\", count)\n        end\n    end\n    updateJointCount()\n    character.DescendantAdded:Connect(function(item)\n        addJoint(item)\n        if isJoint(item) then updateJointCount() end\n    end)\n    character.DescendantRemoving:Connect(function(item)\n        if not isJoint(item) then return end\n        info.rebuild = true\n        local key = string.lower(item.Name):gsub(\"%s+\", \"\")\n        if info.joints[key] == item then info.joints[key] = nil end\n        info.baseline[item] = nil\n        task.defer(updateJointCount)\n    end)\n    character.Destroying:Connect(function()\n        if active[player] == info then active[player] = nil end\n    end)\nend\n\nlocal function registerPlayer(player)\n    player.CharacterAdded:Connect(function(character)\n        registerCharacter(player, character)\n    end)\n    if player.Character then task.spawn(registerCharacter, player, player.Character) end\nend\n\nfor _, player in ipairs(Players:GetPlayers()) do registerPlayer(player) end\nPlayers.PlayerAdded:Connect(registerPlayer)\nPlayers.PlayerRemoving:Connect(function(player) active[player] = nil end)\n\n-- Se o Animator nao avaliou um frame, restaurar o Transform anterior\n-- impede que os offsets sejam aplicados duas vezes e se acumulem.\nRunService.PreAnimation:Connect(function()\n    for _, info in pairs(active) do\n        for joint, base in pairs(info.baseline) do\n            if joint.Parent then joint.Transform = base end\n        end\n        table.clear(info.baseline)\n    end\nend)\n\nlocal function toCFrame(values, basis)\n    if not values then return CFrame.identity end\n    local frame = CFrame.new(values[1], values[2], values[3])\n        * CFrame.Angles(values[4], values[5], values[6])\n    return basis:Inverse() * frame * basis\nend\n\n-- Reconstrui a arvore a partir do root. O Transform de PreSimulation\n-- so chega as partes depois deste callback.\nlocal function buildChain(info, root)\n    table.clear(info.chain)\n    local pending = {}\n    for _, joint in pairs(info.joints) do\n        if joint.Part0 and joint.Part1 then\n            table.insert(pending, joint)\n        end\n    end\n    local connected = {[root] = true}\n    for _ = 1, #pending do\n        for i = #pending, 1, -1 do\n            local joint = pending[i]\n            if connected[joint.Part0] then\n                connected[joint.Part1] = true\n                table.insert(info.chain, joint)\n                table.remove(pending, i)\n            end\n        end\n        if #pending == 0 then break end\n    end\n    info.rebuild = #pending > 0 or #info.chain == 0\n    info.root = root\nend\n\nlocal function groundPose(info, root, rootJoint, weight, dt)\n    if not rootJoint or rootJoint.Part0 ~= root then return end\n    if info.rebuild or info.root ~= root then buildChain(info, root) end\n\n    local position = root.Position\n    local hit = workspace:Raycast(position, Vector3.new(0, -7, 0), info.rayParams)\n    local target = 0\n    if hit and hit.Normal.Y > 0.65 then\n        local normal = hit.Normal\n        local frames = info.frames\n        table.clear(frames)\n        frames[root] = root.CFrame\n        local closest = math.huge\n        for _, joint in ipairs(info.chain) do\n            local parent, part = frames[joint.Part0], joint.Part1\n            if not parent or not part then continue end\n            local frame = parent * joint.C0 * joint.Transform * joint.C1:Inverse()\n            frames[part] = frame\n            local size = part.Size * 0.5\n            local extent = math.abs(normal:Dot(frame.RightVector)) * size.X\n                + math.abs(normal:Dot(frame.UpVector)) * size.Y\n                + math.abs(normal:Dot(frame.LookVector)) * size.Z\n            local distance = normal:Dot(frame.Position - hit.Position) - extent\n            closest = math.min(closest, distance)\n        end\n        if closest < math.huge then\n            target = math.clamp((0.035 - closest) / normal.Y, -3, 2) * weight\n        end\n    end\n    info.groundOffset += (target - info.groundOffset) * (1 - math.exp(-dt * 28))\n    local jointFrame = root.CFrame * rootJoint.C0\n    local vertical = jointFrame:VectorToObjectSpace(Vector3.new(0, info.groundOffset, 0))\n    rootJoint.Transform = CFrame.new(vertical) * rootJoint.Transform\nend\n\nlocal function aimLowPistol(info, root, weight)\n    local character = info.character\n    local tool = character:FindFirstChildOfClass(\"Tool\")\n    if not tool or not tool:GetAttribute(\"P17Pistol\") or weight < .01 then return end\n    local shoulder = info.joints.rightshoulder\n    local hand = character:FindFirstChild(\"RightHand\")\n    local grip = hand and (hand:FindFirstChild(\"RightGrip\") or character:FindFirstChild(\"RightGrip\",true))\n    local tip = tool:FindFirstChild(\"TipAttachment\", true)\n    local camera = workspace.CurrentCamera\n    if not shoulder or not grip or not grip:IsA(\"JointInstance\") or not grip.Part1\n        or grip.Part0 ~= hand or not tip or not tip:IsA(\"Attachment\") or not camera then return end\n\n    if info.rebuild or info.root ~= root then buildChain(info,root) end\n    local frames = info.frames\n    table.clear(frames)\n    frames[root] = root.CFrame\n    for _, joint in ipairs(info.chain) do\n        local parent = frames[joint.Part0]\n        if parent then frames[joint.Part1] = parent * joint.C0 * joint.Transform * joint.C1:Inverse() end\n    end\n    local parent, handFrame = frames[shoulder.Part0], frames[hand]\n    if not parent or not handFrame then return end\n\n    local gun = handFrame * grip.C0 * grip.C1:Inverse()\n    local muzzle = gun * grip.Part1.CFrame:ToObjectSpace(tip.WorldCFrame)\n    local basis = parent * shoulder.C0\n    local aim = camera.CFrame.Position + camera.CFrame.LookVector * 80\n    local from, toward = muzzle.LookVector, (aim - muzzle.Position).Unit\n    local axis = from:Cross(toward)\n    if axis.Magnitude < .001 then return end\n    local angle = math.acos(math.clamp(from:Dot(toward),-1,1))\n    info.baseline[shoulder] = info.baseline[shoulder] or shoulder.Transform\n    shoulder.Transform = CFrame.fromAxisAngle(basis:VectorToObjectSpace(axis.Unit),angle*weight)\n        * shoulder.Transform\nend\n\nRunService.PreSimulation:Connect(function(dt)\n    dt = math.min(dt, 1/20)\n    local smoothing = 1 - math.exp(-dt * 13)\n    for player, info in pairs(active) do\n        local humanoid = info.humanoid\n        local root = humanoid.RootPart\n        if not root or not info.character.Parent or humanoid.Health <= 0 then continue end\n        -- R6 usa os keyframes aprovados; R15 preserva seu controlador atual.\n        if not info.isR15 and R6Frames.update(player, info, dt) then continue end\n\n        local hidden = player:GetAttribute(\"Posto17Hidden\") == true\n        local stance = (not hidden and player:GetAttribute(\"Posto17Stance\"))\n            or \"STAND\"\n        local cover = player:GetAttribute(\"Posto17CoverHeight\")\n        if not hidden and cover and stance ~= \"PRONE\" then\n            stance = (cover == \"LOW\" or stance == \"CROUCH\") and \"COVER_LOW\" or \"COVER_HIGH\"\n        elseif stance == \"STAND\" and not hidden and player:GetAttribute(\"Posto17Sprint\") then\n            stance = \"SPRINT\"\n        end\n\n        local velocity = root.AssemblyLinearVelocity\n        local planar = Vector3.new(velocity.X, 0, velocity.Z)\n        local speed = planar.Magnitude\n        if stance == \"SPRINT\" and (speed < 1 or humanoid.FloorMaterial == Enum.Material.Air) then\n            stance = \"STAND\"\n        end\n\n        local weight = 0\n        for _, track in ipairs(tracks) do\n            local blend = info.weights[track] or 0\n            blend += ((stance == track and 1 or 0) - blend) * smoothing\n            info.weights[track] = blend\n            weight += blend\n        end\n        weight = math.clamp(weight, 0, 1)\n        local action = not hidden and info.character:GetAttribute(\"P17Motion\")\n        local started = info.character:GetAttribute(\"P17MotionStart\") or 0\n        local duration = info.character:GetAttribute(\"P17MotionDuration\") or 1\n        local elapsed = workspace:GetServerTimeNow() - started\n        local progress = math.clamp(elapsed / duration, 0, 1)\n        local target = info.character:GetAttribute(\"P17MotionTarget\")\n        local envelope = action and math.clamp(math.min(elapsed / 0.18, (duration-elapsed) / 0.24), 0, 1) or 0\n        local actionWeight = envelope * envelope * (3 - 2 * envelope)\n        if player == Players.LocalPlayer then\n            local groundedStance = stance ~= \"STAND\" and stance ~= \"SPRINT\"\n            if info.lastJumpAllowed ~= (not groundedStance) then\n                humanoid:SetStateEnabled(Enum.HumanoidStateType.Jumping, not groundedStance)\n                humanoid.AutoJumpEnabled = not groundedStance and info.baseAutoJump\n                info.lastJumpAllowed = not groundedStance\n            end\n            if groundedStance then humanoid.Jump = false end\n            if target and actionWeight > 0.12 and not cover and not root.Anchored and speed < 1.2 then\n                local delta = target - root.Position\n                local aim = Vector3.new(delta.X, 0, delta.Z)\n                if aim.Magnitude > 0.5 then\n                    local face = CFrame.lookAt(root.Position, root.Position + aim)\n                    root.CFrame = root.CFrame:Lerp(face, (1 - math.exp(-dt * 13)) * actionWeight)\n                end\n            end\n        end\n\n        local basic = info.isR15 and weight < .003 and actionWeight < .003\n            and stance == \"STAND\" and not hidden\n            and humanoid.FloorMaterial ~= Enum.Material.Air\n            and info.character:GetAttribute(\"P17BodyStyle\") == \"BLOCKBENCH_CC0\"\n            and not info.character:FindFirstChildOfClass(\"Tool\")\n        if weight < 0.003 and actionWeight < 0.003 and not basic then\n            info.groundOffset, info.cycle, info.motion = 0, 0, 0\n            continue\n        end\n        info.idleTime += dt\n        local speedAndStride = rates[stance] or rates.CROUCH\n        local nominalSpeed, strideLength = speedAndStride[1], speedAndStride[2]\n        local moving = humanoid.FloorMaterial ~= Enum.Material.Air\n            and math.clamp(speed / nominalSpeed, 0, 1) or 0\n        info.motion += (moving - info.motion) * smoothing\n        local axis = cover and root.CFrame.RightVector or root.CFrame.LookVector\n        local direction = planar:Dot(axis) < -0.1 and -1 or 1\n        info.cycle = (info.cycle + dt * direction * math.min(speed, nominalSpeed)\n            * (2 * math.pi / strideLength)) % (2 * math.pi)\n\n        for name, joint in pairs(info.joints) do\n            if not joint.Parent or not joint.Part0 or not joint.Part1 then continue end\n            local base = joint.Transform\n            local basis = info.isR15 and joint.C0.Rotation or CFrame.identity\n            if basic then\n                local lateral = speed > 0.15 and math.clamp(root.CFrame:VectorToObjectSpace(planar).X / speed, -1, 1) or 0\n                local motion = PoseLibrary.basic(name, speed, info.cycle, info.idleTime, lateral)\n                if motion then\n                    info.baseline[joint] = base\n                    joint.Transform = toCFrame(motion,basis)\n                end\n            end\n            local poseOffset, blended = CFrame.identity, 0\n            for _, track in ipairs(tracks) do\n                local amount = info.weights[track]\n                if amount < 0.002 then continue end\n                local values = PoseLibrary.get(track, name, info.motion, info.cycle, info.isR15)\n                if values then\n                    blended += amount\n                    poseOffset = poseOffset:Lerp(toCFrame(values, basis), amount / blended)\n                end\n            end\n            local cue = actionWeight > 0.003 and info.isR15\n                and PoseLibrary.action(action, name, progress)\n            if blended > 0 or cue then\n                info.baseline[joint] = base\n                joint.Transform = base:Lerp(poseOffset, math.clamp(blended, 0, 1))\n                if cue then joint.Transform = joint.Transform:Lerp(toCFrame(cue, basis), actionWeight) end\n            end\n        end\n        local groundedWeight = weight - (info.weights.SPRINT or 0)\n        if action == \"BOX\" then groundedWeight = math.max(groundedWeight, actionWeight) end\n        if info.isR15 and groundedWeight > 0.003\n            and humanoid.FloorMaterial ~= Enum.Material.Air then\n            local rootJoint = info.joints.root\n            if rootJoint and not info.baseline[rootJoint] then info.baseline[rootJoint] = rootJoint.Transform end\n            groundPose(info, root, rootJoint, groundedWeight, dt)\n            local crouchWeight = (info.weights.CROUCH or 0) * (1 - actionWeight)\n            if rootJoint and rootJoint.Part0 == root and crouchWeight > 0.01 then\n                CrouchLegs.apply(info, root, rootJoint, rates.CROUCH[2], crouchWeight)\n            end\n        else\n            info.groundOffset = 0\n        end\n        if player == Players.LocalPlayer and info.isR15 then\n            local aiming = math.clamp((info.weights.CROUCH or 0) + (info.weights.PRONE or 0),0,1)\n            aimLowPistol(info,root,aiming*(1-actionWeight))\n        end\n    end\nend)\n"},{"studio":"StarterPlayer/StarterPlayerScripts/R6Frames","class":"ModuleScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/R6Frames (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto 17 | Reprodutor de movimento R6\n-- Le as KeyframeSequences limpas e aciona movimentos reais do personagem.\n-- Sem assets externos, sem animacoes de objetos/armas; R15 permanece com o controlador antigo.\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal Motion = {}\nlocal shared = ReplicatedStorage:WaitForChild(\"Posto17Shared\")\nlocal library = shared:WaitForChild(\"Posto17R6Corpo\", 12)\nif library and not library:FindFirstChild(\"P17_Corpo_003\") then\n    for _, child in ipairs(library:GetDescendants()) do\n        if child:IsA(\"Folder\") and child:FindFirstChild(\"P17_Corpo_003\") then\n            library = child\n            break\n        end\n    end\nend\n\nlocal ids = {\n    idle = \"P17_Corpo_003\",\n    walk = \"P17_Corpo_036\",\n    run = \"P17_Corpo_001\",\n    crouchIdle = \"P17_Corpo_013\",\n    crouchWalk = \"P17_Corpo_015\",\n    proneIdle = \"P17_Corpo_008\",\n    proneCrawl = \"P17_Corpo_017\",\n    coverLow = \"P17_Corpo_020\",\n    coverHigh = \"P17_Corpo_025\",\n    coverMove = \"P17_Corpo_016\",\n    jump = \"P17_Corpo_045\",\n    fall = \"P17_Corpo_044\",\n    landing = \"P17_Corpo_009\",\n    standToCrouch = \"P17_Corpo_022\",\n    standToProne = \"P17_Corpo_026\",\n    crouchToProne = \"P17_Corpo_028\",\n    proneToStand = \"P17_Corpo_042\",\n    proneToCrouch = \"P17_Corpo_047\",\n    leaveCover = \"P17_Corpo_031\",\n    enterHighCover = \"P17_Corpo_034\",\n    leaveHighCover = \"P17_Corpo_023\",\n}\nlocal poseNames = {\n    \"Torso\", \"Head\", \"Left Arm\", \"Right Arm\", \"Left Leg\", \"Right Leg\",\n}\nlocal transitions = {\n    [\"STAND>CROUCH\"] = \"standToCrouch\",\n    [\"STAND>PRONE\"] = \"standToProne\",\n    [\"CROUCH>PRONE\"] = \"crouchToProne\",\n    [\"PRONE>STAND\"] = \"proneToStand\",\n    [\"PRONE>CROUCH\"] = \"proneToCrouch\",\n    [\"COVER_HIGH>STAND\"] = \"leaveHighCover\",\n    [\"COVER_LOW>STAND\"] = \"leaveCover\",\n    [\"STAND>COVER_HIGH\"] = \"enterHighCover\",\n}\n\nlocal cache = {}\nlocal active = setmetatable({}, {__mode=\"k\"})\n\nlocal function readClip(key)\n    if cache[key] ~= nil then return cache[key] or nil end\n    if not library then return nil end\n    local id = ids[key]\n    local sequence = id and library:FindFirstChild(id)\n    if not sequence or not sequence:IsA(\"KeyframeSequence\") then\n        warn(\"[P17 R6] Sequencia nao encontrada: \", key, id)\n        cache[key] = false\n        return nil\n    end\n    local entries = sequence:GetKeyframes()\n    table.sort(entries, function(a, b) return a.Time < b.Time end)\n    if #entries < 2 then cache[key] = false; return nil end\n    local frames = {}\n    for _, entry in ipairs(entries) do\n        local transforms = {}\n        for _, pose in ipairs(entry:GetDescendants()) do\n            if pose:IsA(\"Pose\") and pose.Name ~= \"HumanoidRootPart\" then\n                transforms[pose.Name] = pose.CFrame\n            end\n        end\n        table.insert(frames, {time = entry.Time, transforms = transforms})\n    end\n    local duration = frames[#frames].time\n    if duration <= 0 then cache[key] = false; return nil end\n    local result = {frames = frames, duration = duration, loop = sequence.Loop}\n    cache[key] = result\n    return result\nend\n\nlocal function sample(clip, rawTime)\n    local t = (clip.loop and rawTime % clip.duration) or math.min(rawTime, clip.duration)\n    local frames = clip.frames\n    if t <= frames[1].time then return frames[1].transforms end\n    local left, right = frames[1], frames[#frames]\n    for index = 2, #frames do\n        if t <= frames[index].time then\n            left, right = frames[index-1], frames[index]\n            break\n        end\n    end\n    local progress = math.clamp((t-left.time)/math.max(right.time-left.time, .00001), 0, 1)\n    local result = {}\n    for _, name in ipairs(poseNames) do\n        local a = left.transforms[name] or CFrame.identity\n        local b = right.transforms[name] or a\n        result[name] = a:Lerp(b, progress)\n    end\n    return result\nend\n\nlocal function makeState(character)\n    local joints = {}\n    for _, desc in ipairs(character:GetDescendants()) do\n        if desc:IsA(\"Motor6D\") and desc.Part1 then\n            for _, name in ipairs(poseNames) do\n                if desc.Part1.Name == name then joints[name] = desc; break end\n            end\n        end\n    end\n    for _, name in ipairs(poseNames) do\n        if not joints[name] then return nil end\n    end\n    return {\n        joints=joints, time=0, actionTime=0,\n        clip=nil, action=nil, stance=nil, previousPose=nil, fade=0,\n        lastFloor=true, traversing=false,\n    }\nend\n\nlocal function stanceFor(player)\n    local current = player:GetAttribute(\"Posto17Stance\") or \"STAND\"\n    if current == \"VENT\" then current = \"PRONE\" end\n    local cover = player:GetAttribute(\"Posto17CoverHeight\")\n    if cover and current ~= \"PRONE\" then\n        current = cover == \"LOW\" and \"COVER_LOW\" or \"COVER_HIGH\"\n    end\n    return current\nend\n\nlocal function preferredClip(player, info)\n    local humanoid = info.humanoid\n    local root = humanoid.RootPart\n    local speed = Vector3.new(root.AssemblyLinearVelocity.X,0,root.AssemblyLinearVelocity.Z).Magnitude\n    local grounded = humanoid.FloorMaterial ~= Enum.Material.Air\n    local stance = stanceFor(player)\n    if not grounded then\n        return root.AssemblyLinearVelocity.Y > 0.8 and \"jump\" or \"fall\", stance, grounded, speed\n    end\n    if stance == \"PRONE\" then return speed > .45 and \"proneCrawl\" or \"proneIdle\", stance, grounded, speed end\n    if stance == \"CROUCH\" then return speed > .45 and \"crouchWalk\" or \"crouchIdle\", stance, grounded, speed end\n    if stance == \"COVER_HIGH\" then return speed > .45 and \"coverMove\" or \"coverHigh\", stance, grounded, speed end\n    if stance == \"COVER_LOW\" then return \"coverLow\", stance, grounded, speed end\n    if player:GetAttribute(\"Posto17Sprint\") and speed > 3 then return \"run\", stance, grounded, speed end\n    if speed > .45 then return \"walk\", stance, grounded, speed end\n    return \"idle\", stance, grounded, speed\nend\n\nlocal function changeClip(state, key)\n    if state.clip == key then return end\n    state.clip=key\n    state.time=0\n    state.fade=0\nend\n\nfunction Motion.update(player, info, dt)\n    if info.isR15 or not library or not info.character or not info.character.Parent then return false end\n    local humanoid = info.humanoid\n    if humanoid.RigType ~= Enum.HumanoidRigType.R6 or not humanoid.RootPart then return false end\n    if player:GetAttribute(\"Posto17Hidden\") then return false end\n    if info.character:GetAttribute(\"P17Motion\") then return false end\n\n    local state = active[info.character]\n    if not state then\n        state = makeState(info.character)\n        if not state then return false end\n        active[info.character]=state\n    end\n    local key,stance,grounded,speed = preferredClip(player,info)\n    local newAction\n    if player:GetAttribute(\"Posto17Traversing\") then\n        return false -- travessia ja e controlada pelo sistema existente\n    elseif state.stance ~= nil and state.stance ~= stance then\n        newAction=transitions[state.stance..\">\"..stance]\n    elseif grounded and not state.lastFloor and stance == \"STAND\" then\n        newAction=\"landing\"\n    end\n    if newAction and not readClip(newAction) then newAction=nil end\n    if newAction then\n        state.action=newAction\n        state.actionTime=0\n        state.fade=0\n    end\n    state.stance=stance\n    state.lastFloor=grounded\n    if state.action then\n        local activeClip=readClip(state.action)\n        if not activeClip or state.actionTime >= activeClip.duration\n            then\n            state.action=nil\n        end\n    end\n    local selected=state.action or key\n    local clip=readClip(selected)\n    if not clip then return false end\n    changeClip(state,selected)\n    local rate=1\n    if selected == \"walk\" then rate=math.clamp(speed/9,.4,1.8)\n    elseif selected == \"run\" then rate=math.clamp(speed/17,.6,1.6)\n    elseif selected == \"crouchWalk\" then rate=math.clamp(speed/6,.4,1.6)\n    elseif selected == \"proneCrawl\" then rate=math.clamp(speed/3.4,.5,1.5) end\n    local inc=math.min(math.max(dt,0),.06)*rate\n    state.time+=inc\n    if state.action then state.actionTime+=inc end\n    local pose=sample(clip,state.time)\n    state.fade=math.min(1,state.fade+inc/.13)\n    local blend=state.fade*state.fade*(3-2*state.fade)\n    for _,name in ipairs(poseNames) do\n        local joint=state.joints[name]\n        local target=pose[name] or CFrame.identity\n        if state.previousPose and state.fade < 1 then\n            target=(state.previousPose[name] or CFrame.identity):Lerp(target,blend)\n        end\n        if joint.Parent then joint.Transform=target end\n    end\n    state.previousPose=pose\n    -- local QA indicator, not authoritative game state\n    if player == game:GetService(\"Players\").LocalPlayer then\n        if player:GetAttribute(\"Posto17R6Animation\") ~= selected then\n            player:SetAttribute(\"Posto17R6Animation\",selected)\n        end\n    end\n    return true\nend\n\nreturn Motion\n"},{"studio":"StarterPlayer/StarterPlayerScripts/TouchLayout","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/TouchLayout (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal Theme = require(game:GetService(\"ReplicatedStorage\"):WaitForChild(\"Posto17Shared\"):WaitForChild(\"HudTheme\"))\nlocal Players = game:GetService(\"Players\")\nlocal UIS = game:GetService(\"UserInputService\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nif not UIS.TouchEnabled then return end\n\nlocal player = Players.LocalPlayer\nlocal playerGui = player:WaitForChild(\"PlayerGui\")\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17TouchLayout\"\ngui.ResetOnSpawn = false\ngui.DisplayOrder = 14\ngui.Parent = playerGui\nlocal safe = Instance.new(\"Frame\")\nsafe.Name = \"AreaSegura\"\nsafe.Size = UDim2.fromScale(1, 1)\nsafe.BackgroundTransparency = 1\nsafe.Parent = gui\n\nlocal tray = Instance.new(\"Frame\")\ntray.Name = \"Ferramentas\"\ntray.BackgroundColor3 = Theme.Panel\ntray.BackgroundTransparency = 0.22\ntray.BorderSizePixel = 0\ntray.Size = UDim2.fromOffset(166, 138)\ntray.Visible = false\ntray.Parent = safe\nlocal trayCorner = Instance.new(\"UICorner\")\ntrayCorner.CornerRadius = UDim.new(0, 7)\ntrayCorner.Parent = tray\n\nlocal WHITE = Theme.Text\nlocal SELECTED = Theme.Active\nlocal function style(b, label)\n    b.Text, b.TextColor3 = label, WHITE\n    b.BackgroundColor3, b.BackgroundTransparency = Theme.Panel, 0.84\n    b.BorderSizePixel = 0\n    b.TextStrokeColor3, b.TextStrokeTransparency = Theme.Stroke, 0.54\n    b.Font, b.TextSize = Enum.Font.GothamMedium, 13\n    local corner = b:FindFirstChildOfClass(\"UICorner\") or Instance.new(\"UICorner\")\n    corner.CornerRadius = UDim.new(0, 6)\n    corner.Parent = b\nend\n\nlocal function button(name, label, callback)\n    local b = Instance.new(\"TextButton\")\n    b.Name = name\n    style(b, label)\n    b.Parent = safe\n    b.Activated:Connect(callback)\n    return b\nend\n\nlocal function tool(name, label, callback)\n    return button(name, label, function()\n        tray.Visible = false\n        callback()\n    end)\nend\n\nlocal more = button(\"Mais\", \"···\", function() tray.Visible = not tray.Visible end)\nmore.TextSize = 23\nlocal stone = tool(\"PEDRA\", \"Pedra\", function()\n    if player:GetAttribute(\"Posto17Won\") or player:GetAttribute(\"Posto17Hidden\") then return end\n    local root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n    local camera = workspace.CurrentCamera\n    if root and camera then RS:WaitForChild(\"Posto17Stone\"):FireServer(root.Position + camera.CFrame.LookVector * 26) end\nend)\nlocal light = tool(\"LUZ\", \"Lanterna\", function()\n    RS:WaitForChild(\"Posto17Flashlight\"):FireServer(player:GetAttribute(\"Posto17Flashlight\") ~= true)\nend)\nlocal exit = button(\"SAIR\", \"Sair do abrigo\", function()\n    RS:WaitForChild(\"Posto17HideToggle\"):FireServer()\nend)\nlocal mobility = RS:WaitForChild(\"Posto17Mobility\")\nlocal sprint = tool(\"CORRER\", \"Correr\", function()\n    mobility:FireServer(\"SPRINT\", player:GetAttribute(\"Posto17Sprint\") ~= true)\nend)\nlocal box = tool(\"CAIXA\", \"Caixa\", function() mobility:FireServer(\"BOX\") end)\nlocal options = tool(\"OPCOES\", \"Opções\", function()\n    player:SetAttribute(\"P17OptionsOpen\", not player:GetAttribute(\"P17OptionsOpen\"))\nend)\n\nlocal function find(guiName, name)\n    local owner = playerGui:FindFirstChild(guiName)\n    return owner and owner:FindFirstChild(name, true)\nend\n\nlocal function put(b, parent, x, y, w, h)\n    b.AnchorPoint = Vector2.zero\n    if b.Parent ~= parent then b.Parent = parent end\n    b.Position, b.Size = UDim2.fromOffset(x, y), UDim2.fromOffset(w, h)\nend\n\nlocal function attach(guiName, name, parent, label)\n    local b = find(guiName, name)\n    if b then\n        style(b, label)\n        b.Parent = parent\n    end\n    return b\nend\n\nlocal crouch, prone, cover, instinct, ops\nwhile gui.Parent do\n    local size = safe.AbsoluteSize\n    local hidden, won = player:GetAttribute(\"Posto17Hidden\"), player:GetAttribute(\"Posto17Won\")\n    local reviewing = player:GetAttribute(\"P17Reviewing\") == true\n    local stance = player:GetAttribute(\"Posto17Stance\")\n    gui.Enabled = not won and not reviewing\n    if hidden or won or reviewing then tray.Visible = false end\n\n    crouch = crouch or attach(\"Posto17HUD\", \"AGACHAR\", safe, \"Agachar\")\n    prone = prone or attach(\"Posto17HUD\", \"DEITAR\", safe, \"Deitar\")\n    cover = cover or attach(\"Posto17CoberturaTouch\", \"BotaoCobertura\", safe, \"Cobertura\")\n    instinct = instinct or attach(\"Posto17HUD\", \"INSTINTO\", tray, \"Instinto\")\n    ops = ops or find(\"Posto17Operacoes\", \"AcoesTouch\")\n\n    local radarWidth = 116\n    local right = size.X - 12 - radarWidth\n    local jumpX, jumpY = right - 60, size.Y - 67\n    local dockX, dockY = right - 236, jumpY - 50\n    local width = 60\n    local function postureButton(b, slot, active, visible)\n        if not b then return end\n        put(b, safe, dockX + slot, dockY, width, 46)\n        b.BackgroundTransparency = active and 0.54 or 0.87\n        b.TextColor3 = active and SELECTED or WHITE\n        b.Visible = visible and not hidden\n    end\n    local covered = player:GetAttribute(\"Posto17InCover\") == true\n    postureButton(crouch, 0, stance == \"CROUCH\", stance ~= \"VENT\")\n    postureButton(prone, 62, stance == \"PRONE\", stance ~= \"VENT\" and not covered)\n    postureButton(cover, 124, covered, covered or player:GetAttribute(\"P17NearbyCover\") == true)\n\n    put(more, safe, right-112, jumpY, 49, 46)\n    more.BackgroundTransparency = tray.Visible and 0.52 or 0.87\n    more.Visible = not hidden\n    put(tray, safe, right-170, math.max(8, dockY-147), 166, 138)\n    for i, b in pairs({[1] = instinct, [2] = stone, [3] = light, [4] = sprint, [5] = box, [6] = options}) do\n        put(b, tray, ((i-1)%2)*82, math.floor((i-1)/2)*46, 82, 46)\n    end\n    if instinct then instinct.TextColor3 = player:GetAttribute(\"Posto17Instinct\") and SELECTED or WHITE end\n    stone.Text = string.format(\"Pedra · %d\", player:GetAttribute(\"Posto17Stones\") or 3)\n    light.TextColor3 = player:GetAttribute(\"Posto17Flashlight\") and SELECTED or WHITE\n    sprint.TextColor3 = player:GetAttribute(\"Posto17Sprint\") and SELECTED or WHITE\n    box.TextColor3 = player:GetAttribute(\"Posto17Box\") and SELECTED or WHITE\n    sprint.Visible = stance == \"STAND\" and not covered\n    box.Visible = not player:GetAttribute(\"Posto17Prone\")\n\n    local touchGui = playerGui:FindFirstChild(\"TouchGui\")\n    local jump = touchGui and touchGui:FindFirstChild(\"JumpButton\", true)\n    if jump then\n        jump.AnchorPoint = Vector2.zero\n        jump.Size = UDim2.fromOffset(56, 56)\n        jump.Position = UDim2.fromOffset(jumpX, jumpY)\n        jump.Visible = not hidden and not won and not reviewing and not covered\n            and (stance == nil or stance == \"STAND\")\n    end\n    if ops then\n        local opsWidth = math.clamp(right-290, 155, 285)\n        put(ops, safe, math.max(92, (size.X-opsWidth)*0.5), size.Y-54, opsWidth, 44)\n        local n = 0\n        for _, b in ipairs(ops:GetChildren()) do\n            if b:IsA(\"TextButton\") then\n                b.Size = UDim2.fromOffset(opsWidth/3, 44)\n                b.Position = UDim2.fromOffset(n*opsWidth/3, 0)\n                n += 1\n            end\n        end\n    end\n    put(exit, safe, size.X/2-70, size.Y-55, 140, 44)\n    exit.Visible = hidden == true\n    task.wait(0.2)\nend\n"},{"studio":"StarterPlayer/StarterPlayerScripts/Traversal","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/Traversal (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto17 / entrada contextual de escalada (G, Y de gamepad, botao touch).\nlocal Players = game:GetService(\"Players\")\nlocal RS = game:GetService(\"ReplicatedStorage\")\nlocal RunService = game:GetService(\"RunService\")\nlocal CAS = game:GetService(\"ContextActionService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal player = Players.LocalPlayer\nlocal world = workspace:WaitForChild(\"Posto17\", 30)\nlocal event = RS:WaitForChild(\"Posto17Traversal\", 30)\nif not world or not event then return end\nlocal params = RaycastParams.new()\nparams.FilterType = Enum.RaycastFilterType.Exclude\nparams.RespectCanCollide = true\n\nlocal function getObstacle()\n    if player:GetAttribute(\"P17InMainMenu\")\n        or player:GetAttribute(\"Posto17Traversing\")\n        or player:GetAttribute(\"Posto17Hidden\")\n        or player:GetAttribute(\"Posto17InCover\")\n        or player:GetAttribute(\"Posto17Stance\") ~= \"STAND\" then return nil end\n    local character = player.Character\n    local hum = character and character:FindFirstChildOfClass(\"Humanoid\")\n    local root = character and character:FindFirstChild(\"HumanoidRootPart\")\n    if not hum or not root or hum.Health <= 0 or root.Anchored then return nil end\n    local direction = root.CFrame.LookVector * Vector3.new(1,0,1)\n    if direction.Magnitude < .8 then return nil end\n    direction = direction.Unit\n    params.FilterDescendantsInstances = {character}\n    local ground = workspace:Raycast(root.Position, Vector3.new(0,-8,0), params)\n    if not ground then return nil end\n    local origin = Vector3.new(root.Position.X, ground.Position.Y + 1.2, root.Position.Z)\n    local hit = workspace:Raycast(origin, direction*3.4, params)\n    if not hit or not hit.Instance:IsDescendantOf(world)\n        or not hit.Instance.CanCollide or hit.Normal:Dot(direction) > -.7 then return nil end\n    local part = hit.Instance\n    local top = workspace:Raycast(hit.Position - hit.Normal*.18 + Vector3.new(0,8,0),\n        Vector3.new(0,-11,0), params)\n    if not top or top.Instance ~= part or top.Normal.Y < .8 then return nil end\n    local h = top.Position.Y-ground.Position.Y\n    if h < 1.15 or h > 5.8 then return nil end\n    local localDir = part.CFrame:VectorToObjectSpace(direction)\n    local thickness = math.abs(localDir.X)*part.Size.X + math.abs(localDir.Z)*part.Size.Z\n    if h <= 2.7 and thickness <= 2.6 then return \"VAULT\" end\n    if h > 2.7 and thickness <= 7.5 then return \"CLIMB\" end\n    return nil\nend\nlocal lastPressed = 0\nlocal function trigger(_, state)\n    if state ~= Enum.UserInputState.Begin then return Enum.ContextActionResult.Pass end\n    if not getObstacle() then return Enum.ContextActionResult.Pass end\n    local now = os.clock()\n    if now - lastPressed < .6 then return Enum.ContextActionResult.Sink end\n    lastPressed = now\n    event:FireServer()\n    return Enum.ContextActionResult.Sink\nend\nCAS:BindAction(\"P17TraversarObstaculo\",trigger,false,Enum.KeyCode.G,Enum.KeyCode.ButtonY)\n\nif UserInputService.TouchEnabled then\n    local ui = Instance.new(\"ScreenGui\")\n    ui.Name = \"Posto17TravessiaTouch\"\n    ui.DisplayOrder = 10\n    ui.ResetOnSpawn = false\n    ui.Parent = player:WaitForChild(\"PlayerGui\")\n    local button = Instance.new(\"TextButton\")\n    button.Name = \"BotaoTravessia\"\n    button.AnchorPoint = Vector2.new(1,1)\n    button.Position = UDim2.new(1,-20,1,-299)\n    button.Size = UDim2.fromOffset(79,37)\n    button.BackgroundColor3 = Color3.fromRGB(31,35,39)\n    button.BackgroundTransparency = .22\n    button.BorderSizePixel = 0\n    button.Text = \"ESCALAR\"\n    button.TextSize = 12\n    button.Font = Enum.Font.GothamMedium\n    button.TextColor3 = Color3.fromRGB(228,232,234)\n    button.Visible = false\n    button.Parent = ui\n    local edge = Instance.new(\"UIStroke\")\n    edge.Color = Color3.fromRGB(130,57,56)\n    edge.Thickness = 1\n    edge.Transparency = .34\n    edge.Parent = button\n    local rounded = Instance.new(\"UICorner\")\n    rounded.CornerRadius = UDim.new(0,5)\n    rounded.Parent = button\n    button.Activated:Connect(function() trigger(nil,Enum.UserInputState.Begin) end)\n    local elapsed = 0\n    RunService.Heartbeat:Connect(function(dt)\n        elapsed += dt\n        if elapsed < .15 then return end\n        elapsed = 0\n        local action = getObstacle()\n        button.Visible = action ~= nil\n        if action then button.Text = action == \"CLIMB\" and \"ESCALAR\" or \"PASSAR\" end\n    end)\nend\n\nif game.PlaceId == 119377443515742 or RunService:IsStudio() then\n    local demo = RS:WaitForChild(\"P17TraversalDemo\", 10)\n    if demo then\n        local panel = Instance.new(\"ScreenGui\")\n        panel.Name = \"Posto17TravessiaEnsaio\"\n        panel.ResetOnSpawn = false\n        panel.DisplayOrder = 9\n        panel.Parent = player:WaitForChild(\"PlayerGui\")\n        local function make(name,text,y,color)\n            local b=Instance.new(\"TextButton\")\n            b.Name=name\n            b.Size=UDim2.fromOffset(141,33)\n            b.Position=UDim2.fromOffset(16,y)\n            b.Text=text\n            b.TextSize=11\n            b.Font=Enum.Font.GothamMedium\n            b.TextColor3=Color3.fromRGB(240,242,243)\n            b.BackgroundColor3=color\n            b.BorderSizePixel=0\n            b.Parent=panel\n            local corner=Instance.new(\"UICorner\")\n            corner.CornerRadius=UDim.new(0,4)\n            corner.Parent=b\n            return b\n        end\n        local climb=make(\"ReverEscalada\",\"TESTAR ESCALADA\",156,Color3.fromRGB(43,66,70))\n        local vault=make(\"ReverTravessia\",\"TESTAR BARREIRA\",194,Color3.fromRGB(80,46,47))\n        climb.Activated:Connect(function() demo:FireServer(\"CLIMB\") end)\n        vault.Activated:Connect(function() demo:FireServer(\"VAULT\") end)\n        local function visibility()\n            local active=player:GetAttribute(\"Posto17InTestRange\") ~= false\n                and player:GetAttribute(\"Posto17InVisualShowcase\")~=true\n                and player:GetAttribute(\"P17InMainMenu\")~=true\n            climb.Visible=active\n            vault.Visible=active\n        end\n        player:GetAttributeChangedSignal(\"P17InMainMenu\"):Connect(visibility)\n        player:GetAttributeChangedSignal(\"Posto17InTestRange\"):Connect(visibility)\n        player:GetAttributeChangedSignal(\"Posto17InVisualShowcase\"):Connect(visibility)\n        visibility()\n    end\nend\n"},{"studio":"StarterPlayer/StarterPlayerScripts/VisualShowcase","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/VisualShowcase (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- P17 Visual Showcase: HUD de referencia separado dos controles de jogo.\n-- Alternar AMOSTRAS nao afeta dificuldade, IA ou estado real da missao.\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal player = Players.LocalPlayer\nlocal playerGui = player:WaitForChild(\"PlayerGui\")\nlocal Theme = require(ReplicatedStorage:WaitForChild(\"Posto17Shared\")\n    :WaitForChild(\"HudTheme\"))\n\nlocal gui = Instance.new(\"ScreenGui\")\ngui.Name = \"Posto17MostraVisual\"\ngui.ResetOnSpawn = false\ngui.IgnoreGuiInset = false\ngui.DisplayOrder = 35\ngui.Enabled = false\ngui.Parent = playerGui\n\nlocal function frame(name,parent,size,position,background,transparency)\n    local f=Instance.new(\"Frame\")\n    f.Name=name\n    f.Size=size\n    f.Position=position\n    f.BackgroundColor3=background or Theme.Panel\n    f.BackgroundTransparency=transparency or 0\n    f.BorderSizePixel=0\n    f.Parent=parent\n    return f\nend\nlocal function text(name,parent,value,size,pos,color,fontSize,bold)\n    local lbl=Instance.new(\"TextLabel\")\n    lbl.Name=name\n    lbl.Text=value\n    lbl.Size=size\n    lbl.Position=pos\n    lbl.TextColor3=color or Theme.Text\n    lbl.BackgroundTransparency=1\n    lbl.Font=bold and Enum.Font.GothamBold or Enum.Font.Code\n    lbl.TextSize=fontSize or 13\n    lbl.TextXAlignment=Enum.TextXAlignment.Left\n    lbl.TextYAlignment=Enum.TextYAlignment.Center\n    lbl.TextTruncate=Enum.TextTruncate.AtEnd\n    lbl.Parent=parent\n    return lbl\nend\n\nlocal top=frame(\"FaixaOperacional\",gui,UDim2.fromOffset(382,66),\n    UDim2.fromOffset(18,18),Theme.Panel,.22)\nframe(\"IdentidadeMinima\",top,UDim2.fromOffset(3,55),\n    UDim2.fromOffset(0,6),Theme.Brand,0)\ntext(\"CodigoOperacao\",top,\"P17  /  VISUAL SYSTEM 01\",\n    UDim2.fromOffset(350,22),UDim2.fromOffset(12,3),Theme.Active,12)\ntext(\"ObjetivoAmostra\",top,\"OBJETIVO  /  AVALIAR COERENCIA VISUAL\",\n    UDim2.fromOffset(350,24),UDim2.fromOffset(12,30),Theme.Text,13)\n\nlocal alert=frame(\"AmostraDeAlerta\",gui,UDim2.fromOffset(208,38),\n    UDim2.new(1,-227,0,23),Theme.Panel,.28)\nlocal alertEdge=frame(\"BarraDeEstado\",alert,UDim2.fromOffset(3,34),\n    UDim2.fromOffset(0,2),Theme.Caution,0)\nlocal alertLabel=text(\"Estado\",alert,\"STATUS  /  SEGURO\",\n    UDim2.fromOffset(194,32),UDim2.fromOffset(13,3),Theme.Muted,13)\nalert.Visible=false\n\nlocal radar=frame(\"RadarAmostra\",gui,UDim2.fromOffset(124,124),\n    UDim2.new(0,18,1,-150),Theme.Panel,.26)\nlocal rim=Instance.new(\"UIStroke\")\nrim.Name=\"LinhaRadar\"\nrim.Color=Theme.Border\nrim.Thickness=1\nrim.Transparency=.3\nrim.Parent=radar\ntext(\"RadarLegenda\",radar,\"SETOR  P17\",\n    UDim2.fromOffset(110,18),UDim2.fromOffset(7,5),Theme.Muted,10)\nfor _, rect in ipairs({\n    {x=13,y=38,w=83,h=2},{x=13,y=38,w=2,h=61},\n    {x=33,y=52,w=56,h=2},{x=89,y=52,w=2,h=46},\n    {x=17,y=97,w=74,h=2},\n}) do\n    frame(\"PlantaTecnica\",radar,UDim2.fromOffset(rect.w,rect.h),\n        UDim2.fromOffset(rect.x,rect.y),Theme.MapLine,.28)\nend\nlocal playerDot=frame(\"PontoOperador\",radar,UDim2.fromOffset(7,7),\n    UDim2.fromOffset(57,72),Theme.Text,0)\nlocal targetDot=frame(\"MarcadorObjetivo\",radar,UDim2.fromOffset(6,6),\n    UDim2.fromOffset(82,46),Theme.Caution,0)\n\nlocal controls=frame(\"ComparacaoDeEstados\",gui,UDim2.fromOffset(278,45),\n    UDim2.new(.5,-139,1,-60),Theme.Panel,.16)\nlocal selected=\"PADRAO\"\nlocal buttons={}\nfor i,option in ipairs({\"PADRAO\",\"SUSPEITA\",\"ALERTA\"}) do\n    local b=Instance.new(\"TextButton\")\n    b.Name=\"Exemplo_\"..option\n    b.Position=UDim2.fromOffset(6+(i-1)*92,6)\n    b.Size=UDim2.fromOffset(86,33)\n    b.Text=option\n    b.Font=Enum.Font.Code\n    b.TextSize=12\n    b.TextColor3=Theme.Text\n    b.BorderSizePixel=0\n    b.AutoButtonColor=false\n    b.Parent=controls\n    buttons[option]=b\nend\nlocal function select(mode)\n    selected=mode\n    for name,button in pairs(buttons) do\n        button.BackgroundColor3=name==mode and Theme.Surface or Theme.Panel\n        button.BackgroundTransparency=name==mode and .12 or .70\n        button.TextColor3=name==mode and Theme.Highlight or Theme.Muted\n    end\n    alert.Visible=mode~=\"PADRAO\"\n    if mode==\"SUSPEITA\" then\n        alertLabel.Text=\"STATUS  /  SUSPEITA\"\n        alertLabel.TextColor3=Theme.Caution\n        alertEdge.BackgroundColor3=Theme.Caution\n    elseif mode==\"ALERTA\" then\n        alertLabel.Text=\"STATUS  /  ALERTA\"\n        alertLabel.TextColor3=Theme.Danger\n        alertEdge.BackgroundColor3=Theme.Danger\n    else\n        alertLabel.Text=\"STATUS  /  SEGURO\"\n    end\nend\nfor option,button in pairs(buttons) do\n    button.Activated:Connect(function() select(option) end)\nend\nselect(\"PADRAO\")\nlocal caption=text(\"AvisoLaboratorio\",gui,\n    \"AMOSTRA VISUAL / NAO REPRESENTA ALERTA REAL\",\n    UDim2.fromOffset(360,18),UDim2.fromOffset(18,87),Theme.Muted,10)\n\n-- Preservar estado anterior das GUIs de jogabilidade. Controles mobile\n-- (TouchLayout e TouchGui) continuam ativos para caminhar na showcase.\nlocal hidden={}\nlocal names={Posto17HUD=true,Posto17MiniMapa=true,Posto17Guia=true}\nlocal function toggleOthers(hide)\n    if hide then\n        for _,layer in ipairs(playerGui:GetChildren()) do\n            if names[layer.Name] and layer:IsA(\"ScreenGui\") then\n                if hidden[layer]==nil then hidden[layer]=layer.Enabled end\n                layer.Enabled=false\n            end\n        end\n    else\n        for layer,enabled in pairs(hidden) do\n            if layer.Parent then layer.Enabled=enabled end\n        end\n        table.clear(hidden)\n    end\nend\nlocal world=workspace:WaitForChild(\"Posto17\",30)\nif not world then return end\nlocal function update()\n    local inside=player:GetAttribute(\"Posto17InVisualShowcase\")==true\n    if gui.Enabled~=inside then\n        gui.Enabled=inside\n        toggleOthers(inside)\n        if inside then select(\"PADRAO\") end\n    end\nend\nplayer:GetAttributeChangedSignal(\"Posto17InVisualShowcase\"):Connect(update)\nplayerGui.ChildAdded:Connect(function(layer)\n    if gui.Enabled and names[layer.Name] and layer:IsA(\"ScreenGui\") then\n        if hidden[layer]==nil then hidden[layer]=layer.Enabled end\n        layer.Enabled=false\n    end\nend)\nupdate()\n"},{"studio":"StarterPlayer/StarterPlayerScripts/WorldMotion","class":"LocalScript","source":"-- Local no Studio: StarterPlayer/StarterPlayerScripts/WorldMotion (LocalScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Animacoes de equipamentos do posto. Visual local sem lag de rede,\n-- com pausa durante sabotagem da rede eletrica.\nlocal RunService = game:GetService(\"RunService\")\nlocal UserInputService = game:GetService(\"UserInputService\")\nlocal Lighting = game:GetService(\"Lighting\")\n\nlocal world = workspace:WaitForChild(\"Posto17\", 30)\nif not world then return end\nlocal scenery = world:WaitForChild(\"Cenario3D\", 30)\nif not scenery then return end\n\nlocal rotors = {}\nlocal tracked = {}\nlocal function trackRotor(model)\n    if not model:IsA(\"Model\") or tracked[model]\n        or model:GetAttribute(\"Animation\") ~= \"ROTATE\"\n        or not model:FindFirstChildWhichIsA(\"BasePart\", true) then return end\n    tracked[model] = true\n    rotors[#rotors + 1] = {\n        model = model,\n        pivot = model:GetPivot(),\n        rate = model:GetAttribute(\"AngularSpeed\") or 1.5,\n    }\n    world:SetAttribute(\"AnimatedPropsClient\", #rotors)\nend\nfor _, item in ipairs(scenery:GetDescendants()) do trackRotor(item) end\n\n-- Celulares usam menos pos-processamento e luzes de menor alcance.\n-- Nenhuma hitbox ou fonte de deteccao muda; a otimização é só visual.\nif UserInputService.TouchEnabled then\n    local bloom = Lighting:FindFirstChild(\"Posto17Bloom\")\n    if bloom and bloom:IsA(\"BloomEffect\") then bloom.Enabled = false end\n    local atmosphere = Lighting:FindFirstChild(\"Posto17Atmosphere\")\n    if atmosphere and atmosphere:IsA(\"Atmosphere\") then\n        atmosphere.Density = math.min(atmosphere.Density, 0.20)\n        atmosphere.Haze = math.min(atmosphere.Haze, 0.7)\n    end\nend\nlocal tuned = {}\nlocal function tuneLight(light)\n    if not UserInputService.TouchEnabled or not light:IsA(\"PointLight\")\n        or tuned[light] then return end\n    tuned[light] = true\n    light.Range *= 0.84\n    light.Brightness *= 0.82\nend\nfor _, item in ipairs(world:GetDescendants()) do tuneLight(item) end\nscenery.DescendantAdded:Connect(function(item)\n    -- StreamingEnabled pode adicionar os ventiladores depois do jogador entrar.\n    task.defer(function()\n        if not scenery.Parent then return end\n        tuneLight(item)\n        trackRotor(item)\n        local ancestor = item.Parent\n        while ancestor and ancestor ~= scenery do\n            if ancestor:IsA(\"Model\") then trackRotor(ancestor) end\n            ancestor = ancestor.Parent\n        end\n    end)\nend)\n\nlocal currentAngle = 0\nlocal elapsed = 0\nlocal connection\nconnection = RunService.RenderStepped:Connect(function(dt)\n    if not scenery.Parent or not world.Parent then\n        connection:Disconnect()\n        return\n    end\n    elapsed += math.min(dt, 0.1)\n    if elapsed < 1/20 then return end -- 20 Hz: suficiente para o low-poly.\n    if world:GetAttribute(\"PowerOnline\") ~= false then\n        currentAngle += elapsed\n    end\n    for _, rotor in ipairs(rotors) do\n        if rotor.model.Parent then\n            rotor.model:PivotTo(rotor.pivot\n                * CFrame.Angles(0, currentAngle * rotor.rate, 0))\n        end\n    end\n    elapsed = 0\nend)\n"},{"studio":"ReplicatedStorage/Posto17Shared/ArsenalCatalog","class":"ModuleScript","source":"-- Local no Studio: ReplicatedStorage/Posto17Shared/ArsenalCatalog (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal items = {\n    {id=\"Pistol\", attribute=\"P17LoadoutPistol\", label=\"Pistola\",\n        description=\"Arma secundária para a missão.\", enable=\"Equipar\", disable=\"Guardar\",\n        on=\"Equipada\", off=\"Na reserva\"},\n    {id=\"Suppressor\", attribute=\"P17LoadoutSuppressor\", label=\"Supressor\",\n        description=\"12 disparos silenciados por missão.\", enable=\"Instalar\", disable=\"Retirar\",\n        on=\"Instalado\", off=\"Na bancada\"},\n}\nreturn items\n"},{"studio":"ReplicatedStorage/Posto17Shared/HudTheme","class":"ModuleScript","source":"-- Local no Studio: ReplicatedStorage/Posto17Shared/HudTheme (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\nlocal function rgb(r, g, b)\n    return Color3.fromRGB(r, g, b)\nend\n\n-- P17 VIS-1: escala 80% neutra / 15% funcao / 5% destaque.\n-- HUD e menu usam a mesma hierarquia, sem brilho decorativo.\nreturn table.freeze({\n    Panel = rgb(31, 35, 40),\n    Surface = rgb(53, 60, 68),\n    Border = rgb(76, 83, 87),\n    MapLine = rgb(105, 115, 118),\n    Text = rgb(227, 228, 219),\n    Highlight = rgb(245, 246, 241),\n    Muted = rgb(151, 158, 157),\n    Stroke = rgb(15, 18, 21),\n    Brand = rgb(139, 0, 0),\n    Active = rgb(206, 191, 165),\n    Danger = rgb(188, 67, 59),\n    Caution = rgb(184, 131, 47),\n    Success = rgb(126, 161, 141),\n    ShadowZone = rgb(47, 59, 58),\n    Font = Enum.Font.GothamMedium,\n    TechnicalFont = Enum.Font.Code,\n    ArtRevision = \"P17-VIS-1\",\n})\n"},{"studio":"ReplicatedStorage/Posto17Shared/PoseLibrary","class":"ModuleScript","source":"-- Local no Studio: ReplicatedStorage/Posto17Shared/PoseLibrary (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Posto 17: biblioteca de poses humanas procedurais (R15/AJU e R6).\n-- Os valores sao offsets relativos ao Transform do Animator, nao movimentos\n-- de HumanoidRootPart. Nao teleporta o personagem nem simula pulo.\nlocal PoseLibrary = {}\n\nlocal rad = math.rad\nlocal function value(x, y, z, rx, ry, rz)\n    return {x or 0, y or 0, z or 0, rad(rx or 0), rad(ry or 0), rad(rz or 0)}\nend\n\n-- Angulos R15 nos eixos da parte pai, em graus. O cliente converte para\n-- os eixos de cada junta, preservando os pontos de rotacao do avatar.\nlocal R15 = {\n    CROUCH = {\n        root = value(0, 0, 0.22, -11),\n        waist = value(0, 0, 0, -25),\n        neck = value(0, 0, 0, 29),\n        lefthip = value(0, 0, 0, 55, 0, -4),\n        righthip = value(0, 0, 0, 55, 0, 4),\n        leftknee = value(0, 0, 0, -94),\n        rightknee = value(0, 0, 0, -91),\n        leftankle = value(0, 0, 0, 50),\n        rightankle = value(0, 0, 0, 47),\n        leftshoulder = value(0, 0, 0, 12, -3, -10),\n        rightshoulder = value(0, 0, 0, 4, 3, 10),\n        leftelbow = value(0, 0, 0, 30),\n        rightelbow = value(0, 0, 0, 42),\n        leftwrist = value(0, 0, 0, -12),\n        rightwrist = value(0, 0, 0, -10),\n    },\n    PRONE = {\n        root = value(0, -0.19, 0, -78),\n        waist = value(0, 0, 0, -9),\n        neck = value(0, 0, 0, 49),\n        lefthip = value(0, 0, 0, -10, 0, -9),\n        righthip = value(0, 0, 0, -9, 0, 9),\n        leftknee = value(0, 0, 0, -12),\n        rightknee = value(0, 0, 0, -9),\n        leftankle = value(0, 0, 0, 25),\n        rightankle = value(0, 0, 0, 23),\n        leftshoulder = value(0, 0, 0, 72, 0, -19),\n        rightshoulder = value(0, 0, 0, 65, 0, 19),\n        leftelbow = value(0, 0, 0, 94, 10),\n        rightelbow = value(0, 0, 0, 100, -11),\n        leftwrist = value(0, 0, 0, 1),\n        rightwrist = value(0, 0, 0, 2),\n    },\n}\n\nlocal function mirrored(angles, depth, offset, lean)\n    local pose = {root = value(0, depth, offset, lean)}\n    for name, angle in pairs(angles) do\n        local joint, pitch, roll = name:lower(), angle[1], angle[2] or 0\n        pose[\"left\" .. joint] = value(0, 0, 0, pitch, 0, -roll)\n        pose[\"right\" .. joint] = value(0, 0, 0, pitch, 0, roll)\n    end\n    return pose\nend\n\nR15.VENT = mirrored({\n    Hip = {65, 8}, Knee = {-100}, Ankle = {15}, Shoulder = {64, 12},\n    Elbow = {31}, Wrist = {-12},\n}, -0.32, 0, -66)\nR15.VENT.waist = value(0, 0, 0, -11)\nR15.VENT.neck = value(0, 0, 0, 48)\n\nR15.COVER_HIGH = mirrored({\n    Hip = {4, 5}, Knee = {-9}, Ankle = {5}, Shoulder = {7, 10},\n    Elbow = {20},\n}, 0, 0, 0)\nR15.COVER_HIGH.waist = value(0, 0, 0, 1)\nR15.COVER_HIGH.neck = value(0, 0, 0, 0, 21)\nR15.COVER_HIGH.leftshoulder = value(0, 0, 0, 17, -6, -13)\nR15.COVER_HIGH.leftelbow = value(0, 0, 0, 35)\nR15.COVER_LOW = mirrored({\n    Hip = {77, 14}, Knee = {-119}, Ankle = {51}, Shoulder = {23, 15},\n    Elbow = {43}, Wrist = {-12},\n}, 0, 0.17, -10)\nR15.COVER_LOW.waist = value(0, 0, 0, -25, -24, 6)\nR15.COVER_LOW.neck = value(0, 0, 0, 28, 35)\nR15.COVER_LOW.leftshoulder = value(0, 0, 0, 52, 7, -14)\nR15.COVER_LOW.leftelbow = value(0, 0, 0, 77)\n\nR15.SPRINT = mirrored({\n    Hip = {7, 2}, Knee = {-23}, Ankle = {8}, Shoulder = {12, 10},\n    Elbow = {63},\n}, 0, 0, -13)\nR15.SPRINT.waist = value(0, 0, 0, -4)\nR15.SPRINT.neck = value(0, 0, 0, 15)\n\n-- R6 nao tem joelho articulado: pose de reducao limitada, sem fingir R15.\nlocal R6 = {\n    CROUCH = {\n        rootjoint = value(0, -0.23, 0.02, -10),\n        neck = value(0, 0, 0, 9),\n        lefthip = value(0, 0, 0, -40),\n        righthip = value(0, 0, 0, -40),\n        leftshoulder = value(0, 0, 0, -15),\n        rightshoulder = value(0, 0, 0, -15),\n    },\n    PRONE = {\n        rootjoint = value(0, -0.57, -0.16, -69),\n        neck = value(0, 0, 0, 49),\n        lefthip = value(0, 0, 0, 16),\n        righthip = value(0, 0, 0, 16),\n        leftshoulder = value(0, 0, 0, 79),\n        rightshoulder = value(0, 0, 0, 79),\n    },\n}\n\n-- Um ciclo por membro. Na primeira metade o membro fica apoiado e\n-- recua em relacao ao corpo. Na segunda ele levanta e avanca.\nlocal function stride(phase)\n    local half = phase / math.pi % 2\n    if half < 1 then return 1 - 2 * half, 0 end\n    local swing = half - 1\n    local reach = swing * swing * (3 - 2 * swing)\n    return 2 * reach - 1, math.sin(math.pi * swing) ^ 2\nend\n\nfunction PoseLibrary.get(stance, jointName, motion, cycle, isR15)\n    local key = string.lower(jointName):gsub(\"%s+\", \"\")\n    local poses = (isR15 and R15 or R6)[stance]\n    local base = poses and poses[key]\n    if not base then return nil end\n    local weight = motion == true and 1 or tonumber(motion) or 0\n    if weight == 0 then return base end\n\n    local left = key:sub(1, 4) == \"left\"\n    local leg, lift = stride(cycle + (left and 0 or math.pi))\n    local arm, elbowLift = stride(cycle + (left and math.pi or 0))\n    local offset = 0\n    if stance == \"CROUCH\" then\n        local hip = 11 * leg + 6 * lift\n        local knee = -7 * leg - 27 * lift\n        if key:find(\"hip\", 1, true) then offset = isR15 and hip or -hip end\n        if key:find(\"knee\", 1, true) then offset = knee end\n        if key:find(\"ankle\", 1, true) then offset = -hip - knee + 8 * lift end\n        if key:find(\"shoulder\", 1, true) then offset = 8 * arm end\n        if key:find(\"elbow\", 1, true) then offset = 7 * elbowLift end\n    elseif stance == \"COVER_HIGH\" then\n        local sweep = math.sin(cycle)\n        local side = left and -1 or 1\n        local step = math.max(0, side * math.cos(cycle)) ^ 2\n        local roll = 0\n        if key:find(\"hip\", 1, true) then\n            roll = 16 * sweep + side * 5 * step\n            offset = 7 * step\n        elseif key:find(\"knee\", 1, true) then\n            offset = -20 * step\n        elseif key:find(\"ankle\", 1, true) then\n            roll = -16 * sweep - side * 5 * step\n            offset = 13 * step\n        elseif key:find(\"shoulder\", 1, true) then\n            roll = -4 * sweep\n        elseif key == \"waist\" then\n            roll = -2.5 * sweep\n        end\n        return {base[1], base[2], base[3], base[4] + rad(offset * weight),\n            base[5], base[6] + rad(roll * weight)}\n    elseif stance == \"COVER_LOW\" then\n        -- Passos laterais em cobertura baixa: um pe apoia, o outro recolhe.\n        local sweep = math.sin(cycle)\n        local side = left and 1 or -1\n        local step = math.max(0, side * math.cos(cycle)) ^ 2\n        if key == \"root\" then\n            return {base[1], base[2] + .023 * step * weight, base[3],\n                base[4], base[5], base[6] + rad(2.3 * sweep * weight)}\n        end\n        if key == \"waist\" then\n            return {base[1], base[2], base[3], base[4],\n                base[5] + rad(-6 * sweep * weight),\n                base[6] + rad(3 * sweep * weight)}\n        end\n        if key == \"neck\" then\n            return {base[1], base[2], base[3], base[4],\n                base[5] + rad(4 * sweep * weight), base[6]}\n        end\n        if key:find(\"hip\", 1, true) then\n            return {base[1], base[2], base[3],\n                base[4] + rad((13 * step - 4 * sweep) * weight),\n                base[5], base[6] + rad(side * 17 * sweep * weight)}\n        end\n        if key:find(\"knee\", 1, true) then offset = -30 * step end\n        if key:find(\"ankle\", 1, true) then offset = 15 * step end\n        if key:find(\"shoulder\", 1, true) then offset = 6 * sweep end\n    elseif stance == \"VENT\" then\n        if key:find(\"hip\", 1, true) then offset = 17 * leg + 13 * lift end\n        if key:find(\"knee\", 1, true) then offset = -12 * leg - 19 * lift end\n        if key:find(\"shoulder\", 1, true) then offset = 21 * arm + 12 * elbowLift end\n        if key:find(\"elbow\", 1, true) then offset = -18 * arm + 33 * elbowLift end\n        if key:find(\"wrist\", 1, true) then offset = -16 * elbowLift end\n    elseif stance == \"SPRINT\" then\n        if key:find(\"hip\", 1, true) then offset = 43 * leg + 18 * lift end\n        if key:find(\"knee\", 1, true) then offset = 10 * leg - 68 * lift end\n        if key:find(\"ankle\", 1, true) then offset = -22 * leg + 21 * lift end\n        if key:find(\"shoulder\", 1, true) then offset = 38 * arm end\n        if key:find(\"elbow\", 1, true) then offset = 21 * arm end\n    else\n        if key:find(\"shoulder\", 1, true) then offset = 25 * arm + 8 * elbowLift end\n        if key:find(\"elbow\", 1, true) then offset = -24 * arm + 19 * elbowLift end\n        if key:find(\"hip\", 1, true) and isR15 then\n            local roll = base[6] + rad((left and -1 or 1) * 21 * lift * weight)\n            return {base[1], base[2], base[3], base[4] + rad((13 * leg + 19 * lift) * weight), base[5], roll}\n        end\n        if key:find(\"knee\", 1, true) then offset = -11 * leg - 43 * lift end\n        if key:find(\"ankle\", 1, true) then offset = 20 * lift end\n    end\n\n    local twist = key == \"waist\" and math.sin(cycle) * (stance == \"PRONE\" and 6 or 4) or 0\n    return {base[1], base[2], base[3], base[4] + rad(offset * weight),\n        base[5] + rad(twist * weight), base[6]}\nend\n\n-- P17 Movimento Estilizado v1: silhueta quadrada inspirada em R6, rig R15.\n-- O ciclo usa fase de apoio + balanço; o joelho só recolhe durante o passo.\n-- Isso preserva a lógica do jogo (R15) sem usar o Roblox Tool ou trocar o avatar.\nfunction PoseLibrary.basic(jointName, speed, cycle, clock, strafe)\n    local key = string.lower(jointName):gsub(\"%s+\", \"\")\n    local moving = math.clamp(speed / 13, 0, 1)\n    local grounded = moving * moving * (3 - 2 * moving)\n    local lateral = math.clamp(strafe or 0, -1, 1) * grounded\n    local supportLeft, upLeft = stride(cycle)\n    local supportRight, upRight = stride(cycle + math.pi)\n    local hipLeft = (27 * supportLeft + 10 * upLeft) * grounded\n    local hipRight = (27 * supportRight + 10 * upRight) * grounded\n    local kneeLeft = (-36 * upLeft - 3 * math.max(0, -supportLeft)) * grounded\n    local kneeRight = (-36 * upRight - 3 * math.max(0, -supportRight)) * grounded\n    local rotation = (supportLeft - supportRight) * 1.55 * grounded\n    local rise = (upLeft + upRight) * .018 * grounded\n    local breathing = math.sin(clock * 2.4)\n    local idleSway = math.sin(clock * 1.15)\n    if key == \"root\" then\n        return value(0, rise + .006 * breathing * (1 - grounded), 0,\n            -3.5 * grounded, -lateral * 4.5, -lateral * 6)\n    end\n    if key == \"waist\" then\n        return value(0, 0, 0, -3 * grounded + .7 * breathing * (1-grounded),\n            rotation + lateral * 4, -lateral * 3)\n    end\n    if key == \"neck\" then\n        return value(0, 0, 0, 3.5 * grounded - .55 * breathing * (1-grounded),\n            -rotation * .55 - lateral * 2, lateral * 2)\n    end\n    if key == \"lefthip\" then return value(0,0,0,hipLeft,0,-lateral*3) end\n    if key == \"righthip\" then return value(0,0,0,hipRight,0,-lateral*3) end\n    if key == \"leftknee\" then return value(0,0,0,kneeLeft) end\n    if key == \"rightknee\" then return value(0,0,0,kneeRight) end\n    if key == \"leftankle\" then return value(0,0,0,-hipLeft*.60-kneeLeft*.83) end\n    if key == \"rightankle\" then return value(0,0,0,-hipRight*.60-kneeRight*.83) end\n    if key == \"leftshoulder\" then\n        return value(0,0,0,-.81*hipLeft - 6*grounded + 2*idleSway*(1-grounded),0,-3)\n    end\n    if key == \"rightshoulder\" then\n        return value(0,0,0,-.81*hipRight - 6*grounded - 2*idleSway*(1-grounded),0,3)\n    end\n    if key == \"leftelbow\" then return value(0,0,0,13+10*upRight*grounded) end\n    if key == \"rightelbow\" then return value(0,0,0,13+10*upLeft*grounded) end\n    if key == \"leftwrist\" then return value(0,0,0,-4*grounded) end\n    if key == \"rightwrist\" then return value(0,0,0,-4*grounded) end\nend\n\n-- Quadro-a-quadro original de travessia: mao no topo, impulso, perna recolhida,\n-- passagem do quadril e retorno ao apoio. Valores em graus para o Motor6D.\nlocal TraversalClips = {\n    CLIMB = {\n        {0,    {leftelbow={12},rightelbow={12}}},\n        {.14,  {root={-6},waist={-18},neck={12},leftshoulder={112,0,-19},rightshoulder={112,0,19},\n                 leftelbow={22},rightelbow={22},lefthip={-10},righthip={-10}}},\n        {.31,  {root={-12},waist={-26},neck={17},leftshoulder={128,0,-16},rightshoulder={128,0,16},\n                 leftelbow={45},rightelbow={45},lefthip={29},righthip={17},\n                 leftknee={-47},rightknee={-36}}},\n        {.51,  {root={-18},waist={-31},neck={20},leftshoulder={70,0,-21},rightshoulder={70,0,21},\n                 leftelbow={73},rightelbow={73},lefthip={68},righthip={56},\n                 leftknee={-91},rightknee={-76},leftankle={34},rightankle={32}}},\n        {.72,  {root={-8},waist={-17},neck={10},leftshoulder={39,0,-12},rightshoulder={39,0,12},\n                 leftelbow={38},rightelbow={38},lefthip={29},righthip={17},\n                 leftknee={-56},rightknee={-38},leftankle={20},rightankle={15}}},\n        {.89,  {root={-2},waist={-7},neck={5},leftshoulder={11},rightshoulder={13},\n                 leftelbow={17},rightelbow={17},lefthip={8},righthip={4},\n                 leftknee={-12},rightknee={-9}}},\n        {1,    {leftelbow={12},rightelbow={12}}}\n    },\n    VAULT = {\n        {0,   {leftelbow={12},rightelbow={12}}},\n        {.13, {root={-12},waist={-14},neck={9},leftshoulder={66,0,-15},rightshoulder={66,0,15},\n                leftelbow={28},rightelbow={28},lefthip={25},righthip={21},leftknee={-27},rightknee={-24}}},\n        {.38, {root={-25},waist={-24},neck={20},leftshoulder={89,0,-21},rightshoulder={89,0,21},\n                leftelbow={49},rightelbow={49},lefthip={73},righthip={66},\n                leftknee={-96},rightknee={-83},leftankle={44},rightankle={40}}},\n        {.61, {root={-16},waist={-14},neck={13},leftshoulder={42,0,-14},rightshoulder={42,0,14},\n                leftelbow={34},rightelbow={34},lefthip={52},righthip={61},\n                leftknee={-76},rightknee={-89},leftankle={32},rightankle={35}}},\n        {.83, {root={-4},waist={-6},neck={5},leftshoulder={10},rightshoulder={13},\n                leftelbow={16},rightelbow={16},lefthip={18},righthip={18},\n                leftknee={-26},rightknee={-29}}},\n        {1,   {leftelbow={12},rightelbow={12}}}\n    }\n}\n\nlocal function sampleTraversal(clip, joint, progress)\n    progress = math.clamp(progress, 0, 1)\n    local first, second = clip[1], clip[#clip]\n    for n = 1, #clip-1 do\n        if progress <= clip[n+1][1] then\n            first, second = clip[n],clip[n+1]\n            break\n        end\n    end\n    local fraction = (progress-first[1]) / math.max(.001,second[1]-first[1])\n    fraction = fraction*fraction*(3-2*fraction)\n    local a,b=first[2][joint] or {0,0,0},second[2][joint] or {0,0,0}\n    local rx=(a[1] or 0)+((b[1] or 0)-(a[1] or 0))*fraction\n    local ry=(a[2] or 0)+((b[2] or 0)-(a[2] or 0))*fraction\n    local rz=(a[3] or 0)+((b[3] or 0)-(a[3] or 0))*fraction\n    return value(0,0,0,rx,ry,rz)\nend\n\n-- (pitch, yaw, roll) em graus. O peso da acao entra e sai numa curva suave.\nlocal Actions = {\n    LOCK = {waist = {-26}, neck = {-18}, rightshoulder = {41, -6},\n        rightelbow = {68}, leftshoulder = {34, 7}, leftelbow = {72}},\n    BUTTON = {waist = {-7, 8}, rightshoulder = {71, -9, 10}, rightelbow = {19}},\n    DOOR = {waist = {-13, 12}, rightshoulder = {55, -14, 16}, rightelbow = {32}},\n    LOCKER = {waist = {-9, -14}, rightshoulder = {59, -19, 17}, rightelbow = {24}},\n    TERMINAL = {waist = {-12}, neck = {-9}, rightshoulder = {54, -8}, rightelbow = {51},\n        leftshoulder = {49, 9}, leftelbow = {55}},\n    STEAL = {waist = {-13, 11}, rightshoulder = {40, -18, 14}, rightelbow = {31}},\n    BOX = {root = {-14}, waist = {-33}, lefthip = {49}, righthip = {49},\n        leftknee = {-78}, rightknee = {-78}, leftankle = {43}, rightankle = {43},\n        leftshoulder = {74, 0, -21}, rightshoulder = {74, 0, 21},\n        leftelbow = {44}, rightelbow = {44}},\n    VENT_OPEN = {waist = {-9}, neck = {12}, rightshoulder = {109, 0, 17}, rightelbow = {30}},\n    VENT_UP = {waist = {-14}, neck = {19}, leftshoulder = {148, 0, -13},\n        rightshoulder = {155, 0, 12}, leftelbow = {24}, rightelbow = {28},\n        lefthip = {40}, righthip = {24}, leftknee = {-53}, rightknee = {-45}},\n    KO = {root = {-7}, waist = {-11, -13}, leftshoulder = {68, -13, -14},\n        rightshoulder = {68, 14, 14}, leftelbow = {54}, rightelbow = {69}},\n    KILL = {root = {-10}, waist = {-19, 19}, leftshoulder = {68, 11, -16},\n        rightshoulder = {83, -10, 13}, leftelbow = {42}, rightelbow = {56}},\n}\n\nfunction PoseLibrary.action(name, joint, progress)\n    if TraversalClips[name] then\n        return sampleTraversal(TraversalClips[name],joint,progress)\n    end\n    local pose = Actions[name]\n    local angle = pose and pose[joint]\n    if not angle then return nil end\n    local beat = math.sin(progress * math.pi)\n    local micro = 0\n    if joint:find(\"elbow\", 1, true) then\n        if name == \"LOCK\" or name == \"TERMINAL\" then\n            micro = 7 * math.sin(progress * math.pi * 13 + (joint == \"leftelbow\" and 2 or 0))\n        elseif name == \"LOCKER\" then\n            micro = -20 * beat\n        end\n    end\n    local yaw = angle[2] or 0\n    if joint == \"waist\" and (name == \"KO\" or name == \"KILL\") then\n        yaw = yaw * (0.45 + 0.55 * beat)\n    end\n    local slide = joint == \"root\" and name == \"BOX\" and -0.22 or 0\n    return value(0, slide, 0, angle[1] + micro, yaw, angle[3])\nend\n\nfunction PoseLibrary.hipDrop(stance, originalHip, isR15)\n    if not isR15 then return 0 end\n    local height = math.max(0, originalHip or 0)\n    if stance == \"CROUCH\" then return math.min(0.56, height * 0.36) end\n    if stance == \"PRONE\" or stance == \"VENT\" then return math.min(1.02, height * 0.62) end\n    return 0\nend\n\nfunction PoseLibrary.jumpAllowed(stance)\n    return stance == \"STAND\"\nend\n\nreturn PoseLibrary\n"},{"studio":"ReplicatedStorage/Posto17Shared/Posto17ModelData","class":"ModuleScript","source":"-- Local no Studio: ReplicatedStorage/Posto17Shared/Posto17ModelData (ModuleScript)\n-- Fonte sincronizada do Posto17 v125; preserva o nome Rojo (.client/.server).\n-- Modelos originais, dados geometricos. Sem executar os scripts Lua da fonte.\nlocal HttpService = game:GetService(\"HttpService\")\nreturn HttpService:JSONDecode([==[{\"pistola\":{\"parts\":[{\"name\":\"Slide_Superior\",\"size\":[0.235,0.205,0.87],\"position\":[0.0,0.225,0.045],\"rotation\":[0,0,0],\"color\":[38,40,42],\"shape\":\"box\"},{\"name\":\"Slide_Calha\",\"size\":[0.206,0.035,0.79],\"position\":[0.0,0.342,0.038],\"rotation\":[0,0,0],\"color\":[26,28,30],\"shape\":\"box\"},{\"name\":\"Slide_Frente\",\"size\":[0.23,0.18,0.092],\"position\":[0.0,0.225,0.493],\"rotation\":[0,0,0],\"color\":[26,28,30],\"shape\":\"box\"},{\"name\":\"Slide_Traseira\",\"size\":[0.24,0.215,0.074],\"position\":[0.0,0.221,-0.391],\"rotation\":[0,0,0],\"color\":[38,40,42],\"shape\":\"box\"},{\"name\":\"Estrutura_Lateral\",\"size\":[0.204,0.155,0.64],\"position\":[0.0,0.057,-0.052],\"rotation\":[0,0,0],\"color\":[26,28,30],\"shape\":\"box\